window.ANOS_SERIES = {"title": "تعلّم مع أنوس: ما لا يسع الطفل المسلم جهله", "seasons": [{"n": 1, "title": "الموسم الأول: العقيدة والفقه", "episodes": [1, 10]}, {"n": 2, "title": "الموسم الثاني: السيرة والتفسير والحديث والآداب", "episodes": [11, 21]}, {"n": 3, "title": "الموسم الثالث: الأخلاق والأذكار والمنوّعات", "episodes": [22, 30]}], "goals": {"aqeeda": "العقيدة", "fiqh": "الفقه", "seerah": "السيرة", "tafsir": "التفسير", "hadith": "الحديث", "adab": "الآداب", "akhlaq": "الأخلاق", "adhkar": "الأدعية والأذكار", "munawaat": "المنوعات"}, "episodes": [{"n": 1, "title": "ربّي ودِيني ونبيّي", "season": 1, "goals": ["aqeeda"], "hook": "أهلًا يا أصدقاء! أنا أنوس، ومعي صديقي الببغاء «فصيح» الذي يحبّ الأسئلة. فصيح يسأل: «ثلاثة أسئلة… ثلاثة أسئلة… أهمّ ثلاثة أسئلة في حياة كل مسلم!». هل تعرف ما هي؟", "sections": [{"h": "أنوس يرحّب: ما الذي لا يسعنا جهله؟", "p": ["في هذه السلسلة نتعلّم معًا كتاب «<b>ما لا يسع أطفال المسلمين جهله</b>»، أي: الأشياء المهمّة التي يجب على كل طفل مسلم أن يعرفها.", "في كل حلقة يسأل فصيح أسئلة الكتاب، ونجيب عنها بجواب الكتاب ودليله، ثم أشرحها لكم بكلماتي، ونلعب ونتعلّم «هل تعلم؟»، وفي آخر الحلقة لغز «مَن أنا؟».", "واليوم نبدأ بأهمّ ثلاثة أسئلة: <b>مَن ربّك؟ وما دينك؟ ومَن نبيّك؟</b>"], "board": ["مَن ربّك؟", "ما دينك؟", "مَن نبيّك؟"]}, {"h": "ربّي الله، وديني الإسلام، ونبيّي محمد ﷺ", "p": ["<b>ربّي الله</b>: هو الذي خلقني ورزقني، وأعطاني عينيّ لأرى، وأمّي وأبي ليرعياني، والطعام والماء. وهو الذي خلق كل شيء في الكون، ولا أعبد أحدًا غيره.", "<b>ديني الإسلام</b>: أن أسلّم قلبي لله، فأوحّده، وأطيعه، وأبتعد عن الشرك. والإسلام هو الدين الذي يرضاه الله.", "<b>نبيّي محمد ﷺ</b>: أرسله الله إلينا ليعلّمنا ديننا. ومعنى «أشهد أنّ محمدًا رسول الله»: أن أطيعه فيما أمر، وأصدّقه فيما أخبر، وأبتعد عمّا نهى عنه، وأعبد الله كما علّمنا."], "board": ["ربّي الله", "ديني الإسلام", "نبيّي محمد ﷺ"]}, {"h": "كلمة التوحيد: لا إله إلا الله", "p": ["أعظم كلمة في الدنيا: <b>لا إله إلا الله</b>. ومعناها: <b>لا معبودَ حقٌّ إلا الله</b>؛ فلا أصلّي ولا أدعو ولا أسجد إلا لله وحده.", "و<b>أين الله؟</b> اللهُ في السماء، فوق العرش، فوق جميع المخلوقات، وهو معنا بعلمه يسمعنا ويرانا."], "board": ["لا إله إلا الله", "لا معبود حقّ إلا الله"]}, {"h": "لماذا خلقنا الله؟", "p": ["فصيح يسأل: «لماذا خلقنا الله؟ لنلعب فقط؟». لا يا فصيح! خلقنا الله <b>لنعبده وحده</b>، ولم يخلقنا عبثًا.", "و<b>العبادة</b> كلمة كبيرة جميلة: كل ما يحبّه الله من الأقوال والأعمال. منها أعمال <b>ظاهرة</b> نراها: مثل الصلاة، والتسبيح، والحجّ. ومنها أعمال في <b>القلب</b>: مثل التوكّل على الله، وحبّه، والخوف منه، ورجاء رحمته.", "وحتى لعبك ونومك وطعامك يصير عبادة إذا نويت به أن تتقوّى على طاعة الله. وأعظم واجب علينا هو <b>توحيد الله</b>."], "board": ["عبادة ظاهرة", "عبادة في القلب", "أعظم واجب: التوحيد"]}], "summary": ["ربّي الله، وديني الإسلام، ونبيّي محمد ﷺ.", "كلمة التوحيد «لا إله إلا الله» معناها: لا معبود حقّ إلا الله.", "خلقنا الله لنعبده وحده، وأعظم واجب علينا هو التوحيد."], "islam": {"intro": "قال الله تعالى يخبرنا لماذا خلقنا:", "text": "فكل يوم نعيش فيه فرصة جديدة لنعبد الله: نصلّي، ونذكره، ونطيع والدينا، ونبتسم لإخوتنا.", "ayah": {"text": "وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ", "src": "سُورَةُ الذَّارِيَاتِ: ٥٦"}, "hadith": null}, "home": {"title": "بطاقات أنوس الثلاث", "goal": "أن يحفظ الطفل الأسئلة الثلاثة وأجوبتها وأدلّتها، ويعلّمها لأسرته.", "materials": ["ثلاث بطاقات ورقية", "ألوان"], "steps": ["اكتب على كل بطاقة سؤالًا: مَن ربّك؟ ما دينك؟ مَن نبيّك؟ وعلى ظهرها الجواب والدليل.", "زيّن البطاقات، والعب مع أسرتك: اسألهم وهم يجيبون، ثم يسألونك.", "قل كلمة التوحيد «لا إله إلا الله» عشر مرّات بعد صلاة المغرب.", "ارسم شيئًا تحبّ أن تفعله، واكتب تحته كيف يمكن أن يكون عبادة بنيّة طيّبة."], "parent": "احتفلوا بكل جواب صحيح، واجعلوا الأسئلة لعبة يومية قصيرة قبل النوم."}, "online": {"title": "أسئلة فصيح", "intro": "ساعد فصيحًا على ترتيب أجوبته، وصنّف العبادات!", "steps": [{"type": "match", "title": "صِل السؤال بجوابه", "prompt": "اختر السؤال، ثم جوابه الصحيح.", "pairs": [["مَن ربّك؟", "ربّي الله"], ["ما دينك؟", "ديني الإسلام"], ["مَن نبيّك؟", "محمد ﷺ"], ["ما كلمة التوحيد؟", "لا إله إلا الله"], ["لماذا خلقنا الله؟", "لنعبده وحده"]]}, {"type": "sort", "title": "عبادة ظاهرة أم في القلب؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["عبادة ظاهرة", "عبادة في القلب"], "items": [{"t": "الصلاة", "icon": "🕌", "bin": 0, "why": "نراها بالقيام والركوع والسجود."}, {"t": "التسبيح", "icon": "📿", "bin": 0, "why": "نقوله باللسان: سبحان الله."}, {"t": "الحجّ", "icon": "🕋", "bin": 0, "why": "نذهب إلى مكّة ونطوف بالكعبة."}, {"t": "التوكّل على الله", "icon": "🤲", "bin": 1, "why": "اعتماد القلب على الله."}, {"t": "الخوف من الله", "icon": "💗", "bin": 1, "why": "شعور في القلب يمنعنا من المعصية."}, {"t": "رجاء رحمة الله", "icon": "🌈", "bin": 1, "why": "أن يرجو القلب رحمة الله وجنّته."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "أين الله؟", "o": ["في السماء فوق العرش", "في كل مكان بذاته", "لا أعرف"], "a": 0}, {"q": "ما أعظم ذنب؟", "o": ["النوم", "الشرك بالله", "اللعب"], "a": 1}, {"q": "معنى «أشهد أنّ محمدًا رسول الله»:", "o": ["أن أعرف اسمه فقط", "أن أحفظ تاريخ ميلاده فقط", "أن أطيعه وأصدّقه وأتّبع سنّته"], "a": 2}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز، فيها شخصية تتكلّم عن نفسها. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا أوّل البشر، خلقني الله بيده، ونفخ فيّ من روحه.", "أمر الله الملائكة أن يسجدوا لي.", "أسكنني الله الجنّة، ثم أُهبطتُ إلى الأرض."], "options": ["نوح عليه السلام", "آدم عليه السلام", "إبراهيم عليه السلام"], "deep": "لماذا أمر الله الملائكة بالسجود لآدم؟ وما الذنب الذي جعل إبليس يرفض؟", "reveal": "أنا آدم عليه السلام، أبو البشر! وقد رفض إبليس السجود تكبّرًا، فطرده الله. وفي الحلقة القادمة نتعلّم أنواع التوحيد، وأعظم ذنب يجب أن نحذره."}, "quiz": [{"q": "مَن ربّك؟", "o": ["ربّي الله", "ربّي الشمس", "لا أعرف"], "a": 0, "why": "ربّي الله الذي خلقني ورزقني."}], "qa": [{"id": 1, "q": "مَن ربُّك؟", "a": "ربّي اللهُ الذي رَبّاني ورَبّى جميعَ العالمينَ بنعمتِه، وهو معبودي ليس لي معبودٌ سواه، وهو الخالقُ المالكُ الرازقُ المدبِّرُ لجميعِ ما في الكون.\nوالدليل: قوله تعالى: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ [الفاتحة: ٢]."}, {"id": 2, "q": "ما دينُك؟", "a": "ديني الإسلام، وهو الاستسلامُ لله بالتوحيد، والانقيادُ له بالطاعة، والبراءةُ من الشركِ وأهلِه.\nقال تعالى: ﴿إِنَّ الدِّينَ عِندَ اللَّهِ الْإِسْلَامُ﴾ [آل عمران: ١٩]."}, {"id": 3, "q": "مَن نبيُّك؟", "a": "محمدٌ ﷺ. قال تعالى: ﴿مُحَمَّدٌ رَّسُولُ اللَّهِ﴾ [الفتح: ٢٩]."}, {"id": 4, "q": "اذكرْ كلمةَ التوحيد، وما معناها؟", "a": "كلمةُ التوحيد \"لا إله إلا الله\" ومعناها: لا معبودَ حقٌّ إلا الله.\nقال تعالى: ﴿فَاعْلَمْ أَنَّهُ لَا إِلَٰهَ إِلَّا اللَّهُ﴾ [محمد: ١٩]. وقال سبحانه: ﴿ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ هُوَ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ﴾ [الحج: ٦٢]."}, {"id": 5, "q": "أين اللهُ عزَّ وجلَّ؟", "a": "اللهُ في السماءِ فوقَ العرش، فوقَ جميعِ المخلوقات.\nقال تعالى: ﴿الرَّحْمَٰنُ عَلَى الْعَرْشِ اسْتَوَىٰ﴾ [طه: ٥]، وقال: ﴿وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ﴾ [الأنعام: ١٨]."}, {"id": 6, "q": "ما معنى شهادةِ أنَّ محمدًا رسولُ الله؟", "a": "معناها: أنَّ اللهَ أرسلَهُ للعالمينَ بشيرًا ونذيرًا. ويجب:\n١. طاعتُهُ فيما أمَر.\n٢. تصديقُهُ فيما أخبَر.\n٣. عدمُ معصيتِه.\n٤. لا يُعبَدُ اللهُ إلا بما شرَع، وهو الاقتداءُ بالسنةِ وتركُ البدعة.\nقال تعالى: ﴿مَّن يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ﴾ [النساء: ٨٠]."}, {"id": 7, "q": "لماذا خلقَنا اللهُ تعالى؟", "a": "خلقَنا لعبادتِهِ وحدَهُ لا شريكَ له. ولم يخلُقْنا عبثًا أو للهوِ واللعب، أو يتركَنا سدًى وهمَلًا.\nقال تعالى: ﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ﴾ [الذاريات: ٥٦]."}, {"id": 8, "q": "ما هي العبادة؟", "a": "هي اسمٌ جامعٌ لكلِّ ما يحبُّهُ اللهُ ويرضاهُ من الأقوالِ والأعمالِ الباطنةِ والظاهرة.\n• الظاهرة: مثلُ ذكرِ الله باللسانِ من التسبيحِ والتحميدِ والتكبير، والصلاةِ والحج.\n• الباطنة: مثلُ التوكلِ والخوفِ والرجاء."}, {"id": 9, "q": "ما أعظمُ واجبٍ علينا؟", "a": "أعظمُ واجبٍ علينا: توحيدُ الله تعالى.\nقال تعالى: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ﴾ [البينة: ٥]."}], "dyk": ["مَن قال «لا إله إلا الله» صادقاً من قلبِه دخلَ الجنة، فهي مفتاحُ الجنةِ وأثقلُ ما في الميزان.", "قال اللهُ: ﴿وجعلنا من الماءِ كلَّ شيءٍ حي﴾ — والعلمُ يؤكِّدُ أن الماءَ أساسُ كلِّ كائنٍ حي."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»! أَنَا أَنُوس، وَمَعِي الْبَبَّغَاءُ فَصِيح."}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! أَنَا فَصِيح، أُحِبُّ الْأَسْئِلَةَ! الْيَوْمَ عِنْدِي أَهَمُّ ثَلَاثَةِ أَسْئِلَةٍ فِي حَيَاةِ كُلِّ مُسْلِمٍ! أَوَّلُهَا: مَنْ رَبُّكَ؟"}, {"s": "anos", "t": "رَبِّيَ اللَّهُ الَّذِي رَبَّانِي وَرَبَّى جَمِيعَ الْعَالَمِينَ بِنِعْمَتِهِ، وَهُوَ مَعْبُودِي، الْخَالِقُ الْمَالِكُ الرَّازِقُ الْمُدَبِّرُ. وَالدَّلِيلُ: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ."}, {"s": "fasih", "t": "مَا دِينُكَ؟"}, {"s": "anos", "t": "دِينِيَ الْإِسْلَامُ: الِاسْتِسْلَامُ لِلَّهِ بِالتَّوْحِيدِ، وَالِانْقِيَادُ لَهُ بِالطَّاعَةِ، وَالْبَرَاءَةُ مِنَ الشِّرْكِ وَأَهْلِهِ. قَالَ تَعَالَى: إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ."}, {"s": "fasih", "t": "مَنْ نَبِيُّكَ؟"}, {"s": "anos", "t": "نَبِيِّي مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ تَعَالَى: مُحَمَّدٌ رَسُولُ اللَّهِ."}, {"s": "fasih", "t": "وَمَا مَعْنَى: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ؟"}, {"s": "anos", "t": "أَنَّ اللَّهَ أَرْسَلَهُ بَشِيرًا وَنَذِيرًا، فَنُطِيعُهُ فِيمَا أَمَرَ، وَنُصَدِّقُهُ فِيمَا أَخْبَرَ، وَلَا نَعْصِيهِ، وَنَعْبُدُ اللَّهَ بِمَا شَرَعَ، فَنَتَّبِعُ السُّنَّةَ وَنَتْرُكُ الْبِدْعَةَ."}, {"s": "fasih", "t": "اذْكُرْ كَلِمَةَ التَّوْحِيدِ، وَمَا مَعْنَاهَا؟"}, {"s": "anos", "t": "لَا إِلَهَ إِلَّا اللَّهُ، وَمَعْنَاهَا: لَا مَعْبُودَ حَقٌّ إِلَّا اللَّهُ. قَالَ تَعَالَى: فَاعْلَمْ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ مَنْ قَالَ «لَا إِلَهَ إِلَّا اللَّهُ» صَادِقًا مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ، فَهِيَ مِفْتَاحُ الْجَنَّةِ، وَأَثْقَلُ مَا فِي الْمِيزَانِ!"}, {"s": "fasih", "t": "أَيْنَ اللَّهُ عَزَّ وَجَلَّ؟"}, {"s": "anos", "t": "اللَّهُ فِي السَّمَاءِ فَوْقَ الْعَرْشِ، فَوْقَ جَمِيعِ الْمَخْلُوقَاتِ. قَالَ تَعَالَى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى. وَهُوَ مَعَنَا بِعِلْمِهِ، يَسْمَعُنَا وَيَرَانَا."}, {"s": "fasih", "t": "لِمَاذَا خَلَقَنَا اللَّهُ؟ لِنَلْعَبَ فَقَطْ؟"}, {"s": "anos", "t": "لَا يَا فَصِيح! خَلَقَنَا لِنَعْبُدَهُ وَحْدَهُ، وَلَمْ يَخْلُقْنَا عَبَثًا. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ يَتْلُو الدَّلِيلَ مِنْ سُورَةِ الذَّارِيَاتِ."}, {"s": "quran", "ref": "51:56", "t": "وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ"}, {"s": "fasih", "t": "الْجِنُّ وَالْإِنْسُ خُلِقُوا لِيَعْبُدُوا اللَّهَ! فَكُلُّ يَوْمٍ فُرْصَةٌ جَدِيدَةٌ لِلْعِبَادَةِ. وَمَا هِيَ الْعِبَادَةُ؟"}, {"s": "anos", "t": "اسْمٌ جَامِعٌ لِكُلِّ مَا يُحِبُّهُ اللَّهُ وَيَرْضَاهُ مِنَ الْأَقْوَالِ وَالْأَعْمَالِ: ظَاهِرَةٌ كَالتَّسْبِيحِ وَالصَّلَاةِ وَالْحَجِّ، وَبَاطِنَةٌ فِي الْقَلْبِ كَالتَّوَكُّلِ وَالْخَوْفِ وَالرَّجَاءِ."}, {"s": "fasih", "t": "مَا أَعْظَمُ وَاجِبٍ عَلَيْنَا؟"}, {"s": "anos", "t": "تَوْحِيدُ اللَّهِ تَعَالَى. قَالَ تَعَالَى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ."}, {"s": "anos", "t": "الْآنَ «نَشِيدُ الْأَسْئِلَةِ الثَّلَاثَةِ»: يَسْأَلُ الْمُعَلِّمُ، وَتُجِيبُونَ مَعًا بِالدَّلِيلِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَافْعَلُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد الأسئلة الثلاثة"}, {"s": "anos", "t": "أَهْلًا بِعَوْدَتِكُمْ! مُخْتَبَرُ الْقَرَارِ: لِمَاذَا خَلَقَنَا اللَّهُ؟ أ: لِنَلْعَبَ فَقَطْ. ب: لِنَأْكُلَ وَنَنَامَ فَقَطْ. ج: لِنَعْبُدَهُ وَحْدَهُ، وَنَجْعَلَ حَيَاتَنَا فِي طَاعَتِهِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: لماذا خلقنا الله؟"}, {"s": "anos", "t": "«أ» وَ«ب» نِعَمٌ، لَا سَبَبُ خَلْقِنَا، وَالصَّحِيحُ «ج». وَلَعِبُكَ عِبَادَةٌ إِذَا نَوَيْتَ بِهِ التَّقَوِّيَ عَلَى الطَّاعَةِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: أَيُّ هَذِهِ عِبَادَةٌ فِي الْقَلْبِ: التَّوَكُّلُ، أَمِ الْحَجُّ، أَمِ التَّسْبِيحُ؟ فَكِّرُوا..."}, {"s": "anos", "t": "التَّوَكُّلُ عَلَى اللَّهِ! وَمَا أَعْظَمُ وَاجِبٍ عَلَيْنَا؟ فَكِّرُوا..."}, {"s": "fasih", "t": "تَوْحِيدُ اللَّهِ! وَالْآنَ لُغْزُ «مَنْ أَنَا؟»: أَنَا أَوَّلُ الْبَشَرِ، خَلَقَنِي اللَّهُ بِيَدِهِ، وَأَمَرَ الْمَلَائِكَةَ أَنْ يَسْجُدُوا لِي، وَأَسْكَنَنِي الْجَنَّةَ ثُمَّ أُهْبِطْتُ إِلَى الْأَرْضِ."}, {"s": "anos", "t": "نُوحٌ، أَمْ آدَمُ، أَمْ إِبْرَاهِيمُ عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟ الْحَلُّ فِي الْحَلْقَةِ الْقَادِمَةِ!"}, {"s": "fasih", "t": "وَفِي الْبَيْتِ: «بِطَاقَاتُ أَنُوس الثَّلَاثُ»: سُؤَالٌ وَجَوَابٌ وَدَلِيلٌ، تَلْعَبُونَ بِهَا مَعَ أُسْرَتِكُمْ."}, {"s": "anos", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: نَشَاطُ «أَسْئِلَةِ فَصِيح». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 2, "title": "التوحيد وأركان الإيمان", "season": 1, "goals": ["aqeeda"], "hook": "أهلًا يا أصدقاء! فصيح يرفرف بجناحيه ويقول: «ثلاثة… ستة… ثلاثة… ستة!». ما هذه الأرقام يا فصيح؟ اليوم نكتشف معًا: <b>ثلاثة أنواع للتوحيد</b>، و<b>ستة أركان للإيمان</b>. هل أنتم مستعدّون؟", "sections": [{"h": "أنواع التوحيد الثلاثة", "p": ["تعلّمنا في الحلقة الماضية أنّ أعظم واجب علينا هو <b>توحيد الله</b>. واليوم يسأل فصيح: «ما أنواع التوحيد؟». والجواب: ثلاثة أنواع.", "<b>توحيد الربوبية</b>: أن أؤمن أنّ الله وحده هو الخالق الرازق المالك المدبّر. هو الذي خلق الشمس والقمر، وأنزل المطر، وأعطاني طعام الفطور اليوم.", "<b>توحيد الألوهية</b>: أن أعبد الله وحده؛ فلا أصلّي إلا له، ولا أدعو إلا هو، ولا أسجد إلا له.", "<b>توحيد الأسماء والصفات</b>: أن أؤمن بأسماء الله وصفاته التي جاءت في القرآن والسنّة، ولا أقول إنّ الله يشبه أحدًا من خلقه، ولا أنكر شيئًا منها، ولا أسأل: كيف هي؟ فالله «ليس كمثله شيء».", "وقد جمع الله الأنواع الثلاثة في آية واحدة من سورة مريم: «ربّ السماوات والأرض» هذا الربوبية، «فاعبده» هذه الألوهية، «هل تعلم له سميًّا» أي: لا أحد يشبهه، وهذه الأسماء والصفات."], "board": ["توحيد الربوبية", "توحيد الألوهية", "توحيد الأسماء والصفات"]}, {"h": "أعظم ذنب: الشرك بالله", "p": ["فصيح يسأل: «ما أعظم ذنب؟». أنوس يجيب بسرعة: <b>الشرك بالله تعالى</b>. وهو الذنب الذي لا يغفره الله لمن مات عليه، كما في سورة النساء.", "والشرك: أن يجعل الإنسان لله شريكًا أو شبيهًا في عبادته أو ربوبيته أو أسمائه وصفاته. ومنه أن يصرف أيّ عبادة لغير الله.", "وهو نوعان: <b>شرك أكبر</b> مثل: دعاء غير الله، أو السجود لغير الله، أو الذبح لغير الله. و<b>شرك أصغر</b> لا يُخرج من الإسلام، لكنه ذنب خطير، مثل: الحلف بغير الله كأن تقول «وحياة أمّي»، ومثل التمائم وهي أشياء يعلّقها الناس يظنّون أنها تجلب الخير أو تمنع الشرّ، ومثل يسير الرياء: أن يحسّن الولد صلاته لأنّ الناس ينظرون إليه.", "فإذا أردت أن تحلف فقل: «والله». وإذا صلّيت فصلِّ لله وحده، سواء رآك الناس أم لم يروك."], "board": ["شرك أكبر: دعاء غير الله", "شرك أصغر: الحلف بغير الله"]}, {"h": "مَن يعلم الغيب؟", "p": ["الغيب: هو ما غاب عنّا ولا نعرفه، مثل: ماذا سيحدث غدًا؟ ومتى تقوم الساعة؟", "و<b>لا يعلم الغيب إلا الله وحده</b>؛ لا الملَك، ولا الإنسان، ولا الجنّ، ولا الذي يقرأ الفنجان أو الكفّ. قال الله تعالى في سورة النمل: لا يعلم مَن في السماوات والأرض الغيب إلا الله.", "فإذا قال لك أحد: «أنا أعرف ماذا سيحدث لك غدًا»، فاعرف أنه لا يعلم ذلك، وتوكّل على الله الذي يعلم كل شيء."], "board": ["لا يعلم الغيب إلا الله"]}, {"h": "أركان الإيمان الستة", "p": ["جاء جبريل عليه السلام إلى النبيّ ﷺ في صورة رجل، وسأله عن الإيمان، فقال ﷺ: أن تؤمن <b>بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشرّه</b>. رواه مسلم.", "<b>الإيمان بالله</b>: أنّه خالقي ورازقي، وهو وحده المعبود بحقّ، وله الأسماء الحسنى، ولا يشبهه شيء. <b>والملائكة</b>: خلقهم الله من نور، يعبدونه ويطيعون أمره دائمًا. <b>والكتب</b>: مثل القرآن على محمد ﷺ، والإنجيل على عيسى، والتوراة على موسى، والزبور على داود، وصحف إبراهيم وموسى.", "<b>والرسل</b>: أرسلهم الله ليعلّموا الناس، ويبشّروهم بالجنّة، وينذروهم من النار. وأفضلهم أولو العزم: نوح، وإبراهيم، وموسى، وعيسى، ومحمد ﷺ. <b>واليوم الآخر</b>: ما بعد الموت في القبر، ثم يوم القيامة والحساب، ثم يستقرّ أهل الجنّة في الجنّة وأهل النار في النار.", "<b>والقدر</b>: أنّ الله يعلم كل شيء، وكتبه في اللوح المحفوظ، وشاءه، وخلقه. فمراتب القدر أربع: العلم، ثم الكتابة، ثم المشيئة، ثم الخلق. فإذا سقطت كرتك في الماء، أو فزت في السباق، فكل ذلك بقدر الله."], "board": ["الله", "الملائكة", "الكتب", "الرسل", "اليوم الآخر", "القدر"]}], "summary": ["التوحيد ثلاثة أنواع: الربوبية، والألوهية، والأسماء والصفات.", "أعظم ذنب هو الشرك بالله، ومنه أكبر وأصغر، ولا يعلم الغيب إلا الله.", "أركان الإيمان ستة: الله، والملائكة، والكتب، والرسل، واليوم الآخر، والقدر خيره وشرّه."], "islam": {"intro": "قال الله تعالى، في آية جمعت أنواع التوحيد الثلاثة:", "text": "فالله هو ربّنا الذي خلقنا، فنعبده وحده ونصبر على طاعته، ولا أحد يشبهه سبحانه.", "ayah": {"text": "رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّۭا", "src": "سُورَةُ مَرۡيَمَ: ٦٥"}, "hadith": {"text": "أن تؤمن بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وتؤمن بالقدر خيره وشرّه", "source": "حديث جبريل، رواه مسلم"}}, "home": {"title": "شجرة الإيمان الستة", "goal": "أن يحفظ الطفل أركان الإيمان الستة بالترتيب، ويشرحها لأسرته.", "materials": ["ورقة كبيرة", "ألوان"], "steps": ["ارسم شجرة لها ستة أغصان، واكتب على كل غصن ركنًا من أركان الإيمان.", "اكتب تحت الجذع: «لا إله إلا الله»، فهي أصل الشجرة.", "اشرح لأسرتك كل غصن بجملة واحدة.", "اتّفق مع أسرتك: كل من يقول «وحياة…» يقول بدلها: «والله»."], "parent": "علّقوا الشجرة في مكان ظاهر، وراجعوا ركنًا واحدًا كل يوم. وكونوا قدوة في ترك الحلف بغير الله أمام الأطفال."}, "online": {"title": "مختبر التوحيد", "intro": "ساعد فصيحًا على تصنيف أنواع التوحيد، ورتّب أركان الإيمان!", "steps": [{"type": "sort", "title": "أيّ نوع من التوحيد؟", "prompt": "اضغط على البطاقة، ثم اختر نوع التوحيد المناسب.", "bins": ["توحيد الربوبية", "توحيد الألوهية", "توحيد الأسماء والصفات"], "items": [{"t": "الله وحده خلق السماوات والأرض", "icon": "🌍", "bin": 0, "why": "الخلق من أفعال الربّ وحده."}, {"t": "الله وحده يرزقنا الطعام", "icon": "🍎", "bin": 0, "why": "الرزق من أفعال الربّ وحده."}, {"t": "لا أصلّي إلا لله", "icon": "🕌", "bin": 1, "why": "الصلاة عبادة، والعبادة لله وحده."}, {"t": "لا أدعو إلا الله", "icon": "🤲", "bin": 1, "why": "الدعاء عبادة لا تكون إلا لله."}, {"t": "الله السميع البصير", "icon": "✨", "bin": 2, "why": "من أسماء الله الحسنى."}, {"t": "لا يشبه الله أحد من خلقه", "icon": "🌟", "bin": 2, "why": "نؤمن بالصفات بلا تشبيه ولا تمثيل."}]}, {"type": "order", "title": "رتّب أركان الإيمان", "prompt": "رتّب الأركان كما جاءت في حديث جبريل.", "items": ["الإيمان بالله", "الملائكة", "الكتب", "الرسل", "اليوم الآخر", "القدر خيره وشرّه"]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "من أيّ شيء خلق الله الملائكة؟", "o": ["من طين", "من نور", "من نار"], "a": 1, "why": "الملائكة مخلوقات خلقها الله من نور."}, {"q": "التوراة أنزلها الله على…", "o": ["موسى عليه السلام", "عيسى عليه السلام", "داود عليه السلام"], "a": 0, "why": "التوراة على موسى، والإنجيل على عيسى، والزبور على داود."}, {"q": "تعليق شيء لجلب الخير أو دفع الشرّ اسمه:", "o": ["الصدقة", "الدعاء", "التمائم"], "a": 2, "why": "التمائم من الشرك الأصغر كما في الكتاب."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز تحت جناحه، فيها نبيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا خليل الرحمن.", "كسرت أصنام قومي، فأُلقيت في النار، فجعلها الله بردًا وسلامًا عليّ.", "بنيت الكعبة مع ابني."], "options": ["نوح عليه السلام", "إبراهيم عليه السلام", "إسماعيل عليه السلام"], "deep": "لماذا كسر هذا النبيّ الأصنام؟ وأيّ نوع من التوحيد كان يدعو قومه إليه؟", "reveal": "أنا إبراهيم عليه السلام، خليل الرحمن! وأنا من أولي العزم من الرسل، وأُنزلت عليّ صحف إبراهيم. وفي الحلقة القادمة نتعرّف على القرآن والسنّة، ومعجزات الأنبياء العجيبة."}, "quiz": [{"q": "الإيمان بأنّ الله وحده الخالق الرازق المدبّر هو توحيد…", "o": ["الألوهية", "الربوبية", "الأسماء والصفات"], "a": 1, "why": "توحيد الربوبية: أنّ الله وحده الخالق الرازق المالك المدبّر."}], "qa": [{"id": 10, "q": "ما أنواعُ التوحيد؟", "a": "١. توحيدُ الربوبية: وهو الإيمانُ بأنَّ اللهَ هو الخالقُ الرازقُ المالكُ المدبِّر، وحدَهُ لا شريكَ له.\n٢. توحيدُ الألوهية: وهو إفرادُ الله بالعبادة، فلا يُعبَدُ أحدٌ إلا اللهُ تعالى.\n٣. توحيدُ الأسماءِ والصفات: وهو الإيمانُ بالأسماءِ والصفاتِ لله تعالى الواردةِ في الكتابِ والسنة، من دونِ تمثيل، ولا تشبيه، ولا تعطيل، ولا تكييف.\nودليلُ الأنواعِ الثلاثة: ﴿رَّبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِهِ هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾ [مريم: ٦٥]."}, {"id": 11, "q": "ما أعظمُ ذنب؟", "a": "الشركُ بالله تعالى.\nقال تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ وَمَن يُشْرِكْ بِاللَّهِ فَقَدِ افْتَرَىٰ إِثْمًا عَظِيمًا﴾ [النساء: ٤٨]."}, {"id": 12, "q": "ما الشركُ وأنواعه؟", "a": "الشرك: هو أن يجعلَ الإنسانُ لله ندًّا في عبادتِهِ أو ربوبيتِهِ أو أسمائِهِ وصفاتِه. ومن الشركِ صرفُ أيِّ نوعٍ من أنواعِ العبادةِ لغيرِ الله تعالى.\nأنواعه:\n• شركٌ أكبر؛ مثل: دعاءِ غيرِ الله تعالى، أو السجودِ لغيرِهِ سبحانه، أو الذبحِ لغيرِ الله عزَّ وجلَّ.\n• شركٌ أصغر؛ وهو الذي لا يُخرِجُ من الملة مثل: الحلفِ بغيرِ الله تعالى، أو التمائم — وهي ما يُعلَّقُ من الأشياءِ لجلبِ نفعٍ أو دفعِ ضرٍّ — ويسيرِ الرياء، كأن يُحسِّنَ صلاتَهُ لما يرى من نظرِ الناسِ إليه."}, {"id": 13, "q": "هل يعلمُ الغيبَ أحدٌ سوى الله تعالى؟", "a": "لا يعلمُ الغيبَ إلا اللهُ وحدَه.\nقال تعالى: ﴿قُل لَّا يَعْلَمُ مَن فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ﴾ [النمل: ٦٥]."}, {"id": 14, "q": "ما أركانُ الإيمان؟", "a": "أركانُ الإيمانِ ستة:\n١. الإيمانُ بالله تعالى.\n٢. وملائكتِه.\n٣. وكتبِه.\n٤. ورسلِه.\n٥. واليومِ الآخر.\n٦. والقدرِ خيرِهِ وشرِّه.\nوالدليل: حديثُ جبريلَ المشهورُ عند مسلم، قال جبريلُ للنبيِّ ﷺ: «فأخبرني عن الإيمان، قال: أن تؤمنَ بالله، وملائكتِه، وكتبِه، ورسلِه، واليومِ الآخر، وتؤمنَ بالقدرِ خيرِهِ وشرِّه»."}, {"id": 15, "q": "ما معنى أركانِ الإيمان؟", "a": "• الإيمانُ بالله تعالى: أن تؤمنَ بأنَّ اللهَ هو الذي خلقَكَ ورزقَك، وهو المالكُ المدبِّرُ وحدَهُ للمخلوقات، وهو المعبودُ لا معبودَ بحقٍّ سواه، الذي له الخلقُ والأمرُ والحكمُ والتشريعُ وحدَهُ لا شريكَ له. وأنه العظيمُ الكبيرُ الكاملُ الذي له الحمدُ كلُّه، وله الأسماءُ الحسنى والصفاتُ العُلى، ليس له نِدٌّ، ولا يشبهُهُ شيءٌ سبحانه.\n• الإيمانُ بالملائكة: وهي مخلوقاتٌ خلقَها اللهُ من نور، لعبادتِهِ وللانقيادِ التامِّ لأمرِه.\n• الإيمانُ بالكتب: وهي الكتبُ التي أنزلَها اللهُ على رسلِه؛ كالقرآنِ على محمدٍ ﷺ، والإنجيلِ على عيسى، والتوراةِ على موسى، والزبورِ على داود، وصحفِ إبراهيمَ وموسى عليهما السلام.\n• الإيمانُ بالرسل: وهم مَن أرسلَهمُ اللهُ إلى عبادِهِ ليعلموهم، ويبشروهم بالخيرِ والجنة، وينذروهم عن الشرِّ والنار. وأفضلُهم: أولو العزم، وهم: نوحٌ وإبراهيمُ وموسى وعيسى ومحمدٌ ﷺ.\n• الإيمانُ باليومِ الآخر: وهو ما بعدَ الموتِ في القبر، ويومُ القيامة، ويومُ البعثِ والحساب، حيث يستقرُّ أهلُ الجنةِ في منازلِهم وأهلُ النارِ في منازلِهم. قال تعالى: ﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ الْقِيَامَةِ...﴾ [آل عمران: ١٨٥].\n• الإيمانُ بالقدرِ خيرِهِ وشرِّه: القدرُ هو الاعتقادُ بأنَّ اللهَ يعلمُ كلَّ شيءٍ يقعُ في الكون، وأنه كتبَ ذلك في اللوحِ المحفوظ، وشاءَ وجودَهُ وخلقَه. قال تعالى: ﴿إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ﴾ [القمر: ٤٩].\nوهو على أربعِ مراتب: (العلم، ثم الكتابة، ثم المشيئة، ثم الخلق)."}], "dyk": ["سمَّى القرآنُ الجبالَ «أوتاداً»، والعلمُ يقولُ إن للجبالِ جذوراً عميقةً تحتَ الأرضِ تُثبِّتُها كالوتد.", "وصفَ القرآنُ مراحلَ خلقِ الجنينِ في بطنِ أمِّه (نطفة ثم علقة ثم مضغة) قبلَ أن يكتشفَها العلمُ الحديثُ بأكثرَ من ألفِ عام."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! أَوَّلًا حَلُّ اللُّغْزِ: إِنَّهُ آدَمُ عَلَيْهِ السَّلَامُ، أَبُو الْبَشَرِ! وَقَدْ رَفَضَ إِبْلِيسُ السُّجُودَ تَكَبُّرًا، فَطَرَدَهُ اللَّهُ."}, {"s": "anos", "t": "وَالْيَوْمَ: ثَلَاثَةُ أَنْوَاعٍ لِلتَّوْحِيدِ، وَسِتَّةُ أَرْكَانٍ لِلْإِيمَانِ!"}, {"s": "fasih", "t": "فَمَا أَنْوَاعُ التَّوْحِيدِ؟"}, {"s": "anos", "t": "تَوْحِيدُ الرُّبُوبِيَّةِ: أَنَّ اللَّهَ وَحْدَهُ الْخَالِقُ الرَّازِقُ الْمَالِكُ الْمُدَبِّرُ. وَتَوْحِيدُ الْأُلُوهِيَّةِ: أَلَّا نَعْبُدَ إِلَّا اللَّهَ. وَتَوْحِيدُ الْأَسْمَاءِ وَالصِّفَاتِ: أَنْ نُؤْمِنَ بِهَا كَمَا جَاءَتْ، بِلَا تَمْثِيلٍ وَلَا تَشْبِيهٍ وَلَا تَعْطِيلٍ وَلَا تَكْيِيفٍ."}, {"s": "anos", "t": "وَدَلِيلُهَا آيَةٌ مِنْ سُورَةِ مَرْيَمَ، يَتْلُوهَا الشَّيْخُ الْحُصَرِيُّ."}, {"s": "quran", "ref": "19:65", "t": "رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّۭا"}, {"s": "anos", "t": "«رَبُّ السَّمَاوَاتِ» هَذِهِ الرُّبُوبِيَّةُ، وَ«فَاعْبُدْهُ» الْأُلُوهِيَّةُ، وَ«هَلْ تَعْلَمُ لَهُ سَمِيًّا» أَيْ: لَا أَحَدَ يُشْبِهُهُ، وَهَذِهِ الْأَسْمَاءُ وَالصِّفَاتُ."}, {"s": "fasih", "t": "مَا أَعْظَمُ ذَنْبٍ؟"}, {"s": "anos", "t": "الشِّرْكُ بِاللَّهِ؛ لَا يَغْفِرُهُ اللَّهُ لِمَنْ مَاتَ عَلَيْهِ، كَمَا فِي سُورَةِ النِّسَاءِ."}, {"s": "fasih", "t": "وَمَا الشِّرْكُ وَأَنْوَاعُهُ؟"}, {"s": "anos", "t": "أَنْ يَجْعَلَ الْإِنْسَانُ لِلَّهِ نِدًّا فِي عِبَادَتِهِ أَوْ رُبُوبِيَّتِهِ أَوْ أَسْمَائِهِ وَصِفَاتِهِ. وَهُوَ أَكْبَرُ: كَدُعَاءِ غَيْرِ اللَّهِ وَالسُّجُودِ وَالذَّبْحِ لِغَيْرِهِ. وَأَصْغَرُ لَا يُخْرِجُ مِنَ الْمِلَّةِ: كَالْحَلِفِ بِغَيْرِ اللَّهِ، وَالتَّمَائِمِ، وَيَسِيرِ الرِّيَاءِ."}, {"s": "fasih", "t": "هَلْ يَعْلَمُ الْغَيْبَ أَحَدٌ سِوَى اللَّهِ؟"}, {"s": "anos", "t": "لَا يَعْلَمُ الْغَيْبَ إِلَّا اللَّهُ وَحْدَهُ، كَمَا فِي سُورَةِ النَّمْلِ؛ لَا مَلَكٌ، وَلَا إِنْسٌ، وَلَا جِنٌّ، وَلَا قَارِئُ الْفِنْجَانِ!"}, {"s": "fasih", "t": "مَا أَرْكَانُ الْإِيمَانِ؟"}, {"s": "anos", "t": "سِتَّةٌ: الْإِيمَانُ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَالْقَدَرِ خَيْرِهِ وَشَرِّهِ. وَالدَّلِيلُ حَدِيثُ جِبْرِيلَ عَلَيْهِ السَّلَامُ، رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "وَمَا مَعْنَاهَا بِاخْتِصَارٍ؟"}, {"s": "anos", "t": "اللَّهُ خَالِقُنَا وَمَعْبُودُنَا، لَا يُشْبِهُهُ شَيْءٌ. وَالْمَلَائِكَةُ خُلِقُوا مِنْ نُورٍ يُطِيعُونَهُ. وَالْكُتُبُ: الْقُرْآنُ وَالْإِنْجِيلُ وَالتَّوْرَاةُ وَالزَّبُورُ وَالصُّحُفُ."}, {"s": "anos", "t": "وَالرُّسُلُ يُبَشِّرُونَ وَيُنْذِرُونَ، وَأَفْضَلُهُمْ أُولُو الْعَزْمِ: نُوحٌ وَإِبْرَاهِيمُ وَمُوسَى وَعِيسَى وَمُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَالْيَوْمُ الْآخِرُ: الْقَبْرُ وَالْقِيَامَةُ وَالْحِسَابُ. وَالْقَدَرُ أَرْبَعُ مَرَاتِبَ: الْعِلْمُ، وَالْكِتَابَةُ، وَالْمَشِيئَةُ، وَالْخَلْقُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ سَمَّى الْقُرْآنُ الْجِبَالَ «أَوْتَادًا»، وَالْعِلْمُ يَقُولُ إِنَّ لِلْجِبَالِ جُذُورًا عَمِيقَةً تَحْتَ الْأَرْضِ تُثَبِّتُهَا كَالْوَتَدِ!"}, {"s": "anos", "t": "الْآنَ «نَشِيدُ الْأَصَابِعِ السِّتَّةِ»: ارْفَعُوا إِصْبَعًا مَعَ كُلِّ رُكْنٍ، وَاشْرَحُوهُ بِجُمْلَةٍ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَافْعَلُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد الأصابع الستة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أُرِيدُ أَنْ أَحْلِفَ لِصَدِيقِي، فَمَاذَا أَقُولُ؟ أ: وَحَيَاةِ أُمِّي إِنِّي صَادِقٌ. ب: وَاللَّهِ إِنِّي صَادِقٌ. ج: وَحَيَاةِ النَّبِيِّ إِنِّي صَادِقٌ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ، وَصَوِّتُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ ارْجِعُوا لِلنَّتِيجَةِ."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: كيف أحلف؟"}, {"s": "anos", "t": "«أ» وَ«ج» حَلِفٌ بِغَيْرِ اللَّهِ، وَهُوَ مِنَ الشِّرْكِ الْأَصْغَرِ. وَالصَّحِيحُ «ب»: وَاللَّهِ. وَالْأَفْضَلُ أَنْ نَصْدُقَ فَلَا نَحْتَاجَ إِلَى الْحَلِفِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: الْإِيمَانُ بِأَنَّ اللَّهَ وَحْدَهُ الْخَالِقُ الرَّازِقُ هُوَ تَوْحِيدُ مَاذَا؟ فَكِّرُوا..."}, {"s": "anos", "t": "تَوْحِيدُ الرُّبُوبِيَّةِ! وَمَنْ يَعْلَمُ مَاذَا سَيَحْدُثُ غَدًا؟ فَكِّرُوا..."}, {"s": "fasih", "t": "اللَّهُ وَحْدَهُ! وَالْآنَ لُغْزُ «مَنْ أَنَا؟»: أَنَا خَلِيلُ الرَّحْمَنِ، كَسَرْتُ أَصْنَامَ قَوْمِي فَأُلْقِيتُ فِي النَّارِ، فَجَعَلَهَا اللَّهُ بَرْدًا وَسَلَامًا عَلَيَّ، وَبَنَيْتُ الْكَعْبَةَ مَعَ ابْنِي."}, {"s": "anos", "t": "نُوحٌ، أَمْ إِبْرَاهِيمُ، أَمْ إِسْمَاعِيلُ عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: ارْسُمُوا «شَجَرَةَ الْإِيمَانِ» بِسِتَّةِ أَغْصَانٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مُخْتَبَرُ التَّوْحِيدِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 3, "title": "القرآن والسنّة ومعجزات الأنبياء", "season": 1, "goals": ["aqeeda"], "hook": "أهلًا يا أصدقاء! فصيح ينظر إلى السماء ويصيح: «القمر! القمر انشقّ نصفين!». هل هذا حقيقيّ يا فصيح؟ نعم، حدث ذلك مرّة واحدة معجزةً لنبيّنا ﷺ! اليوم نتعلّم عن القرآن والسنّة ومعجزات الأنبياء.", "sections": [{"h": "القرآن كلام الله، والسنّة طريق نبيّنا ﷺ", "p": ["فصيح يسأل: «ما هو القرآن؟». <b>القرآن كلام الله تعالى، ليس بمخلوق</b>. تكلّم الله به، ونزل به جبريل على نبيّنا محمد ﷺ. وكلام الله أفضل من كل كلام.", "و<b>السنّة</b>: كل ما جاء عن النبيّ ﷺ من <b>قول</b> مثل قوله: «كلّ بدعة ضلالة»، أو <b>فعل</b> مثل صلاته ووضوئه، أو <b>تقرير</b> أي شيء فعله الصحابة أمامه فرضيه وسكت عنه، أو <b>صفة</b> في خَلقه أو خُلُقه، مثل ابتسامته وحسن أخلاقه.", "فنحن نتعلّم ديننا من القرآن والسنّة، كما يتعلّم اللاعب اللعبة من قوانينها."], "board": ["القرآن كلام الله", "السنّة: قول، فعل، تقرير، صفة"]}, {"h": "البدعة: لا نزيد في ديننا", "p": ["<b>البدعة</b>: كل ما أحدثه الناس في الدين، ولم يكن على عهد النبيّ ﷺ وأصحابه. و<b>لا نقبلها</b>، بل نردّها؛ قال ﷺ: «كلّ بدعة ضلالة» رواه أبو داود، وقال: «من عمل عملًا ليس عليه أمرنا فهو ردّ» رواه مسلم.", "ومثالها كما في الكتاب: <b>الزيادة في العبادة</b>، كأن يغسل الإنسان أعضاءه في الوضوء أربع مرّات بدل ثلاث، وكالاحتفال بالمولد النبويّ، فلم يرد عن النبيّ ﷺ وأصحابه.", "أنوس يقول: ديننا كامل، أكمله الله لنا. فنحبّ النبيّ ﷺ بأن نتّبع سنّته كما علّمنا، بلا زيادة ولا نقصان."], "board": ["كل بدعة ضلالة", "نتّبع ولا نبتدع"]}, {"h": "الولاء والبراء، ودين الإسلام", "p": ["<b>الولاء</b>: محبّة المؤمنين ونصرتهم؛ فالمسلم أخو المسلم، يحبّه ويساعده ويفرح لفرحه. قال تعالى: «والمؤمنون والمؤمنات بعضهم أولياء بعض».", "و<b>البراء</b>: بغض الكافرين ومعاداتهم، كما تبرّأ إبراهيم عليه السلام والذين معه من قومهم ومن الأصنام التي يعبدونها من دون الله، حتى يؤمنوا بالله وحده.", "و<b>لا يقبل الله دينًا غير الإسلام</b>؛ قال تعالى في سورة آل عمران: ومن يبتغِ غير الإسلام دينًا فلن يُقبل منه، وهو في الآخرة من الخاسرين."], "board": ["الولاء: محبّة المؤمنين ونصرتهم", "البراء: كما تبرّأ إبراهيم من الأصنام"]}, {"h": "احذر الكفر والنفاق", "p": ["الكفر قد يكون <b>بالقول</b> مثل سبّ الله أو رسوله ﷺ، أو <b>بالعمل</b> مثل إهانة المصحف أو السجود لغير الله، أو <b>بالاعتقاد</b> مثل أن يعتقد أنّ هناك من يستحقّ العبادة غير الله، أو خالقًا مع الله.", "و<b>النفاق الأكبر</b>: أن يُخفي الإنسان الكفر في قلبه ويُظهر الإيمان، وهو كفر يُخرج من الإسلام. أمّا <b>النفاق الأصغر</b> فذنب لا يُخرج من الإسلام، وعلاماته في الحديث: «آية المنافق ثلاث: إذا حدّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان» رواه البخاري ومسلم.", "فإذا وعدت صديقك أن تعيد له قلمه غدًا فأعِده، وإذا تكلّمت فاصدق، وإذا أعطاك أحد أمانة فاحفظها."], "board": ["لا أكذب", "أفي بوعدي", "أحفظ الأمانة"]}, {"h": "خاتم الأنبياء ومعجزات الرسل", "p": ["<b>خاتم الأنبياء والمرسلين هو محمد ﷺ</b>؛ أي آخرهم، فلا نبيّ بعده. قال ﷺ: «وأنا خاتم النبيّين لا نبيّ بعدي».", "و<b>المعجزة</b>: أمر عجيب خارق للعادة يعطيه الله لأنبيائه ليدلّ على صدقهم. مثل <b>شقّ القمر</b> لنبيّنا محمد ﷺ، و<b>شقّ البحر</b> لموسى عليه السلام، فنجا هو وقومه، وغرق فرعون وجنوده.", "فصيح يقول: «يا سلام! القمر ينشقّ والبحر ينفتح!». نعم يا فصيح، فالله على كل شيء قدير."], "board": ["محمد ﷺ خاتم النبيّين", "شقّ القمر", "شقّ البحر"]}], "summary": ["القرآن كلام الله ليس بمخلوق، والسنّة قول النبيّ ﷺ وفعله وتقريره وصفته، والبدعة مردودة.", "الولاء محبّة المؤمنين ونصرتهم، والبراء كما تبرّأ إبراهيم من الشرك وأهله، ولا يقبل الله دينًا غير الإسلام.", "محمد ﷺ خاتم الأنبياء، والمعجزة أمر خارق يدلّ على صدق الأنبياء مثل شقّ القمر وشقّ البحر."], "islam": {"intro": "قال الله تعالى يذكر معجزة انشقاق القمر لنبيّنا ﷺ:", "text": "فالمعجزات تدلّ على صدق الأنبياء، وأعظم معجزة بقيت لنا هي القرآن الكريم الذي نقرؤه كل يوم.", "ayah": {"text": "ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ", "src": "سُورَةُ القَمَرِ: ١"}, "hadith": {"text": "من عمل عملًا ليس عليه أمرنا فهو ردّ", "source": "رواه مسلم"}}, "home": {"title": "دفتر الوعود الصادقة", "goal": "أن يتدرّب الطفل على الصدق والوفاء بالوعد وحفظ الأمانة، بعيدًا عن علامات النفاق.", "materials": ["دفتر صغير", "ملصقات نجوم"], "steps": ["اكتب في الدفتر ثلاثة أعمدة: صدقت، وفيت بوعدي، حفظت الأمانة.", "كل يوم ضع نجمة في العمود إذا فعلت ذلك، واكتب مثالًا قصيرًا.", "اقرأ مع أسرتك حديث: «آية المنافق ثلاث…» واحفظوه معًا.", "احكِ لأسرتك قصّة شقّ البحر لموسى عليه السلام."], "parent": "امدحوا الصدق حتى لو اعترف الطفل بخطأ، فهذا يشجّعه على الصدق دائمًا. وكونوا قدوة في الوفاء بوعودكم له."}, "online": {"title": "رحلة القرآن والسنّة", "intro": "ساعد فصيحًا على الاختيار الصحيح، وصِل كل معجزة بصاحبها!", "steps": [{"type": "decision", "title": "مختبر القرار", "scenario": "قال لك صديق: «لنزد في الوضوء غسلة رابعة لنكون أنظف وأكثر أجرًا!».", "options": [{"t": "أوافقه، فالزيادة خير", "result": "الزيادة في العبادة بدعة، والنبيّ ﷺ لم يزد على ثلاث."}, {"t": "أغضب منه وأتركه دون أن أشرح له", "result": "الغضب لا يعلّمه شيئًا. الأفضل أن تنصحه بلطف وتخبره بالسنّة."}, {"t": "أقول له بلطف: نتوضّأ كما توضّأ النبيّ ﷺ، ثلاثًا بلا زيادة", "result": "أحسنت! نتّبع السنّة ولا نبتدع، و«كلّ بدعة ضلالة».", "best": true}]}, {"type": "match", "title": "صِل الكلمة بمعناها", "prompt": "اختر الكلمة، ثم معناها الصحيح.", "pairs": [["القرآن", "كلام الله ليس بمخلوق"], ["السنّة", "قول النبيّ ﷺ وفعله وتقريره"], ["شقّ القمر", "معجزة لمحمد ﷺ"], ["شقّ البحر", "معجزة لموسى عليه السلام"], ["خاتم النبيّين", "محمد ﷺ لا نبيّ بعده"]]}, {"type": "sort", "title": "علامة مؤمن أم علامة نفاق؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["من صفات المؤمن", "من علامات النفاق"], "items": [{"t": "أصدق في كلامي", "icon": "🗣️", "bin": 0, "why": "الصدق من صفات المؤمن."}, {"t": "أردّ الأمانة لصاحبها", "icon": "🎁", "bin": 0, "why": "حفظ الأمانة من الإيمان."}, {"t": "أفي بوعدي", "icon": "🤝", "bin": 0, "why": "الوفاء بالوعد من صفات المؤمن."}, {"t": "أكذب لأهرب من العقاب", "icon": "🙊", "bin": 1, "why": "إذا حدّث كذب: من آية المنافق."}, {"t": "أعد ولا أفي", "icon": "⏰", "bin": 1, "why": "إذا وعد أخلف: من آية المنافق."}, {"t": "أخون من ائتمنني", "icon": "💔", "bin": 1, "why": "إذا اؤتمن خان: من آية المنافق."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز مكتوبة بخطّ جميل، فيها نبيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["كلّمني الله تكليمًا.", "عصاي تنقلب ثعبانًا بإذن الله.", "شققت البحر بعصاي بأمر الله، فنجا قومي وغرق فرعون."], "options": ["سليمان عليه السلام", "عيسى عليه السلام", "موسى عليه السلام"], "deep": "معجزة شقّ البحر دلّت على صدق هذا النبيّ. فما المعجزة التي أعطاها الله لنبيّنا محمد ﷺ وما زلنا نقرؤها إلى اليوم؟", "reveal": "أنا موسى عليه السلام، كليم الله! وأنزل الله عليّ التوراة، وأنا من أولي العزم من الرسل. وفي الحلقة القادمة نتعرّف على أصحاب نبيّنا ﷺ وآل بيته، وعلى بعض أسماء الله الحسنى."}, "quiz": [{"q": "ما هو القرآن؟", "o": ["كتاب كتبه الناس", "كلام الله تعالى ليس بمخلوق", "قصص قديمة"], "a": 1, "why": "القرآن كلام الله تعالى، ليس بمخلوق."}], "qa": [{"id": 16, "q": "ما هو تعريفُ القرآن؟", "a": "هو كلامُ الله تعالى، ليس بمخلوق.\nقال تعالى: ﴿وَإِنْ أَحَدٌ مِّنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللَّهِ﴾ [التوبة: ٦]. ورُوِيَ في الحديث: «وفضلُ كلامِ الله على سائرِ الكلامِ كفضلِ الله على خلقِه» رواه الترمذي."}, {"id": 17, "q": "ما هي السُّنَّة؟", "a": "هي كلُّ قولٍ أو فعلٍ أو تقريرٍ أو صفةٍ خَلقيةٍ أو خُلُقيةٍ للنبيِّ ﷺ."}, {"id": 18, "q": "ما هي البدعة؟ وهل نقبلها؟", "a": "كلُّ ما أحدثَهُ الناسُ في الدين، ولم يكنْ على عهدِ النبيِّ ﷺ وأصحابِه.\nلا نقبلها، ويجبُ أن نردَّها. لقولِ النبيِّ ﷺ: «كلُّ بدعةٍ ضلالة» رواه أبو داود. وقولِه ﷺ: «من عمِلَ عملًا ليس عليه أمرُنا فهو ردّ» رواه مسلم.\nمثالها: الزيادةُ في العبادة، كالزيادةِ على الوضوءِ غسلةً رابعة، وكالاحتفالِ بالمولدِ النبوي، فلم يرِدْ عن النبيِّ ﷺ وأصحابِه."}, {"id": 19, "q": "ما هي عقيدةُ الولاءِ والبراء؟", "a": "• الولاء: هو محبةُ المؤمنينَ ونصرتُهم. قال تعالى: ﴿وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ﴾ [التوبة: ٧١].\n• البراء: هو بغضُ الكافرينَ ومعاداتُهم. قال تعالى: ﴿قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا بِاللَّهِ وَحْدَهُ﴾ [الممتحنة: ٤]."}, {"id": 20, "q": "هل يقبلُ اللهُ غيرَ الإسلامِ دينًا؟", "a": "لا يقبلُ اللهُ دينًا غيرَ الإسلام.\nقال تعالى: ﴿وَمَن يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخَاسِرِينَ﴾ [آل عمران: ٨٥]."}, {"id": 21, "q": "الكفرُ يكونُ بالقولِ والعملِ والاعتقاد، مثِّلْ لذلك.", "a": "• مثالُ القول: سبُّ الله سبحانه أو رسولِه ﷺ.\n• مثالُ العمل: إهانةُ المصحفِ أو السجودُ لغيرِ الله تعالى.\n• مثالُ الاعتقاد: الاعتقادُ أنَّ هناك من يستحقُّ العبادةَ غيرَ الله تعالى، أو أنَّ هناك خالقًا مع الله تعالى."}, {"id": 22, "q": "ما هو النفاقُ وأنواعه؟", "a": "١. النفاقُ الأكبر: وهو إبطانُ الكفرِ وإظهارُ الإيمان. ويُخرِجُ من الإسلامِ وهو من الكفرِ الأكبر. قال تعالى: ﴿إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا﴾ [النساء: ١٤٥].\n٢. النفاقُ الأصغر: مثل: الكذب، وإخلافِ الوعد، وخيانةِ الأمانة. ولا يُخرِجُ من الإسلام، وهو من الذنوب، وصاحبُهُ معرَّضٌ للعذاب. قال رسولُ الله ﷺ: «آيةُ المنافقِ ثلاث: إذا حدَّثَ كذب، وإذا وعدَ أخلف، وإذا اؤتُمِنَ خان» رواه البخاري ومسلم."}, {"id": 23, "q": "مَن هو خاتمُ الأنبياءِ والمرسلين؟", "a": "هو محمدٌ ﷺ. قال تعالى: ﴿مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ﴾ [الأحزاب: ٤٠]. وقال رسولُ الله ﷺ: «وأنا خاتمُ النبيينَ لا نبيَّ بعدي» رواه أبو داود والترمذي وغيرهما."}, {"id": 24, "q": "ما هي المعجزة؟", "a": "هي كلُّ ما أعطاهُ اللهُ لأنبيائِهِ من خوارقِ العادات؛ للدلالةِ على صدقِهم، مثل:\n• شقِّ القمرِ للنبيِّ ﷺ. قال تعالى: ﴿اقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ ۝ وَإِن يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُّسْتَمِرٌّ﴾ [القمر: ١–٢].\n• وشقِّ البحرِ لموسى عليه السلام، وإغراقِ فرعونَ وجنودِه. قال تعالى: ﴿وَإِذْ فَرَقْنَا بِكُمُ الْبَحْرَ فَأَنجَيْنَاكُمْ وَأَغْرَقْنَا آلَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ﴾ [البقرة: ٥٠]."}], "dyk": ["القرآنُ الكريمُ لم يتغيَّرْ حرفٌ واحدٌ منذُ أكثرَ من ١٤٠٠ سنة، لأن اللهَ تكفَّلَ بحفظِه.", "أخبرَ القرآنُ عن «البحرَين» أحدُهما عذبٌ والآخرُ مِلحٌ لا يختلطان، وقد وجدَ العلماءُ حاجزاً بين مياهِ البحارِ يمنعُ اختلاطَها."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ، خَلِيلُ الرَّحْمَنِ!"}, {"s": "anos", "t": "وَالْيَوْمَ: الْقُرْآنُ وَالسُّنَّةُ وَالْمُعْجِزَاتُ!"}, {"s": "fasih", "t": "مَا تَعْرِيفُ الْقُرْآنِ؟"}, {"s": "anos", "t": "هُوَ كَلَامُ اللَّهِ تَعَالَى، لَيْسَ بِمَخْلُوقٍ. وَفِي سُورَةِ التَّوْبَةِ: حَتَّى يَسْمَعَ كَلَامَ اللَّهِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الْقُرْآنُ لَمْ يَتَغَيَّرْ مِنْهُ حَرْفٌ مُنْذُ أَكْثَرَ مِنْ أَلْفٍ وَأَرْبَعِمِائَةِ سَنَةٍ، لِأَنَّ اللَّهَ تَكَفَّلَ بِحِفْظِهِ! وَمَا هِيَ السُّنَّةُ؟"}, {"s": "anos", "t": "هِيَ كُلُّ قَوْلٍ أَوْ فِعْلٍ أَوْ تَقْرِيرٍ أَوْ صِفَةٍ خَلْقِيَّةٍ أَوْ خُلُقِيَّةٍ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "fasih", "t": "وَمَا الْبِدْعَةُ؟ وَهَلْ نَقْبَلُهَا؟"}, {"s": "anos", "t": "كُلُّ مَا أَحْدَثَهُ النَّاسُ فِي الدِّينِ، وَلَمْ يَكُنْ عَلَى عَهْدِ النَّبِيِّ وَأَصْحَابِهِ. نَرُدُّهَا، فَـ«كُلُّ بِدْعَةٍ ضَلَالَةٌ». وَمِثَالُهَا: غَسْلَةٌ رَابِعَةٌ فِي الْوُضُوءِ، وَالِاحْتِفَالُ بِالْمَوْلِدِ النَّبَوِيِّ. وَفِي صَحِيحِ مُسْلِمٍ: «مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ»."}, {"s": "fasih", "t": "مَا عَقِيدَةُ الْوَلَاءِ وَالْبَرَاءِ؟"}, {"s": "anos", "t": "الْوَلَاءُ: مَحَبَّةُ الْمُؤْمِنِينَ وَنُصْرَتُهُمْ، فَالْمُؤْمِنُونَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ. وَالْبَرَاءُ: بُغْضُ الْكَافِرِينَ وَمُعَادَاتُهُمْ، كَمَا تَبَرَّأَ إِبْرَاهِيمُ وَالَّذِينَ مَعَهُ مِنْ قَوْمِهِمْ وَأَصْنَامِهِمْ."}, {"s": "fasih", "t": "هَلْ يَقْبَلُ اللَّهُ غَيْرَ الْإِسْلَامِ دِينًا؟"}, {"s": "anos", "t": "لَا. قَالَ تَعَالَى: وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ."}, {"s": "fasih", "t": "الْكُفْرُ يَكُونُ بِالْقَوْلِ وَالْعَمَلِ وَالِاعْتِقَادِ. مَثِّلْ لِذَلِكَ!"}, {"s": "anos", "t": "الْقَوْلُ: سَبُّ اللَّهِ أَوْ رَسُولِهِ. وَالْعَمَلُ: إِهَانَةُ الْمُصْحَفِ أَوِ السُّجُودُ لِغَيْرِ اللَّهِ. وَالِاعْتِقَادُ: أَنَّ غَيْرَ اللَّهِ يَسْتَحِقُّ الْعِبَادَةَ، أَوْ أَنَّ مَعَهُ خَالِقًا."}, {"s": "fasih", "t": "وَمَا النِّفَاقُ وَأَنْوَاعُهُ؟"}, {"s": "anos", "t": "النِّفَاقُ الْأَكْبَرُ: إِبْطَانُ الْكُفْرِ وَإِظْهَارُ الْإِيمَانِ، وَيُخْرِجُ مِنَ الْإِسْلَامِ. وَالْأَصْغَرُ ذَنْبٌ لَا يُخْرِجُ مِنْهُ: «آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ»، مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "مَنْ خَاتَمُ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ؟"}, {"s": "anos", "t": "مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَا نَبِيَّ بَعْدَهُ، كَمَا فِي سُورَةِ الْأَحْزَابِ."}, {"s": "fasih", "t": "وَمَا الْمُعْجِزَةُ؟"}, {"s": "anos", "t": "كُلُّ مَا أَعْطَاهُ اللَّهُ لِأَنْبِيَائِهِ مِنْ خَوَارِقِ الْعَادَاتِ لِيَدُلَّ عَلَى صِدْقِهِمْ، كَشَقِّ الْبَحْرِ لِمُوسَى، وَشَقِّ الْقَمَرِ لِنَبِيِّنَا. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ الْقَمَرِ."}, {"s": "quran", "ref": "54:1", "t": "ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ"}, {"s": "fasih", "t": "انْشَقَّ الْقَمَرُ! وَأَعْظَمُ مُعْجِزَةٍ بَقِيَتْ لَنَا هِيَ الْقُرْآنُ الْكَرِيمُ."}, {"s": "anos", "t": "الْآنَ لُعْبَةُ «قَوْلٌ أَمْ فِعْلٌ أَمْ تَقْرِيرٌ؟»: اجْرُوا إِلَى الزَّاوِيَةِ الصَّحِيحَةِ مَعَ كُلِّ مِثَالٍ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَالْعَبُوهَا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: لعبة: قول أم فعل أم تقرير؟"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! وَعَدْتُ صَدِيقِي أَنْ أُعِيدَ كِتَابَهُ الْيَوْمَ، لَكِنِّي أُرِيدُ إِكْمَالَهُ. أ: أُخَبِّئُهُ وَأَقُولُ نَسِيتُهُ. ب: أُعِيدُهُ فِي الْمَوْعِدِ، وَأَسْتَأْذِنُهُ بِصِدْقٍ. ج: لَا أَرُدُّ عَلَيْهِ حَتَّى يَنْسَى."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الوعد"}, {"s": "anos", "t": "«أ» كَذِبٌ، وَ«ج» إِخْلَافٌ لِلْوَعْدِ، وَهُمَا مِنَ النِّفَاقِ الْأَصْغَرِ. وَالصَّحِيحُ «ب»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: غَسْلُ الْوُضُوءِ أَرْبَعًا: سُنَّةٌ أَمْ بِدْعَةٌ؟ فَكِّرُوا..."}, {"s": "anos", "t": "بِدْعَةٌ لَا نَقْبَلُهَا! وَشَقُّ الْبَحْرِ كَانَ مُعْجِزَةً لِمَنْ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "لِمُوسَى عَلَيْهِ السَّلَامُ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: كَلَّمَنِي اللَّهُ تَكْلِيمًا، وَعَصَايَ تَنْقَلِبُ ثُعْبَانًا بِإِذْنِ اللَّهِ."}, {"s": "anos", "t": "سُلَيْمَانُ، أَمْ عِيسَى، أَمْ مُوسَى عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «دَفْتَرُ الْوُعُودِ الصَّادِقَةِ»: نَجْمَةٌ لِكُلِّ صِدْقٍ وَوَفَاءٍ وَأَمَانَةٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ الْقُرْآنِ وَالسُّنَّةِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 4, "title": "أحبّ الصحابة وآل البيت، وأسماء الله الحسنى", "season": 1, "goals": ["aqeeda"], "hook": "أهلًا يا أصدقاء! فصيح يقول: «أحبّ أصدقائي كثيرًا!». وأنوس يسأل: «يا فصيح، هل تعرف مَن هم أفضل أصدقاء عرفتهم الدنيا؟». إنهم <b>أصحاب النبيّ ﷺ</b>! تعالوا نتعرّف عليهم، وعلى أسماء ربّنا الحسنى.", "sections": [{"h": "الصحابة: خير الناس بعد الأنبياء", "p": ["فصيح يسأل: «مَن هو الصحابيّ؟». الصحابيّ: <b>مَن لقي النبيّ ﷺ مؤمنًا به، ومات على الإسلام</b>.", "و<b>يجب علينا أن نحبّهم ونقتدي بهم</b>، فهم خير الناس وأفضلهم بعد الأنبياء. صدّقوا النبيّ ﷺ، ونصروه، وحفظوا لنا القرآن والسنّة. وقد رضي الله عنهم ورضوا عنه، كما في سورة التوبة.", "وأفضلهم <b>الخلفاء الأربعة</b>: أبو بكر، ثم عمر، ثم عثمان، ثم عليّ رضي الله عنهم. فإذا سمعت اسم أحدهم فقل: «رضي الله عنه»."], "board": ["أبو بكر", "عمر", "عثمان", "عليّ"]}, {"h": "أمّهات المؤمنين وآل البيت", "p": ["<b>أمّهات المؤمنين</b>: هنّ زوجات النبيّ ﷺ، مثل خديجة وعائشة رضي الله عنهما. سمّاهنّ الله أمّهات للمؤمنين في سورة الأحزاب، فنحبّهنّ ونحترمهنّ كما نحترم أمّهاتنا.", "و<b>آل بيت النبيّ ﷺ</b>: أزواجه وذرّيته، وبنو هاشم، وبنو المطّلب من المؤمنين. وحقّهم علينا: <b>أن نحبّهم ونتولّاهم، ونبغض من يبغضهم، ولا نغالي فيهم</b>، أي لا نرفعهم فوق منزلتهم. قال ﷺ: «أذكّركم الله في أهل بيتي» رواه مسلم."], "board": ["أمّهات المؤمنين: زوجات النبيّ ﷺ", "نحبّ آل البيت ولا نغالي"]}, {"h": "ولاة الأمر، والجنّة والنار", "p": ["<b>وليّ الأمر</b> هو مَن يتولّى أمور المسلمين. وواجبنا نحوه كما في الكتاب: <b>احترامه، والسمع والطاعة له في غير معصية، والدعاء له، والنصح له سرًّا، وعدم الخروج عليه</b>، إلا أن نرى كفرًا بواحًا أي واضحًا. وفي البيت والمدرسة نتعلّم هذا أيضًا: نسمع لمن يرعانا في الخير.", "و<b>دار المؤمنين هي الجنّة</b>، فيها أنهار تجري، وفيها كل ما تحبّه النفس. و<b>دار الكافرين هي النار</b>، أعاذنا الله منها، وقودها الناس والحجارة."], "board": ["الجنّة دار المؤمنين", "النار دار الكافرين"]}, {"h": "الخوف والرجاء: جناحا الطائر", "p": ["فصيح يفرد جناحيه ويقول: «أنا لا أطير إلا بجناحين!». وكذلك المؤمن يسير إلى الله بجناحين:", "<b>الخوف</b>: هو الخشية من الله ومن عقابه، فيمنعني من المعصية. و<b>الرجاء</b>: هو الطمع في ثواب الله ومغفرته ورحمته، فيجعلني أعمل الخير وأتوب إذا أخطأت.", "والدليل: أنّ الصالحين «يرجون رحمته ويخافون عذابه» كما في سورة الإسراء. وقال الله: «نبّئ عبادي أنّي أنا الغفور الرحيم، وأنّ عذابي هو العذاب الأليم»."], "board": ["الخوف: خشية الله وعقابه", "الرجاء: الطمع في رحمته"]}, {"h": "من أسماء الله الحسنى", "p": ["لله أسماء حسنى وصفات عُلى. ومن أسمائه كما في الكتاب: <b>الله، والربّ، والرحمن، والسميع، والبصير، والعليم، والرزّاق، والحيّ، والعظيم، والحكيم</b>.", "أنوس يقول: كلّما أكلت طعامي تذكّرت أنّ الله هو <b>الرزّاق</b>، وكلّما دعوت بصوت خافت تذكّرت أنّه <b>السميع</b>، وكلّما فعلت شيئًا وحدي تذكّرت أنّه <b>البصير</b> يراني. وفي الحلقة القادمة نشرح هذه الأسماء أكثر."], "board": ["الرحمن", "السميع", "البصير", "العليم", "الرزّاق"]}], "summary": ["الصحابيّ مَن لقي النبيّ ﷺ مؤمنًا به ومات على الإسلام، وأفضلهم الخلفاء الأربعة، ونحبّهم ونقتدي بهم.", "أمّهات المؤمنين زوجات النبيّ ﷺ، ونحبّ آل البيت ولا نغالي فيهم، ونسمع ونطيع لولاة الأمر في غير معصية.", "الجنّة دار المؤمنين والنار دار الكافرين، والمؤمن يجمع الخوف والرجاء، ولله الأسماء الحسنى."], "islam": {"intro": "قال الله تعالى يمدح الصحابة من المهاجرين والأنصار ومن اتّبعهم:", "text": "فمَن أحبّ الصحابة واتّبعهم بإحسان، كان له نصيب من رضا الله وجنّته.", "ayah": {"text": "وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍۢ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", "src": "سُورَةُ التَّوۡبَةِ: ١٠٠"}, "hadith": {"text": "أذكّركم الله في أهل بيتي", "source": "رواه مسلم"}}, "home": {"title": "بطاقات الأسماء الحسنى", "goal": "أن يحفظ الطفل عشرة من أسماء الله الحسنى، ويتذكّرها في يومه.", "materials": ["عشر بطاقات صغيرة", "ألوان"], "steps": ["اكتب على كل بطاقة اسمًا: الله، الربّ، الرحمن، السميع، البصير، العليم، الرزّاق، الحيّ، العظيم، الحكيم.", "اختر كل يوم بطاقة، وقل لأسرتك موقفًا تذكّرت فيه هذا الاسم.", "احكِ لأسرتك قصّة أبي بكر رضي الله عنه في الغار.", "قل «رضي الله عنه» كلّما ذكرت صحابيًّا."], "parent": "اربطوا الأسماء بمواقف يومية: «الرزّاق» عند الطعام، و«السميع» عند الدعاء. وتجنّبوا الحديث السيّئ عن الصحابة أو آل البيت أمام الأطفال."}, "online": {"title": "أصدقاء النبيّ ﷺ", "intro": "رتّب الخلفاء، وصنّف الخوف والرجاء مع فصيح!", "steps": [{"type": "order", "title": "رتّب الخلفاء الأربعة", "prompt": "رتّب الخلفاء من الأوّل إلى الرابع.", "items": ["أبو بكر الصدّيق", "عمر بن الخطّاب", "عثمان بن عفّان", "عليّ بن أبي طالب"]}, {"type": "sort", "title": "خوف أم رجاء؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["الخوف من الله", "الرجاء في رحمة الله"], "items": [{"t": "أترك الكذب خشية عقاب الله", "icon": "🛑", "bin": 0, "why": "الخوف خشية الله وعقابه، فيمنعنا من المعصية."}, {"t": "لا أظلم أخي لأنّ الله يراني", "icon": "👀", "bin": 0, "why": "الخوف من الله يمنعنا من الظلم."}, {"t": "أبتعد عن المعصية ولو لم يرني أحد", "icon": "🚫", "bin": 0, "why": "خشية الله في السرّ والعلن."}, {"t": "أتوب وأنا أطمع في مغفرة الله", "icon": "🌈", "bin": 1, "why": "الرجاء طمع في مغفرة الله."}, {"t": "أصلّي وأرجو الجنّة", "icon": "🌳", "bin": 1, "why": "الرجاء طمع في ثواب الله."}, {"t": "أدعو الله وأنا واثق برحمته", "icon": "🤲", "bin": 1, "why": "الرجاء طمع في رحمة الله."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "مَن آل بيت النبيّ ﷺ؟", "o": ["كل سكّان المدينة", "أصدقاء أنوس", "أزواجه وذرّيته وبنو هاشم وبنو المطّلب المؤمنون"], "a": 2, "why": "هذا ما ذكره الكتاب."}, {"q": "أيّ هذه من أسماء الله الحسنى؟", "o": ["الرزّاق", "القويّ جدًّا", "الكبير في العمر"], "a": 0, "why": "الرزّاق من أسماء الله، فهو الذي يرزق جميع المخلوقات."}, {"q": "نطيع وليّ الأمر…", "o": ["في كل شيء ولو كان معصية", "في غير معصية", "لا نطيعه أبدًا"], "a": 1, "why": "السمع والطاعة لولاة الأمر في غير معصية."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز داخل كتاب السيرة، فيها صحابيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا أوّل من آمن من الرجال.", "صاحبت النبيّ ﷺ في الغار وفي الهجرة.", "كنت أوّل الخلفاء الراشدين، ولُقّبت بالصدّيق."], "options": ["عمر بن الخطّاب رضي الله عنه", "أبو بكر الصدّيق رضي الله عنه", "عليّ بن أبي طالب رضي الله عنه"], "deep": "كان هذا الصحابيّ مع النبيّ ﷺ في الغار والمشركون يبحثون عنهما. كيف يساعدنا التوكّل على الله في أوقات الخوف؟", "reveal": "أنا أبو بكر الصدّيق رضي الله عنه! صدّقت النبيّ ﷺ في كل ما أخبر به، فلُقّبت بالصدّيق. وفي الحلقة القادمة نتعلّم كيف يزيد الإيمان، وما الإحسان، وما التوكّل على الله."}, "quiz": [{"q": "مَن هو الصحابيّ؟", "o": ["كل من عاش في مكّة", "مَن لقي النبيّ ﷺ مؤمنًا به ومات على الإسلام", "كل من قرأ عن النبيّ ﷺ"], "a": 1, "why": "هذا تعريف الصحابيّ في الكتاب."}], "qa": [{"id": 25, "q": "مَن هم الصحابة؟ وهل يجبُ علينا حبُّهم؟", "a": "الصحابي: هو من لقيَ النبيَّ ﷺ مؤمنًا به وماتَ على الإسلام. يجبُ أن نحبَّهم ونقتديَ بهم، وهم خيرُ الناسِ وأفضلُهم بعدَ الأنبياء.\nوأفضلُهم: الخلفاءُ الأربعة: أبو بكرٍ، وعمرُ، وعثمانُ، وعليٌّ رضي الله عنهم.\nقال تعالى: ﴿وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ...﴾ [التوبة: ١٠٠]."}, {"id": 26, "q": "مَن هنَّ أمهاتُ المؤمنين؟", "a": "هنَّ زوجاتُ النبيِّ ﷺ.\nقال تعالى: ﴿النَّبِيُّ أَوْلَىٰ بِالْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ﴾ [الأحزاب: ٦]."}, {"id": 27, "q": "ما هو حقُّ آلِ بيتِ النبيِّ ﷺ علينا؟", "a": "نحبُّهم ونتولاهم ونبغضُ من يبغضُهم ولا نغالي فيهم، وهم أزواجُهُ وذريتُه، وبنو هاشم، وبنو المطلبِ من المؤمنين.\nقال تعالى: ﴿إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا﴾ [الأحزاب: ٣٣]. وفي الحديثِ عن النبيِّ ﷺ قال: «أذكِّرُكمُ اللهَ في أهلِ بيتي» رواه مسلم."}, {"id": 28, "q": "ما واجبُنا تجاهَ وُلاةِ أمرِ المسلمين؟", "a": "واجبُنا: احترامُهم والسمعُ والطاعةُ لهم في غيرِ معصية، والدعاءُ والنصحُ لهم سرًّا، وعدمُ الخروجِ عليهم، إلا أن نرى كفرًا بواحًا.\nقال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنكُمْ...﴾ [النساء: ٥٩]."}, {"id": 29, "q": "ما هي دارُ المؤمنين؟", "a": "الجنة. قال تعالى: ﴿إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ﴾ [محمد: ١٢]."}, {"id": 30, "q": "ما هي دارُ الكافرين؟", "a": "النار. قال تعالى: ﴿فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجَارَةُ أُعِدَّتْ لِلْكَافِرِينَ﴾ [البقرة: ٢٤]."}, {"id": 31, "q": "ما هو الخوف؟ وما هو الرجاء؟ وما الدليل؟", "a": "• الخوف: هو الخشيةُ من الله ومن عقابِه.\n• الرجاء: هو الطمعُ في ثوابِ الله ومغفرتِهِ ورحمتِه.\nالدليل: قوله تعالى: ﴿أُولَٰئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا﴾ [الإسراء: ٥٧]. وقال تعالى: ﴿نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ ۝ وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾ [الحجر: ٤٩–٥٠]."}, {"id": 32, "q": "اذكرْ بعضَ أسماءِ الله تعالى وصفاتِه.", "a": "اللهُ، والربُّ، والرحمنُ، والسميعُ، والبصيرُ، والعليمُ، والرزاقُ، والحيُّ، والعظيمُ، والحكيمُ... إلى غيرِ ذلك من الأسماءِ الحسنى والصفاتِ العُلى."}], "dyk": ["أخبرَ القرآنُ أن أطرافَ الأصابعِ تُميِّزُ كلَّ إنسان، واكتشفَ العلمُ أن بصمةَ كلِّ إصبعٍ فريدةٌ لا تتكرَّر."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ مُوسَى عَلَيْهِ السَّلَامُ، كَلِيمُ اللَّهِ!"}, {"s": "anos", "t": "الْيَوْمَ نَتَعَرَّفُ عَلَى أَفْضَلِ أَصْدِقَاءَ عَرَفَتْهُمُ الدُّنْيَا!"}, {"s": "fasih", "t": "مَنْ هُمُ الصَّحَابَةُ؟ وَهَلْ يَجِبُ عَلَيْنَا حُبُّهُمْ؟"}, {"s": "anos", "t": "الصَّحَابِيُّ: مَنْ لَقِيَ النَّبِيَّ مُؤْمِنًا بِهِ وَمَاتَ عَلَى الْإِسْلَامِ. يَجِبُ أَنْ نُحِبَّهُمْ وَنَقْتَدِيَ بِهِمْ، فَهُمْ خَيْرُ النَّاسِ بَعْدَ الْأَنْبِيَاءِ. وَأَفْضَلُهُمْ: أَبُو بَكْرٍ، وَعُمَرُ، وَعُثْمَانُ، وَعَلِيٌّ رَضِيَ اللَّهُ عَنْهُمْ."}, {"s": "fasih", "t": "وَالدَّلِيلُ يَتْلُوهُ الشَّيْخُ الْحُصَرِيُّ مِنْ سُورَةِ التَّوْبَةِ!"}, {"s": "quran", "ref": "9:100", "t": "وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍۢ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ"}, {"s": "anos", "t": "رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ! فَمَنْ أَحَبَّهُمْ وَاتَّبَعَهُمْ بِإِحْسَانٍ كَانَ لَهُ نَصِيبٌ مِنْ رِضَا اللَّهِ وَجَنَّتِهِ."}, {"s": "fasih", "t": "مَنْ هُنَّ أُمَّهَاتُ الْمُؤْمِنِينَ؟"}, {"s": "anos", "t": "هُنَّ زَوْجَاتُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ تَعَالَى: وَأَزْوَاجُهُ أُمَّهَاتُهُمْ."}, {"s": "fasih", "t": "وَمَا حَقُّ آلِ بَيْتِ النَّبِيِّ عَلَيْنَا؟"}, {"s": "anos", "t": "نُحِبُّهُمْ وَنَتَوَلَّاهُمْ، وَنُبْغِضُ مَنْ يُبْغِضُهُمْ، وَلَا نُغَالِي فِيهِمْ. وَهُمْ أَزْوَاجُهُ وَذُرِّيَّتُهُ، وَبَنُو هَاشِمٍ، وَبَنُو الْمُطَّلِبِ مِنَ الْمُؤْمِنِينَ. وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أُذَكِّرُكُمُ اللَّهَ فِي أَهْلِ بَيْتِي»، رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "مَا وَاجِبُنَا تُجَاهَ وُلَاةِ أَمْرِ الْمُسْلِمِينَ؟"}, {"s": "anos", "t": "احْتِرَامُهُمْ، وَالسَّمْعُ وَالطَّاعَةُ لَهُمْ فِي غَيْرِ مَعْصِيَةٍ، وَالدُّعَاءُ لَهُمْ، وَالنُّصْحُ سِرًّا، وَعَدَمُ الْخُرُوجِ عَلَيْهِمْ إِلَّا أَنْ نَرَى كُفْرًا بَوَاحًا. قَالَ تَعَالَى: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ."}, {"s": "fasih", "t": "مَا دَارُ الْمُؤْمِنِينَ؟ وَمَا دَارُ الْكَافِرِينَ؟"}, {"s": "anos", "t": "دَارُ الْمُؤْمِنِينَ الْجَنَّةُ، تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ. وَدَارُ الْكَافِرِينَ النَّارُ، وَقُودُهَا النَّاسُ وَالْحِجَارَةُ، أَعَاذَنَا اللَّهُ مِنْهَا."}, {"s": "fasih", "t": "أَنَا لَا أَطِيرُ إِلَّا بِجَنَاحَيْنِ! فَمَا الْخَوْفُ؟ وَمَا الرَّجَاءُ؟"}, {"s": "anos", "t": "وَالْمُؤْمِنُ كَذَلِكَ: الْخَوْفُ: الْخَشْيَةُ مِنَ اللَّهِ وَمِنْ عِقَابِهِ. وَالرَّجَاءُ: الطَّمَعُ فِي ثَوَابِهِ وَمَغْفِرَتِهِ وَرَحْمَتِهِ. وَالدَّلِيلُ فِي سُورَةِ الْإِسْرَاءِ: وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ."}, {"s": "fasih", "t": "اذْكُرْ بَعْضَ أَسْمَاءِ اللَّهِ وَصِفَاتِهِ."}, {"s": "anos", "t": "اللَّهُ، وَالرَّبُّ، وَالرَّحْمَنُ، وَالسَّمِيعُ، وَالْبَصِيرُ، وَالْعَلِيمُ، وَالرَّزَّاقُ، وَالْحَيُّ، وَالْعَظِيمُ، وَالْحَكِيمُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ أَخْبَرَ الْقُرْآنُ أَنَّ أَطْرَافَ الْأَصَابِعِ تُمَيِّزُ كُلَّ إِنْسَانٍ، وَاكْتَشَفَ الْعِلْمُ أَنَّ بَصْمَةَ كُلِّ إِصْبَعٍ فَرِيدَةٌ لَا تَتَكَرَّرُ!"}, {"s": "anos", "t": "الْآنَ «قِطَارُ الْخُلَفَاءِ الْأَرْبَعَةِ»: قِفُوا بِالتَّرْتِيبِ، وَقُولُوا اسْمَ كُلِّ خَلِيفَةٍ ثُمَّ: رَضِيَ اللَّهُ عَنْهُ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَالْعَبُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: قطار الخلفاء الأربعة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! كَذَبْتُ عَلَى أُمِّي وَأَنَا حَزِينٌ. أ: أَقُولُ لَنْ يَغْفِرَ اللَّهُ لِي أَبَدًا، فَأَيْأَسُ. ب: أَقُولُ الْكَذِبُ شَيْءٌ صَغِيرٌ. ج: أَخَافُ اللَّهَ فَأَتُوبُ، وَأَرْجُو رَحْمَتَهُ فَأَعْتَذِرُ لِأُمِّي."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الخوف والرجاء"}, {"s": "anos", "t": "«أ» يَأْسٌ، وَ«ب» أَمْنٌ بِلَا خَوْفٍ. وَالصَّحِيحُ «ج»: نَخَافُ فَنَتُوبُ، وَنَرْجُو فَنَعْمَلُ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَنْ أَوَّلُ الْخُلَفَاءِ الْأَرْبَعَةِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ! وَالطَّمَعُ فِي ثَوَابِ اللَّهِ وَرَحْمَتِهِ اسْمُهُ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "الرَّجَاءُ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا أَوَّلُ مَنْ آمَنَ مِنَ الرِّجَالِ، صَاحَبْتُ النَّبِيَّ فِي الْغَارِ وَفِي الْهِجْرَةِ، وَلُقِّبْتُ بِالصِّدِّيقِ."}, {"s": "anos", "t": "عُمَرُ، أَمْ أَبُو بَكْرٍ، أَمْ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: اصْنَعُوا «بِطَاقَاتِ الْأَسْمَاءِ الْحُسْنَى»."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «أَصْدِقَاءُ النَّبِيِّ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 5, "title": "الإيمان يزيد، والإحسان، والتوكّل", "season": 1, "goals": ["aqeeda"], "hook": "أهلًا يا أصدقاء! فصيح يسقي نبتة صغيرة ويقول: «اكبري… اكبري!». أنوس يضحك ويقول: «يا فصيح، الإيمان في قلبك مثل هذه النبتة؛ يكبر ويزيد إذا سقيته بالطاعات!». واليوم عندنا مفاجأة: <b>مسابقة أنوس</b> الكبرى!", "sections": [{"h": "معاني أسماء الله الحسنى", "p": ["تعرّفنا في الحلقة الماضية على بعض أسماء الله، واليوم نفهم معانيها. <b>الله</b>: الإله المعبود بحقّ وحده لا شريك له. <b>الربّ</b>: الخالق المالك الرازق المدبّر وحده.", "<b>السميع</b>: الذي يسمع كل الأصوات، حتى همسك في دعائك. <b>البصير</b>: الذي يرى كل شيء صغيرًا كان أو كبيرًا، حتى النملة السوداء في الليل. <b>العليم</b>: الذي يعلم كل شيء في الماضي والحاضر والمستقبل.", "<b>الرحمن</b>: الذي وسعت رحمته كل مخلوق. <b>الرزّاق</b>: الذي يرزق كل المخلوقات من الإنس والجنّ والدوابّ. <b>الحيّ</b>: الذي لا يموت، وكل الخلق يموتون. <b>العظيم</b>: الذي له الكمال والعظمة كلّها. <b>الحكيم</b>: الذي أتقن خلقه، وله الحكمة في خلقه وأمره. والحكمة: وضع الأشياء في مواضعها."], "board": ["السميع يسمعني", "البصير يراني", "الرزّاق يرزقني"]}, {"h": "العلماء وأولياء الله", "p": ["فصيح يسأل: «ما واجبنا نحو العلماء؟». <b>نحبّهم، ونرجع إليهم في مسائل الدين، ولا نذكرهم إلا بالجميل</b>. ومن ذكرهم بسوء فهو على غير السبيل الصحيح.", "و<b>أولياء الله</b>: هم <b>المؤمنون المتّقون المتّبعون لسنّة النبيّ ﷺ</b>. فكل مؤمن تقيّ يتّبع السنّة هو وليّ لله، وقد وعدهم الله أنه لا خوف عليهم ولا هم يحزنون. فأنت أيضًا تستطيع أن تكون من أولياء الله بالإيمان والتقوى!"], "board": ["نحبّ العلماء", "أولياء الله: المؤمنون المتّقون"]}, {"h": "الإيمان قول وعمل، يزيد وينقص", "p": ["<b>الإيمان قول وعمل واعتقاد</b>: قول باللسان مثل «لا إله إلا الله»، واعتقاد وعمل بالقلب مثل حبّ الله، وعمل بالجوارح مثل الصلاة وإزالة الأذى عن الطريق.", "قال ﷺ: «الإيمان بضع وسبعون أو بضع وستّون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان» رواه مسلم. فإذا رفعت قشرة موز عن الطريق، فهذا من الإيمان!", "و<b>الإيمان يزيد بالطاعة، وينقص بالمعصية</b>. كلّما صلّيت وقرأت القرآن وبررت والديك زاد إيمانك، وإذا عصيت نقص، فتب إلى الله ليعود ويزيد."], "board": ["قول باللسان", "اعتقاد بالقلب", "عمل بالجوارح", "يزيد بالطاعة"]}, {"h": "الإحسان، ومتى يقبل الله العمل؟", "p": ["<b>الإحسان</b>: أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك. فإذا صلّيت، صلِّ بخشوع كأنك ترى الله، واعلم أنه يراك دائمًا.", "فصيح يسأل: «متى يقبل الله عملي؟». يُقبل العمل <b>بشرطين</b>: الأوّل أن يكون <b>خالصًا لوجه الله</b>، لا لكي يمدحك الناس. والثاني أن يكون <b>على سنّة النبيّ ﷺ</b>، كما علّمنا بلا زيادة."], "board": ["الإحسان: كأنك تراه", "الشرط ١: الإخلاص", "الشرط ٢: متابعة السنّة"]}, {"h": "التوكّل، والأمر بالمعروف، وأهل السنّة", "p": ["<b>التوكّل على الله</b>: هو الاعتماد على الله في جلب المنافع ودفع المضارّ، <b>مع الأخذ بالأسباب</b>. فإذا كان عندك اختبار، تذاكر جيّدًا، ثم تدعو الله وتعتمد عليه. قال تعالى: ومن يتوكّل على الله فهو حسبه، أي: كافيه.", "و<b>المعروف</b>: كل طاعة لله، و<b>المنكر</b>: كل معصية لله. ونحن نأمر بالمعروف وننهى عن المنكر بلطف، فبذلك كانت أمّة محمد ﷺ خير أمّة أُخرجت للناس.", "و<b>أهل السنّة والجماعة</b>: هم من كانوا على مثل ما كان عليه النبيّ ﷺ وأصحابه في القول والعمل والاعتقاد. سُمّوا أهل السنّة لاتّباعهم السنّة وتركهم البدع، وسُمّوا الجماعة لأنهم اجتمعوا على الحقّ ولم يتفرّقوا فيه."], "board": ["توكّل + أسباب", "أهل السنّة: ما عليه النبيّ ﷺ وأصحابه"]}], "summary": ["من أسماء الله: السميع الذي يسمع كل شيء، والبصير الذي يرى كل شيء، والعليم الذي يعلم كل شيء، والحكيم الذي أتقن خلقه.", "الإيمان قول وعمل واعتقاد، يزيد بالطاعة وينقص بالمعصية، والإحسان أن تعبد الله كأنك تراه.", "يُقبل العمل إذا كان خالصًا لله وعلى سنّة النبيّ ﷺ، والتوكّل اعتماد على الله مع الأخذ بالأسباب."], "islam": {"intro": "قال الله تعالى يصف المؤمنين الذين يزيد إيمانهم ويتوكّلون عليه:", "text": "فكلّما سمعنا القرآن وتدبّرناه زاد إيماننا، واعتمدنا على ربّنا في كل أمورنا.", "ayah": {"text": "إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًۭا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ", "src": "سُورَةُ الأَنفَالِ: ٢"}, "hadith": {"text": "الإيمان بضع وسبعون أو بضع وستّون شعبة، فأفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان", "source": "رواه مسلم"}}, "home": {"title": "مقياس الإيمان في بيتنا", "goal": "أن يفهم الطفل أنّ الإيمان يزيد بالطاعة، وأنّ التوكّل يكون مع العمل.", "materials": ["ورقة عليها ميزان حرارة كبير", "ألوان"], "steps": ["ارسم ميزانًا كبيرًا، واكتب فوقه: «إيماني يزيد بالطاعة».", "كلّما فعلت طاعة (صلاة، قراءة، برّ، إماطة أذى) لوّن درجة في الميزان.", "قبل أيّ عمل مهمّ هذا الأسبوع، قل لأسرتك: «سأعمل جهدي، وأتوكّل على الله».", "اسأل والديك: «ما الإحسان؟»، وصحّح لهم الجواب إن احتاجوا!"], "parent": "امدحوا كل طاعة صغيرة، وذكّروا الطفل بأنّ الله يرى عمله ولو لم يره أحد. وفرّقوا أمامه بين التوكّل والتواكل بأمثلة من حياتكم."}, "online": {"title": "مسابقة أنوس الإلكترونية", "intro": "صِل الأسماء بمعانيها، واتّخذ القرار الصحيح، وأجب عن أسئلة المسابقة!", "steps": [{"type": "match", "title": "صِل الاسم بمعناه", "prompt": "اختر اسم الله، ثم معناه الصحيح.", "pairs": [["السميع", "يسمع كل الأصوات"], ["البصير", "يرى كل شيء صغر أو كبر"], ["العليم", "يعلم الماضي والحاضر والمستقبل"], ["الرزّاق", "يرزق جميع المخلوقات"], ["الحيّ", "لا يموت أبدًا"]]}, {"type": "decision", "title": "مختبر القرار", "scenario": "قرّر فريقك في المدرسة أن يشارك في مسابقة لحفظ القرآن، والمسابقة بعد أسبوع.", "options": [{"t": "ندعو الله فقط ولا نحفظ", "result": "الدعاء عظيم، لكن ترك الأسباب ليس توكّلًا. يجب أن نحفظ ونراجع."}, {"t": "نحفظ ونراجع كل يوم، وندعو الله أن يوفّقنا", "result": "أحسنت! هذا هو التوكّل: اعتماد على الله مع الأخذ بالأسباب.", "best": true}, {"t": "نحفظ لكي يمدحنا الناس فقط", "result": "العمل يُقبل إذا كان خالصًا لله، فاجعل نيّتك لله وحده."}]}, {"type": "quiz", "title": "أسئلة المسابقة", "items": [{"q": "أدنى شعب الإيمان:", "o": ["إماطة الأذى عن الطريق", "الصيام", "الحجّ"], "a": 0, "why": "وأدناها إماطة الأذى عن الطريق."}, {"q": "شرطا قبول العمل:", "o": ["السرعة والقوّة", "الإخلاص ومتابعة السنّة", "كثرة الناس والمدح"], "a": 1, "why": "خالصًا لوجه الله، وعلى سنّة النبيّ ﷺ."}, {"q": "لماذا سُمّي أهل السنّة بالجماعة؟", "o": ["لأنهم كثيرون", "لأنهم يسكنون معًا", "لأنهم اجتمعوا على الحقّ ولم يتفرّقوا فيه"], "a": 2, "why": "هذا ما ذكره الكتاب."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز بين كتب العلماء، فيها صحابيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["كنت حبر الأمّة، أي عالمها الكبير.", "لقّبوني ترجمان القرآن؛ لأنني أشرح معانيه.", "دعا لي النبيّ ﷺ: «اللهمّ فقّهه في الدين وعلّمه التأويل»."], "options": ["زيد بن ثابت رضي الله عنه", "أبو هريرة رضي الله عنه", "عبد الله بن عبّاس رضي الله عنهما"], "deep": "صار هذا الصحابيّ عالمًا كبيرًا وهو شابّ. لماذا يجب علينا أن نحبّ العلماء ونرجع إليهم؟", "reveal": "أنا عبد الله بن عبّاس رضي الله عنهما، ابن عمّ النبيّ ﷺ! استجاب الله دعاء نبيّه لي فصرت من أعلم الناس بالقرآن. وفي الحلقة القادمة ننتقل إلى باب الفقه، فنتعلّم الطهارة وكيف نتوضّأ."}, "quiz": [{"q": "ما معنى اسم الله «البصير»؟", "o": ["الذي يرى كل شيء صغيرًا أو كبيرًا", "الذي ينام قليلًا", "الذي يعرف القراءة"], "a": 0, "why": "البصير: الذي يرى كل شيء، ويبصر كل شيء صغر أو كبر."}], "qa": [{"id": 33, "q": "اشرحْ هذه الأسماء.", "a": "• الله: ومعناهُ الإلهُ المعبودُ بحق، وحدَهُ لا شريكَ له.\n• الرب: أي الخالقُ المالكُ الرازقُ المدبِّرُ وحدَهُ سبحانه.\n• السميع: الذي وسِعَ سمعُهُ كلَّ شيء، ويسمعُ كلَّ الأصواتِ على اختلافِها وتنوعِها.\n• البصير: الذي يرى كلَّ شيء، ويبصرُ كلَّ شيءٍ صغرَ أو كبر.\n• العليم: فهو الذي أحاطَ علمُهُ بكلِّ شيءٍ بالماضي والحاضرِ والمستقبل.\n• الرحمن: الذي وسِعَتْ رحمتُهُ كلَّ مخلوقٍ وحي، فكلُّ العبادِ والمخلوقاتِ تحتَ رحمتِه.\n• الرزاق: الذي عليه رزقُ جميعِ المخلوقاتِ من الإنسِ والجنِّ وجميعِ الدواب.\n• الحي: الحيُّ الذي لا يموت، وكلُّ الخلقِ يموتون.\n• العظيم: الذي له الكمالُ كلُّهُ والعظمةُ كلُّها في أسمائِهِ وصفاتِهِ وأفعالِه.\n• الحكيم: الذي أحكمَ خلقَهُ وأتقنَهُ وأحسنَه، وله الحكمةُ في خلقِهِ وأمرِه.\n• والحكمة: وضعُ الأشياءِ مواضعَها، وتنزيلُها منازلَها."}, {"id": 34, "q": "ما واجبُنا تجاهَ علماءِ المسلمين؟", "a": "نحبُّهم، ونرجعُ إليهم في المسائلِ والنوازلِ الشرعية، ولا نذكرُهم إلا بالجميل، ومن ذكرَهم بغيرِ ذلك من السوء؛ فهو على غيرِ السبيل."}, {"id": 35, "q": "مَن هم أولياءُ الله تعالى؟", "a": "هم المؤمنونَ المتقونَ المتبعونَ لسنةِ النبيِّ ﷺ.\nقال تعالى: ﴿أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ﴾ [يونس: ٦٢–٦٣]."}, {"id": 36, "q": "هل الإيمانُ قولٌ وعمل؟", "a": "الإيمانُ قولٌ وعملٌ واعتقاد. فهو قولٌ باللسان، واعتقادٌ وعملٌ بالجَنان — أي: القلب — وعملٌ بالجوارحِ والأركان.\nفي الحديثِ عن أبي هريرة، عن النبيِّ ﷺ قال: «الإيمانُ بِضعٌ وسبعون — أو بِضعٌ وستون — شعبة، فأفضلُها قولُ: لا إله إلا الله، وأدناها إماطةُ الأذى عن الطريق، والحياءُ شعبةٌ من الإيمان» رواه مسلم."}, {"id": 37, "q": "هل الإيمانُ يزيدُ وينقص؟", "a": "الإيمانُ يزيدُ بالطاعةِ وينقصُ بالمعصية.\nقال تعالى: ﴿إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ﴾ [الأنفال: ٢]."}, {"id": 38, "q": "ما الإحسان؟", "a": "أن تعبدَ اللهَ كأنك تراه، فإن لم تكنْ تراه؛ فإنه يراك."}, {"id": 39, "q": "متى تكونُ الأعمالُ مقبولةً عند الله سبحانه؟", "a": "الأعمالُ تكونُ مقبولةً بشرطين:\n١. إذا كانت خالصةً لوجهِ الله تعالى.\n٢. وإذا كانت على سنةِ النبيِّ ﷺ."}, {"id": 40, "q": "ما هو التوكلُ على الله تعالى؟", "a": "هو الاعتمادُ على الله تعالى في جلبِ المنافعِ ودفعِ المضار، مع الأخذِ بالأسباب.\nقال تعالى: ﴿وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ﴾ [الطلاق: ٣]. ﴿حَسْبُهُ﴾: أي كافيه."}, {"id": 41, "q": "ما هو واجبُ الأمرِ بالمعروفِ والنهيِ عن المنكر؟", "a": "المعروف: هو الأمرُ بكلِّ طاعةٍ لله عزَّ وجلَّ، والمنكر: هو النهيُ عن كلِّ معصيةٍ لله عزَّ وجلَّ.\nقال تعالى: ﴿كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ﴾ [آل عمران: ١١٠]."}, {"id": 42, "q": "مَن هم أهلُ السنةِ والجماعة؟", "a": "هم من كان على مثلِ ما كان عليه النبيُّ ﷺ وأصحابُهُ في القولِ والعملِ والاعتقاد.\n• وسُمُّوا أهلَ السنة: لاتباعِهم سنةَ النبيِّ ﷺ، وتركِ الابتداع.\n• والجماعة: لأنهم اجتمعوا على الحقِّ ولم يتفرقوا فيه.\nقال ﷺ: «إنَّ بني إسرائيلَ تفرقتْ على ثنتينِ وسبعينَ ملة، وتفترقُ أمتي على ثلاثٍ وسبعينَ ملة، كلُّهم في النار، إلا ملةً واحدة» قالوا: ومن هي يا رسولَ الله؟ قال: «ما أنا عليه وأصحابي» رواه الترمذي."}], "dyk": ["ذكرَ اللهُ النحلةَ في سورةٍ باسمِها، ويخرجُ من بطونِها عسلٌ فيه شفاءٌ للناس، ولا يُنتِجُ العسلَ إلا النحلُ الإناث!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ!"}, {"s": "anos", "t": "وَالْيَوْمَ: إِيمَانٌ يَكْبُرُ كَالنَّبْتَةِ، وَمُسَابَقَةُ أَنُوس الْكُبْرَى!"}, {"s": "fasih", "t": "اشْرَحْ أَسْمَاءَ اللَّهِ هَذِهِ!"}, {"s": "anos", "t": "اللَّهُ: الْمَعْبُودُ بِحَقٍّ. الرَّبُّ: الْخَالِقُ الْمَالِكُ الرَّازِقُ الْمُدَبِّرُ. السَّمِيعُ: يَسْمَعُ كُلَّ الْأَصْوَاتِ. الْبَصِيرُ: يَرَى كُلَّ شَيْءٍ. الْعَلِيمُ: أَحَاطَ عِلْمُهُ بِالْمَاضِي وَالْحَاضِرِ وَالْمُسْتَقْبَلِ."}, {"s": "anos", "t": "الرَّحْمَنُ: وَسِعَتْ رَحْمَتُهُ كُلَّ مَخْلُوقٍ. الرَّزَّاقُ: يَرْزُقُ جَمِيعَ الْمَخْلُوقَاتِ. الْحَيُّ: لَا يَمُوتُ. الْعَظِيمُ: لَهُ الْكَمَالُ وَالْعَظَمَةُ كُلُّهَا. الْحَكِيمُ: أَتْقَنَ خَلْقَهُ."}, {"s": "fasih", "t": "مَا وَاجِبُنَا تُجَاهَ عُلَمَاءِ الْمُسْلِمِينَ؟"}, {"s": "anos", "t": "نُحِبُّهُمْ، وَنَرْجِعُ إِلَيْهِمْ فِي مَسَائِلِ الدِّينِ، وَلَا نَذْكُرُهُمْ إِلَّا بِالْجَمِيلِ."}, {"s": "fasih", "t": "مَنْ هُمْ أَوْلِيَاءُ اللَّهِ؟"}, {"s": "anos", "t": "الْمُؤْمِنُونَ الْمُتَّقُونَ الْمُتَّبِعُونَ لِلسُّنَّةِ، لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ، كَمَا فِي سُورَةِ يُونُسَ."}, {"s": "fasih", "t": "هَلِ الْإِيمَانُ قَوْلٌ وَعَمَلٌ؟"}, {"s": "anos", "t": "الْإِيمَانُ قَوْلٌ بِاللِّسَانِ، وَاعْتِقَادٌ وَعَمَلٌ بِالْقَلْبِ، وَعَمَلٌ بِالْجَوَارِحِ. وَفِي صَحِيحِ مُسْلِمٍ: الْإِيمَانُ بِضْعٌ وَسَبْعُونَ شُعْبَةً، أَفْضَلُهَا لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ."}, {"s": "fasih", "t": "هَلِ الْإِيمَانُ يَزِيدُ وَيَنْقُصُ؟"}, {"s": "anos", "t": "يَزِيدُ بِالطَّاعَةِ، وَيَنْقُصُ بِالْمَعْصِيَةِ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ الْأَنْفَالِ."}, {"s": "quran", "ref": "8:2", "t": "إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًۭا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ"}, {"s": "fasih", "t": "زَادَتْهُمْ إِيمَانًا! وَمَا الْإِحْسَانُ؟"}, {"s": "anos", "t": "أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ."}, {"s": "fasih", "t": "مَتَى تَكُونُ الْأَعْمَالُ مَقْبُولَةً؟"}, {"s": "anos", "t": "بِشَرْطَيْنِ: أَنْ تَكُونَ خَالِصَةً لِوَجْهِ اللَّهِ، وَعَلَى سُنَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "fasih", "t": "وَمَا التَّوَكُّلُ عَلَى اللَّهِ؟"}, {"s": "anos", "t": "الِاعْتِمَادُ عَلَى اللَّهِ فِي جَلْبِ الْمَنَافِعِ وَدَفْعِ الْمَضَارِّ، مَعَ الْأَخْذِ بِالْأَسْبَابِ. قَالَ تَعَالَى: وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ، أَيْ: كَافِيهِ."}, {"s": "fasih", "t": "وَالْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ؟"}, {"s": "anos", "t": "الْمَعْرُوفُ: كُلُّ طَاعَةٍ لِلَّهِ، وَالْمُنْكَرُ: كُلُّ مَعْصِيَةٍ. وَبِهِمَا كُنَّا خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ."}, {"s": "fasih", "t": "مَنْ هُمْ أَهْلُ السُّنَّةِ وَالْجَمَاعَةِ؟"}, {"s": "anos", "t": "مَنْ كَانُوا عَلَى مَا كَانَ عَلَيْهِ النَّبِيُّ وَأَصْحَابُهُ: سُمُّوا أَهْلَ السُّنَّةِ لِاتِّبَاعِهِمُ السُّنَّةَ وَتَرْكِ الْبِدَعِ، وَالْجَمَاعَةَ لِأَنَّهُمُ اجْتَمَعُوا عَلَى الْحَقِّ وَلَمْ يَتَفَرَّقُوا."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ ذَكَرَ اللَّهُ النَّحْلَةَ فِي سُورَةٍ بِاسْمِهَا، وَعَسَلُهَا فِيهِ شِفَاءٌ لِلنَّاسِ، وَلَا يُنْتِجُ الْعَسَلَ إِلَّا إِنَاثُ النَّحْلِ!"}, {"s": "anos", "t": "الْآنَ «مُسَابَقَةُ أَنُوس»: فَرِيقَانِ، نُقْطَتَانِ لِلْجَوَابِ، وَنُقْطَةٌ لِلدَّلِيلِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس: بطل الإيمان"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! غَدًا عِنْدِي اخْتِبَارٌ. أ: لَا أُذَاكِرُ وَأَقُولُ تَوَكَّلْتُ عَلَى اللَّهِ. ب: أُذَاكِرُ ثُمَّ أَدْعُو وَأَعْتَمِدُ عَلَى اللَّهِ. ج: أُذَاكِرُ وَلَا أَدْعُو."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: التوكّل"}, {"s": "anos", "t": "«أ» تَرَكَ الْأَسْبَابَ، وَ«ج» نَسِيَ الِاعْتِمَادَ عَلَى اللَّهِ. وَالصَّحِيحُ «ب»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: بِمَاذَا يَزِيدُ الْإِيمَانُ؟ فَكِّرُوا..."}, {"s": "anos", "t": "بِالطَّاعَةِ! وَمَا مَعْنَى «الْبَصِيرِ»؟ فَكِّرُوا..."}, {"s": "fasih", "t": "الَّذِي يَرَى كُلَّ شَيْءٍ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: كُنْتُ حَبْرَ الْأُمَّةِ وَتُرْجُمَانَ الْقُرْآنِ، وَدَعَا لِيَ النَّبِيُّ: اللَّهُمَّ فَقِّهْهُ فِي الدِّينِ وَعَلِّمْهُ التَّأْوِيلَ."}, {"s": "anos", "t": "زَيْدُ بْنُ ثَابِتٍ، أَمْ أَبُو هُرَيْرَةَ، أَمِ ابْنُ عَبَّاسٍ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: ارْسُمُوا «مِقْيَاسَ الْإِيمَانِ»، وَلَوِّنُوا دَرَجَةً مَعَ كُلِّ طَاعَةٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مُسَابَقَةُ أَنُوس الْإِلِكْتُرُونِيَّةُ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 6, "title": "الطهارة والوضوء", "season": 1, "goals": ["fiqh"], "hook": "أهلًا يا أصدقاء! فصيح ينفض ريشه بعد أن استحمّ ويقول: «أنا نظيف… نظيف!». أنوس يقول: «جميل يا فصيح! والمسلم يحبّ النظافة، بل هي مفتاح أعظم عبادة: الصلاة!». اليوم نبدأ باب الفقه، ونتعلّم <b>الطهارة والوضوء</b>.", "sections": [{"h": "ما الطهارة؟", "p": ["فصيح يسأل: «ما الطهارة؟». <b>الطهارة: رفع الحدث، وزوال الخبث</b>، أي: إزالة ما يمنعنا من الصلاة. قال النبيّ ﷺ: «مفتاح الصلاة الطهور» رواه أبو داود. فكما لا يُفتح الباب إلا بالمفتاح، لا تصحّ الصلاة إلا بالطهارة.", "والطهارة نوعان: <b>طهارة من الخبث</b>: أن أزيل النجاسة عن بدني، أو ثوبي، أو المكان الذي أصلّي فيه. و<b>طهارة من الحدث</b>: تكون بالوضوء أو الغسل بالماء الطهور، أو بالتيمّم لمن لم يجد الماء أو لم يستطع استعماله.", "و<b>كيف أطهّر ما أصابته النجاسة؟</b> أغسله بالماء حتى يطهر. أمّا الإناء الذي ولغ فيه الكلب، أي شرب منه بلسانه، فيُغسل <b>سبع مرّات، أولاهنّ بالتراب</b>، كما قال النبيّ ﷺ في حديث رواه مسلم."], "board": ["طهارة من الخبث", "طهارة من الحدث", "مفتاح الصلاة الطهور"]}, {"h": "فضل الوضوء: الذنوب تخرج مع الماء", "p": ["أخبرنا النبيّ ﷺ بخبر رائع: إذا توضّأ المسلم فغسل وجهه، خرجت من وجهه كل خطيئة نظر إليها بعينيه مع الماء. وإذا غسل يديه، خرجت من يديه كل خطيئة عملتها يداه. وإذا غسل رجليه، خرجت كل خطيئة مشت إليها رجلاه، <b>حتى يخرج نقيًّا من الذنوب</b>. رواه مسلم.", "أنوس يقول: كلّما توضّأت تخيّلت قطرات الماء تحمل الأخطاء بعيدًا، فأخرج نظيفًا من الخارج ومن الداخل!"], "board": ["الوجه", "اليدان", "الرجلان", "نقيًّا من الذنوب"]}, {"h": "كيف أتوضّأ؟", "p": ["تعالوا نتوضّأ مع أنوس خطوة خطوة: أوّلًا أغسل <b>كفّيّ</b> ثلاثًا. ثم <b>المضمضة</b> أي أجعل الماء في فمي ثم أمجّه، و<b>الاستنشاق</b> أي أجذب الماء إلى أنفي بيدي اليمنى، و<b>الاستنثار</b> أي أُخرجه بيدي اليسرى، ثلاثًا.", "ثم أغسل <b>وجهي</b> ثلاثًا، ثم <b>يديّ إلى المرفقين</b> ثلاثًا، ثم <b>أمسح رأسي</b> أُقبل بيديّ وأُدبر، وأمسح <b>أذنيّ</b>، ثم أغسل <b>رجليّ إلى الكعبين</b> ثلاثًا.", "هذا هو الأكمل، وقد ثبت عن النبيّ ﷺ في البخاري ومسلم. وثبت أيضًا أنه توضّأ مرّة مرّة، ومرّتين مرّتين."], "board": ["الكفّان", "المضمضة والاستنشاق", "الوجه", "اليدان", "الرأس والأذنان", "الرجلان"]}, {"h": "فرائض الوضوء وسننه", "p": ["<b>فرائض الوضوء</b> ستّ، لا يصحّ الوضوء إذا تُرك واحد منها: غسل الوجه ومنه المضمضة والاستنشاق، وغسل اليدين إلى المرفقين، ومسح الرأس ومنه الأذنان، وغسل الرجلين إلى الكعبين، و<b>الترتيب</b> بين الأعضاء كما في آية الوضوء في سورة المائدة، و<b>الموالاة</b> أي أتوضّأ متتابعًا دون أن أتوقّف حتى تجفّ أعضائي.", "و<b>سنن الوضوء</b>: من فعلها زاد أجره، ومن تركها فوضوؤه صحيح ولا إثم عليه. وهي: التسمية «بسم الله»، والسواك، وغسل الكفّين، وتخليل الأصابع، والغسلة الثانية والثالثة، والبدء باليمين، والذكر بعد الوضوء: «أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أنّ محمدًا عبده ورسوله»، وصلاة ركعتين بعده."], "board": ["فرائض: ٦", "الترتيب والموالاة", "سنن: التسمية، السواك، التيامن"]}, {"h": "نواقض الوضوء", "p": ["فصيح يسأل: «متى ينتقض وضوئي فأتوضّأ من جديد؟». نواقض الوضوء كما في الكتاب: <b>ما خرج من السبيلين</b> من بول أو غائط أو ريح، و<b>النوم</b> أو الجنون أو الإغماء، و<b>أكل لحم الإبل</b>، و<b>مسّ القُبُل أو الدبر باليد بدون حائل</b>.", "فإذا ذهبت إلى الحمّام، أو نمت، أو أكلت لحم جمل، فتوضّأ قبل أن تصلّي. أمّا إذا أكلت تفّاحة أو شربت ماء، فوضوؤك باقٍ."], "board": ["الخارج من السبيلين", "النوم", "لحم الإبل", "المسّ بلا حائل"]}], "summary": ["الطهارة رفع الحدث وزوال الخبث، وهي مفتاح الصلاة، والنجاسة تُغسل بالماء، وما ولغ فيه الكلب يُغسل سبعًا أولاهنّ بالتراب.", "الوضوء تخرج به الخطايا، وفرائضه ستّ: الوجه، واليدان، والرأس، والرجلان، والترتيب، والموالاة.", "نواقض الوضوء: الخارج من السبيلين، والنوم والإغماء، وأكل لحم الإبل، ومسّ الفرج بلا حائل."], "islam": {"intro": "قال الله تعالى يمدح أهل مسجد قباء الذين يحبّون الطهارة:", "text": "فالله يحبّ المتطهّرين، فإذا توضّأت ونظّفت ثوبك ومكانك فأنت تفعل شيئًا يحبّه الله.", "ayah": {"text": "لَا تَقُمْ فِيهِ أَبَدًۭا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌۭ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ", "src": "سُورَةُ التَّوۡبَةِ: ١٠٨"}, "hadith": {"text": "مفتاح الصلاة الطهور", "source": "رواه أبو داود"}}, "home": {"title": "بطل الوضوء في البيت", "goal": "أن يتوضّأ الطفل وضوءًا صحيحًا مرتّبًا، ويقول الذكر بعده.", "materials": ["ورقة خطوات الوضوء", "ملصقات نجوم"], "steps": ["الصق ورقة خطوات الوضوء قرب مكان الوضوء في البيت.", "توضّأ أمام أحد والديك، واطلب منه أن يتابع الخطوات على الورقة.", "قل بعد الوضوء: «أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أنّ محمدًا عبده ورسوله».", "ضع نجمة كل يوم تتوضّأ فيه بالترتيب الصحيح دون إسراف في الماء."], "parent": "تابعوا وضوء الطفل بهدوء، وصحّحوا بلطف: غسل المرفقين والكعبين والترتيب. وعلّموه ألا يُسرف في الماء."}, "online": {"title": "مختبر الوضوء", "intro": "رتّب خطوات الوضوء، وفرّق بين الفرائض والسنن مع فصيح!", "steps": [{"type": "order", "title": "رتّب خطوات الوضوء", "prompt": "رتّب الخطوات كما توضّأ النبيّ ﷺ.", "items": ["غسل الكفّين", "المضمضة والاستنشاق", "غسل الوجه", "غسل اليدين إلى المرفقين", "مسح الرأس والأذنين", "غسل الرجلين إلى الكعبين"]}, {"type": "sort", "title": "فريضة أم سنّة؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["فرائض الوضوء", "سنن الوضوء"], "items": [{"t": "غسل الوجه", "icon": "😊", "bin": 0, "why": "من فرائض الوضوء، ومنه المضمضة والاستنشاق."}, {"t": "مسح الرأس", "icon": "💆", "bin": 0, "why": "من فرائض الوضوء، ومنه الأذنان."}, {"t": "الترتيب بين الأعضاء", "icon": "🔢", "bin": 0, "why": "من الفرائض كما في آية المائدة."}, {"t": "الموالاة", "icon": "⏱️", "bin": 0, "why": "من الفرائض: الوضوء متتابعًا بلا فاصل."}, {"t": "التسمية", "icon": "🗣️", "bin": 1, "why": "من سنن الوضوء: بسم الله."}, {"t": "السواك", "icon": "🪥", "bin": 1, "why": "من سنن الوضوء."}, {"t": "البدء باليمين", "icon": "👉", "bin": 1, "why": "كان النبيّ ﷺ يعجبه التيمّن في طهوره."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ماذا يخرج مع ماء الوضوء؟", "o": ["الألوان", "الخطايا", "الطعام"], "a": 1, "why": "حتى يخرج نقيًّا من الذنوب. رواه مسلم."}, {"q": "نمت بعد الوضوء، فهل أتوضّأ؟", "o": ["نعم، النوم ينقض الوضوء", "لا، الوضوء باقٍ", "أغسل يديّ فقط"], "a": 0, "why": "النوم من نواقض الوضوء."}, {"q": "الطهارة بالتيمّم تكون…", "o": ["لمن أراد السرعة", "لمن يحبّ التراب", "لمن فقد الماء أو تعذّر عليه استعماله"], "a": 2, "why": "التيمّم لمن فقد الماء أو تعذّر عليه استعماله."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز داخل مصحف قديم، فيها صحابيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا ذو النورين.", "جهّزت جيش العسرة من مالي.", "جمعت الناس على مصحف واحد، واشتهرت بالحياء."], "options": ["عثمان بن عفّان رضي الله عنه", "عمر بن الخطّاب رضي الله عنه", "سعد بن أبي وقّاص رضي الله عنه"], "deep": "لماذا كان جمع الناس على مصحف واحد عملًا عظيمًا؟ وكيف نحترم المصحف فلا نمسّه إلا ونحن طاهرون؟", "reveal": "أنا عثمان بن عفّان رضي الله عنه، ثالث الخلفاء الراشدين! وكنت أعلّم الناس وضوء النبيّ ﷺ، فأتوضّأ أمامهم ثلاثًا ثلاثًا. وفي الحلقة القادمة نتعلّم: ماذا نفعل إذا لم نجد الماء؟ إنه التيمّم، والمسح على الخفّين."}, "quiz": [{"q": "ما الطهارة؟", "o": ["رفع الحدث وزوال الخبث", "لبس ثوب جديد", "الأكل باليمين"], "a": 0, "why": "هذا تعريف الطهارة في الكتاب."}], "qa": [{"id": 43, "q": "عرِّفِ الطهارة.", "a": "الطهارة: هي رفعُ الحدث، وزوالُ الخبث. أي: رفعُ ما يمنعُ من الصلاة. قال النبيُّ ﷺ: «مفتاحُ الصلاةِ الطهور» رواه أبو داود.\n• طهارةٌ من الخبث: وهي أن يزيلَ المسلمُ ما وقعَ من النجاسةِ على بدنِه، أو على ثوبِه، أو على البقعةِ والمكانِ الذي يصلي فيه.\n• طهارةٌ من الحدث: وهي التي تكونُ بالوضوءِ أو الغسل، بالماءِ الطهور، أو التيممِ لمن فقدَ الماء، أو تعذَّرَ عليه استعمالُه."}, {"id": 44, "q": "كيف تُطهِّرُ ما أصابتْهُ النجاسة؟", "a": "بغسلِهِ بالماءِ حتى يطهُر. وأما ما ولغَ به الكلبُ؛ فيُغسَلُ سبعَ مرات، الأولى بالتراب.\nفعن أبي هريرةَ قال: قال رسولُ الله ﷺ: «طهورُ إناءِ أحدِكم إذا ولغَ فيه الكلبُ أن يغسلَهُ سبعَ مرات، أولاهنَّ بالتراب» رواه مسلم."}, {"id": 45, "q": "ما هو فضلُ الوضوء؟", "a": "قال النبيُّ ﷺ: «إذا توضأَ العبدُ المسلمُ — أو المؤمنُ — فغسلَ وجهَه؛ خرجَ من وجهِهِ كلُّ خطيئةٍ نظرَ إليها بعينيهِ مع الماء — أو مع آخرِ قطرِ الماء — فإذا غسلَ يديه؛ خرجَ من يديهِ كلُّ خطيئةٍ كان بطشتْها يداهُ مع الماء، فإذا غسلَ رجليه؛ خرجتْ كلُّ خطيئةٍ مشتْها رجلاهُ مع الماء — حتى يخرجَ نقيًّا من الذنوب» رواه مسلم."}, {"id": 46, "q": "كيف تتوضأ؟", "a": "• بغسلِ الكفينِ ثلاثًا. والمضمضةِ والاستنشاقِ والاستنثارِ ثلاثًا.\n– المضمضة: جعلُ الماءِ في الفمِ ومجُّهُ وطرحُه.\n– الاستنشاق: جذبُ الماءِ بالهواءِ إلى داخلِ الأنفِ بيمينه.\n– الاستنثار: إخراجُ الماءِ من الأنفِ بعد الاستنشاقِ بيساره.\n• ثم غسلُ الوجهِ ثلاثًا.\n• ثم غسلُ اليدينِ إلى المرفقينِ ثلاثًا.\n• ثم مسحُ الرأسِ تُقبِلُ بيديكَ وتُدبِر، وتمسحُ الأذنين.\n• ثم غسلُ الرجلينِ إلى الكعبينِ ثلاثًا.\nهذا هو الأكمل، وقد ثبتَ ذلك عن النبيِّ ﷺ في أحاديثَ في البخاريِّ ومسلم. وثبتَ أيضًا: «أنه توضأَ مرةً مرة، وأنه توضأَ مرتينِ مرتين» بمعنى: أنه يغسلُ كلَّ عضوٍ مرةً أو مرتين."}, {"id": 47, "q": "ما هي فرائضُ الوضوء، وعددها؟", "a": "هي التي لا يصحُّ وضوءُ المسلمِ إذا تركَ واحدةً منها:\n١. غسلُ الوجه، ومنه المضمضةُ والاستنشاق.\n٢. غسلُ اليدينِ إلى المرفقين.\n٣. مسحُ الرأسِ ومنه الأذنان.\n٤. غسلُ الرجلينِ إلى الكعبين.\n٥. الترتيبُ بين الأعضاء: الوجهُ ثم اليدانِ ثم مسحُ الرأسِ ثم الرجلان. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ﴾ [المائدة: ٦].\n٦. الموالاة: وهي الوضوءُ في وقتٍ متواصلٍ دونَ فاصلٍ حتى تجفَّ الأعضاءُ من الماء."}, {"id": 48, "q": "ما هي سننُ الوضوء، وعددها؟", "a": "سننُ الوضوء: التي لو فعلَها له مزيدُ أجرٍ وثواب، ولو تركَها فلا إثمَ عليهِ ووضوؤُهُ صحيح:\n١. التسمية: «بسم الله». ٢. السواك. ٣. غسلُ الكفين. ٤. تخليلُ الأصابع. ٥. الغسلةُ الثانيةُ والثالثةُ للأعضاء. ٦. البدءُ باليمين (لحديثِ عائشة: كان النبيُّ ﷺ يعجبُهُ التيمنُ في تنعلِهِ وترجلِهِ وطهورِهِ وفي شأنِهِ كلِّه — متفق عليه). ٧. الذكرُ بعد الوضوء: «أشهدُ أن لا إله إلا اللهُ وحدَهُ لا شريكَ له، وأشهدُ أن محمدًا عبدُهُ ورسولُه» رواه مسلم. ٨. الصلاةُ ركعتينِ بعدَه."}, {"id": 49, "q": "ما نواقضُ الوضوء؟", "a": "• ما خرجَ من السبيلين: القُبُلِ والدبر، من بولٍ أو غائطٍ أو ريح.\n• النومُ، أو الجنونُ أو الإغماء. لحديث: «العينُ وِكاءُ السَّه، فمن نامَ فليتوضأ» رواه أبو داود وابن ماجه.\n• أكلُ لحمِ الإبل. سألَ رجلٌ النبيَّ ﷺ: أتوضأُ من لحومِ الإبل؟ قال: «نعم» رواه مسلم.\n• مسُّ القُبُلِ أو الدبرِ باليدِ بدونِ حائل. لحديث: «من مسَّ ذكرَهُ فليتوضأ» رواه أبو داود والترمذي."}], "dyk": ["حرَّمَ اللهُ الدمَ وأكلَ لحمِ الخنزير، واكتشفَ العلمُ أن لحمَ الخنزيرِ يحملُ طفيلياتٍ وأمراضاً كثيرة."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا!"}, {"s": "anos", "t": "وَالْيَوْمَ نَبْدَأُ بَابَ الْفِقْهِ: الطَّهَارَةَ وَالْوُضُوءَ!"}, {"s": "fasih", "t": "عَرِّفِ الطَّهَارَةَ!"}, {"s": "anos", "t": "رَفْعُ الْحَدَثِ، وَزَوَالُ الْخَبَثِ، أَيْ: رَفْعُ مَا يَمْنَعُ مِنَ الصَّلَاةِ. قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مِفْتَاحُ الصَّلَاةِ الطُّهُورُ»، رَوَاهُ أَبُو دَاوُدَ."}, {"s": "anos", "t": "وَهِيَ نَوْعَانِ: طَهَارَةٌ مِنَ الْخَبَثِ بِإِزَالَةِ النَّجَاسَةِ عَنِ الْبَدَنِ وَالثَّوْبِ وَالْمَكَانِ، وَطَهَارَةٌ مِنَ الْحَدَثِ بِالْوُضُوءِ أَوِ الْغُسْلِ، أَوِ التَّيَمُّمِ لِمَنْ فَقَدَ الْمَاءَ."}, {"s": "fasih", "t": "كَيْفَ أُطَهِّرُ مَا أَصَابَتْهُ النَّجَاسَةُ؟"}, {"s": "anos", "t": "تَغْسِلُهُ بِالْمَاءِ حَتَّى يَطْهُرَ. أَمَّا الْإِنَاءُ الَّذِي وَلَغَ فِيهِ الْكَلْبُ فَيُغْسَلُ سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ، رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "مَا فَضْلُ الْوُضُوءِ؟"}, {"s": "anos", "t": "أَخْبَرَنَا النَّبِيُّ أَنَّ الْمُسْلِمَ إِذَا تَوَضَّأَ خَرَجَتْ خَطَايَا وَجْهِهِ وَيَدَيْهِ وَرِجْلَيْهِ مَعَ الْمَاءِ، حَتَّى يَخْرُجَ نَقِيًّا مِنَ الذُّنُوبِ. رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "كَيْفَ أَتَوَضَّأُ؟"}, {"s": "anos", "t": "أَغْسِلُ كَفَّيَّ ثَلَاثًا، ثُمَّ أَتَمَضْمَضُ وَأَسْتَنْشِقُ وَأَسْتَنْثِرُ ثَلَاثًا، ثُمَّ أَغْسِلُ وَجْهِي ثَلَاثًا، ثُمَّ يَدَيَّ إِلَى الْمِرْفَقَيْنِ ثَلَاثًا، ثُمَّ أَمْسَحُ رَأْسِي وَأُذُنَيَّ، ثُمَّ أَغْسِلُ رِجْلَيَّ إِلَى الْكَعْبَيْنِ ثَلَاثًا."}, {"s": "anos", "t": "هَذَا الْأَكْمَلُ، وَثَبَتَ أَيْضًا أَنَّهُ تَوَضَّأَ مَرَّةً مَرَّةً، وَمَرَّتَيْنِ مَرَّتَيْنِ."}, {"s": "fasih", "t": "وَمَا فَرَائِضُ الْوُضُوءِ؟ وَكَمْ عَدَدُهَا؟"}, {"s": "anos", "t": "سِتٌّ: غَسْلُ الْوَجْهِ وَمِنْهُ الْمَضْمَضَةُ وَالِاسْتِنْشَاقُ، وَغَسْلُ الْيَدَيْنِ إِلَى الْمِرْفَقَيْنِ، وَمَسْحُ الرَّأْسِ وَمِنْهُ الْأُذُنَانِ، وَغَسْلُ الرِّجْلَيْنِ، وَالتَّرْتِيبُ كَمَا فِي سُورَةِ الْمَائِدَةِ، وَالْمُوَالَاةُ بِلَا فَاصِلٍ."}, {"s": "fasih", "t": "وَسُنَنُ الْوُضُوءِ؟"}, {"s": "anos", "t": "ثَمَانٍ: التَّسْمِيَةُ، وَالسِّوَاكُ، وَغَسْلُ الْكَفَّيْنِ، وَتَخْلِيلُ الْأَصَابِعِ، وَالْغَسْلَةُ الثَّانِيَةُ وَالثَّالِثَةُ، وَالْبَدْءُ بِالْيَمِينِ، وَالذِّكْرُ بَعْدَهُ، وَرَكْعَتَانِ. وَمَنْ تَرَكَهَا فَوُضُوؤُهُ صَحِيحٌ."}, {"s": "fasih", "t": "وَمَا نَوَاقِضُ الْوُضُوءِ؟"}, {"s": "anos", "t": "مَا خَرَجَ مِنَ السَّبِيلَيْنِ مِنْ بَوْلٍ أَوْ غَائِطٍ أَوْ رِيحٍ، وَالنَّوْمُ أَوِ الْجُنُونُ أَوِ الْإِغْمَاءُ، وَأَكْلُ لَحْمِ الْإِبِلِ، وَمَسُّ الْقُبُلِ أَوِ الدُّبُرِ بِالْيَدِ بِدُونِ حَائِلٍ."}, {"s": "fasih", "t": "وَاللَّهُ يُحِبُّ الطَّهَارَةَ! اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ التَّوْبَةِ."}, {"s": "quran", "ref": "9:108", "t": "لَا تَقُمْ فِيهِ أَبَدًۭا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌۭ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ"}, {"s": "anos", "t": "وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ! فَإِذَا تَوَضَّأْتَ وَنَظَّفْتَ ثَوْبَكَ، فَعَلْتَ مَا يُحِبُّهُ اللَّهُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ حَرَّمَ اللَّهُ الدَّمَ وَلَحْمَ الْخِنْزِيرِ، وَاكْتَشَفَ الْعِلْمُ أَنَّ لَحْمَ الْخِنْزِيرِ يَحْمِلُ طُفَيْلِيَّاتٍ وَأَمْرَاضًا كَثِيرَةً."}, {"s": "anos", "t": "الْآنَ «نَشِيدُ أَعْضَاءِ الْوُضُوءِ»: قَلِّدُوا الْوُضُوءَ بِلَا مَاءٍ، وَقُولُوا: الْوَجْهُ، ثَلَاثًا!"}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَافْعَلُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد أعضاء الوضوء"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! تَوَضَّأْتُ، ثُمَّ نِمْتُ قَلِيلًا، وَالْآنَ أَذَّنَ الْعَصْرُ. أ: أُصَلِّي بِوُضُوئِي الْأَوَّلِ. ب: أَتَوَضَّأُ مِنْ جَدِيدٍ ثُمَّ أُصَلِّي. ج: أَغْسِلُ وَجْهِي فَقَطْ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: هل أتوضّأ من جديد؟"}, {"s": "anos", "t": "«أ» خَطَأٌ، فَالنَّوْمُ نَاقِضٌ، وَ«ج» لَا يَكْفِي. وَالصَّحِيحُ «ب»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: كَمْ مَرَّةً يُغْسَلُ الْإِنَاءُ إِذَا وَلَغَ فِيهِ الْكَلْبُ؟ فَكِّرُوا..."}, {"s": "anos", "t": "سَبْعَ مَرَّاتٍ، أُولَاهُنَّ بِالتُّرَابِ! وَمَاذَا نَمْسَحُ فِي الْوُضُوءِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "الرَّأْسَ وَالْأُذُنَيْنِ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا ذُو النُّورَيْنِ، جَهَّزْتُ جَيْشَ الْعُسْرَةِ مِنْ مَالِي، وَجَمَعْتُ النَّاسَ عَلَى مُصْحَفٍ وَاحِدٍ، وَاشْتَهَرْتُ بِالْحَيَاءِ."}, {"s": "anos", "t": "عُثْمَانُ، أَمْ عُمَرُ، أَمْ سَعْدٌ رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «بَطَلُ الْوُضُوءِ»: تَوَضَّأْ أَمَامَ وَالِدَيْكَ بِلَا إِسْرَافٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مُخْتَبَرُ الْوُضُوءِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 7, "title": "التيمّم والمسح على الخفّين", "season": 1, "goals": ["fiqh"], "hook": "أهلًا يا أصدقاء! فصيح في رحلة إلى الصحراء، وحان وقت الصلاة، ولا يوجد ماء! فصيح يصيح: «يا أنوس، كيف أتوضّأ؟». أنوس يبتسم: «لا تقلق يا فصيح، ديننا يسر! اليوم نتعلّم <b>التيمّم</b>، و<b>المسح على الخفّين</b>».", "sections": [{"h": "التيمّم: طهارة بالتراب", "p": ["فصيح يسأل: «ما التيمّم؟». <b>التيمّم: استعمال التراب وغيره من صعيد الأرض، عند فقد الماء أو تعذّر استعماله</b>. والصعيد هو وجه الأرض الطيّب.", "متى أتيمّم؟ إذا لم أجد ماء، مثل فصيح في الصحراء، أو إذا كان الماء موجودًا لكن لا أستطيع استعماله، مثل مريض يضرّه الماء. قال تعالى في سورة النساء: فلم تجدوا ماء فتيمّموا صعيدًا طيّبًا فامسحوا بوجوهكم وأيديكم.", "أنوس يقول: انظر إلى رحمة الله! لم يتركنا بلا صلاة إذا فقدنا الماء، بل جعل لنا التراب طهورًا."], "board": ["التيمّم عند فقد الماء", "أو تعذّر استعماله"]}, {"h": "كيف أتيمّم؟ وما ينقضه؟", "p": ["أخطأ الصحابيّ <b>عمّار بن ياسر</b> رضي الله عنه مرّة، فتمرّغ في التراب كله! فقال له النبيّ ﷺ: «إنما كان يكفيك هكذا»، وضرب بكفّيه الأرض، ونفخ فيهما، ثم مسح بهما وجهه وكفّيه. رواه البخاري ومسلم.", "إذن التيمّم سهل: <b>أضرب التراب ضربة واحدة بباطن كفّيّ، ثم أمسح وجهي وظاهر كفّيّ مرّة واحدة</b>.", "و<b>نواقض التيمّم</b>: كل نواقض الوضوء التي تعلّمناها في الحلقة الماضية، و<b>إذا وُجد الماء</b>. فإذا وصل فصيح إلى واحة فيها ماء، انتهى تيمّمه ووجب عليه الوضوء."], "board": ["ضربة واحدة", "الوجه", "ظاهر الكفّين", "ينقضه: وجود الماء"]}, {"h": "الخفّان والجوربان، ولماذا نمسح عليهما؟", "p": ["<b>الخفّان</b>: ما يُلبس في الرِّجل من الجلد، مثل الحذاء الجلديّ الذي يغطّي القدم. و<b>الجوربان</b>: ما يُلبس في الرِّجل من غير الجلد، مثل الشُّرّاب القماشيّ.", "و<b>يُشرع المسح عليهما بدل غسل الرجلين</b>؛ فقد توضّأ رسول الله ﷺ ومسح على الخفّين، كما في البخاري ومسلم.", "و<b>الحكمة</b>: التيسير والتخفيف على العباد، خاصّة في البرد والشتاء والسفر، حين يصعب خلع ما في الرجلين. قال تعالى: يريد الله بكم اليسر ولا يريد بكم العسر."], "board": ["الخفّ: من جلد", "الجورب: من غير الجلد", "الحكمة: التيسير"]}, {"h": "شروط المسح وصفته وما ينقضه", "p": ["<b>شروط المسح أربعة</b>: الأوّل أن ألبسهما على طهارة، أي بعد الوضوء. والثاني أن يكون الخفّ طاهرًا. والثالث أن يكون ساترًا للقدم إلى الكعبين. والرابع أن يكون المسح في المدّة المحدّدة: <b>للمقيم يوم وليلة، وللمسافر ثلاثة أيّام بلياليهنّ</b>.", "و<b>صفة المسح</b>: أبلّ أصابع يديّ بالماء، وأضعها على أصابع رجليّ، ثم أمرّها إلى ساقي. أمسح الرِّجل اليمنى باليد اليمنى، واليسرى باليسرى، وأفرّج أصابعي، ولا أكرّر المسح. فالمسح يكون على ظاهر الخفّ.", "و<b>ينتقض المسح</b> بأمرين: انتهاء المدّة، أو خلع الخفّين أو أحدهما بعد المسح."], "board": ["البس على طهارة", "مقيم: يوم وليلة", "مسافر: ٣ أيّام", "ينقضه: انتهاء المدّة أو الخلع"]}], "summary": ["التيمّم استعمال التراب عند فقد الماء أو تعذّر استعماله: ضربة واحدة، ثم مسح الوجه وظاهر الكفّين.", "ينقض التيمّمَ كلُّ نواقض الوضوء ووجودُ الماء، والمسح على الخفّين والجوربين تيسير من الله.", "شروط المسح: اللبس على طهارة، وطهارة الخفّ، وستره، والمدّة: يوم وليلة للمقيم وثلاثة أيّام للمسافر، وينقضه انتهاء المدّة أو الخلع."], "islam": {"intro": "قال الله تعالى في آية الوضوء والتيمّم:", "text": "فالله لا يريد أن يشقّ علينا، بل يريد أن يطهّرنا ويتمّ نعمته علينا لعلّنا نشكره.", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍۢ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ", "src": "سُورَةُ المَائـِدَةِ: ٦"}, "hadith": {"text": "إنما كان يكفيك هكذا", "source": "قاله النبيّ ﷺ لعمّار بن ياسر في التيمّم، رواه البخاري ومسلم"}}, "home": {"title": "خريطة رحلة فصيح", "goal": "أن يعرف الطفل متى يتوضّأ ومتى يتيمّم، ومدّة المسح للمقيم والمسافر.", "materials": ["ورقة كبيرة", "ألوان", "صحن فيه تراب نظيف"], "steps": ["ارسم رحلة فصيح: بيت فيه ماء، ثم صحراء بلا ماء، ثم واحة فيها ماء.", "اكتب عند كل مكان: «أتوضّأ» أو «أتيمّم».", "تيمّم أمام أسرتك على صحن التراب: ضربة واحدة، ومسح الوجه وظاهر الكفّين.", "اسأل أسرتك: «كم مدّة المسح للمقيم؟ وللمسافر؟» وصحّح لهم."], "parent": "علّموا الطفل التيمّم عمليًّا للتعلّم، وذكّروه أنه لا يكون إلا عند فقد الماء أو تعذّر استعماله. وإن كان أحدكم يمسح على الخفّين فأروه الصفة الصحيحة."}, "online": {"title": "رحلة فصيح في الصحراء", "intro": "صِل الكلمة بمعناها، واتّخذ القرار الصحيح، وأجب عن أسئلة أنوس!", "steps": [{"type": "match", "title": "صِل الكلمة بمعناها", "prompt": "اختر الكلمة، ثم معناها الصحيح.", "pairs": [["التيمّم", "استعمال التراب عند فقد الماء"], ["الخفّ", "ما يُلبس في الرِّجل من الجلد"], ["الجورب", "ما يُلبس في الرِّجل من غير الجلد"], ["مدّة المقيم", "يوم وليلة"], ["مدّة المسافر", "ثلاثة أيّام بلياليهنّ"]]}, {"type": "decision", "title": "مختبر القرار", "scenario": "تيمّم فصيح في الصحراء لأنه لم يجد ماء، وقبل أن يصلّي وصل إلى بئر فيها ماء.", "options": [{"t": "يصلّي بتيمّمه، فقد تيمّم قبل قليل", "result": "وجود الماء ينقض التيمّم، فلا يصلّي به."}, {"t": "يتيمّم مرّة ثانية ليكون أقوى", "result": "التيمّم لا يكون مع وجود الماء الذي يستطيع استعماله."}, {"t": "يتوضّأ بالماء ثم يصلّي", "result": "أحسنت! إذا وُجد الماء انتقض التيمّم ووجب الوضوء.", "best": true}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ماذا أمسح في التيمّم؟", "o": ["الرأس والرجلين", "الوجه وظاهر الكفّين", "الظهر"], "a": 1, "why": "مسح النبيّ ﷺ بكفّيه وجهه وكفّيه."}, {"q": "كيف أمسح على الخفّين؟", "o": ["أمسح أصابع رجليّ إلى ساقي بيد مبلولة مرّة واحدة", "أغسلهما ثلاث مرّات", "أمسح أسفلهما فقط"], "a": 0, "why": "يضع أصابع يديه مبلولة على أصابع رجليه ثم يمرّها إلى ساقه ولا يكرّر."}, {"q": "أوّل شروط المسح على الخفّين:", "o": ["أن يكونا جديدين", "أن يكون لونهما أسود", "أن يلبسهما على طهارة"], "a": 2, "why": "قال ﷺ: دعهما فإني أدخلتهما طاهرتين."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز في كتاب الحديث، فيها امرأة عظيمة تتكلّم عن نفسها. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا أمّ المؤمنين، وبنت الصدّيق.", "أنا أفقه نساء الأمّة.", "رويت كثيرًا من أحاديث النبيّ ﷺ."], "options": ["خديجة بنت خويلد رضي الله عنها", "فاطمة الزهراء رضي الله عنها", "عائشة رضي الله عنها"], "deep": "لماذا نحبّ أمّهات المؤمنين ونحترمهنّ؟ وكيف وصلتنا أحاديث كثيرة عن النبيّ ﷺ؟", "reveal": "أنا عائشة رضي الله عنها، أمّ المؤمنين! ومن قصصي أنّ عقدًا لي ضاع في سفر، فبقي الناس بلا ماء، فأنزل الله آية التيمّم، وهي رخصة لكم إلى اليوم. وفي الحلقة القادمة نتعلّم أعظم عبادة بعد التوحيد: الصلاة، فضلها وشروطها وأركانها."}, "quiz": [{"q": "متى نتيمّم؟", "o": ["عند فقد الماء أو تعذّر استعماله", "إذا كان الماء باردًا قليلًا", "إذا كنّا مستعجلين"], "a": 0, "why": "التيمّم عند فقد الماء أو تعذّر استعماله."}], "qa": [{"id": 50, "q": "ما هو التيمم؟", "a": "التيمم: هو استعمالُ الترابِ وغيرِهِ من صعيدِ الأرض، عند فقدِ الماءِ أو تعذُّرِ استعمالِه.\nقال تعالى: ﴿فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا﴾ [النساء: ٤٣]."}, {"id": 51, "q": "كيف تتيمم؟", "a": "بضربِ الترابِ ضربةً واحدةً بباطنِ الكفين، ومسحِ الوجهِ وظاهرِ الكفينِ مرةً واحدة.\nلقولِ النبيِّ ﷺ لعمارِ بنِ ياسرٍ ﷺ: «إنما كان يكفيكَ هكذا». فضربَ النبيُّ ﷺ بكفيهِ الأرضَ ونفخَ فيهما، ثم مسحَ بهما وجهَهُ وكفيه. رواه البخاري ومسلم."}, {"id": 52, "q": "ما هي نواقضُ التيمم؟", "a": "• كلُّ نواقضِ الوضوء.\n• إذا وُجِدَ الماء."}, {"id": 53, "q": "ما الخُفّانِ والجَورَبان، وهل يُمسَحُ عليهما؟", "a": "• الخفان: ما يُلبَسُ في الرِّجلِ من الجلد.\n• الجوربان: ما يُلبَسُ في الرِّجلِ من غيرِ الجلد.\nويُشرَعُ المسحُ عليهما بدلَ غسلِ الرجلين. لحديثِ المغيرةِ بنِ شعبة: أن رسولَ الله ﷺ توضأَ ومسحَ على الجوربين (رواه أبو داود والترمذي). وفي البخاريِّ ومسلم: فتوضأَ ومسحَ على الخفين."}, {"id": 54, "q": "ما الحكمةُ من المسحِ على الخفين؟", "a": "التيسيرُ والتخفيفُ على العباد، خاصةً في أوقاتِ البردِ والشتاءِ والسفر، حيث يشقُّ نزعُ ما في الرجلين.\nقال تعالى: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾ [البقرة: ١٨٥]."}, {"id": 55, "q": "ما هي شروطُ صحةِ المسحِ على الخفين؟", "a": "١. أن يلبسَ الخفينِ على طهارة، أي بعد وضوء. لحديثِ المغيرة: «دعهما فإني أدخلتُهما طاهرتين» فمسحَ عليهما (متفق عليه).\n٢. أن يكونَ الخفُّ طاهرًا، فلا يجوزُ المسحُ على النجس.\n٣. أن يكونَ الخفُّ ساترًا للمحلِّ المفروضِ غسلُهُ في الوضوء.\n٤. أن يكونَ المسحُ خلالَ المدةِ المحددة: للمقيمِ يومٌ وليلة، وللمسافرِ ثلاثةُ أيامٍ ولياليهن. لحديثِ عليٍّ: جعلَ رسولُ الله ﷺ ثلاثةَ أيامٍ ولياليهنَّ للمسافر، ويومًا وليلةً للمقيم. رواه مسلم."}, {"id": 56, "q": "ما هي صفةُ المسحِ على الخفين؟", "a": "أن يضعَ أصابعَ يديهِ مبلولتينِ بالماءِ على أصابعِ رجليهِ ثم يمرَّهما إلى ساقه؛ يمسحُ الرِّجلَ اليمنى باليدِ اليمنى، والرِّجلَ اليسرى باليدِ اليسرى، ويُفرِّجُ أصابعَهُ إذا مسحَ ولا يُكرِّر."}, {"id": 57, "q": "ما الذي ينقضُ المسحَ على الخفين؟", "a": "١. انقضاءُ مدةِ المسح، فلا يجوزُ المسحُ بعدَ انقضاءِ المدةِ المحددةِ شرعًا (يومٌ وليلةٌ للمقيم، وثلاثةُ أيامٍ بلياليها للمسافر).\n٢. خلعُ الخفين، فإذا نزعَ الإنسانُ الخفينِ أو أحدَهما بعد مسحِهِ بطلَ المسحُ عليهما."}], "dyk": ["تكلَّمَتْ نملةٌ في القرآنِ تُحذِّرُ قومَها من جيشِ سليمان، والعلمُ أثبتَ أن النملَ يتواصلُ ويُنذِرُ بعضُه بعضاً."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ عُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ، ثَالِثُ الْخُلَفَاءِ!"}, {"s": "anos", "t": "وَالْيَوْمَ فَصِيح فِي الصَّحْرَاءِ، وَحَانَ وَقْتُ الصَّلَاةِ، وَلَا مَاءَ!"}, {"s": "fasih", "t": "كَيْفَ أَتَوَضَّأُ؟ بَلْ مَا التَّيَمُّمُ؟"}, {"s": "anos", "t": "لَا تَقْلَقْ، دِينُنَا يُسْرٌ! التَّيَمُّمُ: اسْتِعْمَالُ التُّرَابِ وَغَيْرِهِ مِنْ صَعِيدِ الْأَرْضِ، عِنْدَ فَقْدِ الْمَاءِ أَوْ تَعَذُّرِ اسْتِعْمَالِهِ، كَمَا فِي سُورَةِ النِّسَاءِ: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا."}, {"s": "fasih", "t": "وَكَيْفَ أَتَيَمَّمُ؟"}, {"s": "anos", "t": "تَضْرِبُ التُّرَابَ ضَرْبَةً وَاحِدَةً بِبَاطِنِ كَفَّيْكَ، ثُمَّ تَمْسَحُ وَجْهَكَ وَظَاهِرَ كَفَّيْكَ مَرَّةً وَاحِدَةً. فَقَدْ قَالَ النَّبِيُّ لِعَمَّارِ بْنِ يَاسِرٍ: «إِنَّمَا كَانَ يَكْفِيكَ هَكَذَا»، رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ."}, {"s": "fasih", "t": "وَلِمَاذَا قَالَ لَهُ ذَلِكَ؟"}, {"s": "anos", "t": "لِأَنَّ عَمَّارًا رَضِيَ اللَّهُ عَنْهُ تَمَرَّغَ فِي التُّرَابِ كُلِّهِ! فَعَلَّمَهُ النَّبِيُّ أَنَّ الْأَمْرَ أَسْهَلُ."}, {"s": "fasih", "t": "هَهْهَهْ! وَمَا نَوَاقِضُ التَّيَمُّمِ؟"}, {"s": "anos", "t": "كُلُّ نَوَاقِضِ الْوُضُوءِ، وَإِذَا وُجِدَ الْمَاءُ."}, {"s": "fasih", "t": "مَا الْخُفَّانِ وَالْجَوْرَبَانِ؟ وَهَلْ يُمْسَحُ عَلَيْهِمَا؟"}, {"s": "anos", "t": "الْخُفَّانِ: مَا يُلْبَسُ فِي الرِّجْلِ مِنَ الْجِلْدِ، وَالْجَوْرَبَانِ: مِنْ غَيْرِ الْجِلْدِ. وَيُشْرَعُ الْمَسْحُ عَلَيْهِمَا بَدَلَ غَسْلِ الرِّجْلَيْنِ؛ فَقَدْ تَوَضَّأَ النَّبِيُّ وَمَسَحَ عَلَى الْخُفَّيْنِ."}, {"s": "fasih", "t": "وَمَا الْحِكْمَةُ مِنْ ذَلِكَ؟"}, {"s": "anos", "t": "التَّيْسِيرُ وَالتَّخْفِيفُ، خَاصَّةً فِي الْبَرْدِ وَالسَّفَرِ. قَالَ تَعَالَى: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ."}, {"s": "fasih", "t": "وَمَا شُرُوطُ صِحَّةِ الْمَسْحِ؟"}, {"s": "anos", "t": "أَرْبَعَةٌ: أَنْ تَلْبَسَهُمَا عَلَى طَهَارَةٍ، وَأَنْ يَكُونَا طَاهِرَيْنِ، وَسَاتِرَيْنِ لِلْقَدَمِ إِلَى الْكَعْبَيْنِ، وَفِي الْمُدَّةِ: لِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ، وَلِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ بِلَيَالِيهِنَّ."}, {"s": "fasih", "t": "وَمَا صِفَةُ الْمَسْحِ؟"}, {"s": "anos", "t": "تَبُلُّ أَصَابِعَ يَدَيْكَ، وَتَضَعُهَا عَلَى أَصَابِعِ رِجْلَيْكَ، ثُمَّ تُمِرُّهَا إِلَى سَاقِكَ؛ الْيُمْنَى بِالْيُمْنَى، وَالْيُسْرَى بِالْيُسْرَى، وَتُفَرِّجُ أَصَابِعَكَ، وَلَا تُكَرِّرُ."}, {"s": "fasih", "t": "وَمَا الَّذِي يَنْقُضُ الْمَسْحَ؟"}, {"s": "anos", "t": "انْقِضَاءُ الْمُدَّةِ، أَوْ خَلْعُ الْخُفَّيْنِ أَوْ أَحَدِهِمَا بَعْدَ الْمَسْحِ. وَالْآنَ اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ يَتْلُو آيَةَ الْوُضُوءِ وَالتَّيَمُّمِ مِنْ سُورَةِ الْمَائِدَةِ."}, {"s": "quran", "ref": "5:6", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍۢ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ"}, {"s": "anos", "t": "مَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُمْ مِنْ حَرَجٍ! فَاللَّهُ يُرِيدُ أَنْ يُطَهِّرَنَا، وَيُتِمَّ نِعْمَتَهُ عَلَيْنَا لَعَلَّنَا نَشْكُرُهُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ تَكَلَّمَتْ نَمْلَةٌ فِي الْقُرْآنِ تُحَذِّرُ قَوْمَهَا مِنْ جَيْشِ سُلَيْمَانَ، وَالْعِلْمُ أَثْبَتَ أَنَّ النَّمْلَ يَتَوَاصَلُ وَيُنْذِرُ بَعْضُهُ بَعْضًا!"}, {"s": "anos", "t": "الْآنَ لُعْبَةُ «مَاءٌ أَمْ تُرَابٌ؟»: ارْفَعُوا الْبِطَاقَةَ الزَّرْقَاءَ لِلْوُضُوءِ، أَوِ الْبُنِّيَّةَ لِلتَّيَمُّمِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَالْعَبُوهَا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: لعبة: ماء أم تراب؟"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! لَبِسْتُ جَوْرَبَيَّ قَبْلَ الْوُضُوءِ، وَأُرِيدُ الْوُضُوءَ الْآنَ. أ: أَمْسَحُ عَلَيْهِمَا. ب: أَخْلَعُهُمَا وَأَغْسِلُ رِجْلَيَّ. ج: لَا أَتَوَضَّأُ الْيَوْمَ أَبَدًا."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: هل أمسح على الجورب؟"}, {"s": "anos", "t": "«أ» خَطَأٌ، فَلَمْ تَلْبَسْهُمَا عَلَى طَهَارَةٍ، وَ«ج» تَرْكٌ لِلصَّلَاةِ! وَالصَّحِيحُ «ب»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: كَمْ ضَرْبَةً عَلَى التُّرَابِ فِي التَّيَمُّمِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "ضَرْبَةٌ وَاحِدَةٌ! وَمَا مُدَّةُ الْمَسْحِ لِلْمُسَافِرِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "ثَلَاثَةُ أَيَّامٍ بِلَيَالِيهِنَّ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا أُمُّ الْمُؤْمِنِينَ، وَبِنْتُ الصِّدِّيقِ، وَأَفْقَهُ نِسَاءِ الْأُمَّةِ."}, {"s": "anos", "t": "خَدِيجَةُ، أَمْ فَاطِمَةُ، أَمْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهُنَّ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: ارْسُمُوا «خَرِيطَةَ رِحْلَةِ فَصِيح»."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ فَصِيح فِي الصَّحْرَاءِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 8, "title": "الصلاة: فضلها وشروطها وأركانها", "season": 1, "goals": ["fiqh"], "hook": "أهلًا يا أصدقاء! فصيح يسمع الأذان ويرفرف: «الله أكبر… الله أكبر! حان وقت الصلاة!». أنوس يقول: «أحسنت يا فصيح! هل تعرف أنّ الصلاة مثل نهر عند باب بيتك تغتسل منه خمس مرّات كل يوم؟». تعالوا نتعلّم <b>الصلاة: فضلها وشروطها وأركانها</b>.", "sections": [{"h": "فضل الصلاة: نهر عند الباب", "p": ["قال رسول الله ﷺ: «أرأيتم لو أنّ نهرًا بباب أحدكم يغتسل منه كل يوم خمس مرّات، هل يبقى من درنه شيء؟» قالوا: لا يبقى من درنه شيء. قال: «فذلك مثل الصلوات الخمس، يمحو الله بهنّ الخطايا». متّفق عليه. والدرن: الوسخ.", "و<b>الصلاة</b>: هي التعبّد لله بأقوال وأفعال مخصوصة، تبدأ بالتكبير «الله أكبر»، وتنتهي بالتسليم «السلام عليكم ورحمة الله».", "و<b>الصلاة فريضة على كل مسلم</b>، لها أوقات محدّدة. و<b>ترك الصلاة كفر</b>؛ قال النبيّ ﷺ: «العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر». فالصلاة هي العلامة التي تميّز المسلم."], "board": ["تبدأ بالتكبير", "تنتهي بالتسليم", "فريضة على كل مسلم"]}, {"h": "خمس صلوات، وسبع عشرة ركعة", "p": ["فصيح يعدّ على أصابعه: «كم صلاة في اليوم؟». <b>خمس صلوات</b> في اليوم والليلة: <b>الفجر ركعتان</b>، و<b>الظهر أربع</b>، و<b>العصر أربع</b>، و<b>المغرب ثلاث</b>، و<b>العشاء أربع</b>.", "فإذا جمعناها صارت سبع عشرة ركعة كل يوم. أنوس يقول: الفجر هي الأقصر، والمغرب هي الوحيدة التي ركعاتها ثلاث!"], "board": ["الفجر ٢", "الظهر ٤", "العصر ٤", "المغرب ٣", "العشاء ٤"]}, {"h": "شروط الصلاة التسعة", "p": ["الشروط أشياء تكون قبل الصلاة، ولا تصحّ الصلاة بدونها. وهي تسعة: <b>الإسلام</b>، و<b>العقل</b>، و<b>التمييز</b> أي أن يكبر الطفل حتى يفهم، و<b>النيّة</b> لقوله ﷺ: «إنما الأعمال بالنيّات».", "ثم <b>دخول الوقت</b>، فلا أصلّي الظهر قبل أذانه، و<b>الطهارة من الحدث</b> بالوضوء، و<b>التطهّر من النجاسة</b> في البدن والثوب والمكان، و<b>ستر العورة</b> بلبس ثياب ساترة نظيفة، و<b>استقبال القبلة</b> أي التوجّه نحو الكعبة.", "فقبل أن أكبّر أسأل نفسي: هل توضّأت؟ هل ثوبي نظيف وساتر؟ هل دخل الوقت؟ هل أنا متّجه إلى القبلة؟"], "board": ["الطهارة", "دخول الوقت", "ستر العورة", "استقبال القبلة", "النيّة"]}, {"h": "أركان الصلاة وواجباتها وسننها", "p": ["<b>أركان الصلاة</b> أربعة عشر، وهي أعمدة الصلاة، لا تصحّ إلا بها، منها: القيام في الفرض للقادر، و<b>تكبيرة الإحرام</b> «الله أكبر»، و<b>قراءة الفاتحة</b>، والركوع والرفع منه والاعتدال قائمًا، والسجود على الأعضاء السبعة: الجبهة مع الأنف، والكفّين، والركبتين، وأطراف القدمين، والرفع منه، والجلوس بين السجدتين، و<b>الطمأنينة</b> أي السكون في كل ركن، والتشهّد الأخير والجلوس له، والتسليمتان، وترتيب الأركان.", "و<b>واجبات الصلاة</b> ثمانية، منها: التكبيرات غير تكبيرة الإحرام، وقول «سمع الله لمن حمده» للإمام والمنفرد، و«ربّنا ولك الحمد»، و«سبحان ربّي العظيم» مرّة في الركوع، و«سبحان ربّي الأعلى» مرّة في السجود، و«ربّ اغفر لي» بين السجدتين، والتشهّد الأوّل والجلوس له.", "و<b>سنن الصلاة</b> كثيرة، يزيد بها الأجر، مثل: دعاء الاستفتاح، والتعوّذ، والبسملة، وقول «آمين»، وقراءة سورة بعد الفاتحة، ورفع اليدين مع التكبير، ووضع اليد اليمنى على اليسرى، والنظر إلى موضع السجود."], "board": ["أركان: ١٤", "واجبات: ٨", "سنن: يزيد بها الأجر"]}, {"h": "مبطلات الصلاة", "p": ["فصيح يسأل: «ما الأشياء التي تُفسد صلاتي؟». مبطلات الصلاة خمسة: <b>ترك ركن أو شرط</b>، و<b>الكلام عمدًا</b>، و<b>الأكل أو الشرب</b>، و<b>الحركات الكثيرة المتوالية</b> بلا حاجة، و<b>ترك واجب من واجبات الصلاة عمدًا</b>.", "فإذا صلّيت فلا تتكلّم مع أخيك، ولا تأكل الحلوى، ولا تلعب بثيابك كثيرًا. قف بخشوع، فأنت تقف بين يدي الله."], "board": ["لا كلام", "لا أكل ولا شرب", "لا حركة كثيرة"]}], "summary": ["الصلاة كالنهر يمحو الله به الخطايا، وهي فريضة على كل مسلم، وتركها كفر.", "الصلوات خمس: الفجر ٢، والظهر ٤، والعصر ٤، والمغرب ٣، والعشاء ٤، ولها تسعة شروط، منها الطهارة ودخول الوقت واستقبال القبلة.", "للصلاة ١٤ ركنًا و٨ واجبات وسنن كثيرة، وتبطل بترك ركن أو شرط، وبالكلام عمدًا، والأكل والشرب، والحركة الكثيرة، وترك واجب عمدًا."], "islam": {"intro": "قال الله تعالى يخبرنا أنّ للصلاة أوقاتًا محدّدة فرضها على المؤمنين:", "text": "فنحافظ على كل صلاة في وقتها، فإذا سمعنا الأذان تركنا اللعب وقمنا إلى الوضوء.", "ayah": {"text": "فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًۭا مَّوْقُوتًۭا", "src": "سُورَةُ النِّسَاءِ: ١٠٣"}, "hadith": {"text": "أرأيتم لو أنّ نهرًا بباب أحدكم يغتسل منه كل يوم خمس مرّات، هل يبقى من درنه شيء؟ قالوا: لا يبقى من درنه شيء. قال: فذلك مثل الصلوات الخمس يمحو الله بهنّ الخطايا", "source": "متّفق عليه"}}, "home": {"title": "جدول صلواتي الخمس", "goal": "أن يحافظ الطفل على الصلوات الخمس في وقتها، ويتأكّد من شروطها قبل أن يكبّر.", "materials": ["ورقة جدول للأسبوع", "ملصقات"], "steps": ["اصنع جدولًا فيه أيّام الأسبوع والصلوات الخمس، واكتب بجانب كل صلاة عدد ركعاتها.", "ضع ملصقًا كلّما صلّيت صلاة في وقتها.", "قبل كل صلاة اسأل نفسك أسئلة الشروط: هل توضّأت؟ هل ثوبي نظيف؟ هل أنا متّجه إلى القبلة؟", "صلِّ مرّة أمام أحد والديك، واطلب منه أن يتأكّد من الطمأنينة في كل ركن."], "parent": "شجّعوا الطفل على الصلاة بحبّ لا بخوف، وصلّوا معه جماعة في البيت قدر الإمكان، واحتفلوا بالأسبوع الكامل في الجدول."}, "online": {"title": "مختبر الصلاة", "intro": "صِل كل صلاة بعدد ركعاتها، وصنّف أعمال الصلاة مع فصيح!", "steps": [{"type": "match", "title": "صِل الصلاة بعدد ركعاتها", "prompt": "اختر الصلاة، ثم عدد ركعاتها.", "pairs": [["الفجر", "ركعتان"], ["المغرب", "ثلاث ركعات"], ["الظهر", "أربع ركعات"], ["مجموع ركعات اليوم", "سبع عشرة ركعة"]]}, {"type": "sort", "title": "ركن أم واجب أم سنّة؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["أركان الصلاة", "واجبات الصلاة", "سنن الصلاة"], "items": [{"t": "تكبيرة الإحرام", "icon": "🙌", "bin": 0, "why": "تكبيرة الإحرام ركن: «إذا قمت إلى الصلاة فكبّر»."}, {"t": "قراءة الفاتحة", "icon": "📖", "bin": 0, "why": "لا صلاة لمن لم يقرأ بفاتحة الكتاب."}, {"t": "الطمأنينة", "icon": "🧘", "bin": 0, "why": "الطمأنينة ركن: السكون في كل ركن فعليّ."}, {"t": "سبحان ربّي العظيم مرّة", "icon": "🙇", "bin": 1, "why": "قولها مرّة في الركوع من الواجبات."}, {"t": "التشهّد الأوّل", "icon": "☝️", "bin": 1, "why": "التشهّد الأوّل من الواجبات الثمانية."}, {"t": "دعاء الاستفتاح", "icon": "🌅", "bin": 2, "why": "دعاء الاستفتاح من سنن الأقوال."}, {"t": "قول آمين", "icon": "🗣️", "bin": 2, "why": "قول آمين من سنن الصلاة."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "كم شرطًا للصلاة؟", "o": ["تسعة شروط", "خمسة شروط", "ثلاثة شروط"], "a": 0, "why": "شروط الصلاة تسعة كما في الكتاب."}, {"q": "ما معنى «الدرن» في حديث النهر؟", "o": ["الماء", "الوسخ", "الطعام"], "a": 1, "why": "الدرن: الوسخ، والصلوات الخمس يمحو الله بهنّ الخطايا."}, {"q": "أكل فصيح حبّة حلوى وهو يصلّي، فما حكم صلاته؟", "o": ["صحيحة", "صحيحة إذا كانت صغيرة", "باطلة"], "a": 2, "why": "الأكل أو الشرب من مبطلات الصلاة."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح سمع صوتًا جميلًا يؤذّن، فوجد بجانبه ورقة لغز فيها صحابيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["كنت عبدًا، فعُذّبت على الإيمان، فكنت أقول: أحدٌ أحد.", "أعتقني أبو بكر الصدّيق رضي الله عنه.", "صرت مؤذّن رسول الله ﷺ."], "options": ["سلمان الفارسيّ رضي الله عنه", "بلال بن رباح رضي الله عنه", "مصعب بن عمير رضي الله عنه"], "deep": "صبر هذا الصحابيّ على العذاب ولم يترك التوحيد. ماذا تتعلّم منه عندما يدعوك شيء إلى ترك الصلاة؟", "reveal": "أنا بلال بن رباح رضي الله عنه، مؤذّن رسول الله ﷺ! كنت أنادي الناس بصوتي الجميل إلى الصلاة. وفي الحلقة القادمة نتعلّم معًا: كيف أصلّي خطوة خطوة؟ وما فضل صلاة الجمعة والجماعة؟"}, "quiz": [{"q": "بماذا تبدأ الصلاة وبماذا تنتهي؟", "o": ["تبدأ بالتسليم وتنتهي بالتكبير", "تبدأ بالتكبير وتنتهي بالتسليم", "تبدأ بالسجود وتنتهي بالركوع"], "a": 1, "why": "الصلاة مفتتحة بالتكبير، مختتمة بالتسليم."}], "qa": [{"id": 58, "q": "ما فضلُ الصلاة؟", "a": "عن أبي هريرةَ أن رسولَ الله ﷺ قال: «أرأيتُم لو أنَّ نهرًا ببابِ أحدِكم يغتسلُ منه كلَّ يومٍ خمسَ مرات، هل يبقى من درنِهِ شيء؟» قالوا: لا يبقى من درنِهِ شيء. قال: «فذلك مثلُ الصلواتِ الخمسِ يمحو اللهُ بهنَّ الخطايا» متفق عليه. (الدرن: الوسخ)."}, {"id": 59, "q": "ما معنى الصلاة؟", "a": "الصلاة: هي التعبدُ لله بأقوالٍ وأفعالٍ مخصوصة، مفتتحةٍ بالتكبير، مختتمةٍ بالتسليم."}, {"id": 60, "q": "ما حكمُ الصلاة؟", "a": "الصلاةُ فريضةٌ على كلِّ مسلم.\nقال تعالى: ﴿إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَّوْقُوتًا﴾ [النساء: ١٠٣]."}, {"id": 61, "q": "ما حكمُ تركِ الصلاة؟", "a": "تركُ الصلاةِ كفر. قال النبيُّ ﷺ: «العهدُ الذي بيننا وبينهمُ الصلاة، فمن تركَها فقد كفر» رواه أحمد والترمذي وغيرهما."}, {"id": 62, "q": "كم صلاةً تجبُ على المسلمِ في اليومِ والليلة؟ وكم عددُ ركعاتِ كلِّ صلاة؟", "a": "خمسُ صلواتٍ في اليومِ والليلة:\n• صلاةُ الفجر: ركعتان.\n• صلاةُ الظهر: أربعُ ركعات.\n• صلاةُ العصر: أربعُ ركعات.\n• صلاةُ المغرب: ثلاثُ ركعات.\n• صلاةُ العشاء: أربعُ ركعات."}, {"id": 63, "q": "ما هي شروطُ الصلاة؟", "a": "١. الإسلام؛ فلا تصحُّ من كافر؛ لحبوطِ العملِ بالشرك. قال تعالى: ﴿لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ﴾ [الزمر: ٦٥].\n٢. العقل؛ فلا تصحُّ من مجنون.\n٣. التمييز؛ فلا تصحُّ من صغيرٍ غيرِ مميز. لقوله ﷺ: «رُفِعَ القلمُ عن ثلاث: عن النائمِ حتى يستيقظ، وعن الصغيرِ حتى يكبر، وعن المجنونِ حتى يعقلَ أو يفيق» رواه أهل السنن.\n٤. النية. في الحديث: «إنما الأعمالُ بالنيات، وإنما لكلِّ امرئٍ ما نوى» رواه البخاري.\n٥. دخولُ الوقت. قال تعالى: ﴿إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَّوْقُوتًا﴾ [النساء: ١٠٣].\n٦. الطهارةُ في رفعِ الحدث. لحديث: «لا يقبلُ اللهُ صلاةَ أحدِكم إذا أحدثَ حتى يتوضأ» متفق عليه.\n٧. التطهرُ من النجاسة. لقوله تعالى: ﴿وَثِيَابَكَ فَطَهِّرْ﴾ [المدثر: ٤].\n٨. سترُ العورة. قال تعالى: ﴿يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ﴾ [الأعراف: ٣١].\n٩. استقبالُ القبلة. قال تعالى: ﴿فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ﴾ [البقرة: ١٤٤]."}, {"id": 64, "q": "ما أركانُ الصلاة؟", "a": "هي أربعةَ عشرَ ركنًا، كما يلي:\n١. القيامُ في الفرضِ على القادر. لحديث عمرانَ بنِ حصين، عن النبيِّ ﷺ: «صلِّ قائمًا، فإن لم تستطعْ فقاعدًا، فإن لم تستطعْ فعلى جنب» رواه البخاري.\n٢. تكبيرةُ الإحرام، وهي: \"الله أكبر\". لقوله ﷺ: «إذا قمتَ إلى الصلاةِ فكبِّر» متفق عليه.\n٣. قراءةُ الفاتحة. لقوله ﷺ: «لا صلاةَ لمن لم يقرأْ بفاتحةِ الكتاب» متفق عليه.\n٤. الركوع، ويمدُّ ظهرَهُ مستويًا ويجعلُ رأسَهُ حياله.\n٥. الرفعُ منه.\n٦. الاعتدالُ قائمًا. لقوله ﷺ: «ثم اركعْ حتى تطمئنَّ راكعًا، ثم ارفعْ حتى تعتدلَ قائمًا» متفق عليه.\n٧. السجود، وتمكينُ جبهتِه، وأنفِه، وكفيه، وركبتيه، وأطرافِ أصابعِ قدميه من محلِّ سجوده.\n٨. الرفعُ من السجود.\n٩. الجلوسُ بين السجدتين. لقوله ﷺ: «ثم اسجدْ حتى تطمئنَّ ساجدًا، ثم ارفعْ حتى تطمئنَّ جالسًا» متفق عليه. (والسُّنة: أن يجلسَ مفترشًا على رجلِهِ اليسرى، وينصبَ اليمنى، ويوجهَها إلى القبلة).\n١٠. الطمأنينة، وهي السكونُ في كلِّ ركنٍ فعلي.\n١١. التشهدُ الأخير. لحديث ابنِ مسعود.\n١٢. الجلوسُ له.\n١٣. التسليمتان، وهو أن يقولَ مرتين: \"السلامُ عليكم ورحمةُ الله\".\n١٤. ترتيبُ الأركان — فلو سجدَ مثلًا قبلَ ركوعِهِ عمدًا؛ بطلتْ صلاتُه، وسهوًا؛ لزمَهُ الرجوعُ ليركعَ ثم يسجد."}, {"id": 65, "q": "ما هي واجباتُ الصلاة؟", "a": "واجباتُ الصلاة، وهي ثمانية، كما يلي:\n١. التكبيراتُ غيرُ تكبيرةِ الإحرام.\n٢. قولُ: \"سمِعَ اللهُ لمن حمِدَه\" للإمامِ والمنفرد.\n٣. قولُ: \"ربنا ولك الحمد\".\n٤. قولُ: \"سبحان ربيَ العظيم\" مرةً في الركوع.\n٥. قولُ: \"سبحان ربيَ الأعلى\" مرةً في السجود.\n٦. قولُ: \"ربِّ اغفرْ لي\" بين السجدتين.\n٧. التشهدُ الأول.\n٨. الجلوسُ للتشهدِ الأول."}, {"id": 66, "q": "ما هي سننُ الصلاة؟", "a": "سننُ الأقوال (إحدى عشرة):\n١. دعاءُ الاستفتاح: \"سبحانك اللهمَّ وبحمدك، وتبارك اسمُك، وتعالى جدُّك، ولا إله غيرُك\".\n٢. التعوذ. ٣. البسملة. ٤. قولُ: آمين. ٥. قراءةُ السورةِ بعد الفاتحة. ٦. الجهرُ بالقراءةِ للإمام.\n٧. القولُ بعد التحميد: \"ملءَ السمواتِ، وملءَ الأرض، وملءَ ما شئتَ من شيءٍ بعد\".\n٨. ما زادَ على المرةِ في تسبيحِ الركوع. ٩. ما زادَ على المرةِ في تسبيحِ السجود. ١٠. ما زادَ على المرةِ في قولِهِ بين السجدتين: \"ربِّ اغفرْ لي\".\n١١. الصلاةُ في التشهدِ الأخيرِ على آلِهِ عليهمُ السلام، والبركةُ عليه وعليهم، والدعاءُ بعده.\n\nسننُ الأفعالِ (وتسمى الهيئات):\n١. رفعُ اليدينِ مع تكبيرةِ الإحرام. ٢. وعند الركوع. ٣. وعند الرفعِ منه. ٤. وحطُّهما عقبَ ذلك. ٥. وضعُ اليمينِ على الشمال. ٦. نظرُهُ إلى موضعِ سجوده. ٧. تفرقتُهُ بين قدميهِ قائمًا. ٨. قبضُ ركبتيهِ بيديهِ مفرجتَي الأصابعِ في ركوعه، ومدُّ ظهره، وجعلُ رأسِهِ حياله. ٩. تمكينُ أعضاءِ السجودِ من الأرض، ومباشرتُها لمحلِّ السجود. ١٠. مجافاةُ عضديهِ عن جنبيه، وبطنِهِ عن فخذيه، وفخذيهِ عن ساقيه، وتفريقُهُ بين ركبتيه، وإقامةُ قدميه. ١١. الافتراشُ في الجلوسِ بين السجدتين، وفي التشهدِ الأول، والتوركُ في الثاني. ١٢. وضعُ اليدينِ على الفخذين، وفي التشهدِ يقبضُ من اليمنى الخنصرَ والبنصر، ويحلِّقُ إبهامَها مع الوسطى، ويشيرُ بسبابتِها عند ذكرِ الله. ١٣. التفاتُهُ يمينًا وشمالًا في تسليمه."}, {"id": 67, "q": "ما هي مبطلاتُ الصلاة؟", "a": "١. تركُ ركنٍ أو شرطٍ من شروطِ الصلاة.\n٢. التكلمُ عمدًا.\n٣. الأكلُ أو الشرب.\n٤. الحركاتُ الكثيرةُ المتوالية.\n٥. تركُ واجبٍ من واجباتِ الصلاةِ عمدًا."}], "dyk": ["ضربَ اللهُ بيتَ العنكبوتِ مثلاً لأوهنِ البيوت، وخيوطُه رغم ضعفِها الظاهرِ أقوى من الفولاذِ بنفسِ الوزن!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهَا عَائِشَةُ أُمُّ الْمُؤْمِنِينَ رَضِيَ اللَّهُ عَنْهَا، وَبِسَبَبِ عِقْدِهَا نَزَلَتْ آيَةُ التَّيَمُّمِ!"}, {"s": "anos", "t": "وَالْيَوْمَ: أَعْظَمُ عِبَادَةٍ بَعْدَ التَّوْحِيدِ، الصَّلَاةُ!"}, {"s": "fasih", "t": "مَا فَضْلُ الصَّلَاةِ؟"}, {"s": "anos", "t": "قَالَ النَّبِيُّ: لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، هَلْ يَبْقَى مِنْ وَسَخِهِ شَيْءٌ؟ قَالُوا: لَا. قَالَ: فَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهِنَّ الْخَطَايَا. مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "وَمَا مَعْنَى الصَّلَاةِ؟"}, {"s": "anos", "t": "التَّعَبُّدُ لِلَّهِ بِأَقْوَالٍ وَأَفْعَالٍ مَخْصُوصَةٍ، تَبْدَأُ بِالتَّكْبِيرِ، وَتَنْتَهِي بِالتَّسْلِيمِ."}, {"s": "fasih", "t": "وَمَا حُكْمُهَا؟"}, {"s": "anos", "t": "فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ فِي أَوْقَاتٍ مُحَدَّدَةٍ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ النِّسَاءِ."}, {"s": "quran", "ref": "4:103", "t": "فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًۭا مَّوْقُوتًۭا"}, {"s": "fasih", "t": "كِتَابًا مَوْقُوتًا، أَيْ: فَرْضًا فِي أَوْقَاتٍ! وَمَا حُكْمُ تَرْكِ الصَّلَاةِ؟"}, {"s": "anos", "t": "تَرْكُ الصَّلَاةِ كُفْرٌ. قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ»."}, {"s": "fasih", "t": "كَمْ صَلَاةً فِي الْيَوْمِ وَاللَّيْلَةِ؟ وَكَمْ رَكْعَةً؟"}, {"s": "anos", "t": "خَمْسٌ: الْفَجْرُ رَكْعَتَانِ، وَالظُّهْرُ أَرْبَعٌ، وَالْعَصْرُ أَرْبَعٌ، وَالْمَغْرِبُ ثَلَاثٌ، وَالْعِشَاءُ أَرْبَعٌ. الْمَجْمُوعُ سَبْعَ عَشْرَةَ!"}, {"s": "fasih", "t": "مَا شُرُوطُ الصَّلَاةِ؟"}, {"s": "anos", "t": "تِسْعَةٌ: الْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ، وَالنِّيَّةُ، وَدُخُولُ الْوَقْتِ، وَالطَّهَارَةُ مِنَ الْحَدَثِ، وَالتَّطَهُّرُ مِنَ النَّجَاسَةِ، وَسَتْرُ الْعَوْرَةِ، وَاسْتِقْبَالُ الْقِبْلَةِ."}, {"s": "fasih", "t": "وَأَرْكَانُ الصَّلَاةِ؟"}, {"s": "anos", "t": "أَرْبَعَةَ عَشَرَ: الْقِيَامُ لِلْقَادِرِ، وَتَكْبِيرَةُ الْإِحْرَامِ، وَالْفَاتِحَةُ، وَالرُّكُوعُ، وَالرَّفْعُ مِنْهُ، وَالِاعْتِدَالُ، وَالسُّجُودُ عَلَى الْأَعْضَاءِ السَّبْعَةِ، وَالرَّفْعُ مِنْهُ، وَالْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ،"}, {"s": "anos", "t": "وَالطُّمَأْنِينَةُ، وَالتَّشَهُّدُ الْأَخِيرُ، وَالْجُلُوسُ لَهُ، وَالتَّسْلِيمَتَانِ، وَتَرْتِيبُ الْأَرْكَانِ."}, {"s": "fasih", "t": "وَوَاجِبَاتُ الصَّلَاةِ؟"}, {"s": "anos", "t": "ثَمَانِيَةٌ: التَّكْبِيرَاتُ غَيْرُ تَكْبِيرَةِ الْإِحْرَامِ، وَسَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، وَرَبَّنَا وَلَكَ الْحَمْدُ، وَسُبْحَانَ رَبِّيَ الْعَظِيمِ، وَسُبْحَانَ رَبِّيَ الْأَعْلَى، وَرَبِّ اغْفِرْ لِي، وَالتَّشَهُّدُ الْأَوَّلُ، وَالْجُلُوسُ لَهُ."}, {"s": "fasih", "t": "وَسُنَنُ الصَّلَاةِ؟"}, {"s": "anos", "t": "كَثِيرَةٌ، مِنْ أَقْوَالِهَا: دُعَاءُ الِاسْتِفْتَاحِ، وَالتَّعَوُّذُ، وَالْبَسْمَلَةُ، وَآمِينَ، وَسُورَةٌ بَعْدَ الْفَاتِحَةِ. وَمِنْ أَفْعَالِهَا: رَفْعُ الْيَدَيْنِ، وَوَضْعُ الْيُمْنَى عَلَى الْيُسْرَى، وَالنَّظَرُ إِلَى مَوْضِعِ السُّجُودِ."}, {"s": "fasih", "t": "وَمَا مُبْطِلَاتُ الصَّلَاةِ؟"}, {"s": "anos", "t": "تَرْكُ رُكْنٍ أَوْ شَرْطٍ، وَالْكَلَامُ عَمْدًا، وَالْأَكْلُ أَوِ الشُّرْبُ، وَالْحَرَكَاتُ الْكَثِيرَةُ الْمُتَوَالِيَةُ، وَتَرْكُ وَاجِبٍ عَمْدًا."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ بَيْتُ الْعَنْكَبُوتِ أَوْهَنُ الْبُيُوتِ، لَكِنَّ خُيُوطَهُ أَقْوَى مِنَ الْفُولَاذِ بِنَفْسِ الْوَزْنِ!"}, {"s": "anos", "t": "الْآنَ «نَشِيدُ الرَّكَعَاتِ»: ارْفَعُوا أَصَابِعَكُمْ بِعَدَدِ رَكَعَاتِ كُلِّ صَلَاةٍ، ثُمَّ طَبِّقُوا رَكْعَةً بِطُمَأْنِينَةٍ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَافْعَلُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد الركعات السبع عشرة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أَلْعَبُ مَعَ أَصْدِقَائِي وَأَذَّنَ الْعَصْرُ. أ: أُكْمِلُ وَأُصَلِّي بَعْدَ الْمَغْرِبِ. ب: أَتَوَضَّأُ وَأُصَلِّي فِي الْوَقْتِ. ج: أُصَلِّي بِسُرْعَةٍ بِلَا طُمَأْنِينَةٍ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: صلاة العصر واللعب"}, {"s": "anos", "t": "«أ» تَأْخِيرٌ عَنِ الْوَقْتِ، وَ«ج» تَرْكٌ لِرُكْنِ الطُّمَأْنِينَةِ. وَالصَّحِيحُ «ب»، ثُمَّ تَعُودُ لِلَّعِبِ!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: كَمْ رَكْعَةً فِي صَلَاةِ الْمَغْرِبِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "ثَلَاثٌ! وَقِرَاءَةُ الْفَاتِحَةِ: رُكْنٌ أَمْ سُنَّةٌ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "رُكْنٌ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: عُذِّبْتُ عَلَى الْإِيمَانِ فَكُنْتُ أَقُولُ: أَحَدٌ أَحَدٌ. أَعْتَقَنِي أَبُو بَكْرٍ، وَصِرْتُ مُؤَذِّنَ رَسُولِ اللَّهِ."}, {"s": "anos", "t": "سَلْمَانُ، أَمْ بِلَالٌ، أَمْ مُصْعَبٌ رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «جَدْوَلُ صَلَوَاتِي»: مُلْصَقٌ لِكُلِّ صَلَاةٍ فِي وَقْتِهَا."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مُخْتَبَرُ الصَّلَاةِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 9, "title": "كيف أصلّي؟ والجمعة والجماعة", "season": 1, "goals": ["fiqh"], "hook": "أهلًا يا أصدقاء! فصيح يرفرف ويقول: «الله أكبر… الله أكبر! أنوس، أنا أعرف أنّ الصلاة مهمّة جدًّا، لكن كيف نصلّي خطوةً خطوة؟ ولماذا يلبس الناس أجمل ثيابهم يوم الجمعة؟». هيّا نتعلّم معًا!", "sections": [{"h": "من القبلة إلى التسليم: خطوات الصلاة", "p": ["أوّلًا: أقف و<b>أستقبل القبلة</b> بجسمي كلّه، ولا ألتفت. ثم <b>أنوي بقلبي</b>، ولا أقول النيّة بلساني.", "ثم أكبّر <b>تكبيرة الإحرام</b>: «الله أكبر»، وأرفع يديّ إلى حذو كتفيّ. ثم أضع يدي اليمنى على ظهر يدي اليسرى فوق صدري.", "ثم أقرأ دعاء الاستفتاح، وأتعوّذ، وأقرأ <b>الفاتحة</b> وأقول: «آمين»، ثم أقرأ ما تيسّر من القرآن.", "ثم أركع وأقول: «<b>سبحان ربيَ العظيم</b>» ثلاثًا، وأرفع قائلًا: «سمع الله لمن حمده، ربنا ولك الحمد». ثم أسجد على <b>سبعة أعضاء</b>: الجبهة مع الأنف، والكفّين، والركبتين، وأطراف القدمين، وأقول: «<b>سبحان ربيَ الأعلى</b>» ثلاثًا.", "وبين السجدتين أجلس وأقول: «ربِّ اغفر لي، وارحمني، واهدني، وارزقني، واجبرني، وعافني». وفي آخر الصلاة أقرأ <b>التشهّد</b>، ثم أسلّم عن يميني وعن يساري: «السلام عليكم ورحمة الله».", "فصيح يسأل: «وإذا كانت الصلاة أربع ركعات مثل الظهر؟». أنوس: أجلس بعد الركعتين للتشهّد الأوّل، ثم أقوم وأكمل بالفاتحة فقط، وأجلس في التشهّد الأخير ثم أسلّم."], "board": ["القبلة والنيّة", "التكبير والفاتحة", "الركوع والسجود", "التشهّد والتسليم"]}, {"h": "بعد السلام: أذكار وهدايا", "p": ["الصلاة انتهت؟ لا تقم بسرعة! قل: «<b>أستغفر الله</b>» ثلاث مرّات، ثم: «اللهمّ أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام».", "ثم سبّح: «سبحان الله» 33، و«الحمد لله» 33، و«الله أكبر» 33، وتمام المئة: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير». واقرأ <b>آية الكرسي</b> مرّة، والإخلاص والمعوّذتين.", "و<b>السنن الرواتب</b> صلوات نصلّيها مع الفرائض: ركعتان قبل الفجر، وأربع قبل الظهر، وركعتان بعده، وركعتان بعد المغرب، وركعتان بعد العشاء. المجموع <b>12 ركعة</b>، ومن صلّاها في اليوم والليلة <b>بنى الله له بيتًا في الجنّة</b>."], "board": ["أستغفر الله ×3", "33 + 33 + 33", "12 ركعة = بيت في الجنّة"]}, {"h": "يوم الجمعة: عيد الأسبوع", "p": ["<b>أفضل أيام الأسبوع يوم الجمعة</b>. فيه خُلق آدم عليه السلام، ونُكثر فيه من الصلاة على النبيّ ﷺ.", "و<b>صلاة الجمعة فرض</b> على كل مسلم، ذكر، بالغ، عاقل، مقيم. وهي <b>ركعتان</b> يجهر فيهما الإمام بالقراءة، وقبلهما <b>خطبتان</b>. ولا يجوز تركها إلا بعذر شرعي.", "أنوس يحكي: «يوم الجمعة أذهب مع أبي، مع أنّي ما زلت صغيرًا، لأتعوّد عليها. نغتسل، ونتطيّب، ونلبس أحسن الثياب، ونبكّر إلى المسجد ماشيين، ثم نسكت ونستمع للخطبة».", "ومن سنن الجمعة أيضًا: قراءة <b>سورة الكهف</b>، والإكثار من الصلاة على النبيّ ﷺ، والدعاء في ساعة الإجابة."], "board": ["أفضل يوم: الجمعة", "ركعتان + خطبتان", "غُسل، طيب، ثياب حسنة، تبكير"]}, {"h": "الجماعة والخشوع", "p": ["فصيح يحسب بأصابعه: «إذا صلّيت وحدي أخذت درجة، وإذا صلّيت مع الجماعة؟». أنوس: <b>صلاة الجماعة أفضل من صلاة الواحد بسبع وعشرين درجة</b>!", "و<b>الخشوع</b> هو: <b>حضور القلب، وسكون الجوارح</b>. يعني: قلبي يفكّر في الصلاة، ويداي ورجلاي ساكنة، لا ألعب بثيابي، ولا أنظر يمينًا وشمالًا.", "جرّب: قبل أن تكبّر، تذكّر أنّك تقف بين يدي الله، وافهم معنى «سبحان ربيَ العظيم». هكذا تصير صلاتك أجمل."], "board": ["الجماعة = 27 درجة", "الخشوع: قلب حاضر وجسم ساكن"]}], "summary": ["نصلّي بالترتيب: القبلة والنيّة، التكبير، الفاتحة، الركوع، السجود، التشهّد، ثم التسليم.", "السنن الرواتب 12 ركعة ببيت في الجنّة، ويوم الجمعة أفضل الأيام، وصلاة الجمعة ركعتان بعد خطبتين.", "صلاة الجماعة أفضل بسبع وعشرين درجة، والخشوع حضور القلب وسكون الجوارح."], "islam": {"intro": "قال الله تعالى يمدح المؤمنين المفلحين:", "text": "فالخشوع سرّ الصلاة الجميلة: قلب حاضر، وجسم هادئ، ولسان يفهم ما يقول.", "ayah": {"text": "ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ", "src": "سُورَةُ المُؤۡمِنُونَ: ٢"}, "hadith": {"text": "صلاة الجماعة أفضل من صلاة الفذّ بسبع وعشرين درجة", "source": "رواه مسلم عن ابن عمر رضي الله عنهما"}}, "home": {"title": "جدول بيت الجنّة", "goal": "أن يحافظ الطفل على السنن الرواتب وأذكار ما بعد الصلاة أسبوعًا كاملًا.", "materials": ["ورقة كبيرة", "ألوان", "ملصقات نجوم"], "steps": ["ارسم بيتًا كبيرًا فيه 12 نافذة، كل نافذة ركعة من السنن الرواتب.", "كل يوم، لوّن النافذة عندما تصلّي ركعاتها: قبل الفجر، قبل الظهر وبعده، بعد المغرب، بعد العشاء.", "بعد كل صلاة، قل الأذكار مع أحد والديك: أستغفر الله ثلاثًا، والتسبيح 33.", "يوم الجمعة: اغتسل، والبس أحسن ثيابك، واقرأ أو استمع لسورة الكهف مع أسرتك."], "parent": "صلّوا مع أطفالكم ليقلّدوكم، وصحّحوا الحركات بلطف. وخذوا الأولاد إلى صلاة الجمعة والجماعة ليتعوّدوا عليها."}, "online": {"title": "مدرسة فصيح للصلاة", "intro": "ساعد فصيحًا على ترتيب خطوات الصلاة، وصِل كل حركة بذكرها!", "steps": [{"type": "order", "title": "رتّب خطوات الصلاة", "prompt": "رتّب الخطوات من الأولى إلى الأخيرة باستعمال الأسهم.", "items": ["أستقبل القبلة وأنوي بقلبي", "أكبّر تكبيرة الإحرام: الله أكبر", "أقرأ الفاتحة ثم ما تيسّر من القرآن", "أركع وأقول: سبحان ربيَ العظيم", "أسجد وأقول: سبحان ربيَ الأعلى", "أجلس للتشهّد", "أسلّم عن يميني وعن يساري"]}, {"type": "match", "title": "صِل الحركة بذكرها", "prompt": "اختر الحركة، ثم الذكر الذي نقوله فيها.", "pairs": [["الركوع", "سبحان ربيَ العظيم"], ["السجود", "سبحان ربيَ الأعلى"], ["الرفع من الركوع", "سمع الله لمن حمده، ربنا ولك الحمد"], ["الجلسة بين السجدتين", "ربِّ اغفر لي وارحمني"], ["بعد السلام", "أستغفر الله ثلاثًا"]]}, {"type": "quiz", "title": "تحدّي الجمعة", "items": [{"q": "أيّ هذه من سنن يوم الجمعة؟", "o": ["النوم حتى الظهر", "قراءة سورة الكهف", "لبس أقدم الثياب"], "a": 1, "why": "من قرأ الكهف يوم الجمعة أضاء له من النور ما بين الجمعتين."}, {"q": "على كم عضوًا نسجد؟", "o": ["ثلاثة", "خمسة", "سبعة"], "a": 2, "why": "الجبهة مع الأنف، والكفّان، والركبتان، وأطراف القدمين."}, {"q": "كيف ننوي الصلاة؟", "o": ["بالقلب بلا نطق", "بالصراخ بصوت عالٍ", "بالكتابة على ورقة"], "a": 0, "why": "ينوي المصلّي الصلاة بقلبه بدون نطق النيّة."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عند باب المسجد، فيها صحابيّ يتكلّم عن نفسه. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا صحابيّ من أصحاب النبيّ ﷺ.", "أنا أكثر الصحابة رواية للحديث.", "دعا لي النبيّ ﷺ بالحفظ، فما نسيت شيئًا سمعته."], "options": ["عبد الله بن عباس رضي الله عنهما", "أبو هريرة رضي الله عنه", "زيد بن ثابت رضي الله عنه"], "deep": "لماذا نحتاج إلى من يحفظ أحاديث النبيّ ﷺ؟ وكيف عرفنا خطوات الصلاة لولا هذه الأحاديث؟", "reveal": "أنا أبو هريرة رضي الله عنه! ومن الأحاديث التي رويتها: «من صام رمضان إيمانًا واحتسابًا غُفر له ما تقدّم من ذنبه». وفي الحلقة القادمة نتعلّم الصيام، والزكاة، والحجّ، والعمرة."}, "quiz": [{"q": "ماذا نقول في الركوع؟", "o": ["سبحان ربيَ الأعلى", "سبحان ربيَ العظيم", "آمين"], "a": 1, "why": "في الركوع: «سبحان ربيَ العظيم» ثلاثًا، وفي السجود: «سبحان ربيَ الأعلى»."}], "qa": [{"id": 68, "q": "كيف يصلي المسلم؟", "a": "١. يستقبلُ القبلةَ بجميعِ بدنه، بدون انحرافٍ ولا التفات.\n٢. ثم ينوي الصلاةَ بقلبِهِ بدون نطقِ النية.\n٣. ثم يكبِّرُ تكبيرةَ الإحرام: \"الله أكبر\"، ويرفعُ يديه إلى حذوِ منكبيه.\n٤. ثم يضعُ كفَّ يدِهِ اليمنى على ظهرِ كفِّ اليسرى فوقَ صدره.\n٥. ثم يستفتح: \"اللهم باعِدْ بيني وبين خطاياي كما باعدتَ بين المشرقِ والمغرب، اللهم نقِّني من خطاياي كما يُنقّى الثوبُ الأبيضُ من الدنس، اللهم اغسلني من خطاياي بالماءِ والثلجِ والبرد\". أو: \"سبحانك اللهمَّ وبحمدك...\".\n٦. ثم يتعوذ: \"أعوذ بالله من الشيطان الرجيم\".\n٧. ثم يسمِّي ويقرأ الفاتحة، ثم يقول: \"آمين\".\n٨. ثم يقرأ ما تيسَّرَ من القرآن، ويطيلُ القراءةَ في صلاةِ الصبح.\n٩. ثم يركع مكبِّرًا، ويرفعُ يديه، ويمدُّ ظهرَه، ويضعُ يديه على ركبتيه مفرِّجًا أصابعه.\n١٠. ويقول في ركوعه: \"سبحان ربيَ العظيم\" ثلاثًا.\n١١. ثم يرفعُ رأسَه: \"سمِعَ اللهُ لمن حمِدَه\" (والمأمومُ يقول: \"ربنا ولك الحمد\").\n١٢. ثم يقول: \"ربنا ولك الحمد، ملءَ السمواتِ والأرض، وملءَ ما شئتَ من شيءٍ بعد\".\n١٣. ثم يسجدُ مكبِّرًا على أعضائِهِ السبعة (الجبهةُ والأنف، والكفان، والركبتان، وأطرافُ القدمين)، ويجافي عضديهِ عن جنبيه.\n١٤. ويقول: \"سبحان ربيَ الأعلى\" ثلاثًا.\n١٥. ثم يرفعُ رأسَه مكبِّرًا.\n١٦. ثم يجلسُ بين السجدتين على قدمِهِ اليسرى، وينصبُ اليمنى.\n١٧. ويقول: \"ربِّ اغفرْ لي، وارحمني، واهدني، وارزقني، واجبرني، وعافني\".\n١٨. ثم يسجدُ السجدةَ الثانيةَ كالأولى.\n١٩. ثم يقومُ للركعةِ الثانيةِ كالأولى، إلا أنه لا يستفتحُ فيها.\n٢٠. ثم يجلسُ بعد الركعةِ الثانية.\n٢١. ويقرأُ التشهد: \"التحياتُ لله والصلواتُ والطيبات، السلامُ عليك أيها النبيُّ ورحمةُ الله وبركاته، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا الله، وأشهدُ أن محمدًا عبدُهُ ورسوله، اللهم صلِّ على محمدٍ وعلى آلِ محمد... إنك حميدٌ مجيد\"، ثم يستعيذُ ويدعو.\n٢٢. ثم يسلِّمُ عن يمينِه: \"السلامُ عليكم ورحمةُ الله\"، وعن يسارِهِ كذلك.\n٢٣. وإذا كانت الصلاةُ ثلاثيةً أو رباعية؛ وقفَ عند منتهى التشهدِ الأول.\n٢٤. ثم ينهضُ قائمًا مكبِّرًا، رافعًا يديه.\n٢٥. ثم يصلي ما بقيَ على صفةِ الركعةِ الثانية، مقتصرًا على قراءةِ الفاتحة.\n٢٦. ثم يجلسُ متورِّكًا في التشهدِ الأخير.\n٢٧. ويقرأُ التشهدَ كلَّه.\n٢٨. ثم يسلِّمُ عن يمينِهِ ويسارِه."}, {"id": 69, "q": "ما تقولُ من الأذكارِ بعد السلامِ من الصلاة؟", "a": "• \"أستغفرُ الله\" ثلاثَ مرات.\n• \"اللهم أنت السلام، ومنك السلام، تباركتَ يا ذا الجلالِ والإكرام\".\n• \"لا إله إلا الله وحده لا شريك له، له الملكُ وله الحمد، وهو على كل شيءٍ قدير، اللهم لا مانعَ لما أعطيت، ولا معطيَ لما منعت، ولا ينفعُ ذا الجدِّ منك الجد\".\n• \"لا إله إلا الله وحده لا شريك له... لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبدُ إلا إياه، له النعمةُ وله الفضلُ وله الثناءُ الحسن، لا إله إلا الله مخلصين له الدينَ ولو كره الكافرون\".\n• \"سبحان الله\" ثلاثًا وثلاثين، \"الحمد لله\" ثلاثًا وثلاثين، \"الله أكبر\" ثلاثًا وثلاثين، ثم يقول تمامَ المائة: \"لا إله إلا الله وحده لا شريك له، له الملكُ وله الحمد، وهو على كل شيءٍ قدير\".\n• ويقرأ سورةَ الإخلاصِ والمعوذات، ثلاثَ مراتٍ بعد الفجرِ والمغرب، ومرةً بعد باقي الصلوات.\n• ويقرأ آيةَ الكرسي مرةً واحدة."}, {"id": 70, "q": "ما السننُ الرواتب؟ وما فضلها؟", "a": "• ركعتان قبل الفجر.\n• أربعُ ركعاتٍ قبل الظهر.\n• ركعتان بعد الظهر.\n• ركعتان بعد المغرب.\n• ركعتان بعد العشاء.\nفضلها: قال النبيُّ ﷺ: «من صلّى في اليومِ والليلةِ اثنتي عشرةَ ركعةً تطوعًا بنى اللهُ له بيتًا في الجنة» رواه مسلم وأحمد وغيرهما."}, {"id": 71, "q": "ما أفضلُ أيامِ الأسبوع؟", "a": "يومُ الجمعة، قال النبيُّ ﷺ: «إنَّ من أفضلِ أيامِكم يومَ الجمعة، فيه خُلِقَ آدم، وفيه قُبِض، وفيه النفخة، وفيه الصعقة، فأكثِروا عليَّ من الصلاةِ فيه؛ فإنَّ صلاتَكم معروضةٌ عليَّ» قالوا: يا رسولَ الله، وكيف تُعرَضُ صلاتُنا عليك وقد أرِمتَ؟ — يعنون بَليت — فقال: «إنَّ اللهَ عزَّ وجلَّ حرَّمَ على الأرضِ أجسادَ الأنبياء» رواه أبو داود وغيره."}, {"id": 72, "q": "ما حكمُ صلاةِ الجمعة؟", "a": "فرضُ عينٍ على كلِّ مسلمٍ، ذكرٍ، بالغٍ، عاقلٍ، مقيم.\nقال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ﴾ [الجمعة: ٩]."}, {"id": 73, "q": "كم عددُ ركعاتِ صلاةِ الجمعة؟", "a": "ركعتان يجهرُ فيهما الإمامُ بالقراءة، حيث تتقدَّمُهما خطبتان معروفتان."}, {"id": 74, "q": "هل يجوزُ التخلفُ عن صلاةِ الجمعة؟", "a": "لا يجوزُ التخلفُ عن صلاةِ الجمعةِ إلا من عذرٍ شرعي، وجاء عن النبيِّ ﷺ قوله: «من تركَ ثلاثَ جُمَعٍ تهاونًا بها؛ طبعَ اللهُ على قلبِه» رواه أبو داود وغيره."}, {"id": 75, "q": "اذكرْ سننَ يومِ الجمعة.", "a": "١. الاغتسال. لقوله ﷺ: «غسلُ يومِ الجمعةِ واجبٌ على كلِّ محتلم» رواه البخاري.\n٢. التطيب. لحديث: «حقٌّ على المسلمين أن يغتسلوا يومَ الجمعة، وليمسَّ أحدُهم من طِيبِ أهله» رواه أحمد والترمذي.\n٣. لبسُ أحسنِ الثياب. لحديث: «ما على أحدِكم إن وجدَ سعةً أن يتخذَ ثوبينِ لجمعتِه، سوى ثوبَي مِهنتِه» رواه ابن ماجه ومالك.\n٤. التبكيرُ إلى المسجد.\n٥. الذهابُ إلى المسجدِ ماشيًا. لحديث: «من اغتسلَ يومَ الجمعة، وغسَّل، وبكَّر، وابتكر، ودنا، واستمع، وأنصت كان له بكلِّ خطوةٍ يخطوها أجرُ سنةٍ صيامِها وقيامِها» رواه الترمذي والنسائي.\n٦. الإكثارُ من الصلاةِ على النبيِّ ﷺ.\n٧. قراءةُ سورةِ الكهف. لحديث: «من قرأ سورةَ الكهفِ يومَ الجمعة، أضاءَ له من النورِ ما بين الجمعتين» رواه الحاكم وغيره.\n٨. تحرّي ساعةِ إجابةِ الدعاء. للحديث: «فيه ساعةٌ لا يوافقُها عبدٌ مسلمٌ، وهو قائمٌ يصلي يسألُ اللهَ تعالى شيئًا، إلا أعطاهُ إياه» متفق عليه."}, {"id": 76, "q": "ما فضلُ صلاةِ الجماعة؟", "a": "عن عبدِ اللهِ بنِ عمرَ رضي الله عنهما، أن رسولَ الله ﷺ قال: «صلاةُ الجماعةِ أفضلُ من صلاةِ الفذِّ بسبعٍ وعشرينَ درجة» رواه مسلم. (الفذُّ: المنفرد)."}, {"id": 77, "q": "ما هو الخشوعُ في الصلاة؟", "a": "هو حضورُ القلبِ وسكونُ الجوارحِ فيها.\nقال تعالى: ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ﴾ [المؤمنون: ١–٢]."}], "dyk": ["قال النبيُّ ﷺ إن للعينِ حقاً في النوم، والعلمُ يؤكِّدُ أن النومَ ضروريٌّ لراحةِ الدماغِ والجسم."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ بِلَالُ بْنُ رَبَاحٍ رَضِيَ اللَّهُ عَنْهُ!"}, {"s": "fasih", "t": "كَيْفَ يُصَلِّي الْمُسْلِمُ؟"}, {"s": "anos", "t": "أَسْتَقْبِلُ الْقِبْلَةَ، وَأَنْوِي بِقَلْبِي، وَأُكَبِّرُ رَافِعًا يَدَيَّ، وَأَضَعُ الْيُمْنَى عَلَى الْيُسْرَى فَوْقَ صَدْرِي، ثُمَّ أَسْتَفْتِحُ وَأَتَعَوَّذُ وَأَقْرَأُ الْفَاتِحَةَ، ثُمَّ مَا تَيَسَّرَ."}, {"s": "anos", "t": "ثُمَّ أَرْكَعُ وَأَقُولُ: سُبْحَانَ رَبِّيَ الْعَظِيمِ ثَلَاثًا، وَأَرْفَعُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. ثُمَّ أَسْجُدُ: سُبْحَانَ رَبِّيَ الْأَعْلَى ثَلَاثًا."}, {"s": "anos", "t": "وَبَيْنَ السَّجْدَتَيْنِ: رَبِّ اغْفِرْ لِي وَارْحَمْنِي. وَبَعْدَ الرَّكْعَتَيْنِ أَتَشَهَّدُ، وَفِي الرُّبَاعِيَّةِ أَقُومُ وَأَقْرَأُ الْفَاتِحَةَ فَقَطْ، ثُمَّ التَّشَهُّدُ الْأَخِيرُ وَالتَّسْلِيمُ."}, {"s": "fasih", "t": "وَمَاذَا أَقُولُ بَعْدَ السَّلَامِ؟"}, {"s": "anos", "t": "أَسْتَغْفِرُ اللَّهَ ثَلَاثًا، وَاللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ. ثُمَّ أُسَبِّحُ وَأَحْمَدُ وَأُكَبِّرُ ثَلَاثًا وَثَلَاثِينَ، وَأَقْرَأُ آيَةَ الْكُرْسِيِّ وَالْمُعَوِّذَاتِ."}, {"s": "fasih", "t": "مَا السُّنَنُ الرَّوَاتِبُ؟ وَمَا فَضْلُهَا؟"}, {"s": "anos", "t": "رَكْعَتَانِ قَبْلَ الْفَجْرِ، وَأَرْبَعٌ قَبْلَ الظُّهْرِ، وَرَكْعَتَانِ بَعْدَهُ، وَبَعْدَ الْمَغْرِبِ، وَبَعْدَ الْعِشَاءِ: اثْنَتَا عَشْرَةَ رَكْعَةً، مَنْ صَلَّاهَا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ."}, {"s": "fasih", "t": "مَا أَفْضَلُ أَيَّامِ الْأُسْبُوعِ؟"}, {"s": "anos", "t": "يَوْمُ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَنُكْثِرُ فِيهِ الصَّلَاةَ عَلَى النَّبِيِّ."}, {"s": "fasih", "t": "وَمَا حُكْمُ صَلَاةِ الْجُمُعَةِ؟ وَكَمْ رَكْعَةً؟"}, {"s": "anos", "t": "فَرْضُ عَيْنٍ عَلَى كُلِّ مُسْلِمٍ ذَكَرٍ بَالِغٍ عَاقِلٍ مُقِيمٍ. وَهِيَ رَكْعَتَانِ يَجْهَرُ فِيهِمَا الْإِمَامُ، قَبْلَهُمَا خُطْبَتَانِ."}, {"s": "fasih", "t": "هَلْ يَجُوزُ التَّخَلُّفُ عَنْهَا؟"}, {"s": "anos", "t": "لَا، إِلَّا مِنْ عُذْرٍ شَرْعِيٍّ؛ فَمَنْ تَرَكَ ثَلَاثَ جُمَعٍ تَهَاوُنًا طَبَعَ اللَّهُ عَلَى قَلْبِهِ."}, {"s": "fasih", "t": "وَسُنَنُ يَوْمِ الْجُمُعَةِ؟"}, {"s": "anos", "t": "الِاغْتِسَالُ، وَالتَّطَيُّبُ، وَلُبْسُ أَحْسَنِ الثِّيَابِ، وَالتَّبْكِيرُ مَاشِيًا، وَالْإِكْثَارُ مِنَ الصَّلَاةِ عَلَى النَّبِيِّ، وَقِرَاءَةُ سُورَةِ الْكَهْفِ، وَتَحَرِّي سَاعَةِ الْإِجَابَةِ."}, {"s": "fasih", "t": "وَمَا فَضْلُ صَلَاةِ الْجَمَاعَةِ؟"}, {"s": "anos", "t": "قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «صَلَاةُ الْجَمَاعَةِ أَفْضَلُ مِنْ صَلَاةِ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً»، رَوَاهُ مُسْلِمٌ. وَالْفَذُّ: الْمُنْفَرِدُ."}, {"s": "fasih", "t": "وَمَا الْخُشُوعُ فِي الصَّلَاةِ؟"}, {"s": "anos", "t": "حُضُورُ الْقَلْبِ، وَسُكُونُ الْجَوَارِحِ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ الْمُؤْمِنُونَ."}, {"s": "quran", "ref": "23:2", "t": "ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ"}, {"s": "fasih", "t": "الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ! قَلْبٌ حَاضِرٌ، وَجِسْمٌ هَادِئٌ."}, {"s": "anos", "t": "هَلْ تَعْلَمُ؟ أَخْبَرَنَا النَّبِيُّ أَنَّ لِلْعَيْنِ حَقًّا فِي النَّوْمِ، وَالْعِلْمُ يُؤَكِّدُ أَنَّ النَّوْمَ ضَرُورِيٌّ لِرَاحَةِ الدِّمَاغِ وَالْجِسْمِ."}, {"s": "fasih", "t": "الْآنَ «صَلَاةُ أَنُوس التَّعْلِيمِيَّةُ»: طَبِّقُوا الْخُطُوَاتِ بِبُطْءٍ، وَعُدُّوا أَعْضَاءَ السُّجُودِ السَّبْعَةَ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَافْعَلُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: صلاة أنوس التعليمية خطوة خطوة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أَنُوس يَلْعَبُ، وَأَذَّنَ الْعَصْرُ، وَأَبُوهُ ذَاهِبٌ لِلْمَسْجِدِ. أ: يُصَلِّي وَحْدَهُ آخِرَ الْوَقْتِ. ب: يَذْهَبُ مَعَ أَبِيهِ لِلْجَمَاعَةِ. ج: يُصَلِّي بِسُرْعَةٍ لِيَعُودَ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: صوت الأذان والمباراة"}, {"s": "anos", "t": "«أ» يُفَوِّتُ أَجْرَ الْجَمَاعَةِ، وَ«ج» يَذْهَبُ بِالْخُشُوعِ. وَالصَّحِيحُ «ب»!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَاذَا نَقُولُ فِي الرُّكُوعِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "سُبْحَانَ رَبِّيَ الْعَظِيمِ! وَكَمْ رَكْعَةً فِي صَلَاةِ الْجُمُعَةِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "رَكْعَتَانِ بَعْدَ خُطْبَتَيْنِ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا أَكْثَرُ الصَّحَابَةِ رِوَايَةً لِلْحَدِيثِ، دَعَا لِيَ النَّبِيُّ بِالْحِفْظِ."}, {"s": "anos", "t": "ابْنُ عَبَّاسٍ، أَمْ أَبُو هُرَيْرَةَ، أَمْ زَيْدُ بْنُ ثَابِتٍ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «بَيْتُ الْجَنَّةِ»: لَوِّنُوا نَافِذَةً لِكُلِّ رَكْعَةٍ مِنَ الرَّوَاتِبِ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مَدْرَسَةُ فَصِيح لِلصَّلَاةِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 10, "title": "الزكاة والصيام والحجّ والعمرة", "season": 1, "goals": ["fiqh"], "hook": "أهلًا يا أصدقاء! اليوم حلقة «مسابقة أنوس»! فصيح يحمل حصّالة وتمرة وصورة الكعبة ويقول: «ما علاقة هذه الأشياء الثلاثة ببعضها؟». تعالوا نكتشف: الزكاة، والصيام، والحجّ والعمرة!", "sections": [{"h": "الزكاة والصدقة: مال يكبر بالعطاء", "p": ["<b>الزكاة</b> حقّ واجب في مال خاصّ، لناس مخصوصين، في وقت مخصوص. وهي <b>ركن من أركان الإسلام</b>: تُؤخذ من الغنيّ وتُعطى للفقير.", "و<b>الصدقة المستحبّة</b> شيء آخر: هي أن تتصدّق بأيّ شيء في الخير، في أيّ وقت. مثل: أن تعطي صديقك نصف شطيرتك، أو تضع درهمًا في صندوق المسجد.", "فصيح يسأل: «إذا أعطيت من مالي، أليس ينقص؟». أنوس يضحك: الله يضاعف الصدقة أضعافًا كثيرة، ويبارك في المال!"], "board": ["الزكاة: واجبة، ركن", "الصدقة: مستحبّة، في أيّ وقت"]}, {"h": "الصيام: صبر جميل من الفجر إلى المغرب", "p": ["<b>الصيام</b>: أن نتعبّد لله بالإمساك عن المفطرات <b>من طلوع الفجر إلى غروب الشمس</b>، مع النيّة.", "وهو نوعان: <b>صيام واجب</b> مثل صيام <b>رمضان</b>، وهو ركن من أركان الإسلام. و<b>صيام غير واجب</b>: مثل صيام الاثنين والخميس، وثلاثة أيام من كل شهر، وأفضلها <b>أيام البيض: 13 و14 و15</b> من الشهر القمري.", "ومن صام رمضان إيمانًا واحتسابًا <b>غُفر له ما تقدّم من ذنبه</b>. ومن صام يومًا في سبيل الله باعد الله وجهه عن النار سبعين خريفًا، أي سبعين سنة!", "<b>مفسدات الصوم</b> ثلاثة: الأكل والشرب <b>عمدًا</b>، والقيء <b>عمدًا</b>، والردّة عن الإسلام. أمّا من نسي فأكل، فليُتمّ صومه.", "و<b>سنن الصيام</b>: تعجيل الفطر، والسحور وتأخيره، والزيادة في الخير، وأن يقول الصائم إذا شُتم: «إني صائم»، والدعاء عند الفطر، والفطر على رطب أو تمر، فإن لم يجد فعلى ماء."], "board": ["من الفجر إلى المغرب", "مفسدات: أكل/شرب عمدًا، قيء عمدًا، ردّة", "أفطر على تمر"]}, {"h": "الحجّ والعمرة: رحلة إلى بيت الله", "p": ["<b>الحجّ</b>: التعبّد لله بقصد بيته الحرام لأعمال مخصوصة <b>في وقت مخصوص</b>، وهو واجب على من استطاع. و<b>العمرة</b> مثله، لكنّها تكون <b>في أيّ وقت</b>.", "<b>أركان الحجّ أربعة</b>: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة.", "<b>أركان العمرة ثلاثة</b>: الإحرام، والطواف بالبيت، والسعي بين الصفا والمروة.", "فصيح يلاحظ: «الوقوف بعرفة في الحجّ فقط!». صحيح يا فصيح. ومن حجّ لله فلم يرفث ولم يفسق، <b>رجع كيوم ولدته أمّه</b>: بلا ذنوب، كصفحة بيضاء!"], "board": ["الحجّ: 4 أركان", "العمرة: 3 أركان", "عرفة في الحجّ فقط"]}, {"h": "الجهاد في سبيل الله", "p": ["<b>الجهاد</b>: بذل الجهد والوسع في نشر الإسلام، والدفاع عنه وعن أهله، أو قتال عدوّ للإسلام وأهله.", "أنوس يقول: «أنا صغير، فكيف أبذل جهدي؟». أجتهد في تعلّم ديني، وأعلّمه لإخوتي، وأكون قدوة حسنة بأخلاقي. أمّا القتال فهو للرجال الكبار بأمر وليّ أمر المسلمين."], "board": ["بذل الجهد في نشر الإسلام", "والدفاع عنه وعن أهله"]}], "summary": ["الزكاة ركن واجب يُعطى للفقير، والصدقة المستحبّة عطاء في الخير في أيّ وقت.", "الصيام إمساك عن المفطرات من الفجر إلى المغرب بنيّة، ومفسداته: الأكل والشرب عمدًا، والقيء عمدًا، والردّة.", "أركان الحجّ أربعة: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي؛ وأركان العمرة ثلاثة: الإحرام، والطواف، والسعي."], "islam": {"intro": "قال الله تعالى عن فرض الصيام:", "text": "فالصيام يعلّمنا التقوى: أن نترك ما نحبّ طاعةً لله، ونصبر، ونشعر بالفقير الجائع.", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "src": "سُورَةُ البَقَرَةِ: ١٨٣"}, "hadith": {"text": "من صام رمضان إيمانًا واحتسابًا غُفر له ما تقدّم من ذنبه", "source": "متفق عليه عن أبي هريرة رضي الله عنه"}}, "home": {"title": "صندوق أنوس للخير وتمرة الإفطار", "goal": "أن يطبّق الطفل الصدقة وسنن الصيام عمليًّا مع أسرته.", "materials": ["علبة فارغة", "ورق ملوّن", "تمر"], "steps": ["زيّن علبة واكتب عليها «صندوق الخير»، وضع فيها شيئًا من مصروفك كل يوم هذا الأسبوع.", "في آخر الأسبوع، اختر مع والديك محتاجًا أو مشروع خير لتعطيه ما جمعت.", "إن استطعت، صم نصف يوم أو يومًا كاملًا مع أسرتك يوم الاثنين أو الخميس، وتسحّر معهم.", "عند الإفطار: افطر على تمرة، وادعُ الله بدعاء تحبّه."], "parent": "شجّعوا الصيام بالتدريج حسب قدرة الطفل وصحّته، ولا تجبروه. واجعلوا الطفل يسلّم الصدقة بيده ليشعر بفرحة العطاء."}, "online": {"title": "رحلة فصيح إلى مكّة", "intro": "ساعد فصيحًا على تصنيف الأركان، ثم خذ القرار الصحيح!", "steps": [{"type": "sort", "title": "ركن في الحجّ فقط، أم في الحجّ والعمرة؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["في الحجّ فقط", "في الحجّ والعمرة معًا"], "items": [{"t": "الوقوف بعرفة", "icon": "⛰️", "bin": 0, "why": "الوقوف بعرفة ركن في الحجّ فقط."}, {"t": "الإحرام", "icon": "🤍", "bin": 1, "why": "الإحرام ركن في الحجّ وفي العمرة."}, {"t": "السعي بين الصفا والمروة", "icon": "🚶", "bin": 1, "why": "السعي ركن في الحجّ وفي العمرة."}, {"t": "طواف الإفاضة", "icon": "🕋", "bin": 0, "why": "طواف الإفاضة من أركان الحجّ."}, {"t": "الطواف بالبيت", "icon": "🔄", "bin": 1, "why": "الطواف ركن في العمرة، وفي الحجّ طواف الإفاضة."}]}, {"type": "decision", "title": "مختبر القرار: ساعة الإفطار", "scenario": "أذّن المغرب، وأنوس صائم، وأمامه تمر وماء وكعكة كبيرة. ماذا يفعل؟", "options": [{"t": "ينتظر ساعة بعد الأذان ليُظهر أنّه قويّ", "result": "السنّة تعجيل الفطر، لا تأخيره بعد غروب الشمس.", "best": false}, {"t": "يفطر فورًا على تمرة، ويدعو الله", "result": "أحسنت! تعجيل الفطر والفطر على التمر والدعاء من سنن الصيام.", "best": true}, {"t": "يأكل الكعكة كلّها بسرعة ولا يدعو", "result": "الأكل حلال، لكنّك فوّتّ سنّة التمر والدعاء عند الفطر.", "best": false}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ماذا يقول الصائم إذا شتمه أحد؟", "o": ["يشتمه مثله", "إني صائم", "يسكت ويغضب"], "a": 1, "why": "من سنن الصيام أن يقول: إني صائم."}, {"q": "كم أركان العمرة؟", "o": ["ثلاثة", "خمسة", "أربعة"], "a": 0, "why": "الإحرام، والطواف بالبيت، والسعي."}, {"q": "من حجّ لله فلم يرفث ولم يفسق رجع…", "o": ["بهديّة كبيرة", "متعبًا فقط", "كيوم ولدته أمّه"], "a": 2, "why": "يرجع بلا ذنوب كيوم ولدته أمّه."}]}]}, "case": {"title": "مَن أنا؟", "story": "في نهاية المسابقة، أخرج فصيح ورقة لغز فيها صحابيّ شجاع. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا صحابيّ شجاع، لُقّبت بسيف الله المسلول.", "ما انهزمت في معركة قطّ.", "قدت جيش المسلمين في معركة اليرموك."], "options": ["سعد بن أبي وقاص رضي الله عنه", "حمزة بن عبد المطلب رضي الله عنه", "خالد بن الوليد رضي الله عنه"], "deep": "الشجاعة صفة جميلة، لكن متى تكون الشجاعة في الخير؟ وكيف تكون شجاعًا في يومك: في قول الحقّ، أو الاعتذار عن الخطأ؟", "reveal": "أنا خالد بن الوليد رضي الله عنه! وقد وصفني النبيّ ﷺ بأنّي «سيف من سيوف الله». وفي الحلقة القادمة نتعرّف على مولد نبيّنا محمد ﷺ وطفولته."}, "quiz": [{"q": "ما الفرق بين الزكاة والصدقة المستحبّة؟", "o": ["الزكاة واجبة، والصدقة في أيّ وقت تطوّعًا", "لا فرق بينهما", "الصدقة واجبة، والزكاة تطوّع"], "a": 0, "why": "الزكاة ركن واجب، والصدقة المستحبّة نعطيها في الخير في أيّ وقت."}], "qa": [{"id": 78, "q": "ما هي الزكاة؟", "a": "هي حقٌّ واجبٌ في مالٍ خاصٍّ لطائفةٍ مخصوصةٍ في وقتٍ مخصوص. وهي ركنٌ من أركانِ الإسلام، وصدقةٌ واجبةٌ تؤخذُ من الغنيِّ وتُعطى للفقير.\nقال تعالى: ﴿وَآتُوا الزَّكَاةَ﴾ [البقرة: ٤٣]."}, {"id": 79, "q": "ما هي الصدقةُ المستحبة؟", "a": "هي غيرُ الزكاة، مثل: التصدقِ بأيِّ شيءٍ في وجوهِ الخيرِ في أيِّ وقت.\nقال تعالى: ﴿وَأَنفِقُوا فِي سَبِيلِ اللَّهِ﴾ [البقرة: ١٩٥]."}, {"id": 80, "q": "عرِّفِ الصيام؟", "a": "هو التعبدُ لله بالإمساكِ عن المفطراتِ من طلوعِ الفجرِ إلى غروبِ الشمس، مع النية، وهو نوعان:\n• صيامٌ واجب: مثلُ صيامِ شهرِ رمضان، وهو ركنٌ من أركانِ الإسلام. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾ [البقرة: ١٨٣].\n• وصيامٌ غيرُ واجب: مثلُ صومِ الاثنينِ والخميسِ من كلِّ أسبوع، وصيامِ ثلاثةِ أيامٍ من كلِّ شهر، وأفضلُها أيامُ البيض \"١٣، ١٤، ١٥\" من كلِّ شهرٍ قمري."}, {"id": 81, "q": "ما فضلُ صيامِ شهرِ رمضان؟", "a": "عن أبي هريرة، أن رسولَ الله ﷺ قال: «من صامَ رمضانَ إيمانًا واحتسابًا؛ غُفِرَ له ما تقدَّمَ من ذنبِه» متفق عليه."}, {"id": 82, "q": "ما فضلُ صيامِ التطوعِ في غيرِ رمضان؟", "a": "عن أبي سعيدٍ الخدري قال: قال رسولُ الله ﷺ: «ما من عبدٍ يصومُ يومًا في سبيلِ الله، إلا باعدَ اللهُ بذلك اليومِ وجهَهُ عن النارِ سبعينَ خريفًا» متفق عليه. (معنى \"سبعين خريفًا\"؛ أي: سبعينَ سنة)."}, {"id": 83, "q": "ما مفسداتُ الصوم؟", "a": "١. الأكلُ والشربُ عمدًا.\n٢. القيءُ عمدًا.\n٣. الردةُ عن الإسلام."}, {"id": 84, "q": "ما سننُ الصيام؟", "a": "١. تعجيلُ الفطر.\n٢. السحورُ وتأخيرُه.\n٣. الزيادةُ في أعمالِ الخيرِ والعبادة.\n٤. قولُ الصائمِ إذا شُتِم: إني صائم.\n٥. الدعاءُ عند الفطر.\n٦. الفطرُ على رطبٍ أو تمر، فإن لم يجدْ؛ فعلى ماء."}, {"id": 85, "q": "ما هو الحج؟", "a": "الحج: هو التعبدُ لله تعالى، بقصدِ بيتِهِ الحرامِ لأعمالٍ مخصوصةٍ في وقتٍ مخصوص.\nقال تعالى: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ عَنِ الْعَالَمِينَ﴾ [آل عمران: ٩٧]."}, {"id": 86, "q": "ما أركانُ الحج؟", "a": "١. الإحرام.\n٢. الوقوفُ بعرفة.\n٣. طوافُ الإفاضة.\n٤. السعيُ بين الصفا والمروة."}, {"id": 87, "q": "ما هو فضلُ الحج؟", "a": "عن أبي هريرة قال: سمعتُ رسولَ الله ﷺ يقول: «من حجَّ لله فلم يرفثْ ولم يفسقْ؛ رجعَ كيومَ ولدتْهُ أمُّه» رواه البخاري وغيره."}, {"id": 88, "q": "ما هي العمرة؟", "a": "العمرة: هي التعبدُ لله تعالى بقصدِ بيتِهِ الحرامِ لأعمالٍ مخصوصةٍ في أيِّ وقت."}, {"id": 89, "q": "ما أركانُ العمرة؟", "a": "١. الإحرام.\n٢. الطوافُ بالبيت.\n٣. السعيُ بين الصفا والمروة."}, {"id": 90, "q": "ما هو الجهادُ في سبيلِ الله؟", "a": "هو بذلُ الجهدِ والوسعِ في نشرِ الإسلامِ والدفاعِ عنه وعن أهله، أو قتالُ عدوٍّ للإسلامِ وأهله.\nقال تعالى: ﴿وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ﴾ [التوبة: ٤١]."}], "dyk": ["حبةٌ واحدةٌ تُنبِتُ سبعَ سنابلَ في كلِّ سنبلةٍ مئةُ حبة — مثلٌ ضربَه اللهُ لمُضاعفةِ الصدقة."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ!"}, {"s": "anos", "t": "وَالْيَوْمَ حَلْقَةُ الْمُسَابَقَةِ: الزَّكَاةُ، وَالصِّيَامُ، وَالْحَجُّ!"}, {"s": "fasih", "t": "مَا هِيَ الزَّكَاةُ؟"}, {"s": "anos", "t": "حَقٌّ وَاجِبٌ فِي مَالٍ خَاصٍّ، لِطَائِفَةٍ مَخْصُوصَةٍ، فِي وَقْتٍ مَخْصُوصٍ. وَهِيَ رُكْنٌ مِنْ أَرْكَانِ الْإِسْلَامِ. قَالَ تَعَالَى: وَآتُوا الزَّكَاةَ."}, {"s": "fasih", "t": "وَالصَّدَقَةُ الْمُسْتَحَبَّةُ؟"}, {"s": "anos", "t": "هِيَ غَيْرُ الزَّكَاةِ: أَنْ تَتَصَدَّقَ بِأَيِّ شَيْءٍ فِي الْخَيْرِ، فِي أَيِّ وَقْتٍ. قَالَ تَعَالَى: وَأَنْفِقُوا فِي سَبِيلِ اللَّهِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ حَبَّةٌ تُنْبِتُ سَبْعَ سَنَابِلَ، فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ: مَثَلٌ ضَرَبَهُ اللَّهُ لِمُضَاعَفَةِ الصَّدَقَةِ!"}, {"s": "fasih", "t": "عَرِّفِ الصِّيَامَ!"}, {"s": "anos", "t": "التَّعَبُّدُ لِلَّهِ بِالْإِمْسَاكِ عَنِ الْمُفْطِرَاتِ مِنْ طُلُوعِ الْفَجْرِ إِلَى غُرُوبِ الشَّمْسِ، مَعَ النِّيَّةِ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ الْبَقَرَةِ."}, {"s": "quran", "ref": "2:183", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ"}, {"s": "fasih", "t": "لَعَلَّكُمْ تَتَّقُونَ!"}, {"s": "anos", "t": "وَهُوَ وَاجِبٌ كَرَمَضَانَ، وَغَيْرُ وَاجِبٍ كَالِاثْنَيْنِ وَالْخَمِيسِ، وَثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَأَفْضَلُهَا أَيَّامُ الْبِيضِ: الثَّالِثَ عَشَرَ، وَالرَّابِعَ عَشَرَ، وَالْخَامِسَ عَشَرَ."}, {"s": "fasih", "t": "مَا فَضْلُ صِيَامِ رَمَضَانَ؟"}, {"s": "anos", "t": "«مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ»، مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "وَفَضْلُ صِيَامِ التَّطَوُّعِ؟"}, {"s": "anos", "t": "مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَاعَدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا، أَيْ: سَبْعِينَ سَنَةً."}, {"s": "fasih", "t": "مَا مُفْسِدَاتُ الصَّوْمِ؟"}, {"s": "anos", "t": "الْأَكْلُ وَالشُّرْبُ عَمْدًا، وَالْقَيْءُ عَمْدًا، وَالرِّدَّةُ عَنِ الْإِسْلَامِ."}, {"s": "fasih", "t": "وَسُنَنُ الصِّيَامِ؟"}, {"s": "anos", "t": "تَعْجِيلُ الْفِطْرِ، وَالسَّحُورُ وَتَأْخِيرُهُ، وَالزِّيَادَةُ فِي الْخَيْرِ، وَقَوْلُ: إِنِّي صَائِمٌ إِذَا شُتِمَ، وَالدُّعَاءُ عِنْدَ الْفِطْرِ، وَالْفِطْرُ عَلَى رُطَبٍ أَوْ تَمْرٍ أَوْ مَاءٍ."}, {"s": "fasih", "t": "وَمَا الْحَجُّ؟"}, {"s": "anos", "t": "التَّعَبُّدُ لِلَّهِ بِقَصْدِ بَيْتِهِ الْحَرَامِ لِأَعْمَالٍ مَخْصُوصَةٍ فِي وَقْتٍ مَخْصُوصٍ، عَلَى مَنِ اسْتَطَاعَ."}, {"s": "fasih", "t": "وَأَرْكَانُهُ؟"}, {"s": "anos", "t": "أَرْبَعَةٌ: الْإِحْرَامُ، وَالْوُقُوفُ بِعَرَفَةَ، وَطَوَافُ الْإِفَاضَةِ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ."}, {"s": "fasih", "t": "وَفَضْلُهُ؟"}, {"s": "anos", "t": "مَنْ حَجَّ لِلَّهِ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمَ وَلَدَتْهُ أُمُّهُ، رَوَاهُ الْبُخَارِيُّ."}, {"s": "fasih", "t": "وَمَا الْعُمْرَةُ؟ وَمَا أَرْكَانُهَا؟"}, {"s": "anos", "t": "التَّعَبُّدُ لِلَّهِ بِقَصْدِ بَيْتِهِ الْحَرَامِ لِأَعْمَالٍ مَخْصُوصَةٍ فِي أَيِّ وَقْتٍ. وَأَرْكَانُهَا ثَلَاثَةٌ: الْإِحْرَامُ، وَالطَّوَافُ، وَالسَّعْيُ."}, {"s": "fasih", "t": "وَمَا الْجِهَادُ فِي سَبِيلِ اللَّهِ؟"}, {"s": "anos", "t": "بَذْلُ الْجُهْدِ وَالْوُسْعِ فِي نَشْرِ الْإِسْلَامِ، وَالدِّفَاعِ عَنْهُ وَعَنْ أَهْلِهِ، أَوْ قِتَالُ عَدُوٍّ لِلْإِسْلَامِ وَأَهْلِهِ. وَنَحْنُ نَجْتَهِدُ الْآنَ فِي تَعَلُّمِ دِينِنَا."}, {"s": "anos", "t": "الْآنَ «مُسَابَقَةُ أَنُوس»: فَرِيقُ الْحَصَّالَةِ ضِدَّ فَرِيقِ التَّمْرَةِ!"}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس: فريق الحصّالة ضدّ فريق التمرة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أَنُوس صَائِمٌ تَطَوُّعًا، فَشَرِبَ نَاسِيًا ثُمَّ تَذَكَّرَ! أ: فَسَدَ صَوْمِي، سَآكُلُ. ب: أُكْمِلُ صَوْمِي. ج: أَتْرُكُ الصِّيَامَ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: نسي أنوس أنّه صائم!"}, {"s": "anos", "t": "الصَّحِيحُ «ب»؛ فَالنَّاسِي يُتِمُّ صَوْمَهُ، فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: أَيُّ رُكْنٍ فِي الْحَجِّ وَلَيْسَ فِي الْعُمْرَةِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "الْوُقُوفُ بِعَرَفَةَ! وَمَتَى يَبْدَأُ الصِّيَامُ وَيَنْتَهِي؟ فَكِّرُوا..."}, {"s": "fasih", "t": "مِنَ الْفَجْرِ إِلَى الْمَغْرِبِ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: لُقِّبْتُ بِسَيْفِ اللَّهِ الْمَسْلُولِ، وَقُدْتُ الْمُسْلِمِينَ فِي الْيَرْمُوكِ."}, {"s": "anos", "t": "سَعْدٌ، أَمْ حَمْزَةُ، أَمْ خَالِدُ بْنُ الْوَلِيدِ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: زَيِّنُوا «صُنْدُوقَ الْخَيْرِ» وَضَعُوا فِيهِ مِنْ مَصْرُوفِكُمْ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ فَصِيح إِلَى مَكَّةَ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 11, "title": "مولد النبيّ ﷺ وطفولته", "season": 2, "goals": ["seerah"], "hook": "أهلًا يا أصدقاء! فصيح يحمل شجرة كبيرة مرسومة على ورقة ويقول: «أنوس، هذه شجرة عائلتي! فهل تعرف شجرة عائلة نبيّنا محمد ﷺ؟ ومتى وُلد؟ ومن ربّاه وهو صغير؟». هيّا نسافر إلى مكّة قبل أكثر من 1400 سنة!", "sections": [{"h": "شجرة عائلة النبيّ ﷺ", "p": ["نبيّنا هو <b>محمد بن عبد الله بن عبد المطلب بن هاشم</b>، من قبيلة <b>قريش</b>. وقريش من العرب، والعرب من ذرّية <b>إسماعيل</b>، وإسماعيل ابن <b>إبراهيم</b> عليهما السلام.", "فصيح يتعجّب: «يعني نبيّنا من ذرّية إبراهيم الذي بنى الكعبة؟». نعم يا فصيح! فإبراهيم وإسماعيل رفعا قواعد الكعبة، ومن ذرّيتهما جاء خاتم الأنبياء ﷺ.", "واسم أمّه: <b>آمنة بنت وهب</b>. أمّا أبوه عبد الله فقد <b>توفّي في المدينة</b> والنبيّ ﷺ ما زال في بطن أمّه، لم يولد بعد. فوُلد ﷺ <b>يتيمًا</b>."], "board": ["محمد بن عبد الله بن عبد المطلب بن هاشم", "قريش ← العرب ← إسماعيل ← إبراهيم", "أمّه: آمنة بنت وهب"]}, {"h": "يوم الاثنين في مكّة: ولادة النور", "p": ["وُلد النبيّ ﷺ في <b>مكّة</b>، في <b>عام الفيل</b>، <b>يوم الاثنين</b> من شهر <b>ربيع الأوّل</b>.", "و«عام الفيل» هو العام الذي جاء فيه أبرهة بجيش معه فيل كبير ليهدم الكعبة، فأرسل الله عليهم طيرًا ترميهم بالحجارة، وحفظ بيته. وسنتعلّم ذلك في سورة الفيل.", "أنوس يقول: «ولهذا كان النبيّ ﷺ يصوم يوم الاثنين؛ لأنّه اليوم الذي وُلد فيه». فإذا صمت الاثنين، فأنت تتّبع سنّته ﷺ."], "board": ["المكان: مكّة", "الزمان: عام الفيل", "يوم الاثنين، ربيع الأوّل"]}, {"h": "قلوب رحيمة أرضعته واحتضنته", "p": ["كانت العرب تحبّ أن يرضع أطفالهم في البادية حيث الهواء النقيّ. وقد أرضع النبيّ ﷺ وحضنه غيرُ أمّه نساءٌ رحيمات:", "<b>أمّ أيمن</b>: مولاة أبيه، حضنته ورعته. و<b>ثويبة</b>: مولاة عمّه أبي لهب. و<b>حليمة السعدية</b>: أخذته إلى البادية في بني سعد.", "فصيح يقول: «ما أجمل أن يحبّ الناس الطفل اليتيم ويرعوه!». صحيح، والإسلام يعلّمنا أن نرحم الأيتام ونحسن إليهم."], "board": ["أمّ أيمن", "ثويبة", "حليمة السعدية"]}, {"h": "من كفله بعد أمّه؟", "p": ["<b>توفّيت أمّه آمنة وهو ابن ستّ سنين</b>، فكفله جدّه <b>عبد المطلب</b>، وكان يحبّه حبًّا شديدًا.", "ثم <b>توفّي جدّه وهو ابن ثماني سنين</b>، فكفله عمّه <b>أبو طالب</b>، فربّاه مع أولاده.", "تخيّل يا صديقي: فقد أباه قبل أن يولد، ثم أمّه، ثم جدّه، ومع ذلك صبر، ورعاه الله، فكان أحسن الناس خُلقًا. فإذا حزنت يومًا، تذكّر أنّ الله لا ينسى عباده."], "board": ["6 سنين: وفاة أمّه ← جدّه عبد المطلب", "8 سنين: وفاة جدّه ← عمّه أبو طالب"]}], "summary": ["نبيّنا محمد بن عبد الله بن عبد المطلب بن هاشم، من قريش، من ذرّية إسماعيل بن إبراهيم، وأمّه آمنة بنت وهب.", "وُلد ﷺ في مكّة، عام الفيل، يوم الاثنين من ربيع الأوّل، وتوفّي أبوه قبل ولادته.", "أرضعته وحضنته أمّ أيمن وثويبة وحليمة السعدية، وكفله جدّه عبد المطلب ثم عمّه أبو طالب."], "islam": {"intro": "قال الله تعالى يذكّر نبيّه ﷺ بنعمته عليه:", "text": "وُلد النبيّ ﷺ يتيمًا فآواه الله ورعاه. فلنرحم الأيتام، ولنشكر الله على والدينا وأسرتنا.", "ayah": {"text": "أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ", "src": "سُورَةُ الضُّحَىٰ: ٦"}, "hadith": {"text": "سُئل رسول الله ﷺ عن صوم يوم الاثنين، فقال: ذاك يوم وُلدت فيه، ويوم بُعثت أو أُنزل عليّ فيه", "source": "رواه مسلم عن أبي قتادة رضي الله عنه"}}, "home": {"title": "شجرتي وشجرة النبيّ ﷺ", "goal": "أن يحفظ الطفل نسب النبيّ ﷺ ويقارنه بنسب عائلته.", "materials": ["ورقتان كبيرتان", "ألوان"], "steps": ["ارسم شجرة واكتب عليها نسب النبيّ ﷺ: محمد، عبد الله، عبد المطلب، هاشم، ثم قريش.", "ارسم شجرة ثانية لعائلتك: اسمك، أبوك، جدّك، جدّ أبيك. اسأل والديك عن الأسماء.", "اسأل جدّك أو جدّتك عن قصّة جميلة من طفولتهم، وقارنها بطفولة النبيّ ﷺ.", "صم يوم الاثنين إن استطعت، أو نصفه، متّبعًا سنّة النبيّ ﷺ."], "parent": "احكوا لأطفالكم عن الأجداد بحبّ، وذكّروهم أنّ النبيّ ﷺ فقد والديه صغيرًا، ليشكروا نعمة الأسرة ويرحموا الأيتام."}, "online": {"title": "رحلة فصيح إلى طفولة النبيّ ﷺ", "intro": "رتّب أحداث الطفولة، ثم صِل كل اسم بقصّته!", "steps": [{"type": "order", "title": "رتّب الأحداث", "prompt": "رتّب الأحداث من الأقدم إلى الأحدث.", "items": ["وفاة أبيه عبد الله والنبيّ ﷺ في بطن أمّه", "ولادة النبيّ ﷺ في مكّة عام الفيل", "وفاة أمّه آمنة وهو ابن ستّ سنين", "وفاة جدّه عبد المطلب وهو ابن ثماني سنين", "عمّه أبو طالب يكفله"]}, {"type": "match", "title": "صِل الاسم بقصّته", "prompt": "اختر الاسم، ثم ما يناسبه.", "pairs": [["آمنة بنت وهب", "أمّ النبيّ ﷺ"], ["عبد الله", "أبو النبيّ ﷺ، توفّي في المدينة قبل ولادته"], ["حليمة السعدية", "مرضعته في البادية"], ["عبد المطلب", "جدّه، كفله بعد وفاة أمّه"], ["أبو طالب", "عمّه، كفله بعد وفاة جدّه"]]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "في أيّ بلد وُلد النبيّ ﷺ؟", "o": ["المدينة", "الطائف", "مكّة"], "a": 2, "why": "وُلد النبيّ ﷺ في مكّة."}, {"q": "أيّ هؤلاء من مرضعات النبيّ ﷺ وحواضنه؟", "o": ["أمّ أيمن", "عائشة", "فاطمة"], "a": 0, "why": "أمّ أيمن مولاة أبيه، وثويبة، وحليمة السعدية."}, {"q": "في أيّ شهر وُلد النبيّ ﷺ؟", "o": ["رمضان", "ربيع الأوّل", "ذو الحجّة"], "a": 1, "why": "وُلد في شهر ربيع الأوّل."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز بين صفحات كتاب السيرة، فيها رجل من عائلة النبيّ ﷺ. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["لُقّبت بـ«أسد الله».", "أنا عمّ النبيّ ﷺ.", "استشهدت في غزوة أُحُد، فكنت سيّد الشهداء."], "options": ["عليّ بن أبي طالب رضي الله عنه", "حمزة بن عبد المطلب رضي الله عنه", "مصعب بن عمير رضي الله عنه"], "deep": "عبد المطلب كان جدّ النبيّ ﷺ. فما صلة حمزة بعبد المطلب؟ وكيف نعرف ذلك من اسمه؟", "reveal": "أنا حمزة بن عبد المطلب رضي الله عنه! وأنا أيضًا أخو النبيّ ﷺ من الرضاعة. وفي الحلقة القادمة نتعلّم كيف كبر النبيّ ﷺ، وكيف نزل عليه الوحي في غار حراء."}, "quiz": [{"q": "ما اسم أمّ النبيّ ﷺ؟", "o": ["حليمة السعدية", "آمنة بنت وهب", "خديجة بنت خويلد"], "a": 1, "why": "أمّه آمنة بنت وهب، وحليمة مرضعته."}], "qa": [{"id": 91, "q": "ما نسبُ نبيِّنا محمدٍ ﷺ؟", "a": "هو محمدُ بنُ عبدِ اللهِ بنِ عبدِ المطلبِ بنِ هاشمٍ من قريش، وقريشٌ من العرب، والعربُ من ذريةِ إسماعيل، وإسماعيلُ ابنُ إبراهيمَ عليه وعلى نبيِّنا أفضلُ الصلاةِ والسلام."}, {"id": 92, "q": "ما اسمُ أمِّ نبيِّنا ﷺ؟", "a": "آمنةُ بنتُ وهب."}, {"id": 93, "q": "متى توفيَ أبوه؟", "a": "توفيَ أبوهُ في المدينةِ وهو حملٌ في بطنِ أمِّه، لم يولدْ ﷺ."}, {"id": 94, "q": "متى وُلِدَ النبيُّ ﷺ؟", "a": "في عامِ الفيل، في يومِ الاثنينِ من شهرِ ربيعٍ الأول."}, {"id": 95, "q": "في أيِّ بلدٍ وُلِد؟", "a": "في مكة."}, {"id": 96, "q": "مَن مرضعاتُهُ وحواضنُهُ غيرَ أمِّه؟", "a": "• مولاةُ أبيهِ أمُّ أيمن.\n• مولاةُ عمِّهِ أبي لهبٍ، ثويبة.\n• حليمةُ السعدية."}, {"id": 97, "q": "متى توفيتْ أمُّه؟", "a": "توفيتْ أمُّهُ وهو ابنُ ستِّ سنين، وكفلَهُ جدُّهُ عبدُ المطلب."}, {"id": 98, "q": "مَن كفلَهُ بعد وفاةِ جدِّهِ عبدِ المطلب؟", "a": "توفيَ جدُّهُ عبدُ المطلبِ وهو ابنُ ثماني سنين، وكفلَهُ عمُّهُ أبو طالب."}], "dyk": ["كانتِ النارُ برداً وسلاماً على إبراهيم — والنارُ لا تُبرِّدُ إلا بأمرِ خالقِها."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ خَالِدُ بْنُ الْوَلِيدِ رَضِيَ اللَّهُ عَنْهُ، سَيْفٌ مِنْ سُيُوفِ اللَّهِ!"}, {"s": "anos", "t": "وَالْيَوْمَ نَبْدَأُ السِّيرَةَ: نَسَبُ نَبِيِّنَا وَطُفُولَتُهُ!"}, {"s": "fasih", "t": "مَا نَسَبُ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟"}, {"s": "anos", "t": "هُوَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمٍ، مِنْ قُرَيْشٍ، وَقُرَيْشٌ مِنَ الْعَرَبِ، وَالْعَرَبُ مِنْ ذُرِّيَّةِ إِسْمَاعِيلَ ابْنِ إِبْرَاهِيمَ عَلَيْهِمَا السَّلَامُ."}, {"s": "fasih", "t": "مِنْ ذُرِّيَّةِ إِبْرَاهِيمَ الَّذِي بَنَى الْكَعْبَةَ! وَمَا اسْمُ أُمِّهِ؟"}, {"s": "anos", "t": "آمِنَةُ بِنْتُ وَهْبٍ."}, {"s": "fasih", "t": "وَمَتَى تُوُفِّيَ أَبُوهُ؟"}, {"s": "anos", "t": "تُوُفِّيَ أَبُوهُ فِي الْمَدِينَةِ وَهُوَ حَمْلٌ فِي بَطْنِ أُمِّهِ، لَمْ يُولَدْ بَعْدُ؛ فَوُلِدَ يَتِيمًا."}, {"s": "fasih", "t": "وَمَتَى وُلِدَ؟ وَفِي أَيِّ بَلَدٍ؟"}, {"s": "anos", "t": "وُلِدَ فِي مَكَّةَ، فِي عَامِ الْفِيلِ، يَوْمَ الِاثْنَيْنِ مِنْ شَهْرِ رَبِيعٍ الْأَوَّلِ. وَعَامُ الْفِيلِ هُوَ الْعَامُ الَّذِي جَاءَ فِيهِ أَبْرَهَةُ لِيَهْدِمَ الْكَعْبَةَ، فَحَفِظَ اللَّهُ بَيْتَهُ."}, {"s": "fasih", "t": "وَلِهَذَا كَانَ يَصُومُ يَوْمَ الِاثْنَيْنِ؟"}, {"s": "anos", "t": "نَعَمْ! سُئِلَ عَنْ صَوْمِ الِاثْنَيْنِ فَقَالَ: «ذَاكَ يَوْمٌ وُلِدْتُ فِيهِ، وَيَوْمٌ بُعِثْتُ أَوْ أُنْزِلَ عَلَيَّ فِيهِ»، رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "مَنْ مُرْضِعَاتُهُ وَحَوَاضِنُهُ غَيْرَ أُمِّهِ؟"}, {"s": "anos", "t": "أُمُّ أَيْمَنَ مَوْلَاةُ أَبِيهِ، وَثُوَيْبَةُ مَوْلَاةُ عَمِّهِ أَبِي لَهَبٍ، وَحَلِيمَةُ السَّعْدِيَّةُ الَّتِي أَخَذَتْهُ إِلَى الْبَادِيَةِ."}, {"s": "fasih", "t": "وَمَتَى تُوُفِّيَتْ أُمُّهُ؟"}, {"s": "anos", "t": "وَهُوَ ابْنُ سِتِّ سِنِينَ، فَكَفَلَهُ جَدُّهُ عَبْدُ الْمُطَّلِبِ، وَكَانَ يُحِبُّهُ حُبًّا شَدِيدًا."}, {"s": "fasih", "t": "وَمَنْ كَفَلَهُ بَعْدَ وَفَاةِ جَدِّهِ؟"}, {"s": "anos", "t": "تُوُفِّيَ جَدُّهُ وَهُوَ ابْنُ ثَمَانِي سِنِينَ، فَكَفَلَهُ عَمُّهُ أَبُو طَالِبٍ."}, {"s": "fasih", "t": "فَقَدَ أَبَاهُ، ثُمَّ أُمَّهُ، ثُمَّ جَدَّهُ! مَسْكِينٌ!"}, {"s": "anos", "t": "لَكِنَّ اللَّهَ رَعَاهُ وَآوَاهُ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ يَتْلُو مِنْ سُورَةِ الضُّحَى."}, {"s": "quran", "ref": "93:6", "t": "أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ"}, {"s": "fasih", "t": "أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى! إِذَنْ فَلْنَرْحَمِ الْأَيْتَامَ، وَلْنَشْكُرِ اللَّهَ عَلَى وَالِدَيْنَا وَأُسْرَتِنَا."}, {"s": "anos", "t": "هَلْ تَعْلَمُ؟ كَانَتِ النَّارُ بَرْدًا وَسَلَامًا عَلَى إِبْرَاهِيمَ جَدِّ نَبِيِّنَا، وَالنَّارُ لَا تَبْرُدُ إِلَّا بِأَمْرِ خَالِقِهَا!"}, {"s": "anos", "t": "الْآنَ «شَجَرَةُ النَّسَبِ الْحَيَّةُ»: يَقِفُ كُلُّ وَاحِدٍ بِبِطَاقَةِ اسْمٍ بِالتَّرْتِيبِ، مِنْ عَبْدِ اللَّهِ إِلَى إِبْرَاهِيمَ، ثُمَّ تُرَدِّدُونَ النَّسَبَ كَامِلًا."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَاصْنَعُوهَا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: شجرة النسب الحيّة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! جَاءَ زَمِيلٌ جَدِيدٌ اسْمُهُ سَالِمٌ، وَأَبُوهُ مُتَوَفًّى. أ: يَتَجَاهَلُهُ أَنُوس. ب: يَسْأَلُهُ أَسْئِلَةً مُحْرِجَةً عَنْ أَبِيهِ. ج: يُرَحِّبُ بِهِ، وَيَلْعَبُ مَعَهُ، وَيُشَارِكُهُ طَعَامَهُ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: زميل جديد يتيم"}, {"s": "anos", "t": "«أ» قَسْوَةٌ، وَ«ب» تُحْزِنُهُ. وَالصَّحِيحُ «ج»؛ فَالْإِحْسَانُ إِلَى الْيَتِيمِ مِنْ أَحَبِّ الْأَعْمَالِ إِلَى اللَّهِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: فِي أَيِّ يَوْمٍ وُلِدَ النَّبِيُّ؟ فَكِّرُوا..."}, {"s": "anos", "t": "يَوْمَ الِاثْنَيْنِ! وَمَنْ كَفَلَهُ بَعْدَ جَدِّهِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "عَمُّهُ أَبُو طَالِبٍ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: لُقِّبْتُ بِأَسَدِ اللَّهِ، وَأَنَا عَمُّ النَّبِيِّ، وَاسْتُشْهِدْتُ فِي غَزْوَةِ أُحُدٍ فَكُنْتُ سَيِّدَ الشُّهَدَاءِ."}, {"s": "anos", "t": "عَلِيٌّ، أَمْ حَمْزَةُ، أَمْ مُصْعَبٌ رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: ارْسُمُوا شَجَرَةَ نَسَبِ النَّبِيِّ، وَشَجَرَةً لِعَائِلَتِكُمْ، وَاسْأَلُوا أَجْدَادَكُمْ عَنْ طُفُولَتِهِمْ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ فَصِيح إِلَى طُفُولَةِ النَّبِيِّ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 12, "title": "البعثة ونزول الوحي", "season": 2, "goals": ["seerah"], "hook": "أهلًا يا أصدقاء! فصيح يهمس: «شششش… نحن الآن قرب جبل عالٍ في مكّة، فيه غار صغير اسمه حراء. في هذا الغار حدث أعظم حدث في تاريخ البشر!». هل تعرفون ما هو؟ هيّا نكتشف!", "sections": [{"h": "شابّ أمين: السفر والتجارة والزواج", "p": ["لمّا كان عمر النبيّ ﷺ <b>اثنتي عشرة سنة</b>، سافر مع عمّه أبي طالب إلى <b>الشام</b>.", "وكان <b>سفره الثاني</b> في تجارة بمال <b>خديجة</b> رضي الله عنها. ولمّا رجع <b>تزوّجها</b> ﷺ، وعمره <b>خمس وعشرون سنة</b>.", "فصيح يسأل: «لماذا اختارته خديجة ليتاجر بمالها؟». أنوس: لأنّه كان صادقًا أمينًا، لا يكذب ولا يغشّ. والتاجر الصادق يحبّه الناس."], "board": ["12 سنة: سفر إلى الشام مع عمّه", "25 سنة: تجارة خديجة ثم الزواج"]}, {"h": "الحجر الأسود: حلّ حكيم بلا خصام", "p": ["لمّا كان عمره <b>خمسًا وثلاثين سنة</b>، أعادت قريش <b>بناء الكعبة</b>. وحين وصلوا إلى مكان <b>الحجر الأسود</b> اختلفوا: كل قبيلة تريد أن تضعه وحدها!", "فحكّموا النبيّ ﷺ، فوضع الحجر في <b>ثوب</b>، وأمر كل قبيلة أن تأخذ بطرف من الثوب، وكانوا <b>أربع قبائل</b>. فلمّا رفعوه إلى مكانه، <b>وضعه ﷺ بيده</b>.", "أنوس يقول: «هكذا نحلّ مشكلاتنا مع أصدقائنا: نبحث عن حلّ يُرضي الجميع، بدل أن نتشاجر على اللعبة!»."], "board": ["35 سنة: بناء الكعبة", "الحجر في ثوب، وكل قبيلة تأخذ بطرف"]}, {"h": "في غار حراء: اقرأ!", "p": ["قبل الوحي كان النبيّ ﷺ <b>يتعبّد لله في غار حراء</b>، ويأخذ معه الزاد من طعام وماء.", "و<b>أوّل ما بُدئ به الوحي: الرؤيا الصادقة</b>؛ فكان لا يرى رؤيا في نومه إلا جاءت واضحة مثل <b>فلق الصبح</b>، أي مثل ضوء الفجر حين يظهر.", "ثم <b>نزل عليه الوحي وهو في الغار يتعبّد</b>، وكان عمره <b>أربعين سنة</b>. فبُعث ﷺ <b>إلى الناس كافّة</b>، بشيرًا بالجنّة لمن أطاع، ونذيرًا من النار لمن عصى.", "و<b>أوّل ما نزل من القرآن</b>: «اقرأ باسم ربّك الذي خلق، خلق الإنسان من علق، اقرأ وربّك الأكرم، الذي علّم بالقلم، علّم الإنسان ما لم يعلم»، وهي أوّل سورة العلق.", "فصيح يرفرف فرحًا: «أوّل كلمة نزلت: اقرأ! إذن القراءة والعلم مهمّان جدًّا في ديننا!». صدقت يا فصيح."], "board": ["الرؤيا الصادقة", "غار حراء", "40 سنة: البعثة", "أوّل ما نزل: اقرأ"]}, {"h": "أوّل المؤمنين", "p": ["من أوّل من آمن برسالته ﷺ؟", "من الرجال: <b>أبو بكر الصدّيق</b>. ومن النساء: <b>خديجة بنت خويلد</b>. ومن الصبيان: <b>عليّ بن أبي طالب</b>. ومن الموالي: <b>زيد بن حارثة</b>. ومن الأرقّاء: <b>بلال الحبشي</b>، وغيرهم.", "انظر يا صديقي: فيهم الكبير والصغير، والرجل والمرأة، والحرّ والعبد. فالإسلام للناس كافّة، وعليّ آمن وهو صبيّ مثلك!"], "board": ["أبو بكر", "خديجة", "عليّ", "زيد بن حارثة", "بلال"]}], "summary": ["سافر النبيّ ﷺ إلى الشام في الثانية عشرة، ثم بتجارة خديجة، وتزوّجها في الخامسة والعشرين، ووضع الحجر الأسود بحكمة في الخامسة والثلاثين.", "بُعث ﷺ وعمره أربعون سنة إلى الناس كافّة، وأوّل الوحي الرؤيا الصادقة، ونزل عليه الوحي في غار حراء: «اقرأ باسم ربّك الذي خلق».", "أوّل من آمن: أبو بكر من الرجال، وخديجة من النساء، وعليّ من الصبيان، وزيد من الموالي، وبلال من الأرقّاء."], "islam": {"intro": "أوّل كلمة نزلت من القرآن على نبيّنا ﷺ في غار حراء:", "text": "فديننا دين العلم والقراءة. ابدأ قراءتك ودراستك باسم الله، واطلب العلم النافع.", "ayah": {"text": "ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ", "src": "سُورَةُ العَلَقِ: ١"}, "hadith": {"text": "أوّل ما بُدئ به رسول الله ﷺ من الوحي الرؤيا الصالحة في النوم، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح", "source": "رواه البخاري عن عائشة رضي الله عنها"}}, "home": {"title": "مكتبة «اقرأ» العائلية", "goal": "أن يحفظ الطفل أوّل ما نزل من القرآن ويحبّ القراءة.", "materials": ["مصحف", "دفتر صغير", "كتاب قصص مناسب"], "steps": ["اقرأ مع أحد والديك أوّل خمس آيات من سورة العلق، وكرّرها حتى تحفظها.", "اكتب كلمة «اقرأ» بخطّ جميل وزيّنها، وعلّقها قرب مكان دراستك.", "اختر كتابًا تقرؤه مع أسرتك عشر دقائق كل يوم هذا الأسبوع، وابدأ بـ«بسم الله».", "احكِ لأسرتك قصّة الحجر الأسود، واسألهم: «كيف نحلّ خلافاتنا في البيت مثل هذا الحلّ؟»."], "parent": "اجعلوا للقراءة وقتًا ثابتًا في البيت، وكونوا قدوة بقراءتكم أمام أطفالكم."}, "online": {"title": "رحلة فصيح إلى غار حراء", "intro": "رتّب أحداث حياة النبيّ ﷺ قبل البعثة وبعدها، ثم صنّف أوّل المؤمنين!", "steps": [{"type": "order", "title": "رتّب الأحداث حسب العمر", "prompt": "رتّب من الأصغر عمرًا إلى الأكبر.", "items": ["12 سنة: سفره مع عمّه إلى الشام", "25 سنة: زواجه من خديجة رضي الله عنها", "35 سنة: وضع الحجر الأسود عند بناء الكعبة", "40 سنة: نزول الوحي في غار حراء"]}, {"type": "match", "title": "أوّل من آمن", "prompt": "صِل الاسم بالمجموعة التي كان أوّل من آمن منها.", "pairs": [["أبو بكر الصدّيق", "أوّل من آمن من الرجال"], ["خديجة بنت خويلد", "أوّل من آمن من النساء"], ["عليّ بن أبي طالب", "أوّل من آمن من الصبيان"], ["زيد بن حارثة", "أوّل من آمن من الموالي"], ["بلال الحبشي", "من أوائل من آمن من الأرقّاء"]]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ما أوّل كلمة نزلت من القرآن؟", "o": ["قل", "اقرأ", "الحمد"], "a": 1, "why": "أوّل ما نزل: «اقرأ باسم ربّك الذي خلق»."}, {"q": "إلى من بُعث النبيّ ﷺ؟", "o": ["إلى الناس كافّة", "إلى قريش وحدها", "إلى أهل مكّة فقط"], "a": 0, "why": "بُعث إلى الناس كافّة بشيرًا ونذيرًا."}, {"q": "بمال من تاجر النبيّ ﷺ في سفره الثاني؟", "o": ["أبي طالب", "أبي بكر", "خديجة رضي الله عنها"], "a": 2, "why": "كان سفره الثاني في تجارة بمال خديجة."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز قرب صورة غار حراء، فيها امرأة عظيمة تتكلّم عن نفسها. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا أوّل من آمن بالنبيّ ﷺ.", "أنا زوجته الأولى.", "واسيته بمالي ونفسي حين كذّبه الناس."], "options": ["عائشة رضي الله عنها", "فاطمة الزهراء رضي الله عنها", "خديجة بنت خويلد رضي الله عنها"], "deep": "عندما رجع النبيّ ﷺ من الغار خائفًا، كيف يمكن أن تساعد الزوجة أو الأمّ أو الصديق من يشعر بالخوف؟", "reveal": "أنا خديجة بنت خويلد رضي الله عنها! ولمّا رجع النبيّ ﷺ من الغار طمأنته وقلت: «كلّا والله ما يخزيك الله أبدًا». وفي الحلقة القادمة نتعلّم كيف دعا النبيّ ﷺ في مكّة، وقصّة الهجرة إلى المدينة."}, "quiz": [{"q": "كم كان عمر النبيّ ﷺ حين بُعث؟", "o": ["خمس وعشرون سنة", "ثلاث وستّون سنة", "أربعون سنة"], "a": 2, "why": "بُعث ﷺ وعمره أربعون سنة."}], "qa": [{"id": 99, "q": "متى سافرَ مع عمِّهِ إلى الشام؟", "a": "سافرَ مع عمِّهِ إلى الشامِ وعمرُهُ اثنتا عشرةَ سنة."}, {"id": 100, "q": "متى كان سفرُهُ الثاني؟", "a": "كان سفرُهُ الثاني في تجارةٍ بمالِ خديجةَ رضي الله عنها، ولما رجعَ تزوَّجَها ﷺ، وله من العمرِ خمسٌ وعشرون سنة."}, {"id": 101, "q": "متى أعادتْ قريشٌ بناءَ الكعبة؟", "a": "أعادتْ قريشٌ بناءَ الكعبة، وله من العمرِ خمسٌ وثلاثون سنة. وحكَّموهُ لما اختلفوا في من يضعُ الحجرَ الأسود، فوضعَهُ في ثوب، وأمرَ كلَّ قبيلةٍ أن تأخذَ بطرفٍ من الثوب، وكانوا أربعَ قبائل، فلما رفعوهُ إلى موضعه، وضعَهُ بيدِهِ عليه الصلاةُ والسلام."}, {"id": 102, "q": "كم كان عمرُهُ يومَ بُعِث؟ وإلى مَن بُعِث؟", "a": "كان عمرُهُ أربعينَ سنة، وبُعِثَ إلى الناسِ كافةً بشيرًا ونذيرًا."}, {"id": 103, "q": "ما أولُ ما بُدِئَ به الوحي؟", "a": "الرؤيا الصادقة، فكان لا يرى رؤيا إلا جاءتْ مثلَ فلقِ الصبح."}, {"id": 104, "q": "كيف كان حالُهُ قبل الوحي؟ ومتى نزلَ عليه الوحيُ أولَ مرة؟", "a": "كان يتعبدُ لله في غارِ حراءَ ويتزودُ لذلك. ونزلَ عليه الوحيُ، وهو في الغارِ يتعبد."}, {"id": 105, "q": "ما أولُ ما نزلَ عليه من القرآن؟", "a": "قوله تعالى: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ۝ خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ ۝ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ ۝ الَّذِي عَلَّمَ بِالْقَلَمِ ۝ عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ﴾ [العلق: ١–٥]."}, {"id": 106, "q": "مَن أولُ من آمنَ برسالته؟", "a": "• من الرجال: أبو بكرٍ الصديق.\n• ومن النساء: خديجةُ بنتُ خويلد.\n• ومن الصبيان: عليُّ بنُ أبي طالب.\n• ومن الموالي: زيدُ بنُ حارثة.\n• ومن الأرقاء: بلالٌ الحبشي، وغيرهم."}], "dyk": ["ضوءُ الشمسِ يصلُ إلى الأرضِ في ٨ دقائقَ تقريباً، رغم أن بينهما نحوَ ١٥٠ مليونَ كيلومتر."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ رَضِيَ اللَّهُ عَنْهُ، عَمُّ النَّبِيِّ!"}, {"s": "anos", "t": "وَالْيَوْمَ نَذْهَبُ إِلَى غَارِ حِرَاءَ، حَيْثُ نَزَلَ الْوَحْيُ!"}, {"s": "fasih", "t": "مَتَى سَافَرَ النَّبِيُّ مَعَ عَمِّهِ إِلَى الشَّامِ؟"}, {"s": "anos", "t": "وَعُمُرُهُ اثْنَتَا عَشْرَةَ سَنَةً."}, {"s": "fasih", "t": "وَمَتَى كَانَ سَفَرُهُ الثَّانِي؟"}, {"s": "anos", "t": "فِي تِجَارَةٍ بِمَالِ خَدِيجَةَ رَضِيَ اللَّهُ عَنْهَا، وَلَمَّا رَجَعَ تَزَوَّجَهَا، وَعُمُرُهُ خَمْسٌ وَعِشْرُونَ سَنَةً."}, {"s": "fasih", "t": "وَمَتَى أَعَادَتْ قُرَيْشٌ بِنَاءَ الْكَعْبَةِ؟"}, {"s": "anos", "t": "وَعُمُرُهُ خَمْسٌ وَثَلَاثُونَ سَنَةً. وَاخْتَلَفُوا: مَنْ يَضَعُ الْحَجَرَ الْأَسْوَدَ؟ فَحَكَّمُوهُ، فَوَضَعَهُ فِي ثَوْبٍ، وَأَخَذَتْ كُلُّ قَبِيلَةٍ مِنَ الْقَبَائِلِ الْأَرْبَعِ بِطَرَفٍ، فَلَمَّا رَفَعُوهُ وَضَعَهُ بِيَدِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "fasih", "t": "وَكَيْفَ كَانَ حَالُهُ قَبْلَ الْوَحْيِ؟"}, {"s": "anos", "t": "كَانَ يَتَعَبَّدُ لِلَّهِ فِي غَارِ حِرَاءَ، وَيَأْخُذُ مَعَهُ الزَّادَ. وَنَزَلَ عَلَيْهِ الْوَحْيُ أَوَّلَ مَرَّةٍ وَهُوَ فِي الْغَارِ يَتَعَبَّدُ."}, {"s": "fasih", "t": "وَمَا أَوَّلُ مَا بُدِئَ بِهِ الْوَحْيُ؟"}, {"s": "anos", "t": "الرُّؤْيَا الصَّادِقَةُ، فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، أَيْ وَاضِحَةً كَضَوْءِ الْفَجْرِ. رَوَاهُ الْبُخَارِيُّ عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا."}, {"s": "fasih", "t": "كَمْ كَانَ عُمُرُهُ يَوْمَ بُعِثَ؟ وَإِلَى مَنْ بُعِثَ؟"}, {"s": "anos", "t": "أَرْبَعِينَ سَنَةً، وَبُعِثَ إِلَى النَّاسِ كَافَّةً، بَشِيرًا وَنَذِيرًا."}, {"s": "fasih", "t": "وَمَا أَوَّلُ مَا نَزَلَ عَلَيْهِ مِنَ الْقُرْآنِ؟"}, {"s": "anos", "t": "أَوَّلُ خَمْسِ آيَاتٍ مِنْ سُورَةِ الْعَلَقِ. اسْمَعُوا أَوَّلَهَا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "96:1", "t": "ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ"}, {"s": "fasih", "t": "أَوَّلُ كَلِمَةٍ: اقْرَأْ! إِذَنْ دِينُنَا دِينُ الْعِلْمِ وَالْقِرَاءَةِ!"}, {"s": "anos", "t": "صَدَقْتَ، فَلْنَبْدَأْ قِرَاءَتَنَا وَدِرَاسَتَنَا بِاسْمِ اللَّهِ، وَنَطْلُبِ الْعِلْمَ النَّافِعَ."}, {"s": "fasih", "t": "وَمَنْ أَوَّلُ مَنْ آمَنَ بِرِسَالَتِهِ؟"}, {"s": "anos", "t": "مِنَ الرِّجَالِ: أَبُو بَكْرٍ الصِّدِّيقُ، وَمِنَ النِّسَاءِ: خَدِيجَةُ بِنْتُ خُوَيْلِدٍ، وَمِنَ الصِّبْيَانِ: عَلِيُّ بْنُ أَبِي طَالِبٍ، وَمِنَ الْمَوَالِي: زَيْدُ بْنُ حَارِثَةَ، وَمِنَ الْأَرِقَّاءِ: بِلَالٌ الْحَبَشِيُّ، وَغَيْرُهُمْ."}, {"s": "fasih", "t": "عَلِيٌّ آمَنَ وَهُوَ صَبِيٌّ مِثْلُكُمْ يَا أَصْدِقَاءُ!"}, {"s": "anos", "t": "هَلْ تَعْلَمُ؟ ضَوْءُ الشَّمْسِ يَصِلُ إِلَى الْأَرْضِ فِي ثَمَانِي دَقَائِقَ تَقْرِيبًا، مَعَ أَنَّ بَيْنَهُمَا نَحْوَ مِائَةٍ وَخَمْسِينَ مِلْيُونَ كِيلُومِتْرٍ!"}, {"s": "anos", "t": "الْآنَ «تَمْثِيلُ حَلِّ الْحَجَرِ الْأَسْوَدِ»: أَرْبَعُ مَجْمُوعَاتٍ تُمْسِكُ بِأَطْرَافِ قُمَاشٍ، وَتَرْفَعُ الْحَجَرَ مَعًا."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَمَثِّلُوهَا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: تمثيل حلّ الحجر الأسود"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أَرْبَعَةُ أَصْدِقَاءَ يُرِيدُ كُلٌّ مِنْهُمْ أَنْ يَبْدَأَ بِالْكُرَةِ. أ: يَأْخُذُهَا الْأَقْوَى بِالْقُوَّةِ. ب: يَغْضَبُ أَنُوس وَيَأْخُذُهَا إِلَى الْبَيْتِ. ج: يَقْتَرِحُ أَنُوس أَنْ يَتَنَاوَبُوا بِالتَّرْتِيبِ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: خلاف على الكرة"}, {"s": "anos", "t": "«أ» ظُلْمٌ، وَ«ب» يُفْسِدُ اللَّعِبَ. وَالصَّحِيحُ «ج»، كَحِكْمَةِ النَّبِيِّ فِي الْحَجَرِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: كَمْ كَانَ عُمُرُ النَّبِيِّ حِينَ بُعِثَ؟ فَكِّرُوا..."}, {"s": "anos", "t": "أَرْبَعُونَ سَنَةً! وَأَيْنَ نَزَلَ عَلَيْهِ الْوَحْيُ أَوَّلَ مَرَّةٍ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "فِي غَارِ حِرَاءَ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا أَوَّلُ مَنْ آمَنَ بِالنَّبِيِّ، وَزَوْجَتُهُ الْأُولَى، وَاسَيْتُهُ بِمَالِي وَنَفْسِي."}, {"s": "anos", "t": "عَائِشَةُ، أَمْ فَاطِمَةُ، أَمْ خَدِيجَةُ رَضِيَ اللَّهُ عَنْهُنَّ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «مَكْتَبَةُ اقْرَأْ»: احْفَظُوا أَوَّلَ سُورَةِ الْعَلَقِ، وَاقْرَؤُوا مَعَ أُسْرَتِكُمْ كُلَّ يَوْمٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ فَصِيح إِلَى غَارِ حِرَاءَ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 13, "title": "الدعوة في مكّة والهجرة", "season": 2, "goals": ["seerah"], "hook": "أهلًا يا أصدقاء! فصيح يحمل خريطة ويرسم سهمًا طويلًا من مكّة إلى المدينة ويقول: «أنوس، لماذا ترك النبيّ ﷺ بلده الحبيب مكّة؟ وما هي الرحلة العجيبة إلى السماء؟». اربطوا الأحزمة، رحلتنا اليوم طويلة وجميلة!", "sections": [{"h": "دعوة سرّية ثم دعوة جهرية", "p": ["بدأ النبيّ ﷺ يدعو إلى الإسلام <b>سرًّا نحو ثلاث سنين</b>، يدعو من يثق بهم واحدًا واحدًا.", "ثم أمره الله <b>بالجهر بالدعوة</b>، فصار يدعو الناس جميعًا علانية: اعبدوا الله وحده، واتركوا الأصنام.", "فصيح يقول: «وهل فرح المشركون؟». لا يا فصيح، <b>بالغ المشركون في أذيّته وأذيّة المسلمين</b>، حتى أذن للمؤمنين أن <b>يهاجروا إلى النجاشيّ في الحبشة</b>. واجتمع المشركون على أذيّته وقتله ﷺ، <b>فحماه الله</b> بعمّه <b>أبي طالب</b>."], "board": ["سرًّا: نحو 3 سنين", "ثم جهرًا", "الهجرة إلى الحبشة", "حماية أبي طالب"]}, {"h": "عام الحزن، ثم رحلة إلى السماء", "p": ["في <b>العام العاشر من البعثة</b> توفّي عمّه <b>أبو طالب</b>، وزوجته <b>خديجة</b> رضي الله عنها. فحزن النبيّ ﷺ حزنًا كبيرًا.", "ثم أكرمه الله برحلة عجيبة: <b>الإسراء والمعراج</b>، وكان ذلك في الخمسين من عمره.", "<b>الإسراء</b>: من <b>المسجد الحرام</b> في مكّة إلى <b>المسجد الأقصى</b> في القدس. و<b>المعراج</b>: من <b>المسجد الأقصى</b> إلى السماء، إلى <b>سدرة المنتهى</b>.", "وفي هذه الرحلة <b>فُرضت الصلوات الخمس</b>. أنوس يقول: «الصلاة هديّة من السماء! فكيف أتركها؟»."], "board": ["العام 10: وفاة أبي طالب وخديجة", "الإسراء: الحرام ← الأقصى", "المعراج: الأقصى ← سدرة المنتهى", "فُرضت الصلوات الخمس"]}, {"h": "يبحث عن قلوب تسمع: الطائف والأنصار", "p": ["لم يتوقّف النبيّ ﷺ عن الدعوة. فكان <b>يدعو أهل الطائف</b>، و<b>يعرض نفسه في المواسم ومجامع الناس</b>، حين تجتمع القبائل في مكّة.", "حتى جاء <b>أهل المدينة من الأنصار</b>، فآمنوا بالنبيّ ﷺ، و<b>بايعوه على نصرته</b>، أي: وعدوه أن يحموه وينصروه.", "فصيح يتعجّب: «كل هذا التعب ولم ييأس!». نعم، هذا هو الصبر. وإذا تعبت في حفظ سورة أو في واجب صعب، فتذكّر صبر النبيّ ﷺ."], "board": ["دعوة أهل الطائف", "المواسم ومجامع الناس", "الأنصار يبايعون"]}, {"h": "الهجرة: من مكّة إلى المدينة", "p": ["<b>بقي النبيّ ﷺ في مكّة ثلاث عشرة سنة</b> يدعو إلى الله.", "ثم <b>هاجر من مكّة إلى المدينة</b>، وصحبه أبو بكر الصدّيق، واختبآ في غار ثور، والله يحفظهما. وقال النبيّ ﷺ لأبي بكر: «ما ظنّك باثنين الله ثالثهما».", "و<b>بقي في المدينة عشر سنين</b>، فصار مجموع سنين الرسالة: 13 + 10 = <b>23 سنة</b>."], "board": ["مكّة: 13 سنة", "الهجرة ← المدينة", "المدينة: 10 سنين"]}], "summary": ["كانت الدعوة سرًّا نحو ثلاث سنين ثم جهرًا، فآذى المشركون المسلمين حتى هاجروا إلى النجاشيّ، وحمى الله نبيّه بعمّه أبي طالب.", "في العام العاشر من البعثة توفّي أبو طالب وخديجة، ثم كان الإسراء من المسجد الحرام إلى الأقصى، والمعراج إلى سدرة المنتهى، وفيه فُرضت الصلوات الخمس.", "دعا ﷺ أهل الطائف والقبائل حتى بايعه الأنصار، وبقي في مكّة 13 سنة، ثم هاجر إلى المدينة وبقي فيها 10 سنين."], "islam": {"intro": "قال الله تعالى يحكي عن الهجرة وصاحبَي الغار:", "text": "فالله مع عباده المؤمنين يحفظهم وينصرهم. إذا خفت، فقل: «لا تحزن، إنّ الله معنا».", "ayah": {"text": "إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ", "src": "سُورَةُ التَّوۡبَةِ: ٤٠"}, "hadith": {"text": "ما ظنّك يا أبا بكر باثنين الله ثالثهما", "source": "متفق عليه عن أبي بكر رضي الله عنه"}}, "home": {"title": "دفتر رحلة الهجرة", "goal": "أن يرتّب الطفل أحداث الدعوة في مكّة والهجرة، ويتعلّم الصبر والثبات.", "materials": ["دفتر صغير", "ألوان", "ملصقات"], "steps": ["ارسم في كل صفحة حدثًا: الدعوة سرًّا، الهجرة إلى الحبشة، الإسراء والمعراج، بيعة الأنصار، الهجرة إلى المدينة.", "اكتب تحت كل رسمة جملة قصيرة من الحلقة.", "احكِ القصّة لأسرتك وقت العشاء مستعملًا الدفتر.", "اختر عملًا صعبًا عليك هذا الأسبوع، واصبر عليه حتى تتمّه، ثم اكتب: «صبرت كما صبر الصحابة»."], "parent": "ساعدوا الطفل في الرسم دون أن ترسموا عنه، واسألوه أسئلة مفتوحة: «لو كنت مكان المسلمين في مكّة، كيف تصبر؟»."}, "online": {"title": "رحلة فصيح من مكّة إلى المدينة", "intro": "رتّب أحداث الدعوة، ثم ميّز الإسراء من المعراج!", "steps": [{"type": "order", "title": "رتّب أحداث الدعوة", "prompt": "رتّب الأحداث من الأوّل إلى الأخير.", "items": ["الدعوة سرًّا نحو ثلاث سنين", "الجهر بالدعوة", "هجرة المسلمين إلى النجاشيّ في الحبشة", "وفاة أبي طالب وخديجة في العام العاشر", "الأنصار يبايعون النبيّ ﷺ على نصرته", "الهجرة من مكّة إلى المدينة"]}, {"type": "sort", "title": "إسراء أم معراج؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["الإسراء", "المعراج"], "items": [{"t": "بدأ من المسجد الحرام", "icon": "🕋", "bin": 0, "why": "الإسراء من المسجد الحرام."}, {"t": "انتهى إلى المسجد الأقصى", "icon": "🕌", "bin": 0, "why": "الإسراء انتهى إلى المسجد الأقصى."}, {"t": "صعود إلى السماء", "icon": "☁️", "bin": 1, "why": "المعراج صعود من الأقصى إلى السماء."}, {"t": "وصل إلى سدرة المنتهى", "icon": "🌳", "bin": 1, "why": "المعراج كان إلى سدرة المنتهى."}, {"t": "رحلة على الأرض من مكّة إلى القدس", "icon": "🗺️", "bin": 0, "why": "هذا هو الإسراء."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "إلى أين هاجر النبيّ ﷺ؟", "o": ["إلى الطائف", "من مكّة إلى المدينة", "إلى الشام"], "a": 1, "why": "هاجر من مكّة إلى المدينة."}, {"q": "على ماذا بايع الأنصار النبيّ ﷺ؟", "o": ["على التجارة", "على السفر", "على نصرته"], "a": 2, "why": "آمنوا به وبايعوه على نصرته."}, {"q": "كم سنة بقي النبيّ ﷺ في المدينة؟", "o": ["عشر سنين", "ثلاث سنين", "عشرين سنة"], "a": 0, "why": "بقي في المدينة عشر سنين."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز على خريطة الهجرة، فيها صحابيّ شجاع. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا أوّل من أسلم من الصبيان.", "نمت في فراش النبيّ ﷺ ليلة الهجرة.", "زوّجني النبيّ ﷺ ابنته فاطمة."], "options": ["أبو بكر الصدّيق رضي الله عنه", "بلال بن رباح رضي الله عنه", "عليّ بن أبي طالب رضي الله عنه"], "deep": "لماذا كان النوم في فراش النبيّ ﷺ ليلة الهجرة عملًا شجاعًا؟ وماذا يعلّمنا عن حبّ الصحابة للنبيّ ﷺ؟", "reveal": "أنا عليّ بن أبي طالب رضي الله عنه، ابن عمّ النبيّ ﷺ، وصرت رابع الخلفاء الراشدين. وفي الحلقة القادمة نتعلّم حياة النبيّ ﷺ في المدينة حتى وفاته، ونتعرّف على أهل بيته."}, "quiz": [{"q": "كم سنة كانت الدعوة سرًّا؟", "o": ["سنة واحدة", "نحو ثلاث سنين", "عشر سنين"], "a": 1, "why": "كانت الدعوة سرًّا نحو ثلاث سنين، ثم أُمر بالجهر."}], "qa": [{"id": 107, "q": "كيف كانتِ الدعوةُ إلى الإسلام؟", "a": "كانتِ الدعوةُ سرًّا نحوَ ثلاثِ سنين، ثم أمرَ ﷺ بالجهرِ بالدعوة."}, {"id": 108, "q": "ما كان حالُ النبيِّ ﷺ ومن آمنَ به بعد الجهرِ بالدعوة؟", "a": "بالغَ المشركونَ في أذيتِهِ وأذيةِ المسلمين، حتى أذِنَ للمؤمنينَ بالهجرةِ إلى النجاشيِّ في الحبشة. وأجمعَ أهلُ الشركِ على أذيةِ وقتلِ النبيِّ ﷺ، فحماهُ اللهُ وأحاطَهُ بعمِّهِ أبي طالبٍ ليحميَهُ منهم."}, {"id": 109, "q": "مَن توفيَ في العامِ العاشرِ من بعثتِهِ ﷺ؟", "a": "توفيَ عمُّهُ أبو طالب، وزوجتُهُ خديجةُ رضي الله عنها."}, {"id": 110, "q": "متى كان الإسراءُ والمعراج؟", "a": "كان في الخمسينَ من عمره، وفُرِضتْ عليه الصلواتُ الخمس.\n• الإسراء: من المسجدِ الحرامِ إلى المسجدِ الأقصى.\n• والمعراج: كان من المسجدِ الأقصى إلى السماءِ إلى سدرةِ المنتهى."}, {"id": 111, "q": "كيف كان النبيُّ ﷺ يدعو الناسَ خارجَ مكة؟", "a": "كان يدعو أهلَ الطائف، ويعرِضُ نفسَهُ في المواسمِ ومجامعِ الناس، حتى جاءَ أهلُ المدينةِ من الأنصار، فآمنوا بالنبيِّ ﷺ، وبايعوهُ على نصرتِه."}, {"id": 112, "q": "كم بقيَ النبيُّ ﷺ في مكةَ يدعو؟", "a": "بقيَ ثلاثَ عشرةَ سنة."}, {"id": 113, "q": "إلى أين هاجرَ النبيُّ ﷺ؟", "a": "من مكةَ إلى المدينة."}, {"id": 114, "q": "كم بقيَ في المدينة؟", "a": "عشرَ سنين."}], "dyk": ["كلُّ نجمٍ عليه حافظٌ بأمرِ الله، والنجومُ زينةٌ للسماءِ وعلاماتٌ يُهتدى بها في الظلام."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهَا خَدِيجَةُ بِنْتُ خُوَيْلِدٍ رَضِيَ اللَّهُ عَنْهَا، طَمْأَنَتِ النَّبِيَّ لَمَّا رَجَعَ مِنَ الْغَارِ!"}, {"s": "anos", "t": "وَالْيَوْمَ نَرْسُمُ سَهْمًا طَوِيلًا عَلَى الْخَرِيطَةِ: مِنْ مَكَّةَ إِلَى الْمَدِينَةِ!"}, {"s": "fasih", "t": "كَيْفَ كَانَتِ الدَّعْوَةُ إِلَى الْإِسْلَامِ؟"}, {"s": "anos", "t": "كَانَتْ سِرًّا نَحْوَ ثَلَاثِ سِنِينَ، ثُمَّ أَمَرَهُ اللَّهُ بِالْجَهْرِ بِالدَّعْوَةِ."}, {"s": "fasih", "t": "وَمَاذَا حَدَثَ بَعْدَ الْجَهْرِ؟"}, {"s": "anos", "t": "بَالَغَ الْمُشْرِكُونَ فِي أَذِيَّتِهِ وَأَذِيَّةِ الْمُسْلِمِينَ، حَتَّى أَذِنَ لِلْمُؤْمِنِينَ بِالْهِجْرَةِ إِلَى النَّجَاشِيِّ فِي الْحَبَشَةِ. وَأَجْمَعُوا عَلَى أَذِيَّتِهِ وَقَتْلِهِ، فَحَمَاهُ اللَّهُ بِعَمِّهِ أَبِي طَالِبٍ."}, {"s": "fasih", "t": "وَمَنْ تُوُفِّيَ فِي الْعَامِ الْعَاشِرِ مِنَ الْبَعْثَةِ؟"}, {"s": "anos", "t": "عَمُّهُ أَبُو طَالِبٍ، وَزَوْجَتُهُ خَدِيجَةُ رَضِيَ اللَّهُ عَنْهَا، فَحَزِنَ حُزْنًا كَبِيرًا."}, {"s": "fasih", "t": "وَمَتَى كَانَ الْإِسْرَاءُ وَالْمِعْرَاجُ؟"}, {"s": "anos", "t": "فِي الْخَمْسِينَ مِنْ عُمُرِهِ، وَفِيهِ فُرِضَتِ الصَّلَوَاتُ الْخَمْسُ. الْإِسْرَاءُ: مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى، وَالْمِعْرَاجُ: مِنَ الْمَسْجِدِ الْأَقْصَى إِلَى السَّمَاءِ، إِلَى سِدْرَةِ الْمُنْتَهَى."}, {"s": "fasih", "t": "الصَّلَاةُ هَدِيَّةٌ مِنَ السَّمَاءِ! وَكَيْفَ كَانَ يَدْعُو النَّاسَ خَارِجَ مَكَّةَ؟"}, {"s": "anos", "t": "كَانَ يَدْعُو أَهْلَ الطَّائِفِ، وَيَعْرِضُ نَفْسَهُ فِي الْمَوَاسِمِ وَمَجَامِعِ النَّاسِ، حَتَّى جَاءَ الْأَنْصَارُ مِنْ أَهْلِ الْمَدِينَةِ، فَآمَنُوا بِهِ، وَبَايَعُوهُ عَلَى نُصْرَتِهِ."}, {"s": "fasih", "t": "لَمْ يَيْأَسْ أَبَدًا! وَكَمْ بَقِيَ فِي مَكَّةَ يَدْعُو؟"}, {"s": "anos", "t": "ثَلَاثَ عَشْرَةَ سَنَةً."}, {"s": "fasih", "t": "وَإِلَى أَيْنَ هَاجَرَ؟ وَكَمْ بَقِيَ هُنَاكَ؟"}, {"s": "anos", "t": "هَاجَرَ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ، وَبَقِيَ فِيهَا عَشْرَ سِنِينَ. وَصَحِبَهُ أَبُو بَكْرٍ، وَاخْتَبَآ فِي غَارِ ثَوْرٍ. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ التَّوْبَةِ."}, {"s": "quran", "ref": "9:40", "t": "إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ"}, {"s": "fasih", "t": "لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا! وَقَالَ النَّبِيُّ لِأَبِي بَكْرٍ: «مَا ظَنُّكَ يَا أَبَا بَكْرٍ بِاثْنَيْنِ اللَّهُ ثَالِثُهُمَا»، مُتَّفَقٌ عَلَيْهِ."}, {"s": "anos", "t": "فَإِذَا خِفْتَ يَوْمًا، فَتَذَكَّرْ أَنَّ اللَّهَ مَعَ عِبَادِهِ الْمُؤْمِنِينَ يَحْفَظُهُمْ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ كُلُّ نَجْمٍ عَلَيْهِ حَافِظٌ بِأَمْرِ اللَّهِ، وَالنُّجُومُ زِينَةٌ لِلسَّمَاءِ وَعَلَامَاتٌ يُهْتَدَى بِهَا فِي الظَّلَامِ!"}, {"s": "anos", "t": "الْآنَ «خَرِيطَةُ الرِّحْلَةِ الْكُبْرَى»: ضَعُوا نَجْمَةً عَلَى مَكَّةَ، وَارْسُمُوا سِهَامَ الْحَبَشَةِ، وَالْإِسْرَاءِ، وَالْمِعْرَاجِ، وَالْهِجْرَةِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَارْسُمُوهَا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: خريطة الرحلة الكبرى"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! قَامَ أَنُوس يُصَلِّي فِي رِحْلَةٍ مَدْرَسِيَّةٍ، فَضَحِكَ مِنْهُ بَعْضُ الْأَوْلَادِ. أ: يَتْرُكُ الصَّلَاةَ. ب: يَصْبِرُ وَيُصَلِّي، ثُمَّ يُكَلِّمُهُمْ بِلُطْفٍ. ج: يَضْرِبُهُمْ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: سخروا منّي لأنّي أصلّي"}, {"s": "anos", "t": "«أ» ضَعْفٌ، وَ«ج» ظُلْمٌ. وَالصَّحِيحُ «ب»؛ فَالنَّبِيُّ وَأَصْحَابُهُ أُوذُوا فِي مَكَّةَ، فَصَبَرُوا وَدَعَوْا بِالْحِكْمَةِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: الْإِسْرَاءُ كَانَ مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى أَيْنَ؟ فَكِّرُوا..."}, {"s": "anos", "t": "إِلَى الْمَسْجِدِ الْأَقْصَى! وَمَاذَا فُرِضَ فِي تِلْكَ الرِّحْلَةِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "الصَّلَوَاتُ الْخَمْسُ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا أَوَّلُ مَنْ أَسْلَمَ مِنَ الصِّبْيَانِ، نِمْتُ فِي فِرَاشِ النَّبِيِّ لَيْلَةَ الْهِجْرَةِ، وَزَوَّجَنِي ابْنَتَهُ فَاطِمَةَ."}, {"s": "anos", "t": "أَبُو بَكْرٍ، أَمْ بِلَالٌ، أَمْ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «دَفْتَرُ رِحْلَةِ الْهِجْرَةِ»: ارْسُمُوا كُلَّ حَدَثٍ، وَاحْكُوا الْقِصَّةَ لِأُسْرَتِكُمْ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «رِحْلَةُ فَصِيح مِنْ مَكَّةَ إِلَى الْمَدِينَةِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 14, "title": "في المدينة حتى الوفاة، وأهل بيته ﷺ", "season": 2, "goals": ["seerah"], "hook": "أهلًا يا أصدقاء! فصيح يقف على نافذة ويقول: «أنوس، وصل النبيّ ﷺ إلى المدينة واستقبله الأنصار بفرح. فماذا حدث بعد ذلك؟ ومن هم أهل بيته؟ وكيف كان شكله الجميل ﷺ؟». هيّا نكمل رحلة السيرة!", "sections": [{"h": "في المدينة: شرائع جديدة", "p": ["في المدينة <b>فُرضت شرائع كثيرة من شرائع الإسلام</b>: <b>الزكاة</b>، و<b>الصيام</b>، و<b>الحجّ</b>، و<b>الجهاد</b>، و<b>الأذان</b>، وغيرها.", "فصيح يتذكّر: «الصلوات الخمس فُرضت في مكّة في الإسراء والمعراج، والزكاة والصيام والحجّ في المدينة!». أحسنت يا فصيح، ذاكرتك قويّة!", "وكلّما سمعت الأذان في حيّك، تذكّر أنّه بدأ في المدينة في زمن النبيّ ﷺ، وما زال يُرفع إلى اليوم."], "board": ["الزكاة", "الصيام", "الحجّ", "الجهاد", "الأذان"]}, {"h": "أهمّ الغزوات، وآخر ما نزل", "p": ["دافع المسلمون عن دينهم في غزوات كثيرة، أهمّها: <b>غزوة بدر الكبرى</b> في العام <b>الثاني</b> من الهجرة، و<b>غزوة أحد</b> في العام <b>الثالث</b>، و<b>غزوة الأحزاب</b> في العام <b>الخامس</b>، و<b>فتح مكّة</b> في العام <b>الثامن</b>.", "أنوس يقول: «تخيّلوا! خرج النبيّ ﷺ من مكّة مهاجرًا، ثم رجع إليها فاتحًا بعد ثماني سنين!».", "و<b>آخر ما نزل من القرآن</b>: «واتّقوا يومًا تُرجعون فيه إلى الله، ثم تُوفّى كلّ نفس ما كسبت وهم لا يُظلمون». آية تذكّرنا بيوم القيامة.", "ثم <b>توفّي النبيّ ﷺ في شهر ربيع الأوّل، من السنة الحادية عشرة من الهجرة</b>، وعمره <b>ثلاث وستّون سنة</b>."], "board": ["بدر: 2 هـ", "أحد: 3 هـ", "الأحزاب: 5 هـ", "فتح مكّة: 8 هـ", "الوفاة: ربيع الأوّل 11 هـ، 63 سنة"]}, {"h": "أهل بيته ﷺ: أزواجه وأولاده", "p": ["<b>أزواج النبيّ ﷺ</b> هنّ أمّهات المؤمنين، ومنهنّ: <b>خديجة بنت خويلد</b>، و<b>سودة بنت زمعة</b>، و<b>عائشة بنت أبي بكر الصدّيق</b>، و<b>حفصة بنت عمر</b>، و<b>أمّ سلمة</b>، و<b>زينب بنت جحش</b>، وغيرهنّ، رضي الله عنهنّ جميعًا. وعددهنّ في الكتاب إحدى عشرة.", "و<b>أولاده من الذكور ثلاثة</b>: <b>القاسم</b> وبه كان يُكنى «أبا القاسم»، و<b>عبد الله</b>، و<b>إبراهيم</b>. <b>ومن الإناث</b>: <b>فاطمة</b>، و<b>رقيّة</b>، و<b>أمّ كلثوم</b>، و<b>زينب</b>.", "وكلّ أولاده من <b>خديجة</b> رضي الله عنها، إلا <b>إبراهيم</b> فمن <b>مارية القبطية</b>. وكلّهم مات قبله، إلا <b>فاطمة</b> ماتت بعده بستّة أشهر."], "board": ["الذكور: القاسم، عبد الله، إبراهيم", "الإناث: فاطمة، رقيّة، أمّ كلثوم، زينب", "فاطمة عاشت بعده 6 أشهر"]}, {"h": "كيف كان شكله ﷺ؟ وعلى ماذا تركنا؟", "p": ["كان ﷺ <b>وسطًا من الرجال</b>: ليس بالقصير ولا بالطويل. وكان <b>أبيض مشربًا بحمرة</b>، <b>كثيف اللحية</b>، <b>واسع العينين</b>، شعره <b>شديد السواد</b>، <b>عظيم المنكبين</b>، <b>طيّب الرائحة</b> ﷺ.", "فصيح يقول: «يا ليتني رأيته!». أنوس: نحن نحبّه وإن لم نره، ونرجو أن نراه في الجنّة إن اتّبعنا سنّته.", "و<b>ترك النبيّ ﷺ أمّته على المحجّة البيضاء</b>: طريق واضح كالنور، <b>ليلها كنهارها</b>. <b>ما ترك خيرًا إلا دلّنا عليه، ولا شرًّا إلا حذّرنا منه</b>."], "board": ["وسط من الرجال", "طيّب الرائحة", "المحجّة البيضاء: ليلها كنهارها"]}], "summary": ["في المدينة فُرضت الزكاة والصيام والحجّ والجهاد والأذان، وأهمّ الغزوات: بدر (2 هـ)، أحد (3 هـ)، الأحزاب (5 هـ)، فتح مكّة (8 هـ).", "آخر ما نزل: «واتّقوا يومًا تُرجعون فيه إلى الله»، وتوفّي النبيّ ﷺ في ربيع الأوّل سنة 11 هـ وعمره 63 سنة.", "أولاده: القاسم وعبد الله وإبراهيم، وفاطمة ورقيّة وأمّ كلثوم وزينب، وتركنا ﷺ على المحجّة البيضاء ليلها كنهارها."], "islam": {"intro": "قال الله تعالى يجعل لنا نبيّنا ﷺ قدوة:", "text": "فنقتدي به ﷺ في صلاته وصدقه ورحمته وصبره، ونتّبع الطريق الواضح الذي تركنا عليه.", "ayah": {"text": "لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًۭا", "src": "سُورَةُ الأَحۡزَابِ: ٢١"}, "hadith": {"text": "قد تركتكم على البيضاء، ليلها كنهارها، لا يزيغ عنها بعدي إلا هالك", "source": "رواه أحمد وابن ماجه عن العرباض بن سارية رضي الله عنه"}}, "home": {"title": "بطاقة عائلة النبيّ ﷺ", "goal": "أن يحفظ الطفل أسماء أولاد النبيّ ﷺ وبعض أمّهات المؤمنين، ويتّبع سنّة من سننه.", "materials": ["ورق مقوّى", "ألوان", "قارورة عطر صغيرة"], "steps": ["اصنع بطاقتين: الأولى فيها أولاد النبيّ ﷺ (القاسم، عبد الله، إبراهيم، فاطمة، رقيّة، أمّ كلثوم، زينب)، والثانية فيها خمس من أمّهات المؤمنين.", "العب مع أسرتك: يقول أحدهم اسمًا، وتقول أنت: «ولد» أو «بنت» أو «أمّ المؤمنين».", "اختر سنّة من سنن النبيّ ﷺ وطبّقها كل يوم هذا الأسبوع، مثل التطيّب، أو التبسّم، أو السلام.", "اكتب في آخر الأسبوع: ماذا تعلّمت من اتّباع هذه السنّة؟"], "parent": "تحدّثوا عن النبيّ ﷺ وأهل بيته بمحبّة وتوقير، وكونوا أوّل من يطبّق السنّة أمام أطفالكم."}, "online": {"title": "قطار فصيح في المدينة", "intro": "رتّب الغزوات، ثم صنّف أولاد النبيّ ﷺ!", "steps": [{"type": "order", "title": "رتّب الأحداث", "prompt": "رتّب من الأقدم إلى الأحدث.", "items": ["غزوة بدر الكبرى (2 هـ)", "غزوة أحد (3 هـ)", "غزوة الأحزاب (5 هـ)", "فتح مكّة (8 هـ)", "وفاة النبيّ ﷺ (11 هـ)"]}, {"type": "sort", "title": "أولاد النبيّ ﷺ: ذكور أم إناث؟", "prompt": "اضغط على الاسم، ثم اختر مكانه.", "bins": ["من الذكور", "من الإناث"], "items": [{"t": "القاسم", "icon": "👦", "bin": 0, "why": "القاسم، وبه كان يُكنى ﷺ."}, {"t": "فاطمة", "icon": "👧", "bin": 1, "why": "فاطمة، عاشت بعده ستّة أشهر."}, {"t": "إبراهيم", "icon": "👶", "bin": 0, "why": "إبراهيم، أمّه مارية القبطية."}, {"t": "رقيّة", "icon": "👧", "bin": 1, "why": "رقيّة، من خديجة رضي الله عنها."}, {"t": "عبد الله", "icon": "👦", "bin": 0, "why": "عبد الله، من خديجة رضي الله عنها."}, {"t": "زينب", "icon": "👧", "bin": 1, "why": "زينب، من خديجة رضي الله عنها."}, {"t": "أمّ كلثوم", "icon": "👧", "bin": 1, "why": "أمّ كلثوم، من خديجة رضي الله عنها."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "أيّ أولاد النبيّ ﷺ ليس من خديجة؟", "o": ["فاطمة", "القاسم", "إبراهيم"], "a": 2, "why": "إبراهيم من مارية القبطية، والباقون من خديجة."}, {"q": "ما آخر ما نزل من القرآن؟", "o": ["واتّقوا يومًا تُرجعون فيه إلى الله", "اقرأ باسم ربّك", "قل هو الله أحد"], "a": 0, "why": "آخر ما نزل آية البقرة 281."}, {"q": "كيف كان طول النبيّ ﷺ؟", "o": ["طويلًا جدًّا", "وسطًا، لا قصيرًا ولا طويلًا", "قصيرًا جدًّا"], "a": 1, "why": "كان وسطًا من الرجال."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز في قصّة غزوة أُحُد، فيها صحابية شجاعة. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["أنا صحابية من الأنصار، دافعت عن النبيّ ﷺ يوم أُحُد بسيفي.", "جُرحت وأنا أحميه.", "أخبر النبيّ ﷺ أنّه كان يراني أقاتل دونه يمينًا وشمالًا."], "options": ["نُسيبة بنت كعب (أمّ عُمارة) رضي الله عنها", "عائشة رضي الله عنها", "فاطمة الزهراء رضي الله عنها"], "deep": "غزوة أُحُد كانت في العام الثالث من الهجرة. ماذا يعلّمنا ثبات نُسيبة عن حبّ الصحابة للنبيّ ﷺ ونصرته؟", "reveal": "أنا نُسيبة بنت كعب، أمّ عُمارة رضي الله عنها! وكنت من الأنصار الذين بايعوا النبيّ ﷺ على نصرته، فوفيت بوعدي. وفي الحلقة القادمة نتعلّم تفسير سورة الفاتحة وقصار السور."}, "quiz": [{"q": "في أيّ عام كانت غزوة بدر الكبرى؟", "o": ["في العام الثامن", "في العام الثاني من الهجرة", "في العام الخامس"], "a": 1, "why": "بدر في العام الثاني، وأحد في الثالث، والأحزاب في الخامس، وفتح مكّة في الثامن."}], "qa": [{"id": 115, "q": "ماذا فُرِضَ عليه في المدينةِ من شرائعِ الإسلام؟", "a": "فُرِضَ عليه الزكاة، والصيام، والحج، والجهاد، والأذان، وغيرها من شرائعِ الإسلام."}, {"id": 116, "q": "ما أهمُّ غزواتِهِ ﷺ؟", "a": "• غزوةُ بدرٍ الكبرى: في العامِ الثاني من الهجرة.\n• غزوةُ أحد: في العامِ الثالث من الهجرة.\n• غزوةُ الأحزاب: في العامِ الخامس من الهجرة.\n• غزوةُ فتحِ مكة: في العامِ الثامن من الهجرة."}, {"id": 117, "q": "ما آخرُ ما نزلَ من القرآن؟", "a": "قوله تعالى: ﴿وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ﴾ [البقرة: ٢٨١]."}, {"id": 118, "q": "متى توفيَ النبيُّ ﷺ؟ وكم كان عمرُه؟", "a": "توفيَ في شهرِ ربيعٍ الأول، من السنةِ الحاديةَ عشرةَ من الهجرة، وله من العمرِ ثلاثٌ وستونَ سنة."}, {"id": 119, "q": "اذكرْ أزواجَ النبيِّ ﷺ؟", "a": "١. خديجةُ بنتُ خويلد. ٢. سودةُ بنتُ زمعة. ٣. عائشةُ بنتُ أبي بكرٍ الصديق. ٤. حفصةُ بنتُ عمر. ٥. زينبُ بنتُ خزيمة. ٦. أمُّ سلمةَ هندُ بنتُ أبي أمية. ٧. أمُّ حبيبةَ رملةُ بنتُ أبي سفيان. ٨. جويريةُ بنتُ الحارث. ٩. ميمونةُ بنتُ الحارث. ١٠. صفيةُ بنتُ حُييّ. ١١. زينبُ بنتُ جحش. رضي الله عنهنَّ جميعًا."}, {"id": 120, "q": "مَن أولادُهُ ﷺ؟", "a": "من الذكورِ ثلاثة:\n• القاسم، وبه كان يُكنى. • وعبدُ الله. • وإبراهيم.\nمن الإناث:\n• فاطمة. • رقية. • أمُّ كلثوم. • زينب.\nوكلُّ ولدِهِ من خديجةَ رضي الله عنها، إلا إبراهيمَ من ماريةَ القبطية، وكلُّهم ماتَ قبلَهُ إلا فاطمةَ بعدَهُ بستةِ أشهر."}, {"id": 121, "q": "اذكرْ بعضَ صفاتِ النبيِّ ﷺ الخَلقية.", "a": "كان ﷺ وسطًا من الرجالِ ليس بالقصيرِ ولا بالطويلِ بل بين ذلك، وكان أبيضَ مُشرَبًا بالحمرةِ عليه الصلاةُ والسلام، وكان كثيفَ اللحية، واسعَ العينين، عظيمَ الفم، شعرُهُ شديدُ السواد، عظيمَ المنكبين، طيبَ الرائحة، وغيرَ ذلك من خِلقتِهِ الجميلةِ ﷺ."}, {"id": 122, "q": "على أيِّ شيءٍ تركَ النبيُّ ﷺ أمتَه؟", "a": "تركَ أمتَهُ ﷺ على المحجةِ البيضاء، ليلُها كنهارِها، لا يزيغُ عنها إلا هالك، ما تركَ خيرًا إلا دلَّ الأمةَ عليه، ولا شرًّا إلا حذَّرَها منه."}], "dyk": ["في العسلِ شفاءٌ للناسِ كما قال القرآن، وأثبتَ العلمُ أنه يقتلُ الجراثيمَ ويشفي الجروح."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهُ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ، ابْنُ عَمِّ النَّبِيِّ، وَرَابِعُ الْخُلَفَاءِ الرَّاشِدِينَ!"}, {"s": "anos", "t": "وَالْيَوْمَ نُكْمِلُ السِّيرَةَ: النَّبِيُّ فِي الْمَدِينَةِ، وَأَهْلُ بَيْتِهِ."}, {"s": "fasih", "t": "مَاذَا فُرِضَ فِي الْمَدِينَةِ مِنْ شَرَائِعِ الْإِسْلَامِ؟"}, {"s": "anos", "t": "الزَّكَاةُ، وَالصِّيَامُ، وَالْحَجُّ، وَالْجِهَادُ، وَالْأَذَانُ، وَغَيْرُهَا."}, {"s": "fasih", "t": "وَمَا أَهَمُّ غَزَوَاتِهِ؟"}, {"s": "anos", "t": "بَدْرٌ الْكُبْرَى فِي الْعَامِ الثَّانِي مِنَ الْهِجْرَةِ، وَأُحُدٌ فِي الثَّالِثِ، وَالْأَحْزَابُ فِي الْخَامِسِ، وَفَتْحُ مَكَّةَ فِي الثَّامِنِ."}, {"s": "fasih", "t": "وَمَا آخِرُ مَا نَزَلَ مِنَ الْقُرْآنِ؟"}, {"s": "anos", "t": "آيَةٌ فِي سُورَةِ الْبَقَرَةِ تُذَكِّرُنَا بِيَوْمٍ نُرْجَعُ فِيهِ إِلَى اللَّهِ، ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ."}, {"s": "fasih", "t": "وَمَتَى تُوُفِّيَ النَّبِيُّ؟ وَكَمْ كَانَ عُمُرُهُ؟"}, {"s": "anos", "t": "فِي رَبِيعٍ الْأَوَّلِ، مِنَ السَّنَةِ الْحَادِيَةَ عَشْرَةَ مِنَ الْهِجْرَةِ، وَعُمُرُهُ ثَلَاثٌ وَسِتُّونَ سَنَةً."}, {"s": "fasih", "t": "اذْكُرْ أَزْوَاجَهُ، أُمَّهَاتِ الْمُؤْمِنِينَ."}, {"s": "anos", "t": "خَدِيجَةُ، وَسَوْدَةُ، وَعَائِشَةُ، وَحَفْصَةُ، وَزَيْنَبُ بِنْتُ خُزَيْمَةَ، وَأُمُّ سَلَمَةَ، وَأُمُّ حَبِيبَةَ، وَجُوَيْرِيَةُ، وَمَيْمُونَةُ، وَصَفِيَّةُ، وَزَيْنَبُ بِنْتُ جَحْشٍ، رَضِيَ اللَّهُ عَنْهُنَّ جَمِيعًا."}, {"s": "fasih", "t": "وَمَنْ أَوْلَادُهُ؟"}, {"s": "anos", "t": "مِنَ الذُّكُورِ: الْقَاسِمُ وَبِهِ كَانَ يُكْنَى، وَعَبْدُ اللَّهِ، وَإِبْرَاهِيمُ. وَمِنَ الْإِنَاثِ: فَاطِمَةُ، وَرُقَيَّةُ، وَأُمُّ كُلْثُومٍ، وَزَيْنَبُ. كُلُّهُمْ مِنْ خَدِيجَةَ إِلَّا إِبْرَاهِيمَ مِنْ مَارِيَةَ، وَمَاتُوا قَبْلَهُ إِلَّا فَاطِمَةَ بَعْدَهُ بِسِتَّةِ أَشْهُرٍ."}, {"s": "fasih", "t": "اذْكُرْ بَعْضَ صِفَاتِهِ الْخَلْقِيَّةِ."}, {"s": "anos", "t": "كَانَ وَسَطًا، لَيْسَ بِالْقَصِيرِ وَلَا بِالطَّوِيلِ، أَبْيَضَ مُشْرَبًا بِحُمْرَةٍ، كَثِيفَ اللِّحْيَةِ، وَاسِعَ الْعَيْنَيْنِ، شَدِيدَ سَوَادِ الشَّعْرِ، عَظِيمَ الْمَنْكِبَيْنِ، طَيِّبَ الرَّائِحَةِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "fasih", "t": "يَا لَيْتَنِي رَأَيْتُهُ! وَعَلَى أَيِّ شَيْءٍ تَرَكَ أُمَّتَهُ؟"}, {"s": "anos", "t": "عَلَى الْمَحَجَّةِ الْبَيْضَاءِ، لَيْلُهَا كَنَهَارِهَا، لَا يَزِيغُ عَنْهَا إِلَّا هَالِكٌ. رَوَاهُ أَحْمَدُ وَابْنُ مَاجَهْ. مَا تَرَكَ خَيْرًا إِلَّا دَلَّنَا عَلَيْهِ، وَلَا شَرًّا إِلَّا حَذَّرَنَا مِنْهُ."}, {"s": "fasih", "t": "وَهُوَ قُدْوَتُنَا! اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ مِنْ سُورَةِ الْأَحْزَابِ."}, {"s": "quran", "ref": "33:21", "t": "لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًۭا"}, {"s": "anos", "t": "أُسْوَةٌ حَسَنَةٌ! فَنَقْتَدِي بِهِ فِي صَلَاتِهِ، وَصِدْقِهِ، وَرَحْمَتِهِ، وَصَبْرِهِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ فِي الْعَسَلِ شِفَاءٌ لِلنَّاسِ كَمَا قَالَ الْقُرْآنُ، وَأَثْبَتَ الْعِلْمُ أَنَّهُ يَقْتُلُ الْجَرَاثِيمَ وَيَشْفِي الْجُرُوحَ!"}, {"s": "anos", "t": "الْآنَ «قِطَارُ السَّنَوَاتِ»: ضَعُوا بِطَاقَاتِ الْهِجْرَةِ، وَبَدْرٍ، وَأُحُدٍ، وَالْأَحْزَابِ، وَفَتْحِ مَكَّةَ، فِي عَرَبَاتِ الْقِطَارِ بِالتَّرْتِيبِ."}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَاصْنَعُوهُ مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: قطار السنوات"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! كَيْفَ يُظْهِرُ أَنُوس حُبَّهُ لِلنَّبِيِّ؟ أ: يَقُولُ أُحِبُّهُ وَلَا يُغَيِّرُ شَيْئًا. ب: يَتَّبِعُ سُنَّتَهُ: يُصَلِّي، وَيَصْدُقُ، وَيَرْحَمُ، وَيَبْتَسِمُ. ج: يَحْفَظُ صِفَاتِهِ فَقَطْ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: أريد أن أكون مثله ﷺ"}, {"s": "anos", "t": "«أ» وَ«ج» نَاقِصَانِ. وَالصَّحِيحُ «ب»؛ فَالْحُبُّ الْحَقِيقِيُّ اتِّبَاعٌ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: فِي أَيِّ عَامٍ كَانَتْ غَزْوَةُ بَدْرٍ؟ فَكِّرُوا..."}, {"s": "anos", "t": "فِي الْعَامِ الثَّانِي مِنَ الْهِجْرَةِ! وَأَيُّ أَوْلَادِهِ عَاشَ بَعْدَهُ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "فَاطِمَةُ رَضِيَ اللَّهُ عَنْهَا! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: أَنَا صَحَابِيَّةٌ مِنَ الْأَنْصَارِ، دَافَعْتُ عَنِ النَّبِيِّ يَوْمَ أُحُدٍ بِسَيْفِي، وَجُرِحْتُ وَأَنَا أَحْمِيهِ."}, {"s": "anos", "t": "نُسَيْبَةُ، أَمْ عَائِشَةُ، أَمْ فَاطِمَةُ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «بِطَاقَةُ عَائِلَةِ النَّبِيِّ»، وَاخْتَارُوا سُنَّةً تُطَبِّقُونَهَا كُلَّ يَوْمٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «قِطَارُ فَصِيح فِي الْمَدِينَةِ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 15, "title": "أفهم سوري (١): الفاتحة وقصار السور", "season": 2, "goals": ["tafsir"], "hook": "أهلًا يا أصدقاء! اليوم حلقة «مسابقة أنوس» القرآنية! فصيح يقول: «أنا أحفظ الفاتحة وأقرؤها في كل صلاة… لكن ماذا تعني: إيّاك نعبد وإيّاك نستعين؟». اليوم لن نحفظ فقط، بل <b>نفهم</b> سورنا!", "sections": [{"h": "الفاتحة: أمّ الكتاب في كل ركعة", "p": ["سُمّيت <b>الفاتحة</b> لأنّ كتاب الله يُفتتح بها. ونقرؤها في كل ركعة من صلاتنا.", "«بسم الله الرحمن الرحيم»: أبدأ قراءة القرآن <b>باسم الله</b>، مستعينًا به. و<b>الرحمن</b>: ذو الرحمة الواسعة التي وسعت كل شيء، و<b>الرحيم</b>: ذو الرحمة بالمؤمنين.", "«الحمد لله ربّ العالمين»: كل أنواع الحمد والكمال لله وحده. «مالك يوم الدين»: يوم الدين هو <b>يوم القيامة</b>.", "«إيّاك نعبد وإيّاك نستعين»: <b>نعبدك وحدك، ونستعين بك وحدك</b>. «اهدنا الصراط المستقيم»: دُلّنا على <b>الإسلام والسنّة</b>. «صراط الذين أنعمت عليهم»: طريق الأنبياء والصالحين، لا طريق المغضوب عليهم ولا الضالّين، وهم كما في الكتاب: اليهود والنصارى.", "وبعدها نقول: «<b>آمين</b>»، أي: يا ربّ استجب لنا."], "board": ["إيّاك نعبد = نعبدك وحدك", "إيّاك نستعين = نستعين بك وحدك", "آمين = استجب لنا"]}, {"h": "الزلزلة والقارعة: يوم عظيم والميزان", "p": ["في <b>سورة الزلزلة</b>: يوم القيامة تتحرّك الأرض حركة شديدة، وتُخرج ما في بطنها من الموتى، و<b>تُخبر بما عُمل عليها من خير وشرّ</b>؛ لأنّ الله أمرها بذلك.", "فصيح يرتجف: «يعني الأرض ستحكي ماذا فعلت في الحديقة؟». نعم! و«<b>فمن يعمل مثقال ذرّة خيرًا يره</b>»: ولو عملت خيرًا بوزن نملة صغيرة، ستراه أمامك. وكذلك الشرّ.", "وفي <b>سورة القارعة</b>: «القارعة» هي يوم القيامة، تقرع القلوب من شدّة هولها. يكون الناس فيه <b>كالفراش المنتشر</b>، والجبال <b>كالصوف المنفوش</b>.", "فمن <b>رجحت حسناته</b> فهو في عيشة راضية في الجنّة، ومن <b>رجحت سيّئاته</b> فمسكنه جهنّم، نار شديدة الحرارة."], "board": ["الأرض تُخبر بأعمالنا", "مثقال ذرّة: وزن نملة صغيرة", "ثقلت موازينه = الجنّة"]}, {"h": "العاديات والتكاثر والهمزة: احذر هذه الصفات", "p": ["في <b>العاديات</b>: أقسم الله بالخيل التي تجري بقوّة وتُطلق الشرر بحوافرها، ثم أخبر أنّ <b>الإنسان منوع للخير</b>، وأنّه <b>لحبّ المال يبخل</b>. لكنّ الله خبير بكل ما في القلوب.", "وفي <b>التكاثر</b>: <b>شغل الناسَ التفاخرُ بالأموال والأولاد عن طاعة الله</b> حتى ماتوا. و«ثم لتُسألنّ يومئذ عن النعيم»: سيسألنا الله عن نعمه: الصحّة، والطعام، وغيرها.", "وفي <b>الهمزة</b>: عذاب شديد <b>للذي يكثر الغيبة والطعن في الناس</b>، والذي همّه جمع المال وعدّه، ويظنّ أنّ ماله يجعله خالدًا.", "أنوس يقول: «إذن لا أتفاخر بلعبتي الجديدة، ولا أسخر من أحد، وأشكر الله على نعمه»."], "board": ["لا للبخل", "لا للتفاخر", "لا للغيبة والسخرية", "سنُسأل عن النعيم"]}, {"h": "العصر: كيف ننجو من الخسارة؟", "p": ["أقسم الله <b>بالعصر</b>، وهو <b>الزمان</b>. ثم قال: <b>كل الإنسان في خسارة</b>… إلا من جمع <b>أربع صفات</b>:", "1) <b>آمنوا</b>. 2) <b>وعملوا الصالحات</b>. 3) <b>وتواصوا بالحقّ</b>: دعوا غيرهم إلى الخير. 4) <b>وتواصوا بالصبر</b>: صبروا عليه.", "فصيح يعدّ على أصابعه: «إيمان، عمل صالح، دعوة، صبر… أربعة أصابع للنجاة!»."], "board": ["إيمان", "عمل صالح", "تواصٍ بالحقّ", "تواصٍ بالصبر"]}, {"h": "الفيل وقريش: الله يحمي بيته", "p": ["في <b>سورة الفيل</b>: جاء <b>أبرهة</b> وجيشه بالفيل ليهدموا الكعبة، فجعل الله كيدهم في ضياع، و<b>أرسل عليهم طيرًا جماعات جماعات</b> ترميهم بحجارة من طين متحجّر، فصاروا كورق زرع أكلته الدوابّ. وفي ذلك العام وُلد نبيّنا ﷺ.", "وفي <b>سورة قريش</b>: كانت قريش تسافر للتجارة آمنة: <b>رحلة الشتاء إلى اليمن، ورحلة الصيف إلى الشام</b>. فأمرهم الله أن <b>يعبدوه وحده</b>، لأنّه <b>أطعمهم من جوع وآمنهم من خوف</b>."], "board": ["الطير الأبابيل", "رحلة الشتاء: اليمن", "رحلة الصيف: الشام"]}], "summary": ["الفاتحة يُفتتح بها القرآن، ومعنى «إيّاك نعبد وإيّاك نستعين»: نعبدك وحدك ونستعين بك وحدك، و«آمين»: استجب لنا.", "الزلزلة والقارعة عن يوم القيامة: الأرض تُخبر بأعمالنا، وكل خير ولو مثقال ذرّة يراه صاحبه، ومن ثقلت موازينه ففي عيشة راضية.", "العاديات والتكاثر والهمزة تحذّر من البخل والتفاخر والغيبة، والعصر تذكر طريق النجاة، والفيل وقريش تذكّران بحماية الله لبيته ونعمه على قريش."], "islam": {"intro": "قال الله تعالى في سورة الزلزلة:", "text": "فلا تحتقر أيّ خير مهما كان صغيرًا: ابتسامة، أو كلمة طيّبة، أو مساعدة أمّك. كله سيُوزن يوم القيامة.", "ayah": {"text": "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ", "src": "سُورَةُ الزَّلۡزَلَةِ: ٧"}, "hadith": {"text": "خيركم من تعلّم القرآن وعلّمه", "source": "رواه البخاري عن عثمان بن عفّان رضي الله عنه"}}, "home": {"title": "مصحف أنوس الصغير المفهوم", "goal": "أن يفهم الطفل معاني السور ويطبّق درسًا من كل سورة مع أسرته.", "materials": ["دفتر", "ألوان", "مصحف"], "steps": ["اختر كل يوم سورة من سور الحلقة، واقرأها مع أحد والديك.", "ارسم في الدفتر صورة تعبّر عنها: ميزانًا للقارعة، أو فيلًا وطيورًا للفيل، أو ساعة للعصر.", "اكتب تحت الرسمة درسًا واحدًا تعلّمته، مثل: «لا أتفاخر بما عندي» للتكاثر.", "في آخر الأسبوع، اعرض دفترك على أسرتك، وعلّم أخاك الصغير معنى «آمين»."], "parent": "اقرؤوا السور بتأنٍّ، واسألوا الطفل: «ماذا تعني هذه الآية لك اليوم؟» لربط القرآن بحياته."}, "online": {"title": "مسابقة فصيح القرآنية", "intro": "صِل كل سورة بموضوعها، ثم رتّب آيات الفاتحة!", "steps": [{"type": "match", "title": "صِل السورة بموضوعها", "prompt": "اختر السورة، ثم موضوعها.", "pairs": [["الزلزلة", "الأرض تُخبر بما عُمل عليها"], ["القارعة", "الناس كالفراش، والجبال كالصوف"], ["التكاثر", "التفاخر بالأموال والأولاد"], ["الهمزة", "عذاب لمن يكثر الغيبة والطعن"], ["الفيل", "طير أبابيل تحمي الكعبة من أبرهة"], ["قريش", "رحلة الشتاء والصيف"]]}, {"type": "order", "title": "رتّب آيات الفاتحة", "prompt": "رتّب الآيات كما في المصحف.", "items": ["بسم الله الرحمن الرحيم", "الحمد لله ربّ العالمين", "الرحمن الرحيم", "مالك يوم الدين", "إيّاك نعبد وإيّاك نستعين", "اهدنا الصراط المستقيم", "صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالّين"]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "كم صفة تنجّي من الخسارة في سورة العصر؟", "o": ["صفتان", "أربع صفات", "صفة واحدة"], "a": 1, "why": "الإيمان، والعمل الصالح، والتواصي بالحقّ، والتواصي بالصبر."}, {"q": "ما معنى «آمين»؟", "o": ["استجب لنا", "انتهت السورة", "اسكتوا"], "a": 0, "why": "آمين: يا ربّ استجب لنا."}, {"q": "ما معنى «يوم الدين»؟", "o": ["يوم الجمعة", "يوم العيد", "يوم القيامة"], "a": 2, "why": "مالك يوم الدين: يوم القيامة."}]}]}, "case": {"title": "مَن أنا؟", "story": "في نهاية المسابقة، وجد فصيح ورقة لغز داخل كتاب تفسير كبير. اقرأ الأدلّة، وخمّن: مَن أنا؟", "evidence": ["لي تفسير مشهور للقرآن يقرؤه المسلمون في كل مكان.", "كتبت كتابًا في التاريخ اسمه «البداية والنهاية».", "كنت تلميذًا لابن تيمية رحمه الله."], "options": ["عبد الله بن عباس رضي الله عنهما", "ابن تيمية رحمه الله", "الحافظ ابن كثير رحمه الله"], "deep": "لماذا نحتاج إلى العلماء ليشرحوا لنا معاني القرآن؟ وكيف يساعدك فهم السورة على الخشوع في الصلاة؟", "reveal": "أنا الحافظ ابن كثير رحمه الله، واسم تفسيري «تفسير القرآن العظيم». وفي الحلقة القادمة نكمل رحلة الفهم: من سورة الماعون إلى سورة الناس."}, "quiz": [{"q": "ما معنى «إيّاك نعبد وإيّاك نستعين»؟", "o": ["نعبد الأصنام", "نعبدك وحدك ونستعين بك وحدك", "نستعين بالناس فقط"], "a": 1, "why": "نعبد الله وحده، ونستعين به وحده."}], "qa": [{"id": 123, "q": "اقرأِ الفاتحةَ وفسِّرها.", "a": "﴿بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَٰنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ﴾ [الفاتحة: ١–٧].\n\nالتفسير — سُمِّيت الفاتحةَ؛ لافتتاحِ كتابِ الله بها:\n١. بسم الله الرحمن الرحيم: باسمِ الله أبدأ قراءةَ القرآن، مستعينًا به تعالى، متبرِّكًا بذكرِ اسمه. (الله): المعبودُ بحق، ولا يُسمّى به غيرُهُ سبحانه. (الرحمن): ذو الرحمةِ الواسعةِ التي وسِعَتْ كلَّ شيء. (الرحيم): ذو الرحمةِ بالمؤمنين.\n٢. الحمد لله رب العالمين: جميعُ أنواعِ المحامدِ والكمالِ لله وحده.\n٣. الرحمن الرحيم: ذو الرحمةِ الواسعة، وذو الرحمةِ الواصلةِ للمؤمنين.\n٤. مالك يوم الدين: هو يومُ القيامة.\n٥. إياك نعبد وإياك نستعين: نعبدُكَ وحدَكَ ونستعينُ بك وحدَك.\n٦. اهدنا الصراط المستقيم: وهو الهدايةُ إلى الإسلامِ والسُّنة.\n٧. صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين: طريقُ عبادِ اللهِ الصالحينَ من الأنبياءِ ومن تبعهم، غيرَ طريقِ النصارى واليهود.\n• ويُسنُّ أن يقولَ بعد قراءتها: \"آمين\" أي: استجِبْ لنا."}, {"id": 124, "q": "اقرأْ سورةَ الزلزلةِ وفسِّرها.", "a": "﴿إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا ۝ وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا ۝ وَقَالَ الْإِنسَانُ مَا لَهَا ۝ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ۝ بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ۝ يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ ۝ فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ﴾ [الزلزلة: ١–٨].\n\nالتفسير:\n١. إذا زُلزلتِ الأرضُ زلزالها: إذا حُرِّكتِ الأرضُ التحريكَ الشديدَ الذي يحدثُ لها يومَ القيامة.\n٢. وأخرجتِ الأرضُ أثقالها: وأخرجتِ الأرضُ ما في بطنِها من الموتى وغيرِهم.\n٣. وقال الإنسانُ ما لها: وقال الإنسانُ متحيرًا: ما شأنُ الأرضِ تتحركُ وتضطرب؟!\n٤. يومئذٍ تُحدِّثُ أخبارها: في ذلك اليومِ العظيمِ تُخبِرُ الأرضُ بما عُمِلَ عليها من خيرٍ وشر.\n٥. بأنَّ ربَّكَ أوحى لها: لأنَّ اللهَ أعلمَها وأمرَها بذلك.\n٦. يومئذٍ يصدرُ الناسُ أشتاتًا ليُروا أعمالهم: في ذلك اليومِ العظيمِ يخرجُ الناسُ من موقفِ الحسابِ فِرقًا؛ ليشاهدوا أعمالَهم التي عملوها في الدنيا.\n٧. فمن يعملْ مثقالَ ذرةٍ خيرًا يره: فمن يعملْ وزنَ نملةٍ صغيرةٍ من أعمالِ الخيرِ والبرِّ؛ يرَهُ أمامه.\n٨. ومن يعملْ مثقالَ ذرةٍ شرًّا يره: ومن يعملْ وزنَها من الأعمالِ الشريرة؛ يرَهُ أمامه."}, {"id": 125, "q": "اقرأْ سورةَ العادياتِ وفسِّرها.", "a": "﴿وَالْعَادِيَاتِ ضَبْحًا ۝ فَالْمُورِيَاتِ قَدْحًا ۝ فَالْمُغِيرَاتِ صُبْحًا ۝ فَأَثَرْنَ بِهِ نَقْعًا ۝ فَوَسَطْنَ بِهِ جَمْعًا ۝ إِنَّ الْإِنسَانَ لِرَبِّهِ لَكَنُودٌ ۝ وَإِنَّهُ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ ۝ وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ ۝ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ ۝ وَحُصِّلَ مَا فِي الصُّدُورِ ۝ إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ﴾ [العاديات: ١–١١].\n\nالتفسير:\n١. أقسمَ اللهُ بالخيلِ التي تجري حتى يُسمعَ لنفَسِها صوتٌ من شدةِ الجري.\n٢. وأقسمَ بالخيلِ التي توقِدُ النارَ بحوافرِها إذا لامستْ بها الصخورَ لشدةِ وقعِها عليها.\n٣. وأقسمَ بالخيلِ التي تُغيرُ على الأعداءِ وقتَ الصباح.\n٤. فحرَّكنَ بجريهنَّ غبارًا.\n٥. فتوسَّطنَ بفوارسِهنَّ جمعًا من الأعداء.\n٦. إنَّ الإنسانَ لمنوعٌ للخيرِ الذي يريدُهُ منه ربُّه.\n٧. وإنه على منعِهِ للخيرِ لشاهد، لا يستطيعُ إنكارَ ذلك لوضوحِه.\n٨. وإنه لفرطِ حبِّهِ للمالِ يبخلُ به.\n٩. أفلا يعلمُ هذا الإنسانُ المغترُّ بالحياةِ الدنيا إذا بعثَ اللهُ ما في القبورِ من الأمواتِ وأخرجَهم للحساب أنَّ الأمرَ لم يكنْ كما كان يتوهم؟!\n١٠. وأُبرِزَ وبُيِّنَ ما في القلوبِ من النياتِ والاعتقاداتِ وغيرها.\n١١. إنَّ ربَّهم بهم في ذلك اليومِ لخبير، لا يخفى عليه من أمرِ عبادِهِ شيء، وسيجازيهم على ذلك."}, {"id": 126, "q": "اقرأْ سورةَ القارعةِ وفسِّرها.", "a": "﴿الْقَارِعَةُ ۝ مَا الْقَارِعَةُ ۝ وَمَا أَدْرَاكَ مَا الْقَارِعَةُ ۝ يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ ۝ وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنفُوشِ ۝ فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ ۝ فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ ۝ وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ ۝ فَأُمُّهُ هَاوِيَةٌ ۝ وَمَا أَدْرَاكَ مَا هِيَهْ ۝ نَارٌ حَامِيَةٌ﴾ [القارعة: ١–١١].\n\nالتفسير:\n١. القارعة: الساعةُ التي تقرعُ قلوبَ الناسِ لعظمِ هولِها.\n٢. ما هذه الساعةُ التي تقرعُ قلوبَ الناسِ لعظمِ هولِها؟!\n٣. وما أعلمَكَ ما هذه الساعة؟! إنها يومُ القيامة.\n٤. يومَ تقرعُ قلوبَ الناس، يكونونَ كالفراشِ المنتشرِ المتناثرِ هنا وهناك.\n٥. وتكونُ الجبالُ مثلَ الصوفِ المندوفِ في خفةِ سيرِها وحركتِها.\n٦. فأما من رجحتْ أعمالُهُ الصالحةُ على أعمالِهِ السيئة.\n٧. فهو في عيشةٍ مرضيةٍ ينالُها في الجنة.\n٨. وأما من رجحتْ أعمالُهُ السيئةُ على أعمالِهِ الصالحة.\n٩. فمسكنُهُ ومستقرُّهُ يومَ القيامةِ هو جهنم.\n١٠. وما أعلمَكَ ما هي؟!\n١١. هي نارٌ شديدةُ الحرارة."}, {"id": 127, "q": "اقرأْ سورةَ التكاثرِ وفسِّرها.", "a": "﴿أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّىٰ زُرْتُمُ الْمَقَابِرَ ۝ كَلَّا سَوْفَ تَعْلَمُونَ ۝ ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ ۝ كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ ۝ لَتَرَوُنَّ الْجَحِيمَ ۝ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ ۝ ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ [التكاثر: ١–٨].\n\nالتفسير:\n١. شغلكم — أيها الناس — التفاخرُ بالأموالِ والأولادِ عن طاعةِ الله.\n٢. حتى متُّم ودخلتُم قبورَكم.\n٣. ما كان لكم أن يشغلَكمُ التفاخرُ عن طاعةِ الله، سوف تعلمونَ عاقبةَ ذلك الانشغال.\n٤. ثم سوف تعلمونَ عاقبتَه.\n٥. حقًّا لو أنكم تعلمونَ يقينًا أنكم مبعوثونَ إلى الله، وأنه سيجازيكم على أعمالِكم، لما انشغلتُم بالتفاخرِ بالأموالِ والأولاد.\n٦. والله لتشاهدنَّ النارَ يومَ القيامة.\n٧. ثم لتشاهدنَّها مشاهدةَ يقينٍ لا شكَّ فيه.\n٨. ثم ليسألنَّكمُ اللهُ في ذلك اليومِ عما أنعمَ به عليكم من الصحةِ والغنى وغيرها."}, {"id": 128, "q": "اقرأْ سورةَ العصرِ وفسِّرها.", "a": "﴿وَالْعَصْرِ ۝ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ﴾ [العصر: ١–٣].\n\nالتفسير:\n١. والعصر: أقسمَ سبحانه بالزمان.\n٢. إن الإنسان لفي خُسر: أي كلُّ الإنسانِ في نقصانٍ وهلاك.\n٣. إلا الذين آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر: إلا من آمنَ وعملَ صالحًا، ومع ذلك دعَوا إلى الحقِّ وصبروا عليه، فهؤلاء هم الناجونَ من الخسارة."}, {"id": 129, "q": "اقرأْ سورةَ الهمزةِ وفسِّرها.", "a": "﴿وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ ۝ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ ۝ يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ ۝ كَلَّا لَيُنبَذَنَّ فِي الْحُطَمَةِ ۝ وَمَا أَدْرَاكَ مَا الْحُطَمَةُ ۝ نَارُ اللَّهِ الْمُوقَدَةُ ۝ الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ ۝ إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ ۝ فِي عَمَدٍ مُّمَدَّدَةٍ﴾ [الهمزة: ١–٩].\n\nالتفسير:\n١. وبالٌ وشدةُ عذابٍ لكثيرِ الاغتيابِ للناس، والطعنِ فيهم.\n٢. الذي همُّهُ جمعُ المالِ وإحصاؤه، لا همَّ له غيرُ ذلك.\n٣. يظنُّ أنَّ مالَهُ الذي جمعَهُ سينجيهِ من الموت، فيبقى خالدًا في الحياةِ الدنيا.\n٤. ليس الأمرُ كما تصوَّرَ هذا الجاهل، ليُطرحنَّ في نارِ جهنمَ التي تدقُّ وتكسِرُ كلَّ ما طُرِحَ فيها لشدةِ بأسِها.\n٥. وما أعلمَكَ ما هذه النارُ التي تحطِّمُ كلَّ ما طُرِحَ فيها؟!\n٦. إنها نارُ الله المستعرة.\n٧. التي تنفذُ من أجسامِ الناسِ إلى قلوبِهم.\n٨. إنها على المعذَّبينَ فيها مغلقة.\n٩. بعمَدٍ ممتدةٍ طويلةٍ حتى لا يخرجوا منها."}, {"id": 130, "q": "اقرأْ سورةَ الفيلِ وفسِّرها.", "a": "﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ۝ أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ۝ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ۝ تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ ۝ فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ﴾ [الفيل: ١–٥].\n\nالتفسير:\n١. ألم تعلمْ — أيها الرسول — كيف فعلَ ربُّكَ بأبرهةَ وأصحابِهِ أصحابِ الفيلِ حين أرادوا هدمَ الكعبة؟\n٢. لقد جعلَ اللهُ تدبيرَهمُ السيءَ لهدمِها في ضياع، فما نالوا ما تمنَّوهُ من صرفِ الناسِ عن الكعبة، وما نالوا منها شيئًا.\n٣. وبعثَ عليهم طيرًا أتتهم جماعاتٍ جماعات.\n٤. ترميهم بحجارةٍ من طينٍ متحجِّر.\n٥. فجعلهمُ اللهُ كورقِ زرعٍ أكلتْهُ الدوابُّ وداسته."}, {"id": 131, "q": "اقرأْ سورةَ قريشٍ وفسِّرها.", "a": "﴿لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ﴾ [قريش: ١–٤].\n\nالتفسير:\n١. لإيلاف قريش: المرادُ بذلك ما كانوا يألفونَهُ من الرحلةِ في الشتاءِ والصيف.\n٢. إيلافهم رحلة الشتاء والصيف: رحلةُ الشتاءِ إلى اليمن، ورحلةُ الصيفِ إلى الشامِ آمنين.\n٣. فليعبدوا رب هذا البيت: فليعبدوا اللهَ ربَّ هذا البيتِ الحرامِ وحده، الذي يسَّرَ لهم هذه الرحلة، ولا يشركوا به أحدًا.\n٤. الذي أطعمهم من جوع وآمنهم من خوف: الذي أطعمهم من جوع، وآمنهم من خوف، بما وضعَ في قلوبِ العربِ من تعظيمِ الحرمِ وتعظيمِ سكانه."}], "dyk": ["أقسمَ اللهُ بالفجرِ والضحى والليل، وكلُّها آياتٌ دقيقةٌ في نظامِ الأرضِ ودورانِها حولَ نفسِها.", "الشمسُ أكبرُ من الأرضِ بأكثرَ من مليونِ مرة، ومع ذلك هي نجمٌ متوسِّطٌ بين نجومِ الكون!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ! بِسْمِ اللَّهِ، أَهْلًا بِكُمْ فِي «تَعَلَّمْ مَعَ أَنُوس»!"}, {"s": "fasih", "t": "وَعَلَيْكُمُ السَّلَامُ! حَلُّ اللُّغْزِ: إِنَّهَا نُسَيْبَةُ بِنْتُ كَعْبٍ، أُمُّ عُمَارَةَ رَضِيَ اللَّهُ عَنْهَا!"}, {"s": "anos", "t": "وَالْيَوْمَ مُسَابَقَةٌ قُرْآنِيَّةٌ: نَفْهَمُ سُوَرَنَا!"}, {"s": "fasih", "t": "فَسِّرِ الْفَاتِحَةَ!"}, {"s": "anos", "t": "بِسْمِ اللَّهِ: أَبْدَأُ مُسْتَعِينًا بِهِ. الرَّحْمَنُ: ذُو الرَّحْمَةِ الْوَاسِعَةِ، وَالرَّحِيمُ: ذُو الرَّحْمَةِ بِالْمُؤْمِنِينَ. الْحَمْدُ لِلَّهِ: كُلُّ الْحَمْدِ وَالْكَمَالِ لَهُ. وَيَوْمُ الدِّينِ: يَوْمُ الْقِيَامَةِ."}, {"s": "anos", "t": "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ: نَعْبُدُكَ وَحْدَكَ، وَنَسْتَعِينُ بِكَ وَحْدَكَ. وَالصِّرَاطُ الْمُسْتَقِيمُ: الْإِسْلَامُ وَالسُّنَّةُ، طَرِيقُ الْأَنْبِيَاءِ وَالصَّالِحِينَ، غَيْرَ طَرِيقِ الْيَهُودِ وَالنَّصَارَى. ثُمَّ نَقُولُ: آمِينَ، أَيِ: اسْتَجِبْ لَنَا."}, {"s": "fasih", "t": "وَسُورَةُ الزَّلْزَلَةِ؟"}, {"s": "anos", "t": "يَوْمَ الْقِيَامَةِ تَتَحَرَّكُ الْأَرْضُ بِشِدَّةٍ، وَتُخْرِجُ مَا فِي بَطْنِهَا، وَتُخْبِرُ بِمَا عُمِلَ عَلَيْهَا لِأَنَّ اللَّهَ أَمَرَهَا. اسْمَعُوا الشَّيْخَ الْحُصَرِيَّ."}, {"s": "quran", "ref": "99:7", "t": "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ"}, {"s": "fasih", "t": "مِثْقَالُ ذَرَّةٍ: وَزْنُ نَمْلَةٍ صَغِيرَةٍ! فَلَا أَحْتَقِرُ خَيْرًا. وَسُورَةُ الْعَادِيَاتِ؟"}, {"s": "anos", "t": "أَقْسَمَ اللَّهُ بِالْخَيْلِ الْمُسْرِعَةِ الَّتِي تُوقِدُ النَّارَ بِحَوَافِرِهَا، ثُمَّ أَخْبَرَ أَنَّ الْإِنْسَانَ مَنُوعٌ لِلْخَيْرِ، بَخِيلٌ لِحُبِّ الْمَالِ، وَاللَّهُ خَبِيرٌ بِعِبَادِهِ."}, {"s": "fasih", "t": "وَسُورَةُ الْقَارِعَةِ؟"}, {"s": "anos", "t": "الْقَارِعَةُ يَوْمُ الْقِيَامَةِ: النَّاسُ كَالْفَرَاشِ الْمُنْتَشِرِ، وَالْجِبَالُ كَالصُّوفِ. فَمَنْ رَجَحَتْ حَسَنَاتُهُ فَفِي الْجَنَّةِ، وَمَنْ رَجَحَتْ سَيِّئَاتُهُ فَمَسْكَنُهُ جَهَنَّمُ."}, {"s": "fasih", "t": "وَسُورَةُ التَّكَاثُرِ؟"}, {"s": "anos", "t": "شَغَلَ النَّاسَ التَّفَاخُرُ بِالْأَمْوَالِ وَالْأَوْلَادِ عَنْ طَاعَةِ اللَّهِ حَتَّى مَاتُوا، ثُمَّ يَسْأَلُهُمُ اللَّهُ عَنِ النَّعِيمِ: الصِّحَّةِ وَالْغِنَى."}, {"s": "fasih", "t": "وَسُورَةُ الْعَصْرِ؟"}, {"s": "anos", "t": "أَقْسَمَ اللَّهُ بِالزَّمَانِ: كُلُّ الْإِنْسَانِ فِي خُسْرٍ، إِلَّا مَنْ آمَنَ، وَعَمِلَ صَالِحًا، وَدَعَا إِلَى الْحَقِّ، وَصَبَرَ عَلَيْهِ."}, {"s": "fasih", "t": "وَسُورَةُ الْهُمَزَةِ؟"}, {"s": "anos", "t": "عَذَابٌ شَدِيدٌ لِكَثِيرِ الْغِيبَةِ وَالطَّعْنِ فِي النَّاسِ، الَّذِي هَمُّهُ جَمْعُ الْمَالِ، يَظُنُّ أَنَّهُ يُخَلِّدُهُ. وَسَيُطْرَحُ فِي نَارٍ تُحَطِّمُ كُلَّ شَيْءٍ."}, {"s": "fasih", "t": "وَسُورَةُ الْفِيلِ؟"}, {"s": "anos", "t": "أَرَادَ أَبْرَهَةُ وَأَصْحَابُ الْفِيلِ هَدْمَ الْكَعْبَةِ، فَأَرْسَلَ عَلَيْهِمْ طَيْرًا جَمَاعَاتٍ تَرْمِيهِمْ بِحِجَارَةٍ مِنْ طِينٍ مُتَحَجِّرٍ، فَصَارُوا كَوَرَقِ زَرْعٍ أَكَلَتْهُ الدَّوَابُّ."}, {"s": "fasih", "t": "وَسُورَةُ قُرَيْشٍ؟"}, {"s": "anos", "t": "كَانَتْ قُرَيْشٌ تُسَافِرُ آمِنَةً: فِي الشِّتَاءِ إِلَى الْيَمَنِ، وَفِي الصَّيْفِ إِلَى الشَّامِ، فَأَمَرَهُمُ اللَّهُ أَنْ يَعْبُدُوهُ وَحْدَهُ، الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ."}, {"s": "fasih", "t": "وَقَالَ النَّبِيُّ: «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ»، رَوَاهُ الْبُخَارِيُّ. هَلْ تَعْلَمُ؟ أَقْسَمَ اللَّهُ بِالْفَجْرِ وَالضُّحَى وَاللَّيْلِ، وَهِيَ آيَاتٌ دَقِيقَةٌ فِي دَوَرَانِ الْأَرْضِ!"}, {"s": "anos", "t": "الْآنَ «مُسَابَقَةُ أَنُوس الْقُرْآنِيَّةُ»: فَرِيقُ الْفَاتِحَةِ ضِدَّ فَرِيقِ الْعَصْرِ!"}, {"s": "fasih", "t": "أَوْقِفُوا الْحَلْقَةَ وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس القرآنية: من قائل الآية؟"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! سَامِرٌ يَتَفَاخَرُ بِلُعْبَتِهِ وَيَسْخَرُ مِنْ لُعْبَةِ زَمِيلِهِ. أ: يَتَفَاخَرُ بِأَغْلَى مِنْهَا. ب: يَضْحَكُ مَعَهُ. ج: يُذَكِّرُهُ بِلُطْفٍ بِالتَّكَاثُرِ وَالْهُمَزَةِ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ وَصَوِّتُوا، ثُمَّ ارْجِعُوا."}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: لعبة جديدة في الصفّ"}, {"s": "anos", "t": "«أ» تَفَاخُرٌ، وَ«ب» سُخْرِيَةٌ. وَالصَّحِيحُ «ج»: نَتَوَاصَى بِالْحَقِّ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: بِمَاذَا أَقْسَمَ اللَّهُ فِي سُورَةِ الْعَصْرِ؟ فَكِّرُوا..."}, {"s": "anos", "t": "بِالزَّمَانِ! وَإِلَى أَيْنَ كَانَتْ رِحْلَةُ الشِّتَاءِ؟ فَكِّرُوا..."}, {"s": "fasih", "t": "إِلَى الْيَمَنِ! وَهَذَا لُغْزُ «مَنْ أَنَا؟»: لِي تَفْسِيرٌ مَشْهُورٌ لِلْقُرْآنِ، وَكَتَبْتُ «الْبِدَايَةَ وَالنِّهَايَةَ»، وَكُنْتُ تِلْمِيذًا لِابْنِ تَيْمِيَّةَ رَحِمَهُ اللَّهُ."}, {"s": "anos", "t": "ابْنُ عَبَّاسٍ، أَمِ ابْنُ تَيْمِيَّةَ، أَمِ ابْنُ كَثِيرٍ؟ مَا رَأْيُكُمْ؟ وَفِي الْبَيْتِ: «مُصْحَفُ أَنُوس الْمَفْهُومُ»: صُورَةٌ وَدَرْسٌ لِكُلِّ سُورَةٍ."}, {"s": "fasih", "t": "وَعَلَى مَوْقِعِ التَّرْبِيَةِ فِي كَوْكَبِ الْإِبْدَاعِ: «مُسَابَقَةُ فَصِيح الْقُرْآنِيَّةُ». نَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ، وَالسَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 16, "title": "أفهم سوري (٢): من الماعون إلى الناس", "season": 2, "goals": ["tafsir"], "hook": "أهلًا يا أصدقاء! فصيح اليوم يطير فرحًا ويقول: «ثماني سور… ثماني سور… قصيرة في الحفظ، كبيرة في المعنى!». هل تعرف ما آخر سورة في القرآن؟ تعال نكتشف معًا!", "sections": [{"h": "الماعون والكوثر: قلب رحيم وصلاة خاشعة", "p": ["فصيح يسأل: «مَن الذي تتكلّم عنه سورة الماعون؟». تتكلّم عن إنسان <b>يكذّب بيوم القيامة</b>، فلا يخاف الحساب، ولذلك <b>يدفع اليتيم بقسوة</b>، ولا يشجّع أحدًا على إطعام الفقير.", "وتحذّر السورة من الذي <b>يسهو عن صلاته</b> فلا يبالي بها حتى يخرج وقتها، ومن الذي <b>يرائي</b> أي يعمل ليراه الناس لا لله، ومن الذي يمنع أن يساعد جاره بشيء صغير لا يضرّه، مثل إعارة قلم أو كوب.", "أما سورة <b>الكوثر</b> فهدية من الله لنبيّنا ﷺ: أعطاه <b>الخير الكثير</b>، ومنه نهر الكوثر في الجنّة. وشُكر هذه النعمة: أن يصلّي لله وحده ويذبح لله وحده. ومَن يُبغض النبيّ ﷺ هو المقطوع عن كل خير."], "board": ["أرحم اليتيم", "أحافظ على صلاتي", "الكوثر: الخير الكثير"]}, {"h": "الكافرون والنصر: ديني واضح وأشكر ربّي", "p": ["في سورة <b>الكافرون</b> علّم الله نبيّه ﷺ أن يقول بوضوح: لا أعبد الأصنام التي تعبدونها، لا اليوم ولا غدًا، وأنا أعبد الله وحده. <b>لكم دينكم ولي دين</b>. فالمسلم يعرف دينه ولا يخلطه بغيره.", "وفي سورة <b>النصر</b> بشارة: جاء نصر الله وفُتحت مكّة، ودخل الناس في الإسلام <b>جماعات بعد جماعات</b>. فماذا يفعل النبيّ ﷺ عند هذا الفرح الكبير؟ يسبّح بحمد ربّه ويستغفره، وكانت علامة على قرب انتهاء مهمّته ولقائه بربّه.", "قال أنوس: «إذا نجحتُ في الاختبار، أقول: الحمد لله، وأستغفر الله». هكذا نتعلّم من سورة النصر!"], "board": ["لكم دينكم ولي دين", "عند الفرح: أسبّح وأستغفر"]}, {"h": "المسد: المال لا يُنجي من العذاب", "p": ["<b>أبو لهب</b> عمّ النبيّ ﷺ، وكان يؤذيه كثيرًا، فخسر عمله وخاب سعيه. ولم ينفعه <b>ماله ولا أولاده</b> شيئًا.", "وكانت زوجته <b>أمّ جميل</b> تضع الشوك في طريق النبيّ ﷺ لتؤذيه، فأخبر الله أنها ستدخل النار معه، وفي عنقها حبل.", "الدرس: القرابة والمال لا ينفعان إذا آذى الإنسانُ النبيّ ﷺ وكفر. الذي ينفع هو <b>الإيمان والعمل الصالح</b>."], "board": ["المال لا يُنجي", "الإيمان والعمل الصالح ينفعان"]}, {"h": "الإخلاص: أعرف ربّي", "p": ["سورة صغيرة جدًّا، لكنها تعرّفنا بالله: <b>قل هو الله أحد</b>: لا إله غيره. <b>الله الصمد</b>: كل المخلوقات ترفع إليه حاجاتها، فأنا أطلب منه وحده.", "<b>لم يلد ولم يولد</b>: ليس له ولد ولا والد سبحانه. <b>ولم يكن له كفوًا أحد</b>: لا يشبهه أحد من خلقه.", "فصيح يقول: «سورة قصيرة… وفضلها كبير!». وسنتعلّم في الحلقة القادمة حديثًا عن فضلها العظيم."], "board": ["أحد", "الصمد", "لا مثيل له"]}, {"h": "المعوّذتان: أحتمي بالله", "p": ["في سورة <b>الفلق</b> نقول: أحتمي بربّ الصبح من شرّ كل ما يؤذي من المخلوقات، ومن شرور الليل، ومن شرّ السواحر، ومن شرّ <b>الحاسد</b> الذي يتمنّى أن تزول النعمة عن غيره.", "وفي سورة <b>الناس</b> نحتمي بالله: <b>ربّ الناس، ملك الناس، إله الناس</b>، من شرّ الشيطان الذي يوسوس في القلوب، والموسوس قد يكون من الجنّ أو من الإنس.", "فإذا خفتُ في الليل أو جاءتني فكرة سيّئة، أقرأ المعوّذتين، وأتذكّر أنّ الله أقوى من كل شرّ."], "board": ["الفلق: ربّ الصبح", "الناس: ربّ، ملك، إله", "أحتمي بالله"]}], "summary": ["سورة الماعون تعلّمنا رحمة اليتيم، وإطعام المسكين، والمحافظة على الصلاة، والإخلاص.", "سورة الإخلاص تعرّفنا بالله: أحد، صمد، لم يلد ولم يولد، ولا مثيل له.", "بالمعوّذتين نحتمي بالله من كل شرّ ومن وسوسة الشيطان."], "islam": {"intro": "قال الله تعالى لنبيّه ﷺ في سورة الكوثر:", "text": "فكما أعطى الله نبيّه الخير الكثير، أعطانا نِعَمًا كثيرة، وشكرها أن نصلّي لله وحده ونحسن إلى الناس.", "ayah": {"text": "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ", "src": "سُورَةُ الكَوۡثَرِ: ١"}, "hadith": null}, "home": {"title": "مصحفي الصغير الملوّن", "goal": "أن يراجع الطفل السور الثماني مع أسرته ويشرح معنى كل سورة بجملة.", "materials": ["ثماني ورقات", "ألوان", "دبّاسة"], "steps": ["اكتب اسم كل سورة على ورقة، وارسم تحته رسمًا يذكّرك بمعناها: يتيم وطعام للماعون، نهر للكوثر، شمس تشرق للفلق.", "اجمع الورقات في كتيّب واحد، وسمّه «مصحفي الصغير».", "اقرأ سورة كل ليلة أمام أسرتك، وقل معناها بجملة واحدة.", "اقرأ المعوّذتين والإخلاص قبل النوم مع أبيك أو أمّك."], "parent": "استمعوا لقراءة طفلكم بصبر، وصحّحوا برفق، وذكّروه بأنّ الله يحبّ من يرحم اليتيم ويساعد غيره."}, "online": {"title": "رحلة فصيح في السور", "intro": "ساعد فصيحًا على ربط كل سورة بمعناها، وترتيب السور!", "steps": [{"type": "match", "title": "صِل السورة بمعناها", "prompt": "اختر السورة، ثم المعنى المناسب.", "pairs": [["الماعون", "رحمة اليتيم وعدم الرياء"], ["الكوثر", "الخير الكثير للنبيّ ﷺ"], ["الكافرون", "لكم دينكم ولي دين"], ["المسد", "المال لم يُنجِ أبا لهب"], ["الإخلاص", "الله أحد صمد لا مثيل له"], ["الناس", "نحتمي بالله من الوسواس"]]}, {"type": "order", "title": "رتّب السور كما في المصحف", "prompt": "رتّب السور من الأولى إلى الأخيرة.", "items": ["الماعون", "الكوثر", "الكافرون", "النصر", "المسد", "الإخلاص", "الفلق", "الناس"]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ما معنى «الله الصمد»؟", "o": ["الذي ينام", "الذي تُرفع إليه حاجات الخلق", "الذي له ولد"], "a": 1}, {"q": "في سورة الفلق نستعيذ بربّ…", "o": ["الصبح", "البحر", "المال"], "a": 0}, {"q": "الذي يرائي في عمله يريد…", "o": ["رضا الله", "أن ينام", "أن يراه الناس"], "a": 2}]}]}, "case": {"title": "مَن أنا؟", "story": "وجد فصيح بين صفحات المصحف ورقة لغز صغيرة. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا صحابيّ كنتُ من كُتّاب الوحي، أكتب القرآن الذي ينزل على النبيّ ﷺ.", "تعلّمتُ لغة اليهود بأمر النبيّ ﷺ.", "جمعتُ القرآن الكريم في مصحف."], "options": ["عبد الله بن عباس رضي الله عنهما", "أبو هريرة رضي الله عنه", "زيد بن ثابت رضي الله عنه"], "deep": "لماذا كان جمع القرآن في مصحف واحد عملًا عظيمًا؟ وكيف نشكر الله على أنّ المصحف بين أيدينا اليوم؟", "reveal": "أنا زيد بن ثابت رضي الله عنه! كلّفني أبو بكر الصديق بجمع القرآن، فجمعته بعناية كبيرة. وفي الحلقة القادمة نحفظ أحاديث من كلام النبيّ ﷺ، وأوّلها حديث النيّة."}, "quiz": [{"q": "ما معنى «الكوثر»؟", "o": ["نهر في الدنيا", "الخير الكثير، ومنه نهر في الجنّة", "اسم جبل"], "a": 1, "why": "أعطى الله نبيّه ﷺ الخير الكثير، ومنه نهر الكوثر في الجنّة."}], "qa": [{"id": 132, "q": "اقرأْ سورةَ الماعونِ وفسِّرها.", "a": "﴿أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ۝ فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ۝ وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ ۝ فَوَيْلٌ لِّلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ﴾ [الماعون: ١–٧].\n\nالتفسير:\n١. هل عرفتَ الذي يكذِّبُ بالجزاءِ يومَ القيامة؟!\n٢. فهو ذلك الذي يدفعُ اليتيمَ بغلظةٍ عن حاجته.\n٣. ولا يحثُّ نفسَه، ولا يحثُّ غيرَهُ على إطعامِ الفقير.\n٤. فهلاكٌ وعذابٌ للمصلِّين.\n٥. الذين هم عن صلاتِهم لاهون، لا يبالونَ بها حتى ينقضيَ وقتُها.\n٦. الذين هم يراؤونَ بصلاتِهم وأعمالِهم، لا يُخلصونَ العملَ لله.\n٧. ويمنعونَ إعانةَ غيرِهم بما لا ضررَ في الإعانةِ به."}, {"id": 133, "q": "اقرأْ سورةَ الكوثرِ وفسِّرها.", "a": "﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ ۝ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ﴾ [الكوثر: ١–٣].\n\nالتفسير:\n١. إنا آتيناك — أيها الرسول — الخيرَ الكثير، ومنه نهرُ الكوثرِ في الجنة.\n٢. فأدِّ شكرَ الله على هذه النعمة، أن تصليَ له وحده وتذبح، خلافًا لما يفعلُهُ المشركونَ من التقرّبِ لأوثانِهم بالذبح.\n٣. إنَّ مُبغِضَكَ هو المنقطعُ عن كلِّ خير، المنسيُّ الذي إن ذُكِرَ ذُكِرَ بسوء."}, {"id": 134, "q": "اقرأْ سورةَ الكافرونِ وفسِّرها.", "a": "﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ ۝ لَا أَعْبُدُ مَا تَعْبُدُونَ ۝ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ۝ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ لَكُمْ دِينُكُمْ وَلِيَ دِينِ﴾ [الكافرون: ١–٦].\n\nالتفسير:\n١. قل — أيها الرسول —: يا أيها الكافرونَ بالله.\n٢. لا أعبدُ في الحالِ ولا في المستقبلِ ما تعبدونَ من الأصنام.\n٣. ولا أنتم عابدونَ ما أعبدُهُ أنا، وهو اللهُ وحده.\n٤. ولا أنا عابدٌ ما عبدتُم من الأصنام.\n٥. ولا أنتم عابدونَ ما أعبدُهُ أنا، وهو اللهُ وحده.\n٦. لكم دينُكمُ الذي ابتدعتموهُ لأنفسِكم، ولي دينيَ الذي أنزلَهُ اللهُ عليّ."}, {"id": 135, "q": "اقرأْ سورةَ النصرِ وفسِّرها.", "a": "﴿إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ۝ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ۝ فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا﴾ [النصر: ١–٣].\n\nالتفسير:\n١. إذا جاء نصرُ الله لدينك — أيها الرسول — وإعزازُهُ له، وحدثَ فتحُ مكة.\n٢. ورأيتَ الناسَ يدخلونَ في الإسلامِ وفدًا بعد وفد.\n٣. فاعلمْ أنَّ ذلك علامةٌ على قربِ انتهاءِ المهمةِ التي بُعِثتَ بها، وقربِ انتهاءِ أجلِكَ ولقائِكَ بربك، فسبِّحْ بحمدِ ربِّكَ شكرًا له على نعمةِ النصرِ والفتح، واطلبْ منه المغفرة، إنه كان توابًا يقبلُ توبةَ عبادِهِ ويغفرُ لهم."}, {"id": 136, "q": "اقرأْ سورةَ المسدِ وفسِّرها.", "a": "﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ۝ مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ ۝ سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ ۝ وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ ۝ فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ﴾ [المسد: ١–٥].\n\nالتفسير:\n١. خسِرتْ يدا عمِّ النبيِّ ﷺ، أبي لهبٍ بنِ عبدِ المطلبِ بخسرانِ عملِه؛ إذ كان يؤذي النبيَّ ﷺ، وخابَ سعيُه.\n٢. أيُّ شيءٍ أغنى عنه مالُهُ وولدُه؟ لم يدفعا عنه عذابًا، ولم يجلبا له رحمة.\n٣. سيدخلُ يومَ القيامةِ نارًا ذاتَ لهب، يقاسي حرَّها.\n٤. وستدخلُها زوجتُهُ أمُّ جميلٍ التي كانت تؤذي النبيَّ ﷺ، بإلقاءِ الشوكِ في طريقه.\n٥. في عنقِها حبلٌ مُحكَمُ الفتلِ تُساقُ به إلى النار."}, {"id": 137, "q": "اقرأْ سورةَ الإخلاصِ وفسِّرها.", "a": "﴿قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ﴾ [الإخلاص: ١–٤].\n\nالتفسير:\n١. قل — يا أيها الرسول —: هو اللهُ لا إله غيرُه.\n٢. الله الصمد: أي تُرفعُ إليه حاجاتُ الخلق.\n٣. لم يلد ولم يولد: فلا ولدَ له سبحانه ولا والد.\n٤. ولم يكن له كفوًا أحد: ولم يكنْ له مماثلٌ من خلقِه."}, {"id": 138, "q": "اقرأْ سورةَ الفلقِ وفسِّرها.", "a": "﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ [الفلق: ١–٥].\n\nالتفسير:\n١. قل — يا أيها الرسول —: أعتصمُ بربِّ الصبح، وأستجيرُ به.\n٢. من شرِّ ما يؤذي من المخلوقات.\n٣. وأعتصمُ بالله من الشرورِ التي تظهرُ في الليلِ من دوابَّ ولصوص.\n٤. وأعتصمُ به من شرِّ السواحرِ اللائي ينفثنَ في العُقَد.\n٥. ومن شرِّ حاسدٍ مبغضٍ للناسِ إذا حسدَهم على ما وهبهمُ اللهُ من نِعَم، يريدُ زوالَها عنهم، وإيقاعَ الأذى بهم."}, {"id": 139, "q": "اقرأْ سورةَ الناسِ وفسِّرها.", "a": "﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ﴾ [الناس: ١–٦].\n\nالتفسير:\n١. قل — يا أيها الرسول —: أعتصمُ بربِّ الناس، وأستجيرُ به.\n٢. ملك الناس: يتصرفُ فيهم بما يشاء، لا مالكَ لهم غيرُه.\n٣. إله الناس: معبودُهم بحقٍّ، لا معبودَ لهم بحقٍّ غيرُه.\n٤. من شرِّ الشيطانِ الذي يلقي وسوستَهُ إلى الناس.\n٥. يلقي بوسوستِهِ إلى قلوبِ الناس.\n٦. من الجنة والناس: أي الموسوسُ يكونُ من الإنسِ ويكونُ من الجن."}], "dyk": ["في مجرَّتِنا وحدَها أكثرُ من ١٠٠ مليارِ نجم، وفي الكونِ مليارات المجرَّات — سبحان الخالق!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي صَدِيقِي الْبَبَّغَاءُ فَصِيح!"}, {"s": "fasih", "t": "أَهْلًا أَهْلًا! فَصِيح، فَصِيح! جَوَابُ لُغْزِ الْمَرَّةِ الْمَاضِيَةِ: الْحَافِظُ ابْنُ كَثِيرٍ رَحِمَهُ اللَّهُ، صَاحِبُ «تَفْسِيرِ الْقُرْآنِ الْعَظِيمِ»!"}, {"s": "anos", "t": "وَالْيَوْمَ نَفْهَمُ ثَمَانِيَ سُوَرٍ، مِنَ الْمَاعُونِ إِلَى النَّاسِ. هَاتِ أَسْئِلَتَكَ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا مَعْنَى سُورَةِ الْمَاعُونِ؟"}, {"s": "anos", "t": "تَتَكَلَّمُ عَمَّنْ يُكَذِّبُ بِيَوْمِ الْقِيَامَةِ، فَيَدْفَعُ الْيَتِيمَ بِغِلْظَةٍ، وَلَا يَحُثُّ عَلَى إِطْعَامِ الْمِسْكِينِ، وَتُحَذِّرُ مِمَّنْ يَسْهُو عَنْ صَلَاتِهِ حَتَّى يَخْرُجَ وَقْتُهَا، وَمَنْ يُرَائِي، وَمَنْ يَمْنَعُ عَوْنَ غَيْرِهِ بِشَيْءٍ لَا يَضُرُّهُ."}, {"s": "fasih", "t": "وَسُورَةُ الْكَوْثَرِ؟"}, {"s": "anos", "t": "أَعْطَى اللَّهُ نَبِيَّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخَيْرَ الْكَثِيرَ، وَمِنْهُ نَهْرٌ فِي الْجَنَّةِ، فَيَشْكُرُهُ بِالصَّلَاةِ وَالذَّبْحِ لِلَّهِ وَحْدَهُ، وَمُبْغِضُهُ هُوَ الْمُنْقَطِعُ عَنْ كُلِّ خَيْرٍ. اسْمَعُوا أَوَّلَ آيَةٍ مِنْهَا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "108:1", "t": "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ"}, {"s": "fasih", "t": "فَكَمَا أَعْطَاهُ اللَّهُ الْخَيْرَ الْكَثِيرَ، أَعْطَانَا نِعَمًا كَثِيرَةً، وَشُكْرُهَا أَنْ نُصَلِّيَ لِلَّهِ وَحْدَهُ وَنُحْسِنَ إِلَى النَّاسِ. وَسُورَةُ الْكَافِرُونَ؟"}, {"s": "anos", "t": "يَقُولُ النَّبِيُّ بِوُضُوحٍ: لَا أَعْبُدُ أَصْنَامَكُمْ، لَا الْيَوْمَ وَلَا غَدًا، وَأَعْبُدُ اللَّهَ وَحْدَهُ. لَكُمْ دِينُكُمْ، وَلِي دِينِيَ الَّذِي أَنْزَلَهُ اللَّهُ."}, {"s": "fasih", "t": "وَسُورَةُ النَّصْرِ؟"}, {"s": "anos", "t": "لَمَّا فُتِحَتْ مَكَّةُ وَدَخَلَ النَّاسُ فِي الْإِسْلَامِ وَفْدًا بَعْدَ وَفْدٍ، كَانَتْ عَلَامَةً عَلَى قُرْبِ لِقَاءِ النَّبِيِّ بِرَبِّهِ، فَسَبَّحَ بِحَمْدِ رَبِّهِ وَاسْتَغْفَرَهُ."}, {"s": "fasih", "t": "وَسُورَةُ الْمَسَدِ؟"}, {"s": "anos", "t": "أَبُو لَهَبٍ آذَى النَّبِيَّ فَخَسِرَ، وَلَمْ يَنْفَعْهُ مَالُهُ وَلَا وَلَدُهُ، وَسَيَدْخُلُ النَّارَ هُوَ وَزَوْجَتُهُ الَّتِي كَانَتْ تُلْقِي الشَّوْكَ فِي طَرِيقِ النَّبِيِّ."}, {"s": "fasih", "t": "وَسُورَةُ الْإِخْلَاصِ؟"}, {"s": "anos", "t": "تُعَرِّفُنَا بِاللَّهِ: لَا إِلَهَ غَيْرُهُ، الصَّمَدُ تُرْفَعُ إِلَيْهِ حَاجَاتُ الْخَلْقِ، لَا وَلَدَ لَهُ وَلَا وَالِدَ، وَلَا مِثْلَ لَهُ."}, {"s": "fasih", "t": "وَسُورَةُ الْفَلَقِ؟"}, {"s": "anos", "t": "أَعْتَصِمُ بِرَبِّ الصُّبْحِ مِنْ شَرِّ الْمَخْلُوقَاتِ، وَمِنْ شُرُورِ اللَّيْلِ، وَمِنَ السَّوَاحِرِ، وَمِنَ الْحَاسِدِ الَّذِي يُرِيدُ زَوَالَ النِّعْمَةِ."}, {"s": "fasih", "t": "وَسُورَةُ النَّاسِ؟"}, {"s": "anos", "t": "نَعْتَصِمُ بِرَبِّ النَّاسِ، مَلِكِهِمْ وَإِلَهِهِمْ، مِنَ الشَّيْطَانِ الَّذِي يُوَسْوِسُ فِي الْقُلُوبِ، وَيَكُونُ مِنَ الْجِنِّ وَمِنَ الْإِنْسِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ فِي مَجَرَّتِنَا وَحْدَهَا أَكْثَرُ مِنْ مِئَةِ مِلْيَارِ نَجْمٍ، وَفِي الْكَوْنِ مِلْيَارَاتُ الْمَجَرَّاتِ! سُبْحَانَ الْخَالِقِ!"}, {"s": "anos", "t": "نَشَاطُنَا: قِطَارُ السُّوَرِ الثَّمَانِي! يَقِفُ ثَمَانِيَةُ أَصْدِقَاءَ بِتَرْتِيبِ السُّوَرِ، وَكُلُّ عَرَبَةٍ تَقُولُ مَعْنَى سُورَتِهَا. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: قطار السور الثماني"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! زَمِيلُكَ نَسِيَ قَلَمَهُ، وَمَعَكَ قَلَمَانِ. أ: تَقُولُ لَيْسَ عِنْدِي. ب: تُعْطِيهِ بِابْتِسَامَةٍ. ج: تُعْطِيهِ لِيَمْدَحَكَ الْمُعَلِّمُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الجار يطلب قلمًا"}, {"s": "anos", "t": "أ يُشْبِهُ مَنْعَ الْمَاعُونِ، وَج فِيهِ رِيَاءٌ، أَمَّا ب فَفِيهِ رَحْمَةٌ وَإِخْلَاصٌ لِلَّهِ. هُوَ الْأَفْضَلُ!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: هَلْ نَفَعَ أَبَا لَهَبٍ مَالُهُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "لَا، لَمْ يَنْفَعْهُ مَالُهُ وَلَا وَلَدُهُ."}, {"s": "fasih", "t": "وَمَنِ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ؟ فَكِّرُوا…"}, {"s": "anos", "t": "الشَّيْطَانُ، مِنَ الْجِنِّ وَالْإِنْسِ!"}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: صَحَابِيٌّ مِنْ كُتَّابِ الْوَحْيِ، تَعَلَّمَ لُغَةَ الْيَهُودِ بِأَمْرِ النَّبِيِّ، وَجَمَعَ الْقُرْآنَ فِي مُصْحَفٍ. ابْنُ عَبَّاسٍ، أَمْ أَبُو هُرَيْرَةَ، أَمْ زَيْدُ بْنُ ثَابِتٍ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ اصْنَعُوا «مُصْحَفِيَ الصَّغِيرَ الْمُلَوَّنَ»، وَالْعَبُوا «رِحْلَةَ فَصِيح فِي السُّوَرِ» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 17, "title": "أحاديث أحفظها (١)", "season": 2, "goals": ["hadith"], "hook": "أهلًا يا أصدقاء! فصيح يرفرف ويقول: «كلام قليل… وعلم كثير! كلام قليل… وعلم كثير!». اليوم نحفظ أحاديث من كلام نبيّنا ﷺ. هل تعرف حديثًا تحفظه؟", "sections": [{"h": "النيّة أوّلًا، واتّباع السنّة دائمًا", "p": ["قال النبيّ ﷺ: <b>إنما الأعمال بالنيات، وإنما لكلّ امرئ ما نوى</b>. والنيّة هي ما تريده في قلبك عندما تعمل.", "مثال: أنوس وصديقه صلّيا معًا. أنوس صلّى لله، وصديقه صلّى ليمدحه الناس. الصلاة في الظاهر واحدة، لكنّ الأجر مختلف! فكل عمل يحتاج نيّة، ويجب أن تكون النيّة <b>خالصة لله</b>.", "وقال ﷺ: <b>من أحدث في أمرنا هذا ما ليس منه فهو ردّ</b>. أي: من زاد في الدين عبادة جديدة لم يعلّمنا إيّاها النبيّ ﷺ، فعمله مردود غير مقبول. فنحن نعبد الله كما علّمنا نبيّنا ﷺ."], "board": ["النيّة لله", "العبادة كما علّمنا النبيّ ﷺ"]}, {"h": "حديث جبريل: درس في مجلس النبيّ ﷺ", "p": ["جاء رجل شديد بياض الثياب، شديد سواد الشعر، لا يُرى عليه أثر السفر، ولا يعرفه أحد. جلس أمام النبيّ ﷺ وسأله أسئلة مهمّة.", "سأل عن <b>الإسلام</b>، فذكر النبيّ ﷺ أركانه الخمسة: الشهادتين، والصلاة، والزكاة، وصوم رمضان، وحجّ البيت لمن استطاع. وسأل عن <b>الإيمان</b>، فذكر أركانه الستة: الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشرّه.", "وسأل عن <b>الإحسان</b>، فقال: أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك. ثم أخبرهم النبيّ ﷺ أنّ السائل هو <b>جبريل</b>، جاء يعلّمهم دينهم. ومن فوائده أيضًا: أنّ وقت قيام الساعة لا يعلمه إلا الله."], "board": ["الإسلام: ٥ أركان", "الإيمان: ٦ أركان", "الإحسان: كأنك تراه"]}, {"h": "أخلاقي من إيماني، وحلفي بالله وحده", "p": ["قال النبيّ ﷺ: <b>أكمل المؤمنين إيمانًا أحسنهم خُلُقًا</b>. فكلّما كانت أخلاقك أجمل، كان إيمانك أكمل. والإيمان يزيد بالطاعة وينقص بالمعصية.", "فصيح يسأل: «هل أقول: وحياة أمّي؟ أو: والكعبة؟». لا يا فصيح! قال ﷺ: <b>من حلف بغير الله فقد كفر أو أشرك</b>. فلا نحلف إلا بالله، والحلف بغير الله من <b>الشرك الأصغر</b>."], "board": ["أحسن خُلُقًا = أكمل إيمانًا", "لا أحلف إلا بالله"]}, {"h": "أحبّ النبيّ ﷺ، وأحبّ الخير لأخي", "p": ["قال ﷺ: <b>لا يؤمن أحدكم حتى أكون أحبّ إليه من والده وولده والناس أجمعين</b>. فنحبّ النبيّ ﷺ أكثر من كل الناس، ونُظهر حبّنا باتّباع سنّته والصلاة عليه.", "وقال ﷺ: <b>لا يؤمن أحدكم حتى يحبّ لأخيه ما يحبّ لنفسه</b>. إذا فرحتَ بلعبة جديدة، فتمنَّ لصديقك أن يفرح مثلك. وإذا نجحتَ، فتمنَّ له النجاح أيضًا.", "وهذا كلّه من <b>كمال الإيمان</b>. قال أنوس: «قلبي يتّسع لحبّ النبيّ ﷺ ولحبّ الخير لكل أصدقائي!»."], "board": ["أحبّ النبيّ ﷺ أكثر من الناس", "أحبّ لأخي ما أحبّ لنفسي"]}], "summary": ["كل عمل يحتاج نيّة خالصة لله، والزيادة في الدين بشيء جديد مردودة.", "حديث جبريل علّمنا أركان الإسلام الخمسة، وأركان الإيمان الستة، ومعنى الإحسان.", "لا نحلف إلا بالله، ونحبّ النبيّ ﷺ أكثر من الناس، ونحبّ لإخواننا ما نحبّ لأنفسنا."], "islam": {"intro": "قال الله تعالى يأمرنا بالإخلاص:", "text": "قبل أن تبدأ أيّ عمل جميل، اسأل قلبك: لمن أعمل هذا؟ وقل في نفسك: لله.", "ayah": {"text": "وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ", "src": "سُورَةُ البَيِّنَةِ: ٥"}, "hadith": {"text": "إنما الأعمال بالنيات، وإنما لكلّ امرئ ما نوى", "source": "رواه البخاري ومسلم"}}, "home": {"title": "صندوق النيّات", "goal": "أن يتدرّب الطفل على تجديد نيّته لله قبل أعماله اليومية.", "materials": ["علبة صغيرة", "أوراق ملوّنة", "قلم"], "steps": ["زيّن العلبة واكتب عليها: «صندوق النيّات».", "كل يوم، اكتب عملًا جميلًا قبل أن تفعله، واكتب بجانبه نيّتك: «لله».", "في آخر الأسبوع، افتح الصندوق مع أسرتك واقرأوا الأوراق معًا.", "احفظ حديث «إنما الأعمال بالنيات» وقُله لأسرتك على مائدة الطعام."], "parent": "ذكّروا طفلكم بالنيّة بلطف قبل الدراسة والنوم واللعب، وكونوا قدوة: قولوا أمامه «نويتُ هذا لله»."}, "online": {"title": "أحاديث فصيح", "intro": "أكمل الأحاديث مع فصيح، وصنّف أركان الإسلام والإيمان!", "steps": [{"type": "match", "title": "أكمل الحديث", "prompt": "اختر بداية الحديث، ثم تكملته الصحيحة.", "pairs": [["إنما الأعمال", "بالنيات"], ["من أحدث في أمرنا هذا ما ليس منه", "فهو ردّ"], ["أكمل المؤمنين إيمانًا", "أحسنهم خُلُقًا"], ["من حلف بغير الله", "فقد كفر أو أشرك"], ["لا يؤمن أحدكم حتى يحبّ لأخيه", "ما يحبّ لنفسه"]]}, {"type": "sort", "title": "ركن إسلام أم ركن إيمان؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["أركان الإسلام", "أركان الإيمان"], "items": [{"t": "إقامة الصلاة", "icon": "🕌", "bin": 0, "why": "الصلاة ركن من أركان الإسلام الخمسة."}, {"t": "صوم رمضان", "icon": "🌙", "bin": 0, "why": "صوم رمضان ركن من أركان الإسلام."}, {"t": "إيتاء الزكاة", "icon": "💰", "bin": 0, "why": "الزكاة ركن من أركان الإسلام."}, {"t": "الإيمان بالملائكة", "icon": "✨", "bin": 1, "why": "الإيمان بالملائكة من أركان الإيمان الستة."}, {"t": "الإيمان باليوم الآخر", "icon": "⏳", "bin": 1, "why": "الإيمان باليوم الآخر من أركان الإيمان."}, {"t": "الإيمان بالقدر خيره وشرّه", "icon": "📜", "bin": 1, "why": "الإيمان بالقدر ركن الإيمان السادس."}]}, {"type": "decision", "title": "قرار أنوس", "scenario": "صديقك حصل على جائزة في المسابقة، وأنت لم تحصل عليها. ماذا تفعل؟", "options": [{"t": "أحزن وأتمنّى لو أخذها غيره", "result": "هذا ليس من حبّ الخير للأخ، والنبيّ ﷺ علّمنا أن نحبّ لإخواننا الخير."}, {"t": "أهنّئه وأفرح له، وأدعو الله أن يرزقني مثله", "result": "أحسنت! هذا من كمال الإيمان: أن تحبّ لأخيك ما تحبّ لنفسك.", "best": true}, {"t": "أبتعد عنه ولا أكلّمه", "result": "هذا يجرح صديقك، والأفضل أن تفرح له وتهنّئه."}]}]}, "case": {"title": "مَن أنا؟", "story": "وجد فصيح كتابًا كبيرًا في مكتبة المسجد، وفي داخله ورقة لغز. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["رحلتُ إلى بلاد كثيرة في طلب حديث النبيّ ﷺ.", "حفظتُ مئات الألوف من الأحاديث.", "جمعتُ أصحّ كتاب بعد كتاب الله."], "options": ["الإمام البخاري رحمه الله", "الإمام مسلم رحمه الله", "الإمام أحمد بن حنبل رحمه الله"], "deep": "لماذا سافر العلماء مسافات بعيدة ليجمعوا الأحاديث؟ وماذا نستفيد نحن من تعبهم اليوم؟", "reveal": "أنا الإمام البخاري رحمه الله، واسم كتابي «صحيح البخاري»، وفيه حديث «إنما الأعمال بالنيات». وفي الحلقة القادمة نحفظ أحاديث أخرى، منها حديث عن كنز من كنوز الجنّة!"}, "quiz": [{"q": "أكمل الحديث: «إنما الأعمال…»", "o": ["بالأموال", "بالنيات", "بالكلام"], "a": 1, "why": "قال ﷺ: «إنما الأعمال بالنيات، وإنما لكلّ امرئ ما نوى»."}], "qa": [{"id": 140, "q": "أكملْ حديث: «إنما الأعمالُ بالنيات...»، واذكرْ بعضَ فوائده.", "a": "عن أميرِ المؤمنينَ أبي حفصٍ عمرَ بنِ الخطابِ رضي الله عنه قال: سمعتُ رسولَ الله ﷺ يقول: «إنما الأعمالُ بالنيات، وإنما لكلِّ امرئٍ ما نوى، فمن كانتْ هجرتُهُ إلى اللهِ ورسولِه؛ فهجرتُهُ إلى اللهِ ورسولِه، ومن كانتْ هجرتُهُ لدنيا يصيبُها، أو امرأةٍ ينكحُها؛ فهجرتُهُ إلى ما هاجرَ إليه» رواه البخاري ومسلم.\n\nفوائد من الحديث:\n١. كلُّ عملٍ لا بدَّ له من نية، من صلاةٍ، وصومٍ، وحجٍّ، وغيرِها من الأعمال.\n٢. لا بدَّ من الإخلاصِ في النيةِ لله تعالى."}, {"id": 141, "q": "أكملْ حديث: «من أحدثَ في أمرِنا هذا...»، واذكرْ بعضَ فوائده.", "a": "عن أمِّ المؤمنينَ أمِّ عبدِ اللهِ عائشةَ رضي الله عنها قالت: قال رسولُ الله ﷺ: «من أحدثَ في أمرِنا هذا ما ليس منه، فهو ردّ» رواه البخاري ومسلم.\n\nفوائد من الحديث:\n١. النهيُ عن الابتداعِ في الدين.\n٢. وأنَّ الأعمالَ المُحدَثةَ مردودةٌ غيرُ مقبولة."}, {"id": 142, "q": "أكملْ حديث: «بينما نحن جلوسٌ عند رسولِ الله ﷺ...» (حديثُ جبريل)، واذكرْ بعضَ فوائده.", "a": "عن عمرَ بنِ الخطابِ قال: «بينما نحن جلوسٌ عند رسولِ الله ﷺ ذاتَ يوم، إذ طلعَ علينا رجلٌ شديدُ بياضِ الثياب، شديدُ سوادِ الشعر، لا يُرى عليه أثرُ السفر، ولا يعرفُهُ منا أحد، حتى جلسَ إلى النبيِّ ﷺ، فأسندَ ركبتيهِ إلى ركبتيه، ووضعَ كفيهِ على فخذيه، وقال: يا محمدُ أخبرني عن الإسلام، فقال: \"الإسلامُ أن تشهدَ أن لا إله إلا الله، وأنَّ محمدًا رسولُ الله، وتقيمَ الصلاة، وتؤتيَ الزكاة، وتصومَ رمضان، وتحجَّ البيتَ إن استطعتَ إليه سبيلًا\"، قال: صدقت... قال: أخبرني عن الإيمان، قال: \"أن تؤمنَ بالله، وملائكتِه، وكتبِه، ورسلِه، واليومِ الآخر، وتؤمنَ بالقدرِ خيرِهِ وشرِّه\"، قال: صدقت، قال: فأخبرني عن الإحسان، قال: \"أن تعبدَ اللهَ كأنك تراه، فإن لم تكنْ تراه فإنه يراك\"... ثم قال: \"يا عمرُ أتدري من السائل؟\" قلت: اللهُ ورسولُهُ أعلم، قال: \"فإنه جبريلُ، أتاكم يعلِّمُكم دينَكم\"» رواه مسلم.\n\nمن فوائد الحديث:\n١. ذكرُ أركانِ الإسلامِ الخمسة: شهادةُ أن لا إله إلا الله وأنَّ محمدًا رسولُ الله، وإقامُ الصلاة، وإيتاءُ الزكاة، وصومُ رمضان، وحجُّ بيتِ اللهِ الحرام.\n٢. ذكرُ أركانِ الإيمانِ الستة.\n٣. ذكرُ ركنِ الإحسان: أن تعبدَ اللهَ كأنك تراه، فإن لم تكنْ تراه فإنه يراك.\n٤. وقتُ قيامِ الساعةِ لا يعلمُهُ إلا اللهُ تعالى."}, {"id": 143, "q": "أكملْ حديث: «أكملُ المؤمنينَ إيمانًا...»، واذكرْ بعضَ فوائده.", "a": "عن أبي هريرة قال: قال رسولُ الله ﷺ: «أكملُ المؤمنينَ إيمانًا: أحسنُهم خُلُقًا» رواه الترمذي وقال: \"حديثٌ حسنٌ صحيح\".\n\nفوائد من الحديث:\n١. الحثُّ على حُسنِ الخُلُق.\n٢. وأنَّ كمالَ الخُلُقِ من كمالِ الإيمان.\n٣. وأنَّ الإيمانَ يزيدُ وينقص."}, {"id": 144, "q": "أكملْ حديث: «من حلفَ بغيرِ الله...»، واذكرْ بعضَ فوائده.", "a": "عن ابنِ عمرَ رضي الله عنهما أنَّ النبيَّ ﷺ قال: «من حلفَ بغيرِ الله؛ فقد كفرَ أو أشرك» رواه الترمذي.\n\nفوائد من الحديث:\n• لا يجوزُ الحلفُ إلا بالله تعالى.\n• الحلفُ بغيرِ الله تعالى من الشركِ الأصغر."}, {"id": 145, "q": "أكملْ حديث: «لا يؤمنُ أحدُكم حتى أكونَ أحبَّ إليه...»، واذكرْ بعضَ فوائده.", "a": "عن أنس، قال رسولُ الله ﷺ: «لا يؤمنُ أحدُكم حتى أكونَ أحبَّ إليه من والدِه، وولدِه، والناسِ أجمعين» رواه البخاري ومسلم.\n\nمن فوائد الحديث:\n• يجبُ محبةُ النبيِّ ﷺ أكثرَ من كلِّ الناس.\n• أنَّ ذلك من كمالِ الإيمان."}, {"id": 146, "q": "أكملْ حديث: «لا يؤمنُ أحدُكم حتى يحبَّ لأخيه...»، واذكرْ بعضَ فوائده.", "a": "عن أنس، قال رسولُ الله ﷺ: «لا يؤمنُ أحدُكم؛ حتى يحبَّ لأخيهِ ما يحبُّ لنفسه» رواه البخاري ومسلم.\n\nمن فوائد الحديث:\n• على المؤمنِ أن يحبَّ للمؤمنينَ من الخيرِ كما يحبُّ لنفسه.\n• وذلك من كمالِ الإيمان."}], "dyk": ["القمرُ يبتعدُ عن الأرضِ نحوَ ٤ سنتيمتراتٍ كلَّ سنة، بنظامٍ دقيقٍ خلقَه الله."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "كَلَامٌ قَلِيلٌ… وَعِلْمٌ كَثِيرٌ! جَوَابُ اللُّغْزِ الْمَاضِي: زَيْدُ بْنُ ثَابِتٍ رَضِيَ اللَّهُ عَنْهُ، كَلَّفَهُ أَبُو بَكْرٍ الصِّدِّيقُ بِجَمْعِ الْقُرْآنِ فَجَمَعَهُ بِعِنَايَةٍ."}, {"s": "anos", "t": "وَالْيَوْمَ نَحْفَظُ أَحَادِيثَ مِنْ كَلَامِ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. هَاتِ يَا فَصِيح!"}, {"s": "fasih", "t": "أَكْمِلْ: «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ…»"}, {"s": "anos", "t": "«وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى». رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ. فَكُلُّ عَمَلٍ يَحْتَاجُ نِيَّةً، وَيَجِبُ أَنْ تَكُونَ خَالِصَةً لِلَّهِ."}, {"s": "fasih", "t": "وَالْقُرْآنُ يَأْمُرُنَا بِالْإِخْلَاصِ أَيْضًا. اسْمَعُوا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "98:5", "t": "وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ"}, {"s": "anos", "t": "فَقَبْلَ أَيِّ عَمَلٍ جَمِيلٍ، اسْأَلْ قَلْبَكَ: لِمَنْ أَعْمَلُ هَذَا؟ وَقُلْ فِي نَفْسِكَ: لِلَّهِ."}, {"s": "fasih", "t": "أَكْمِلْ: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا…»"}, {"s": "anos", "t": "«مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ». رَوَتْهُ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا. فَلَا نَبْتَدِعُ فِي الدِّينِ، وَالْعَمَلُ الْمُحْدَثُ مَرْدُودٌ غَيْرُ مَقْبُولٍ."}, {"s": "fasih", "t": "وَحَدِيثُ جِبْرِيلَ! رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ سَأَلَ النَّبِيَّ. عَمَّ سَأَلَ؟"}, {"s": "anos", "t": "عَنِ الْإِسْلَامِ: الشَّهَادَتَانِ، وَالصَّلَاةُ، وَالزَّكَاةُ، وَصَوْمُ رَمَضَانَ، وَالْحَجُّ. وَعَنِ الْإِيمَانِ: بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَالْقَدَرِ. وَعَنِ الْإِحْسَانِ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ."}, {"s": "fasih", "t": "ثُمَّ قَالَ النَّبِيُّ: «فَإِنَّهُ جِبْرِيلُ، أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ». رَوَاهُ مُسْلِمٌ. وَوَقْتُ السَّاعَةِ لَا يَعْلَمُهُ إِلَّا اللَّهُ."}, {"s": "anos", "t": "أَحْسَنْتَ! الْحَدِيثُ الرَّابِعُ؟"}, {"s": "fasih", "t": "«أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا…»"}, {"s": "anos", "t": "«أَحْسَنُهُمْ خُلُقًا». رَوَاهُ التِّرْمِذِيُّ. فَحُسْنُ الْخُلُقِ مِنْ كَمَالِ الْإِيمَانِ، وَالْإِيمَانُ يَزِيدُ وَيَنْقُصُ."}, {"s": "fasih", "t": "«مَنْ حَلَفَ بِغَيْرِ اللَّهِ…»"}, {"s": "anos", "t": "«فَقَدْ كَفَرَ أَوْ أَشْرَكَ». رَوَاهُ التِّرْمِذِيُّ. فَلَا نَحْلِفُ إِلَّا بِاللَّهِ، وَالْحَلِفُ بِغَيْرِهِ مِنَ الشِّرْكِ الْأَصْغَرِ."}, {"s": "fasih", "t": "«لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ…»"}, {"s": "anos", "t": "«مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ». فَنُحِبُّ النَّبِيَّ أَكْثَرَ مِنْ كُلِّ النَّاسِ."}, {"s": "fasih", "t": "وَالْأَخِيرُ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ…»"}, {"s": "anos", "t": "«مَا يُحِبُّ لِنَفْسِهِ». وَهَذَانِ الْحَدِيثَانِ رَوَاهُمَا الْبُخَارِيُّ وَمُسْلِمٌ عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الْقَمَرُ يَبْتَعِدُ عَنِ الْأَرْضِ نَحْوَ أَرْبَعَةِ سَنْتِيمِتْرَاتٍ كُلَّ سَنَةٍ، بِنِظَامٍ دَقِيقٍ خَلَقَهُ اللَّهُ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: نَشِيدُ أَصَابِعِ الْأَرْكَانِ. عُدُّوا عَلَى أَصَابِعِكُمْ أَرْكَانَ الْإِسْلَامِ الْخَمْسَةَ، ثُمَّ أَرْكَانَ الْإِيمَانِ السِّتَّةَ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد أصابع الأركان"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! سَاعَدَ أَنُوس أُمَّهُ فِي تَرْتِيبِ الْبَيْتِ. أَيُّ نِيَّةٍ أَفْضَلُ؟ أ: لِيَأْخُذَ حَلْوَى فَقَطْ. ب: لِيَمْدَحَهُ الضُّيُوفُ. ج: لِأَنَّ اللَّهَ أَمَرَنَا بِبِرِّ الْوَالِدَيْنِ، وَلِيُفَرِّحَ أُمَّهُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: لماذا ساعدتَ أمّك؟"}, {"s": "anos", "t": "أ وَب نِيَّتُهُمَا لِلدُّنْيَا وَالنَّاسِ، أَمَّا ج فَنِيَّةٌ خَالِصَةٌ لِلَّهِ، يَأْخُذُ صَاحِبُهَا الْأَجْرَ. هِيَ الْأَفْضَلُ!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَنِ الرَّجُلُ الَّذِي سَأَلَ النَّبِيَّ عَنِ الْإِسْلَامِ وَالْإِيمَانِ وَالْإِحْسَانِ؟ فَكِّرُوا…"}, {"s": "anos", "t": "جِبْرِيلُ عَلَيْهِ السَّلَامُ!"}, {"s": "fasih", "t": "وَبِمَاذَا يَحْلِفُ الْمُسْلِمُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "بِاللَّهِ وَحْدَهُ!"}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: رَحَلْتُ إِلَى بِلَادٍ كَثِيرَةٍ فِي طَلَبِ الْحَدِيثِ، وَحَفِظْتُ مِئَاتِ الْأُلُوفِ مِنَ الْأَحَادِيثِ، وَجَمَعْتُ أَصَحَّ كِتَابٍ بَعْدَ كِتَابِ اللَّهِ. الْبُخَارِيُّ، أَمْ مُسْلِمٌ، أَمْ أَحْمَدُ بْنُ حَنْبَلٍ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ اصْنَعُوا «صُنْدُوقَ النِّيَّاتِ»، وَالْعَبُوا «أَحَادِيثَ فَصِيح» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 18, "title": "أحاديث أحفظها (٢)", "season": 2, "goals": ["hadith"], "hook": "أهلًا يا أصدقاء! فصيح يهمس: «عندي سرّ… كنز… كنز من كنوز الجنّة!». هل تحبّ أن تعرف ما هذا الكنز؟ وكيف تحمله معك في كل مكان؟ تابعوا مع أنوس!", "sections": [{"h": "سورة تعدل ثلث القرآن، وكنز من كنوز الجنّة", "p": ["قال النبيّ ﷺ عن سورة الإخلاص: <b>والذي نفسي بيده! إنها لتعدل ثلث القرآن</b>. سورة قصيرة نحفظها في دقيقة، وفضلها عظيم جدًّا!", "وقال ﷺ: <b>لا حول ولا قوة إلا بالله كنز من كنوز الجنّة</b>. فصيح يسأل: «كنز بلا ذهب؟». نعم يا فصيح! كنز أعظم من الذهب.", "ومعناها: أنا ضعيف، ولا أقدر على شيء إلا بعون الله. فإذا كان الواجب صعبًا، أو حملتُ شيئًا ثقيلًا، أقول: لا حول ولا قوة إلا بالله، وأعتمد على الله وحده."], "board": ["الإخلاص = ثلث القرآن", "لا حول ولا قوة إلا بالله = كنز"]}, {"h": "القلب: ملك الجسد", "p": ["قال ﷺ: <b>ألا وإنّ في الجسد مضغة إذا صلحت صلح الجسد كلّه، وإذا فسدت فسد الجسد كلّه، ألا وهي القلب</b>. والمضغة: قطعة لحم صغيرة.", "القلب مثل قائد السفينة: إذا كان القائد جيّدًا، سارت السفينة في الطريق الصحيح. فإذا كان قلبك نظيفًا يحبّ الله، فإنّ عينيك ولسانك ويديك تعمل الخير.", "لذلك نهتمّ بقلوبنا: نملؤها بحبّ الله، وذكره، ونطهّرها من الحسد والكره."], "board": ["القلب الصالح = جسد صالح"]}, {"h": "أجمل كلمة، ولسان نظيف", "p": ["قال ﷺ: <b>من كان آخر كلامه لا إله إلا الله دخل الجنّة</b>. فهي أفضل كلمة، ونحبّ أن نكثر منها في حياتنا كلّها، حتى تكون آخر كلامنا من الدنيا.", "وقال ﷺ: <b>ليس المؤمن بالطعّان، ولا اللعّان، ولا الفاحش، ولا البذيء</b>. المؤمن لا يعيب الناس، ولا يلعن، ولا يقول الكلام القبيح ولا الشتائم.", "قال أنوس: «لساني مثل الحديقة: أزرع فيه الكلمات الطيّبة، ولا أترك فيه الشوك»."], "board": ["لا إله إلا الله", "لا طعن ولا لعن ولا شتم"]}, {"h": "أترك ما لا يعنيني، وأجمع الحسنات بالقرآن", "p": ["قال ﷺ: <b>من حسن إسلام المرء تركه ما لا يعنيه</b>. أي: لا أتدخّل في أمور غيري التي لا تخصّني، ولا أسأل عن أسرار الناس. وهذا من كمال إسلامي.", "وقال ﷺ: <b>من قرأ حرفًا من كتاب الله فله به حسنة، والحسنة بعشر أمثالها</b>، لا أقول: «ألم» حرف، ولكن ألف حرف، ولام حرف، وميم حرف.", "هيّا نحسب مع فصيح: «ألم» ثلاثة أحرف، وكل حرف بعشر حسنات، فهي <b>30 حسنة</b>! فكم حسنة تجمع إذا قرأتَ سورة كاملة؟"], "board": ["أترك ما لا يعنيني", "حرف = حسنة × 10"]}], "summary": ["سورة الإخلاص تعدل ثلث القرآن، و«لا حول ولا قوة إلا بالله» كنز من كنوز الجنّة.", "إذا صلح القلب صلح الجسد كلّه، والمؤمن لا يطعن ولا يلعن ولا يقول القبيح.", "من حسن الإسلام ترك ما لا يعني، وبكل حرف من القرآن حسنة والحسنة بعشر أمثالها."], "islam": {"intro": "قال الله تعالى عن القلوب وذكر الله:", "text": "فإذا شعرتَ بالخوف أو الحزن، اذكر الله، فبذكره يطمئنّ قلبك.", "ayah": {"text": "ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ", "src": "سُورَةُ الرَّعۡدِ: ٢٨"}, "hadith": {"text": "لا حول ولا قوة إلا بالله كنز من كنوز الجنّة", "source": "رواه البخاري ومسلم"}}, "home": {"title": "عدّاد الحسنات العائلي", "goal": "أن يطبّق الطفل حديث الحروف والحسنات، ويحبّ قراءة القرآن مع أسرته.", "materials": ["ورقة كبيرة", "ملصقات نجوم", "مصحف"], "steps": ["اختر مع أسرتك سورة قصيرة، مثل الإخلاص أو الكوثر.", "عدّوا معًا حروف آية واحدة، ثم اضربوا العدد في عشرة لتعرفوا الحسنات.", "الصق نجمة على الورقة كلّما قرأتَ سورة كاملة.", "قل «لا حول ولا قوة إلا بالله» عشر مرّات قبل أن تبدأ واجبك المدرسي."], "parent": "الحساب هنا تقريب لتحبيب الطفل في القرآن، والأجر عند الله أعظم. شجّعوه وامدحوا اجتهاده لا عدد الحسنات فقط."}, "online": {"title": "كنوز فصيح", "intro": "أكمل الأحاديث، واحسب الحسنات، وصنّف الكلمات!", "steps": [{"type": "match", "title": "أكمل الحديث", "prompt": "اختر بداية الحديث، ثم تكملته الصحيحة.", "pairs": [["سورة الإخلاص", "تعدل ثلث القرآن"], ["لا حول ولا قوة إلا بالله", "كنز من كنوز الجنّة"], ["ألا وإنّ في الجسد مضغة", "ألا وهي القلب"], ["من حسن إسلام المرء", "تركه ما لا يعنيه"], ["من كان آخر كلامه لا إله إلا الله", "دخل الجنّة"]]}, {"type": "calc", "title": "احسب الحسنات مع فصيح", "items": [{"q": "قرأ أنوس «ألم» (3 أحرف). كم حسنة؟ (كل حرف بعشر حسنات)", "answer": 30, "unit": "حسنة", "hint": "3 × 10", "why": "ألف حرف، ولام حرف، وميم حرف: 3 × 10 = 30."}, {"q": "قرأ فصيح كلمة من 5 أحرف. كم حسنة؟", "answer": 50, "unit": "حسنة", "hint": "5 × 10", "why": "5 أحرف × 10 حسنات = 50."}]}, {"type": "sort", "title": "لسان المؤمن", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["كلام طيّب", "كلام يجب تركه"], "items": [{"t": "لا إله إلا الله", "icon": "🌟", "bin": 0, "why": "أفضل كلمة، وبها يدخل العبد الجنّة."}, {"t": "جزاك الله خيرًا", "icon": "🤲", "bin": 0, "why": "دعاء جميل لمن أحسن إليك."}, {"t": "لا حول ولا قوة إلا بالله", "icon": "💎", "bin": 0, "why": "كنز من كنوز الجنّة."}, {"t": "اللعن والشتم", "icon": "🚫", "bin": 1, "why": "ليس المؤمن باللعّان ولا البذيء."}, {"t": "عيب الناس والسخرية منهم", "icon": "🙊", "bin": 1, "why": "ليس المؤمن بالطعّان."}, {"t": "السؤال عن أسرار الناس", "icon": "🔒", "bin": 1, "why": "من حسن الإسلام ترك ما لا يعني."}]}]}, "case": {"title": "مَن أنا؟", "story": "وجد فصيح كتابين صغيرين مشهورين على رفّ أنوس، وبينهما ورقة لغز. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا إمام شافعيّ زاهد.", "من كتبي «الأربعون» التي يحفظ منها الأطفال الأحاديث.", "ومن كتبي «رياض الصالحين» الذي يقرؤه المسلمون في كل مكان."], "options": ["الحافظ ابن كثير رحمه الله", "الإمام النووي رحمه الله", "ابن تيمية رحمه الله"], "deep": "لماذا يحبّ المسلمون أن يجمعوا الأحاديث في كتب صغيرة سهلة الحفظ؟ وأيّ حديث تحبّ أن تحفظه أوّلًا؟", "reveal": "أنا الإمام النووي رحمه الله! وفي كتابي «الأربعون» حديث «إنما الأعمال بالنيات» وحديث «من حسن إسلام المرء تركه ما لا يعنيه». وفي الحلقة القادمة نتعلّم آدابنا مع الله والرسول ﷺ والوالدين والناس."}, "quiz": [{"q": "سورة الإخلاص تعدل…", "o": ["نصف القرآن", "ثلث القرآن", "ربع القرآن"], "a": 1, "why": "قال ﷺ: «إنها لتعدل ثلث القرآن»."}], "qa": [{"id": 147, "q": "أكملْ حديث: «والذي نفسي بيده!...»، واذكرْ بعضَ فوائده.", "a": "عن أبي سعيد، عن رسولِ الله ﷺ، قولُهُ عن سورةِ الإخلاص: «والذي نفسي بيده! إنها لتعدلُ ثلثَ القرآن» رواه البخاري.\n\nبعض فوائد الحديث:\n١. فضلُ سورةِ الإخلاص.\n٢. وأنها تعدلُ ثلثَ القرآن."}, {"id": 148, "q": "أكملْ حديث: «لا حولَ ولا قوةَ إلا بالله...»، واذكرْ بعضَ فوائده.", "a": "عن أبي موسى، قال رسولُ الله ﷺ: «لا حولَ ولا قوةَ إلا بالله كنزٌ من كنوزِ الجنة» رواه البخاري ومسلم.\n\nمن فوائد الحديث:\n١. فضلُ هذه الكلمة، وأنها كنزٌ من كنوزِ الجنة.\n٢. تبرُّؤُ العبدِ من حولِهِ وقوته، واعتمادُهُ على الله تعالى وحده."}, {"id": 149, "q": "أكملْ حديث: «ألا إنَّ في الجسدِ مضغةً...»، واذكرْ بعضَ فوائده.", "a": "عن النعمانِ بنِ بشيرٍ رضي الله عنهما قال: سمعتُ رسولَ الله ﷺ يقول: «ألا وإنَّ في الجسدِ مضغةً إذا صلحتْ صلحَ الجسدُ كلُّه، وإذا فسدتْ فسدَ الجسدُ كلُّه، ألا وهي القلب» رواه البخاري ومسلم.\n\nبعض فوائد الحديث:\n١. صلاحُ القلبِ فيه صلاحُ الظاهرِ والباطن.\n٢. الاهتمامُ بصلاحِ القلبِ لأنَّ به صلاحَ الإنسان."}, {"id": 150, "q": "أكملْ حديث: «من كان آخرُ كلامِهِ — من الدنيا — لا إله إلا الله...»، واذكرْ بعضَ فوائده.", "a": "عن معاذِ بنِ جبلٍ قال: قال رسولُ الله ﷺ: «من كان آخرُ كلامِهِ: لا إله إلا الله؛ دخلَ الجنة» رواه أبو داود.\n\nبعض فوائد الحديث:\n١. فضلُ \"لا إله إلا الله\"، وأنَّ العبدَ يدخلُ بها الجنة.\n٢. وفضلُ من كان آخرُ كلامِهِ من الدنيا لا إله إلا الله."}, {"id": 151, "q": "أكملْ حديث: «ليس المؤمنُ بالطعان، ولا اللعان...»، وبعضَ فوائده.", "a": "عن عبدِ اللهِ بنِ مسعودٍ قال: قال رسولُ الله ﷺ: «ليس المؤمنُ بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء» رواه الترمذي.\n\nمن فوائد الحديث:\n• النهيُ عن كلِّ كلامٍ باطلٍ وقبيح.\n• أنَّ ذلك صفةُ المؤمنِ في لسانه."}, {"id": 152, "q": "أكملْ حديث: «من حُسنِ إسلامِ المرء...»، واذكرْ بعضَ فوائده.", "a": "عن أبي هريرة قال: قال رسولُ الله ﷺ: «من حُسنِ إسلامِ المرءِ: تركُهُ ما لا يعنيه» رواه الترمذي وغيره.\n\nمن فوائد الحديث:\n١. تركُ ما لا يعني الإنسانَ من أمورِ دينِ غيرِهِ ودنياه.\n٢. أنَّ تركَ ما لا يعني من كمالِ إسلامه."}, {"id": 153, "q": "أكملْ حديث: «من قرأ حرفًا من كتابِ الله...»، واذكرْ بعضَ فوائده.", "a": "عن عبدِ اللهِ بنِ مسعودٍ: أنَّ النبيَّ ﷺ قال: «من قرأ حرفًا من كتابِ الله فله به حسنة، والحسنةُ بعشرِ أمثالها، لا أقول: ألم حرف، ولكن ألفٌ حرف، ولامٌ حرف، وميمٌ حرف» رواه الترمذي.\n\nبعض فوائد الحديث:\n١. فضلُ تلاوةِ القرآن.\n٢. وأنَّ بكلِّ حرفٍ تقرؤُهُ لك به حسنات."}], "dyk": ["الشُّهُبُ التي نراها ليلاً هي صخورٌ صغيرةٌ تحترقُ عند دخولِها غلافَ الأرضِ الجوي."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "عِنْدِي سِرٌّ… كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ! لَكِنْ أَوَّلًا: جَوَابُ اللُّغْزِ الْمَاضِي هُوَ الْإِمَامُ الْبُخَارِيُّ رَحِمَهُ اللَّهُ، صَاحِبُ «صَحِيحِ الْبُخَارِيِّ»."}, {"s": "anos", "t": "هَيَّا نَحْفَظُ أَحَادِيثَ جَدِيدَةً. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "مَاذَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ سُورَةِ الْإِخْلَاصِ؟"}, {"s": "anos", "t": "قَالَ: «وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ». رَوَاهُ الْبُخَارِيُّ. فَمَا أَعْظَمَ فَضْلَهَا!"}, {"s": "fasih", "t": "وَالْكَنْزُ؟ مَا هُوَ الْكَنْزُ؟"}, {"s": "anos", "t": "قَالَ النَّبِيُّ: «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ». رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ. نَقُولُهَا فَنَعْتَمِدُ عَلَى اللَّهِ وَحْدَهُ، لَا عَلَى قُوَّتِنَا."}, {"s": "fasih", "t": "كَنْزٌ أَحْمِلُهُ فِي كُلِّ مَكَانٍ! أَكْمِلْ: «أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً…»"}, {"s": "anos", "t": "«إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ». فَنَهْتَمُّ بِصَلَاحِ قُلُوبِنَا."}, {"s": "fasih", "t": "وَكَيْفَ يَطْمَئِنُّ الْقَلْبُ؟ اسْمَعُوا الْجَوَابَ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "13:28", "t": "ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ"}, {"s": "anos", "t": "فَإِذَا شَعَرْتَ بِالْخَوْفِ أَوِ الْحُزْنِ، اذْكُرِ اللَّهَ، فَبِذِكْرِهِ يَطْمَئِنُّ قَلْبُكَ."}, {"s": "fasih", "t": "أَكْمِلْ: «مَنْ كَانَ آخِرُ كَلَامِهِ لَا إِلَهَ إِلَّا اللَّهُ…»"}, {"s": "anos", "t": "«دَخَلَ الْجَنَّةَ». رَوَاهُ أَبُو دَاوُدَ. فَمَا أَعْظَمَ فَضْلَ كَلِمَةِ التَّوْحِيدِ!"}, {"s": "fasih", "t": "«لَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ…»"}, {"s": "anos", "t": "«وَلَا اللَّعَّانِ، وَلَا الْفَاحِشِ، وَلَا الْبَذِيءِ». رَوَاهُ التِّرْمِذِيُّ. فَالْمُؤْمِنُ يَحْفَظُ لِسَانَهُ مِنْ كُلِّ كَلَامٍ قَبِيحٍ."}, {"s": "fasih", "t": "«مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ…»"}, {"s": "anos", "t": "«تَرْكُهُ مَا لَا يَعْنِيهِ». رَوَاهُ التِّرْمِذِيُّ. فَلَا نَتَدَخَّلُ فِي مَا لَا يَخُصُّنَا."}, {"s": "fasih", "t": "وَالْأَخِيرُ: «مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ…»"}, {"s": "anos", "t": "«فَلَهُ بِهِ حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لَا أَقُولُ: أَلِفْ لَامْ مِيمْ حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ، وَلَامٌ حَرْفٌ، وَمِيمٌ حَرْفٌ». رَوَاهُ التِّرْمِذِيُّ."}, {"s": "fasih", "t": "يَا سَلَامُ! إِذَنْ كُلُّ حَرْفٍ أَقْرَؤُهُ يُعْطِينِي حَسَنَاتٍ! سَأَقْرَأُ الْقُرْآنَ كُلَّ يَوْمٍ يَا أَنُوس، وَأَعُدُّ الْحُرُوفَ… لَا لَا، لَنْ أَسْتَطِيعَ عَدَّهَا كُلَّهَا!"}, {"s": "anos", "t": "وَلَا يَهُمُّ أَنْ تَعُدَّهَا يَا فَصِيح، فَاللَّهُ لَا يُضَيِّعُ حَرْفًا وَاحِدًا. الْمُهِمُّ أَنْ نَقْرَأَ بِإِخْلَاصٍ، وَنَعْمَلَ بِمَا نَقْرَأُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الشُّهُبُ الَّتِي نَرَاهَا لَيْلًا صُخُورٌ صَغِيرَةٌ تَحْتَرِقُ عِنْدَ دُخُولِهَا غِلَافَ الْأَرْضِ الْجَوِّيَّ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: صُنْدُوقُ الْكَنْزِ. اسْحَبُوا بِطَاقَةً، وَاقْرَؤُوا بِدَايَةَ حَدِيثٍ، وَيُكْمِلُهُ الْجَمِيعُ مَعَ فَائِدَةٍ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: صندوق الكنز"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! صَدِيقُكَ يَتَكَلَّمُ مَعَ الْمُعَلِّمِ وَحْدَهُ. أ: تَقْتَرِبُ لِتَسْمَعَ. ب: تَسْأَلُهُ بِإِلْحَاحٍ حَتَّى يُخْبِرَكَ. ج: تَتْرُكُهُ، فَهَذَا لَا يَعْنِيكَ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: سرّ صديقك"}, {"s": "anos", "t": "أ وَب تَدَخُّلٌ فِي مَا لَا يَعْنِينَا. أَمَّا ج فَهُوَ الْأَفْضَلُ: «مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: سُورَةُ الْإِخْلَاصِ تَعْدِلُ…؟ فَكِّرُوا…"}, {"s": "anos", "t": "ثُلُثَ الْقُرْآنِ!"}, {"s": "fasih", "t": "وَكَمْ حَسَنَةً لِمَنْ قَرَأَ حَرْفًا؟ فَكِّرُوا…"}, {"s": "anos", "t": "حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا!"}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: إِمَامٌ شَافِعِيٌّ زَاهِدٌ، مِنْ كُتُبِي «الْأَرْبَعُونَ» الَّتِي يَحْفَظُ مِنْهَا الْأَطْفَالُ، وَ«رِيَاضُ الصَّالِحِينَ». ابْنُ كَثِيرٍ، أَمِ النَّوَوِيُّ، أَمِ ابْنُ تَيْمِيَّةَ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ جَرِّبُوا «عَدَّادَ الْحَسَنَاتِ الْعَائِلِيَّ» وَأَنْتُمْ تَقْرَؤُونَ الْقُرْآنَ، وَالْعَبُوا «كُنُوزَ فَصِيح» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 19, "title": "آدابي مع الله والرسول والوالدين والناس", "season": 2, "goals": ["adab"], "hook": "أهلًا يا أصدقاء! فصيح يلبس اليوم ربطة عنق صغيرة ويقول: «أنا ببغاء مؤدّب… مؤدّب جدًّا!». هل تعرف مع مَن نتأدّب؟ مع الله، والرسول ﷺ، والوالدين، والناس كلّهم! هيّا نتعلّم.", "sections": [{"h": "أدبي مع الله", "p": ["أعظم أدب هو الأدب مع الله. وكيف يكون؟ أن <b>أعظّمه</b>، فهو الذي تكون الأرض جميعًا قبضته يوم القيامة، والسماوات مطويّات بيمينه.", "وأن <b>أعبده وحده</b>، و<b>أطيعه</b>، و<b>أترك معصيته</b>، و<b>أشكره وأحمده</b> على نِعَمه التي لا تُحصى، و<b>أصبر</b> على أقداره.", "قال أنوس: «إذا أكلتُ قلت: الحمد لله. وإذا مرضتُ صبرتُ ودعوت الله. هكذا أتأدّب مع ربّي»."], "board": ["أعظّم الله", "أعبده وأطيعه", "أشكره وأصبر"]}, {"h": "أدبي مع الرسول ﷺ", "p": ["نتأدّب مع نبيّنا ﷺ بأن <b>نتّبعه ونقتدي به</b>، فهو أسوتنا الحسنة. و<b>نطيعه</b> ونترك معصيته، فمن أطاع الرسول فقد أطاع الله.", "و<b>نصدّقه</b> في كل ما أخبر، لأنه لا ينطق عن الهوى. و<b>لا نبتدع</b> في الدين شيئًا لم يعلّمنا إيّاه.", "و<b>نحبّه</b> أكثر من أنفسنا ومن كل الناس، و<b>نعظّمه</b> وننصر سنّته."], "board": ["أتّبعه", "أصدّقه", "أحبّه أكثر من نفسي"]}, {"h": "أدبي مع والديّ وأقاربي", "p": ["أطيع والديّ في غير معصية، وأخدمهما، وأساعدهما، وأقضي حوائجهما، وأدعو لهما. ولا أقول لهما «أفّ»، وهي أقلّ كلمة!", "أبتسم في وجههما ولا أعبس، ولا أرفع صوتي فوق صوتهما، ولا أقاطعهما، ولا أناديهما باسمهما بل أقول: «أبي، أمّي». وأستأذن قبل الدخول عليهما، وأقبّل يدهما ورأسهما.", "وأصل <b>رحمي</b>: أزور أقاربي، مثل العمّ والخال والجدّة، وأتّصل بهم، وأسأل عن أحوالهم، وأساعدهم. وفي الحديث: <b>لا يدخل الجنّة قاطع رحم</b>."], "board": ["لا أقول: أفّ", "أبي، أمّي", "أصل رحمي"]}, {"h": "أدبي مع أصدقائي وجيراني وضيوفي", "p": ["أصاحب <b>الأخيار</b> وأترك الأشرار. وأسلّم على أصدقائي وأصافحهم، وأزورهم إذا مرضوا، وأجيب دعوتهم، وأنصحهم، وأنصر المظلوم، وأمنع أخي من الظلم. ولا أشتمه ولا أغتابه ولا أحسده ولا أتجسّس عليه.", "ومع <b>جاري</b>: أحسن إليه، وأهنّئه في فرحه، وأزوره إذا مرض، وأهديه من طعامنا، ولا أزعجه بصوت مرتفع.", "وإذا زرتُ أحدًا أستأذن، ولا أتأخّر. وإذا جاءنا <b>ضيف</b> أرحّب به بوجه مبتسم، وأُجلسه في أحسن مكان، وأُكرمه بالطعام والشراب."], "board": ["أصاحب الأخيار", "أحسن إلى جاري", "أكرم ضيفي"]}, {"h": "أدبي مع المريض ومع العلم", "p": ["إذا أحسستُ بألم، أضع يدي اليمنى على مكانه، وأقول: «بسم الله» ثلاث مرّات، و«أعوذ بعزّة الله وقدرته من شرّ ما أجد وأحاذر» سبع مرّات. وأصبر، فالمرض يُذهب الله به الخطايا.", "وأزور أخي المريض ولا أطيل الجلوس عنده، وأدعو له: «أسأل الله العظيم ربّ العرش العظيم أن يشفيك» سبع مرّات.", "وفي <b>طلب العلم</b>: أخلص نيّتي لله، وأعمل بما أتعلّم، وأحترم معلّمي، وأجلس أمامه بأدب، وأنصت ولا أقاطعه، وأسأل بأدب، ولا أناديه باسمه."], "board": ["أدعو للمريض", "أحترم معلّمي", "أعمل بما أتعلّم"]}], "summary": ["أتأدّب مع الله بتعظيمه وعبادته وطاعته وشكره، ومع الرسول ﷺ باتّباعه ومحبّته.", "أبرّ والديّ: لا أقول لهما أفّ، وأخدمهما وأبتسم لهما، وأصل رحمي.", "أحسن إلى أصدقائي وجيراني وضيوفي، وأزور المريض، وأحترم معلّمي."], "islam": {"intro": "قال الله تعالى يأمرنا بعبادته وحده وبالإحسان إلى الوالدين:", "text": "فخدمة أمّك وأبيك عبادة عظيمة، وابتسامتك لهما تُرضي الله.", "ayah": {"text": "۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا", "src": "سُورَةُ الإِسۡرَاءِ: ٢٣"}, "hadith": {"text": "ألك والدان؟ قال: نعم. قال: ففيهما فجاهد", "source": "رواه الترمذي"}}, "home": {"title": "أسبوع البرّ", "goal": "أن يطبّق الطفل آداب البرّ مع والديه وأقاربه كل يوم لمدّة أسبوع.", "materials": ["جدول أسبوعي", "ملصقات قلوب"], "steps": ["اكتب في الجدول سبعة أعمال برّ، مثل: تقبيل يد أمّي، مساعدة أبي، الدعاء لهما.", "كل يوم، افعل عملًا واحدًا على الأقل، والصق قلبًا بجانبه.", "اتّصل بقريب واحد في الأسبوع، مثل جدّتك أو خالك، واسأله عن حاله.", "ادعُ لوالديك بعد كل صلاة: «ربّ ارحمهما كما ربّياني صغيرًا»."], "parent": "لاحظوا أعمال طفلكم واشكروه عليها بكلمة طيّبة، وساعدوه في الاتّصال بالأقارب."}, "online": {"title": "مدينة الأدب", "intro": "تجوّل مع فصيح في مدينة الأدب، وساعده على اختيار الأدب الصحيح!", "steps": [{"type": "match", "title": "صِل الشخص بأدبه", "prompt": "اختر الشخص، ثم الأدب المناسب معه.", "pairs": [["الوالدان", "لا أقول لهما أفّ"], ["الأقارب", "أزورهم وأتّصل بهم"], ["الجار", "أهديه من طعامنا"], ["الضيف", "أُجلسه في أحسن مكان"], ["المريض", "أدعو له بالشفاء"], ["المعلّم", "أنصت ولا أقاطعه"]]}, {"type": "decision", "title": "قرار أنوس", "scenario": "الجار مريض، وأنوس يريد أن يلعب الكرة بقرب بيته بصوت عالٍ. ماذا يفعل؟", "options": [{"t": "يلعب ويصرخ كما يريد", "result": "هذا يزعج الجار المريض، ومن آداب الجار ألّا نزعجه."}, {"t": "يلعب بعيدًا بهدوء، ويزور جاره مع أبيه ويدعو له", "result": "رائع! أحسن إلى جاره، وزاره، ودعا له بالشفاء.", "best": true}, {"t": "يطرق باب الجار كثيرًا ويهرب", "result": "هذا أذى للجار، والمسلم لا يؤذي جاره."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "من الأدب مع الرسول ﷺ:", "o": ["أن أبتدع في الدين", "أن أتّبعه وأصدّقه", "أن أنساه"], "a": 1}, {"q": "صديقك يظلم غيره. كيف تنصره؟", "o": ["أساعده في الظلم", "أضحك معه", "أمنعه من الظلم"], "a": 2}, {"q": "قبل أن أزور أحدًا…", "o": ["أطلب الإذن والموعد", "أدخل فجأة", "أبقى حتى الليل"], "a": 0}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز تحت سجّادة جدّة أنوس. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["لم أرَ النبيّ ﷺ، لكنه ذكرني وأوصى بي.", "بررتُ أمّي، فلم أفارقها.", "كنتُ خير التابعين."], "options": ["الحسن البصري رحمه الله", "عمر بن عبد العزيز رحمه الله", "أويس القرني رحمه الله"], "deep": "ما الذي جعل أويسًا عظيمًا مع أنه لم يرَ النبيّ ﷺ؟ وكيف تبرّ أمّك اليوم؟", "reveal": "أنا أويس القرني رحمه الله! أخبر النبيّ ﷺ عمرَ بن الخطاب عنّي، وأمره إن لقيني أن يطلب منّي أن أستغفر له. وفي الحلقة القادمة نتعلّم آداب يومنا: من المجلس إلى المسجد."}, "quiz": [{"q": "أيّ هذه من الأدب مع الله؟", "o": ["شكره على نِعَمه", "نسيان ذكره", "معصيته"], "a": 0, "why": "قال تعالى: «واشكروا نعمت الله إن كنتم إيّاه تعبدون»."}], "qa": [{"id": 154, "q": "كيف يكونُ الأدبُ مع الله تعالى؟", "a": "١. تعظيمُهُ سبحانه وتعالى. قال تعالى: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾ [الزمر: ٦٧].\n٢. عبادتُهُ وحدَهُ لا شريكَ له. قال سبحانه: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ﴾ [البينة: ٥].\n٣. طاعتُه. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ﴾ [محمد: ٣٣].\n٤. تركُ معصيتِه. قال سبحانه: ﴿وَمَن يَعْصِ اللَّهَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا وَلَهُ عَذَابٌ مُّهِينٌ﴾ [النساء: ١٤].\n٥. شكرُهُ وحمدُهُ على فضلِهِ ونعمِهِ التي لا تُحصى. قال تعالى: ﴿وَاشْكُرُوا نِعْمَتَ اللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ﴾ [النحل: ١١٤].\n٦. والصبرُ على أقدارِه. قال سبحانه: ﴿وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ [الأنفال: ٤٦]."}, {"id": 155, "q": "كيف يكونُ الأدبُ مع الرسولِ ﷺ؟", "a": "١. اتباعُهُ والاقتداءُ به. قال تعالى: ﴿لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ [الأحزاب: ٢١].\n٢. طاعتُه.\n٣. تركُ معصيتِه. قال تعالى: ﴿مَّن يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ﴾ [النساء: ٨٠].\n٤. تصديقُهُ فيما أخبر. قال تعالى: ﴿وَمَا يَنطِقُ عَنِ الْهَوَىٰ ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ﴾ [النجم: ٣–٤].\n٥. عدمُ الابتداعِ في الزيادةِ على سنته. قال ﷺ: «من أحدثَ في أمرِنا هذا ما ليس فيه فهو ردّ» متفق عليه.\n٦. محبتُهُ أكثرَ من النفسِ ومن كلِّ الناس.\n٧. تعظيمُهُ ونصرتُهُ ونصرةُ سنته. قال سبحانه: ﴿لِّتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ﴾ [الفتح: ٩]."}, {"id": 156, "q": "كيف يكونُ الأدبُ مع الوالدين؟", "a": "١. طاعةُ الوالدينِ في غيرِ معصية.\n٢. خدمةُ الوالدين.\n٣. مساعدةُ الوالدين.\n٤. قضاءُ حوائجِ الوالدين.\n٥. الدعاءُ للوالدين.\n٦. التأدبُ معهم في القول؛ فلا يجوزُ قولُ: \"أفٍّ\"، وهي أقلُّ الأقوال.\n٧. الابتسامُ في وجهِ الوالدينِ ولا أعبس.\n٨. لا أرفعُ صوتي فوقَ صوتِ الوالدين، وأُصغي إليهما، ولا أقاطعُهما بالكلام، ولا أناديهما باسمِهما، بل أقول: \"أبي\"، \"أمي\".\n٩. أستأذنُ قبلَ الدخولِ على أبي وأمي وهما في الغرفة.\n١٠. تقبيلُ يدِ ورأسِ الوالدين.\nقال تعالى: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا... وَقُل لَّهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ﴾ [الإسراء: ٢٣–٢٤]. وفي الحديث: جاء رجلٌ إلى النبيِّ ﷺ يستأذنُهُ في الجهاد، فقال: «ألك والدان؟» قال: نعم. قال: «ففيهما فجاهد» رواه الترمذي."}, {"id": 157, "q": "كيف أصِلُ الرحم؟", "a": "١. زيارةُ الأقاربِ من الأخِ والأخت، والعمِّ والعمة، والخالِ والخالةِ وبقيةِ الأقارب.\n٢. الإحسانُ إليهم بالقولِ والفعلِ ومساعدتُهم.\n٣. ومنها الاتصالُ بهم وسؤالُهم عن أحوالهم.\nقال تعالى: ﴿فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ﴾ [محمد: ٢٢]. وفي الحديث: «لا يدخلُ الجنةَ قاطعُ رحم» رواه مسلم."}, {"id": 158, "q": "كيف أكونُ مع إخواني وأصدقائي؟", "a": "١. أحبُّ وأصاحبُ الأخيار.\n٢. أتجنبُ وأتركُ مصاحبةَ الأشرار. في الحديث: «لا تصاحبْ إلا مؤمنًا، ولا يأكلْ طعامَكَ إلا تقي» رواه الترمذي وأبو داود.\n٣. أسلِّمُ على إخواني وأصافحُهم. في الحديث: «ما من مسلمَينِ يلتقيانِ فيتصافحان، إلا غُفِرَ لهما قبلَ أن يفترقا» رواه أبو داود والترمذي.\n٤. أعودُهم إذا مرضوا وأدعو لهم بالشفاء.\n٥. وأُشمِّتُ العاطس.\n٦. أجيبُ دعوتَهُ إذا دعاني. في الحديث: «حقُّ المسلمِ على المسلمِ خمس: ردُّ السلام، وعيادةُ المريض، واتباعُ الجنائز، وإجابةُ الدعوة، وتشميتُ العاطس» متفق عليه.\n٧. أقدِّمُ له النصيحة.\n٨. أنصرُهُ إذا ظُلِم، وأمنعُهُ عن الظلم. قال ﷺ: «انصرْ أخاكَ ظالمًا أو مظلومًا»... قال: «تحجزُهُ — أو تمنعُهُ — من الظلم؛ فإنَّ ذلك نصرُه» رواه البخاري.\n٩. أحبُّ لأخي المسلمِ ما أحبُّ لنفسي.\n١٠. أساعدُهُ إذا احتاج. في الحديث: «واللهُ في عونِ العبدِ ما كان العبدُ في عونِ أخيه» رواه مسلم.\n١١. لا أمسُّهُ بأذًى، بقولٍ أو فعل. في الحديث: «المسلمُ من سلِمَ المسلمونَ من لسانِهِ ويدِه» متفق عليه.\n١٢. أحفظُ سرَّه.\n١٣. لا أشتمُهُ، ولا أغتابُه، ولا أحتقرُه، ولا أحسدُه، ولا أتجسسُ عليه، ولا أغشُّه. في الحديث: «المسلمُ أخو المسلمِ لا يظلمُه، ولا يخذلُه، ولا يحقرُه...» رواه البخاري ومسلم."}, {"id": 159, "q": "ما هي آدابُ الجار؟", "a": "١. أحسِنُ للجارِ بالقولِ والفعل، وأساعدُهُ إذا احتاج.\n٢. أهنِّئُهُ إذا فرِحَ بالعيدِ أو الزواجِ أو غيرها.\n٣. أعودُهُ إذا مرِض وأعزِّيهِ إذا أُصيب.\n٤. أقدِّمُ له مما أصنعُ من الطعامِ ما أمكن.\n٥. لا ألحقُ به أذًى بقولٍ أو فعل.\n٦. لا أزعجُهُ بصوتٍ مرتفعٍ أو أتجسسُ عليه، وأصبرُ عليه.\nقال تعالى: ﴿وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا... وَالْجَارِ ذِي الْقُرْبَىٰ وَالْجَارِ الْجُنُبِ وَالصَّاحِبِ بِالْجَنبِ﴾ [النساء: ٣٦]. وقال ﷺ: «يا أبا ذر، إذا طبختَ مرقةً فأكثِرْ ماءَها وتعاهدْ جيرانك» رواه مسلم. وفي الحديث: «من كان يؤمنُ بالله واليومِ الآخرِ فلا يؤذِ جاره» متفق عليه."}, {"id": 160, "q": "ما هي آدابُ الضيافةِ والضيف؟", "a": "١. أجيبُ من دعاني إلى ضيافته.\n٢. إذا أردتُ زيارةَ أحدٍ أطلبُ الإذنَ والموعد.\n٣. أستأذنُ قبلَ الدخول.\n٤. لا أتأخرُ في الزيارة.\n٥. أغضُّ البصرَ عن أهلِ البيت.\n٦. أرحِّبُ بالضيفِ وأستقبلُهُ أحسنَ استقبال، ببشاشةِ وجه، وأحسنِ عباراتِ الترحيب.\n٧. أُجلِسُ الضيفَ في أحسنِ مكان.\n٨. أُكرِمُهُ بالضيافةِ من طعامٍ وشراب.\nقال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَىٰ أَهْلِهَا﴾ [النور: ٢٧]. وقال ﷺ: «من كان يؤمنُ بالله واليومِ الآخرِ فليكرمْ ضيفه» متفق عليه."}, {"id": 161, "q": "ما آدابُ المرضِ وزيارةِ المرضى؟", "a": "١. عندما أحسُّ بألمٍ؛ أضعُ يدي اليمنى على موضعه، وأقول: \"بسم الله\" ثلاثَ مرات، وأقول: \"أعوذُ بعزةِ الله وقدرتِهِ من شرِّ ما أجدُ وأحاذر\" سبعَ مرات.\n٢. أرضى بما قدَّرَهُ الله وأصبر. في الحديث عن أمِّ العلاء: قال ﷺ: «أبشري يا أمَّ العلاء؛ فإنَّ مرضَ المسلمِ يُذهِبُ اللهُ به خطاياه كما تُذهِبُ النارُ خبثَ الذهبِ والفضة» رواه أبو داود.\n٣. أسارعُ إلى زيارةِ أخي المريض، وأدعو له، ولا أُطيلُ عندَهُ الجلوس.\n٤. أرقبُهُ من دونِ أن يطلبَ مني.\n٥. أوصيهِ بالصبرِ والدعاء، والصلاةِ والطهارةِ على ما يستطيع.\n٦. الدعاءُ للمريض: \"أسألُ اللهَ العظيمَ ربَّ العرشِ العظيمِ أن يشفيك\" سبعَ مرات."}, {"id": 162, "q": "ما آدابُ طلبِ العلم؟", "a": "١. إخلاصُ النيةِ لله عزَّ وجلَّ. في الحديث: «من تعلَّمَ العلمَ ليباهيَ به العلماء، ويماريَ به السفهاء، ويصرفَ به وجوهَ الناسِ إليه أدخلَهُ اللهُ جهنم» رواه ابن ماجه.\n٢. أعملُ بالعلمِ الذي أتعلمُه. في الحديث: «لا تزولُ قدما عبدٍ يومَ القيامةِ حتى يُسألَ عن أربع... وعن علمِهِ ماذا عمِلَ فيه» رواه الترمذي والدارمي.\n٣. أحترمُ المعلمَ وأوقِّرُهُ في حضورِهِ وغيابه.\n٤. أجلسُ أمامَهُ بأدب.\n٥. أنصتُ إليه جيدًا ولا أقاطعُهُ في درسه.\n٦. أتأدبُ بطرحِ السؤال.\n٧. لا أناديهِ باسمه.\nفي الحديث: «إنَّ من إجلالِ اللهِ إكرامَ ذي الشيبةِ المسلم، وحاملِ القرآن» رواه أبو داود."}], "dyk": ["قوسُ قزحٍ يظهرُ حين تنكسرُ أشعةُ الشمسِ في قطراتِ المطرِ فتنقسمُ إلى سبعةِ ألوان."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "أَنَا بَبَّغَاءٌ مُؤَدَّبٌ… مُؤَدَّبٌ جِدًّا! وَجَوَابُ اللُّغْزِ الْمَاضِي: الْإِمَامُ النَّوَوِيُّ رَحِمَهُ اللَّهُ، صَاحِبُ «الْأَرْبَعِينَ»."}, {"s": "anos", "t": "الْيَوْمَ نَتَعَلَّمُ الْآدَابَ. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "كَيْفَ يَكُونُ الْأَدَبُ مَعَ اللَّهِ تَعَالَى؟"}, {"s": "anos", "t": "نُعَظِّمُهُ، وَنَعْبُدُهُ وَحْدَهُ، وَنُطِيعُهُ، وَنَتْرُكُ مَعْصِيَتَهُ، وَنَشْكُرُهُ عَلَى نِعَمِهِ الَّتِي لَا تُحْصَى، وَنَصْبِرُ عَلَى أَقْدَارِهِ، فَاللَّهُ مَعَ الصَّابِرِينَ."}, {"s": "fasih", "t": "وَمَعَ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟"}, {"s": "anos", "t": "نَتَّبِعُهُ وَنَقْتَدِي بِهِ، وَنُطِيعُهُ، وَنُصَدِّقُهُ فِي مَا أَخْبَرَ، وَلَا نَبْتَدِعُ فِي سُنَّتِهِ، وَنُحِبُّهُ أَكْثَرَ مِنْ أَنْفُسِنَا، وَنَنْصُرُ سُنَّتَهُ."}, {"s": "fasih", "t": "وَمَعَ الْوَالِدَيْنِ؟ اسْمَعُوا الْآيَةَ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "17:23", "t": "۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا"}, {"s": "anos", "t": "نُطِيعُهُمَا فِي غَيْرِ مَعْصِيَةٍ، وَنَخْدُمُهُمَا وَنَدْعُو لَهُمَا، وَلَا نَقُولُ أُفٍّ، وَلَا نَرْفَعُ أَصْوَاتَنَا، وَنَقُولُ: أَبِي، أُمِّي، وَنَسْتَأْذِنُ قَبْلَ الدُّخُولِ عَلَيْهِمَا."}, {"s": "fasih", "t": "وَجَاءَ رَجُلٌ يَسْتَأْذِنُ النَّبِيَّ فِي الْجِهَادِ، فَسَأَلَهُ: «أَلَكَ وَالِدَانِ؟» قَالَ: نَعَمْ. قَالَ: «فَفِيهِمَا فَجَاهِدْ». رَوَاهُ التِّرْمِذِيُّ."}, {"s": "anos", "t": "فَخِدْمَةُ وَالِدَيْكَ عِبَادَةٌ عَظِيمَةٌ!"}, {"s": "fasih", "t": "كَيْفَ أَصِلُ رَحِمِي؟"}, {"s": "anos", "t": "أَزُورُ أَقَارِبِي، وَأُحْسِنُ إِلَيْهِمْ وَأُسَاعِدُهُمْ، وَأَتَّصِلُ بِهِمْ وَأَسْأَلُ عَنْ أَحْوَالِهِمْ. وَفِي الْحَدِيثِ: «لَا يَدْخُلُ الْجَنَّةَ قَاطِعُ رَحِمٍ». رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "وَكَيْفَ أَكُونُ مَعَ إِخْوَانِي وَأَصْدِقَائِي؟"}, {"s": "anos", "t": "أُصَاحِبُ الْأَخْيَارَ، وَأُسَلِّمُ وَأُصَافِحُ، وَأَنْصَحُ، وَأَحْفَظُ السِّرَّ، وَلَا أُؤْذِي وَلَا أَغْتَابُ. فَالْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ."}, {"s": "fasih", "t": "وَآدَابُ الْجَارِ؟"}, {"s": "anos", "t": "أُحْسِنُ إِلَيْهِ، وَأُهَنِّئُهُ، وَأَعُودُهُ، وَأُهْدِيهِ مِنْ طَعَامِنَا، وَلَا أُزْعِجُهُ. قَالَ النَّبِيُّ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِ جَارَهُ»."}, {"s": "fasih", "t": "وَآدَابُ الضِّيَافَةِ؟"}, {"s": "anos", "t": "أُجِيبُ الدَّعْوَةَ، وَأَسْتَأْذِنُ، وَأَغُضُّ بَصَرِي، وَأُرَحِّبُ بِالضَّيْفِ بِوَجْهٍ بَشُوشٍ وَأُكْرِمُهُ، فَـ«مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ»."}, {"s": "fasih", "t": "وَإِذَا مَرِضْتُ؟ وَإِذَا زُرْتُ مَرِيضًا؟"}, {"s": "anos", "t": "أَضَعُ يَدِي عَلَى مَوْضِعِ الْأَلَمِ، وَأَقُولُ: بِسْمِ اللَّهِ ثَلَاثًا، وَأَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ سَبْعًا. وَأَزُورُ الْمَرِيضَ وَأَدْعُو لَهُ، وَلَا أُطِيلُ الْجُلُوسَ."}, {"s": "fasih", "t": "وَآدَابُ طَلَبِ الْعِلْمِ؟"}, {"s": "anos", "t": "أُخْلِصُ النِّيَّةَ لِلَّهِ، وَأَعْمَلُ بِمَا أَتَعَلَّمُ، وَأَحْتَرِمُ مُعَلِّمِي، وَأُنْصِتُ وَلَا أُقَاطِعُ، وَلَا أُنَادِيهِ بِاسْمِهِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ قَوْسُ قُزَحٍ يَظْهَرُ حِينَ تَنْكَسِرُ أَشِعَّةُ الشَّمْسِ فِي قَطَرَاتِ الْمَطَرِ، فَتَنْقَسِمُ إِلَى سَبْعَةِ أَلْوَانٍ!"}, {"s": "anos", "t": "نَشَاطُنَا: نَشِيدُ الْأَدَبِ الْجَمِيلِ. نَرْفَعُ صُورَةً، وَنَقُولُ أَدَبًا مَعَ صَاحِبِهَا. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد الأدب الجميل"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! تَلْعَبُ لُعْبَةً تُحِبُّهَا، وَأُمُّكَ تُنَادِيكَ. أ: تَقُولُ أُفٍّ، لَحْظَةً! ب: تَقُولُ نَعَمْ يَا أُمِّي، وَتُسَاعِدُهَا بِابْتِسَامَةٍ. ج: تَذْهَبُ عَابِسًا. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: أمّي تناديني"}, {"s": "anos", "t": "أ فِيهَا كَلِمَةُ أُفٍّ، وَج فِيهَا عُبُوسٌ. أَمَّا ب فَهِيَ الْبِرُّ الْجَمِيلُ!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَا أَقَلُّ كَلِمَةٍ لَا يَجُوزُ أَنْ أَقُولَهَا لِوَالِدَيَّ؟ فَكِّرُوا…"}, {"s": "anos", "t": "أُفٍّ! وَكَيْفَ أُنَادِي مُعَلِّمِي؟ فَكِّرُوا… بِأَدَبٍ، لَا بِاسْمِهِ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: لَمْ أَرَ النَّبِيَّ، لَكِنَّهُ ذَكَرَنِي، بَرَرْتُ أُمِّي فَلَمْ أُفَارِقْهَا، وَكُنْتُ خَيْرَ التَّابِعِينَ. الْحَسَنُ الْبَصْرِيُّ، أَمْ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ، أَمْ أُوَيْسٌ الْقَرَنِيُّ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ عِيشُوا «أُسْبُوعَ الْبِرِّ»، وَتَجَوَّلُوا فِي «مَدِينَةِ الْأَدَبِ» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 20, "title": "آداب يومي: من المجلس إلى المسجد", "season": 2, "goals": ["adab"], "hook": "أهلًا يا أصدقاء! اليوم يوم خاصّ: إنها «مسابقة أنوس»! فصيح يصفّق بجناحيه: «يمين… يسار… يمين… يسار! مَن يعرف أيّ قدم يقدّم؟». من الصباح إلى المساء، لكل شيء أدب جميل. هيّا نتعلّم ثم نتسابق!", "sections": [{"h": "في المجلس: أسلّم وأفسح وأختم بالدعاء", "p": ["إذا دخلتُ مجلسًا <b>أسلّم</b> على أهله، وأجلس حيث ينتهي المجلس، ولا أُقيم أحدًا من مكانه، ولا أجلس بين اثنين إلا بإذنهما.", "و<b>أفسح</b> المكان ليجلس غيري، ولا أقاطع الحديث. وإذا أردتُ الانصراف أستأذن وأسلّم.", "وعندما ينتهي المجلس أقول دعاء <b>كفّارة المجلس</b>: «سبحانك اللهمّ وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك»."], "board": ["أسلّم", "أفسح لغيري", "دعاء كفّارة المجلس"]}, {"h": "في النوم: مبكّرًا، وعلى اليمين", "p": ["<b>أنام مبكّرًا</b>، فقد كان النبيّ ﷺ يكره النوم قبل العشاء والحديث بعدها. وأنام <b>على طهارة</b>، ولا أنام على بطني.", "أنفض فراشي، ثم أنام على <b>جنبي الأيمن</b>، وأضع يدي اليمنى تحت خدّي الأيمن.", "وأقرأ أذكار النوم: آية الكرسي، والإخلاص، والمعوّذتين ثلاث مرّات، وأقول: «باسمك اللهمّ أموت وأحيا»."], "board": ["أنام مبكّرًا", "على جنبي الأيمن", "أذكار النوم"]}, {"h": "على المائدة وفي اللباس", "p": ["أنوي بطعامي أن أتقوّى على طاعة الله، وأغسل يديّ، وأقول: <b>بسم الله</b>، وآكل <b>بيميني</b> وممّا يليني. وإذا نسيتُ قلت: «بسم الله أوّله وآخره».", "لا أعيب الطعام، ولا آكل كثيرًا، ولا أنفخ فيه، وآكل مع أسرتي، ولا أبدأ قبل من هو أكبر منّي. وأشرب <b>جالسًا</b> على ثلاث دفعات، ولا أتنفّس في الإناء، وأحمد الله عندما أنتهي.", "وفي <b>اللباس</b>: أبدأ باليمين وأحمد الله، ولا أطيل الثوب تحت الكعبين، ولا يلبس الأولاد لبس البنات ولا البنات لبس الأولاد، ولا أتشبّه بالكافرين، وأسمّي عند خلع ملابسي، وألبس الحذاء باليمنى أوّلًا وأخلعه باليسرى."], "board": ["بسم الله", "آكل بيميني", "أشرب جالسًا"]}, {"h": "في السيّارة والطريق", "p": ["إذا ركبتُ أقول: «بسم الله، الحمد لله، <b>سبحان الذي سخّر لنا هذا وما كنّا له مقرنين، وإنّا إلى ربّنا لمنقلبون</b>». وإذا مررتُ بمسلم سلّمت عليه.", "وفي <b>الطريق</b>: أمشي بتواضع، وأسلّم على من عرفتُ ومن لم أعرف، وأغضّ بصري، ولا أؤذي أحدًا، وآمر بالمعروف وأنهى عن المنكر.", "و<b>أُميط الأذى</b> عن الطريق، مثل حجر أو قشرة موز، وهذا صدقة!"], "board": ["دعاء الركوب", "أُميط الأذى صدقة"]}, {"h": "في البيت والخلاء والمسجد: يمين أم يسار؟", "p": ["<b>أخرج من البيت</b> بقدمي اليسرى وأقول: «بسم الله، توكّلتُ على الله، لا حول ولا قوة إلا بالله…». و<b>أدخل البيت</b> بقدمي اليمنى وأقول: «بسم الله ولجنا، وبسم الله خرجنا، وعلى ربّنا توكّلنا»، ثم أبدأ بالسواك وأسلّم.", "<b>الخلاء</b>: أدخل باليسرى وأقول: «بسم الله، اللهمّ إني أعوذ بك من الخبث والخبائث»، ولا أُدخل شيئًا فيه ذكر الله، وأستتر، ولا أتكلّم، ولا أستقبل القبلة ولا أستدبرها، وأستعمل يدي اليسرى، وأغسل يديّ، وأخرج باليمنى وأقول: «غفرانك».", "<b>المسجد</b>: أدخل باليمنى وأقول: «بسم الله، اللهمّ افتح لي أبواب رحمتك»، ولا أجلس حتى أصلّي ركعتين، ولا أمرّ بين يدي المصلّين، ولا أبيع فيه، وأحافظ على نظافته، وأخرج باليسرى وأقول: «اللهمّ إني أسألك من فضلك»."], "board": ["البيت: أدخل باليمنى", "الخلاء: أدخل باليسرى", "المسجد: أدخل باليمنى"]}], "summary": ["في المجلس أسلّم، وأفسح لغيري، وأختم بدعاء كفّارة المجلس.", "أنام مبكّرًا على جنبي الأيمن، وآكل بيميني وأسمّي الله، وأشرب جالسًا.", "أدخل البيت والمسجد باليمنى، وأدخل الخلاء باليسرى، ولكل منها دعاء."], "islam": {"intro": "قال الله تعالى يعلّمنا أدب المجلس:", "text": "فإذا أفسحتَ لأخيك في المجلس، أفسح الله لك. والآداب الصغيرة كل يوم تجعل يومك كلّه طاعة.", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ", "src": "سُورَةُ المُجَادلَةِ: ١١"}, "hadith": {"text": "يا غلام، سمِّ الله، وكُل بيمينك، وكُل ممّا يليك", "source": "متفق عليه"}}, "home": {"title": "يومي الجميل بالآداب", "goal": "أن يطبّق الطفل آداب يومه من النوم إلى الطعام إلى دخول البيت والخروج منه.", "materials": ["ورقة كبيرة", "ألوان", "ملصقات"], "steps": ["ارسم ساعة كبيرة، وضع عليها أوقات يومك: الاستيقاظ، الطعام، الخروج، الرجوع، النوم.", "اكتب بجانب كل وقت أدبًا ودعاءً واحدًا، مثل: «الطعام: بسم الله، وآكل بيميني».", "علّق الساعة في غرفتك، والصق ملصقًا كلّما طبّقتَ أدبًا.", "اعمل مع أسرتك «مسابقة أنوس» صغيرة على العشاء: كل واحد يسأل سؤالًا عن آداب اليوم."], "parent": "ذكّروا طفلكم بالآداب بلطف وفي وقتها، وكونوا قدوة له: سمّوا الله وكلوا باليمين أمامه."}, "online": {"title": "يمين أم يسار؟", "intro": "ساعد فصيحًا على اختيار القدم الصحيحة، وترتيب آداب المسجد!", "steps": [{"type": "sort", "title": "يمين أم يسار؟", "prompt": "اضغط على البطاقة، ثم اختر القدم أو اليد المناسبة.", "bins": ["أبدأ باليمين", "أبدأ باليسار"], "items": [{"t": "دخول المسجد", "icon": "🕌", "bin": 0, "why": "أدخل المسجد بقدمي اليمنى."}, {"t": "دخول البيت", "icon": "🏠", "bin": 0, "why": "أدخل البيت بقدمي اليمنى."}, {"t": "لبس الحذاء", "icon": "👟", "bin": 0, "why": "ألبس النعل في اليمنى أوّلًا."}, {"t": "الأكل", "icon": "🍽️", "bin": 0, "why": "آكل بيدي اليمنى."}, {"t": "دخول الخلاء", "icon": "🚪", "bin": 1, "why": "أدخل الخلاء بقدمي اليسرى."}, {"t": "الخروج من المسجد", "icon": "👣", "bin": 1, "why": "أخرج من المسجد بقدمي اليسرى."}, {"t": "خلع الحذاء", "icon": "🥿", "bin": 1, "why": "أخلع النعل من اليسرى أوّلًا."}]}, {"type": "order", "title": "رتّب زيارتك للمسجد", "prompt": "رتّب الخطوات من الأولى إلى الأخيرة.", "items": ["أدخل بقدمي اليمنى وأقول: اللهمّ افتح لي أبواب رحمتك", "أصلّي ركعتين قبل أن أجلس", "أجلس بهدوء ولا أمرّ بين يدي المصلّين", "أخرج بقدمي اليسرى وأقول: اللهمّ إني أسألك من فضلك"]}, {"type": "quiz", "title": "مسابقة أنوس السريعة", "items": [{"q": "ماذا أقول إذا نسيتُ التسمية في أوّل الطعام؟", "o": ["لا شيء", "الحمد لله فقط", "بسم الله أوّله وآخره"], "a": 2}, {"q": "ماذا أقول عند الخروج من الخلاء؟", "o": ["غفرانك", "صباح الخير", "بسم الله"], "a": 0}, {"q": "ماذا أقول في آخر المجلس؟", "o": ["مع السلامة فقط", "سبحانك اللهمّ وبحمدك…", "لا أقول شيئًا"], "a": 1}]}]}, "case": {"title": "مَن أنا؟", "story": "في آخر المسابقة، أخرج فصيح ورقة لغز ذهبية للفريق الفائز. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا بنت النبيّ ﷺ.", "أنا سيّدة نساء أهل الجنّة.", "أنا زوجة عليّ، وأمّ الحسن والحسين."], "options": ["عائشة رضي الله عنها", "فاطمة الزهراء رضي الله عنها", "خديجة بنت خويلد رضي الله عنها"], "deep": "ماذا نتعلّم من بيت فاطمة رضي الله عنها في البرّ بالأب والصبر على العمل في البيت؟", "reveal": "أنا فاطمة الزهراء رضي الله عنها! علّمني أبي ﷺ أنا وعليًّا أن نسبّح ونحمد ونكبّر قبل النوم. وفي الحلقة القادمة نتعلّم آداب السلام والاستئذان واللعب."}, "quiz": [{"q": "على أيّ جنب أنام؟", "o": ["على بطني", "على جنبي الأيمن", "لا يهمّ"], "a": 1, "why": "أنام على جنبي الأيمن، ولا أنام على بطني."}], "qa": [{"id": 163, "q": "ما آدابُ المجلس؟", "a": "١. أسلِّمُ على أهلِ المجلس.\n٢. أجلسُ حيث ينتهي بي المجلس، لا أُقيمُ أحدًا من مجلسه، ولا أجلسُ بين اثنينِ إلا بإذنهما.\n٣. أفسحُ المجلسَ ليجلسَ غيري.\n٤. لا أقاطعُ حديثَ المجلس.\n٥. أستأذنُ وأسلِّمُ قبلَ الانصرافِ من المجلس.\n٦. عندما ينتهي المجلسُ أدعو دعاءَ كفارةِ المجلس: \"سبحانك اللهمَّ وبحمدك، أشهدُ أن لا إله إلا أنت، أستغفرُكَ وأتوبُ إليك\".\nفعن ابنِ عمر، عن النبيِّ ﷺ: «أنه نهى أن يُقامَ الرجلُ من مجلسه، ويجلسَ فيه آخر، ولكن تفسَّحوا وتوسَّعوا» رواه البخاري."}, {"id": 164, "q": "ما آدابُ النوم؟", "a": "١. أنامُ مبكِّرًا. لحديث: «أنَّ رسولَ الله ﷺ كان يكرهُ النومَ قبلَ العشاء، والحديثَ بعدها» رواه البخاري.\n٢. أنامُ على طهارة.\n٣. لا أنامُ على بطني. (قال ﷺ لمن رآهُ مضطجعًا على بطنه: «إنَّ هذه ضجعةٌ لا يحبُّها الله» رواه الترمذي وأحمد).\n٤. أنامُ على جنبي الأيمن، وأضعُ يدي اليمنى تحتَ خدي الأيمن.\n٥. أنفضُ فراشي. قال ﷺ: «إذا أوى أحدُكم إلى فراشِهِ فلينفضْ فراشَهُ بداخلةِ إزاره؛ فإنه لا يدري ما خلفَهُ عليه» رواه البخاري.\n٦. أتلو أذكارَ النوم، من آيةِ الكرسي، وسورةِ الإخلاص، والمعوذتينِ ثلاثَ مرات. وأقول: \"باسمِكَ اللهمَّ أموتُ وأحيا\"."}, {"id": 165, "q": "ما هي آدابُ الطعام؟", "a": "١. أنوي بأكلي وشربي التقوّيَ على طاعةِ الله عزَّ وجلَّ.\n٢. غسلُ اليدينِ قبلَ الأكل.\n٣. أقول: \"بسم الله\"، وآكلُ بيدي اليمنى ومما يليني. لحديث: «يا غلامُ، سمِّ الله، وكُلْ بيمينك، وكُلْ مما يليك» متفق عليه.\n٤. إذا نسيتُ التسميةَ أقول: \"بسم الله أولَهُ وآخرَه\".\n٥. أرضى بالموجودِ من الطعام، ولا أعيبُ الطعام. لحديث: «ما عابَ النبيُّ ﷺ طعامًا قط، إن اشتهاهُ أكلَه، وإلا تركه» متفق عليه.\n٦. آكلُ بضعَ لقيمات، ولا آكلُ كثيرًا. في الحديث: «ما ملأ آدميٌّ وعاءً شرًّا من بطن، حسبُ الآدميِّ لقيماتٌ يُقمنَ صلبَه...» رواه الترمذي وابن ماجه.\n٧. لا أنفخُ في الطعامِ أو الشراب، وأتركُهُ حتى يبرد.\n٨. أجتمعُ مع غيري في الطعام. حديث: «فلعلكم تأكلونَ مفترقين، اجتمعوا على طعامِكم واذكروا اسمَ الله عليه يُبارَكْ لكم فيه» رواه أبو داود وابن ماجه.\n٩. لا أبدأُ بالطعامِ قبلَ غيري ممن هو أكبرُ مني.\n١٠. أُسمِّي اللهَ عندما أشرب، وأشربُ جالسًا وعلى ثلاثِ دفعات، ولا أتنفسُ في الإناء. لحديث: «إذا شربَ أحدُكم فلا يتنفسْ في الإناء» متفق عليه، و«أنَّ النبيَّ ﷺ زجرَ عن الشربِ قائمًا» رواه مسلم.\n١١. أحمدُ اللهَ عندما أنتهي. في الحديث: «إنَّ اللهَ ليرضى عن العبدِ أن يأكلَ الأكلةَ فيحمدَهُ عليها، أو يشربَ الشربةَ فيحمدَهُ عليها» رواه مسلم."}, {"id": 166, "q": "ما آدابُ اللباس؟", "a": "١. أبدأُ بلبسِ ثوبي باليمين، وأحمدُ اللهَ على ذلك. لحديث: «إذا لبستم وإذا توضأتم فابدءوا بأيامنِكم» رواه أبو داود وأحمد.\n٢. لا أُطيلُ الثوبَ تحتَ الكعبين. في الحديث: «ما أسفلَ من الكعبينِ من الإزارِ ففي النار» رواه البخاري. (والكعبانِ العظمانِ الناتئانِ على جانبي القدم).\n٣. لا يلبسُ الأولادُ لبسَ البنات، ولا البناتُ لبسَ الأولاد. في الحديث: «لعنَ رسولُ الله ﷺ الرجلَ يلبسُ لبسةَ المرأة، والمرأةَ تلبسُ لبسةَ الرجل» رواه أبو داود وأحمد.\n٤. عدمُ التشبهِ بلباسِ الكافرينَ أو الفاسقين. لحديث: «من تشبَّهَ بقومٍ فهو منهم» رواه أبو داود.\n٥. التسميةُ عند خلعِ الملابس.\n٦. لبسُ النعالِ في اليمنى أولًا، والخلعُ من اليسرى. لحديث عائشة: «كان النبيُّ ﷺ يعجبُهُ التيمنُ في تنعلِهِ وترجلِهِ وطهورِهِ وفي شأنِهِ كلِّه» رواه البخاري."}, {"id": 167, "q": "ما آدابُ الركوب؟", "a": "١. أقول: \"بسم الله، الحمد لله\"، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ ۝ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ﴾ [الزخرف: ١٣–١٤].\n٢. إذا مررتُ بمسلمٍ؛ ألقي عليه السلام."}, {"id": 168, "q": "ما آدابُ الطريق؟", "a": "١. أعتدلُ وأتواضعُ في مِشيتي. قال تعالى: ﴿وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ الْأَرْضَ وَلَن تَبْلُغَ الْجِبَالَ طُولًا﴾ [الإسراء: ٣٧].\n٢. ألقي السلامَ على من ألقاه. سُئِلَ النبيُّ ﷺ: أيُّ الإسلامِ خير؟ قال: «تُطعِمُ الطعام، وتقرأُ السلامَ على من عرفتَ ومن لم تعرف» متفق عليه.\n٣. أغضُّ بصري، ولا أؤذي أحدًا.\n٤. آمرُ بالمعروف، وأنهى عن المنكر. في الحديث: «فأعطوا الطريقَ حقَّها»... «غضُّ البصر، وكفُّ الأذى، وردُّ السلام، وأمرٌ بالمعروف، ونهيٌ عن المنكر» متفق عليه.\n٥. أُميطُ الأذى عن الطريق. في الحديث: «ويميطُ الأذى عن الطريقِ صدقة» متفق عليه."}, {"id": 169, "q": "ما آدابُ دخولِ البيتِ والخروجِ منه؟", "a": "١. أخرجُ بقدمي اليسرى وأقول: «بسم الله، توكلتُ على الله، لا حولَ ولا قوةَ إلا بالله، اللهم إني أعوذُ بك أن أضِلَّ أو أُضَلَّ، أو أزِلَّ أو أُزَلَّ، أو أظلِمَ أو أُظلَمَ، أو أجهلَ أو يُجهلَ عليَّ».\n٢. أدخلُ البيتَ بقدمي اليمنى، وأقول: «بسم الله ولَجنا، وبسم الله خرَجنا، وعلى ربنا توكلنا».\n٣. وأبدأُ بالسواك، ثم أسلِّمُ على أهلِ البيت. في الحديث: «كان إذا دخلَ يبدأُ بالسواك» رواه ابن ماجه."}, {"id": 170, "q": "ما آدابُ قضاءِ الحاجة؟", "a": "١. أدخلُ بقدمي اليسرى.\n٢. وأقول قبلَ الدخول: «بسم الله، اللهم إني أعوذُ بك من الخُبثِ والخبائث».\n٣. لا أُدخِلُ شيئًا فيه ذكرُ الله.\n٤. أستترُ حالَ قضاءِ الحاجة.\n٥. لا أتكلمُ في مكانِ قضاءِ الحاجة.\n٦. لا أستقبلُ القبلة، ولا أستدبرُها في أثناءِ البولِ أو الغائط. لقوله ﷺ: «لا تستقبلوا القبلةَ بغائطٍ أو بول، ولكن شرِّقوا أو غرِّبوا» متفق عليه.\n٧. أستعملُ يدي اليسرى في إزالةِ النجاسة، ولا أستعملُ اليمنى.\n٨. لا أقضي حاجتي في طريقِ الناسِ أو ظلِّهم. قال ﷺ: «اتقوا اللعانين... الذي يتخلى في طريقِ الناس، أو في ظلِّهم» رواه مسلم.\n٩. أغسلُ يدي بعد قضاءِ الحاجة.\n١٠. أخرجُ بقدمي اليمنى، وأقول: «غفرانك»."}, {"id": 171, "q": "ما آدابُ المسجد؟", "a": "١. أدخلُ المسجدَ بقدمي اليمنى وأقول: «بسم الله، اللهم افتحْ لي أبوابَ رحمتك».\n٢. لا أجلسُ حتى أصليَ ركعتين. لحديث: «إذا دخلَ أحدُكم المسجدَ فلا يجلسْ حتى يصليَ ركعتين» متفق عليه.\n٣. لا أمرُّ بين يدي المصلين، ولا أنشدُ الضالةَ في المسجد، ولا أبيعُ وأشتري فيه. قال ﷺ: «لو يعلمُ المارُّ بين يدي المصلي ماذا عليه لكان أن يقفَ أربعينَ خيرًا له من أن يمرَّ بين يديه» متفق عليه.\n٤. أحرصُ على نظافةِ المسجد. في الحديث عن عائشة: «أمرَ رسولُ الله ﷺ ببناءِ المساجدِ في الدور، وأن تُنظَّفَ وتُطيَّب» رواه الترمذي وأبو داود وأحمد.\n٥. أخرجُ من المسجدِ بقدمي اليسرى، وأقول: «اللهم إني أسألُكَ من فضلك»."}], "dyk": ["حركةُ المدِّ والجزرِ في البحارِ سببُها جاذبيةُ القمرِ للأرض."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "يَمِينٌ… يَسَارٌ… يَمِينٌ… يَسَارٌ! جَوَابُ اللُّغْزِ الْمَاضِي: أُوَيْسٌ الْقَرَنِيُّ رَحِمَهُ اللَّهُ، الَّذِي بَرَّ أُمَّهُ فَذَكَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "anos", "t": "وَالْيَوْمَ آدَابُ يَوْمِنَا، مِنَ الْمَجْلِسِ إِلَى الْمَسْجِدِ. هَاتِ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا آدَابُ الْمَجْلِسِ؟"}, {"s": "anos", "t": "أُسَلِّمُ، وَأَجْلِسُ حَيْثُ يَنْتَهِي الْمَجْلِسُ، وَلَا أُقِيمُ أَحَدًا، وَلَا أَجْلِسُ بَيْنَ اثْنَيْنِ إِلَّا بِإِذْنِهِمَا، وَأُفْسِحُ لِغَيْرِي، وَلَا أُقَاطِعُ، وَأَخْتِمُ بِدُعَاءِ كَفَّارَةِ الْمَجْلِسِ. اسْمَعُوا آيَةَ الْمَجْلِسِ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "58:11", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ"}, {"s": "fasih", "t": "فَإِذَا أَفْسَحْتَ لِأَخِيكَ فِي الْمَجْلِسِ، أَفْسَحَ اللَّهُ لَكَ! وَمَا آدَابُ النَّوْمِ؟"}, {"s": "anos", "t": "أَنَامُ مُبَكِّرًا، عَلَى طَهَارَةٍ، عَلَى جَنْبِي الْأَيْمَنِ لَا عَلَى بَطْنِي، وَأَنْفُضُ فِرَاشِي، وَأَقْرَأُ آيَةَ الْكُرْسِيِّ وَالْمُعَوِّذَاتِ، وَأَقُولُ: بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا."}, {"s": "fasih", "t": "وَآدَابُ الطَّعَامِ؟"}, {"s": "anos", "t": "أَغْسِلُ يَدَيَّ، وَأُسَمِّي، وَآكُلُ بِيَمِينِي وَمِمَّا يَلِينِي، وَلَا أَعِيبُ الطَّعَامَ، وَلَا أُكْثِرُ، وَأَشْرَبُ جَالِسًا عَلَى ثَلَاثِ دَفَعَاتٍ، وَأَحْمَدُ اللَّهَ. قَالَ النَّبِيُّ: «يَا غُلَامُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ». مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "وَآدَابُ اللِّبَاسِ؟"}, {"s": "anos", "t": "أَبْدَأُ بِالْيَمِينِ وَأَحْمَدُ اللَّهَ، وَلَا أُطِيلُ الثَّوْبَ تَحْتَ الْكَعْبَيْنِ، وَلَا يَلْبَسُ الْأَوْلَادُ لِبَاسَ الْبَنَاتِ، وَلَا أَتَشَبَّهُ بِالْكَافِرِينَ، وَأَلْبَسُ النَّعْلَ بِالْيُمْنَى وَأَخْلَعُ بِالْيُسْرَى."}, {"s": "fasih", "t": "وَآدَابُ الرُّكُوبِ؟"}, {"s": "anos", "t": "أَقُولُ: بِسْمِ اللَّهِ، الْحَمْدُ لِلَّهِ، وَأَقْرَأُ دُعَاءَ الرُّكُوبِ، وَأُسَلِّمُ عَلَى مَنْ أَمُرُّ بِهِ."}, {"s": "fasih", "t": "وَآدَابُ الطَّرِيقِ؟"}, {"s": "anos", "t": "أَمْشِي بِتَوَاضُعٍ، وَأُسَلِّمُ، وَأَغُضُّ بَصَرِي، وَلَا أُؤْذِي أَحَدًا، وَآمُرُ بِالْمَعْرُوفِ، وَأُمِيطُ الْأَذَى عَنِ الطَّرِيقِ فَهُوَ صَدَقَةٌ."}, {"s": "fasih", "t": "وَالْبَيْتُ؟"}, {"s": "anos", "t": "أَخْرُجُ بِالْيُسْرَى وَأَقُولُ: بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَأَدْخُلُ بِالْيُمْنَى وَأَقُولُ: بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى رَبِّنَا تَوَكَّلْنَا، ثُمَّ أَسْتَاكُ وَأُسَلِّمُ."}, {"s": "fasih", "t": "وَقَضَاءُ الْحَاجَةِ؟"}, {"s": "anos", "t": "أَدْخُلُ بِالْيُسْرَى وَأَسْتَعِيذُ مِنَ الْخُبُثِ وَالْخَبَائِثِ، وَأَسْتَتِرُ، وَلَا أَتَكَلَّمُ، وَلَا أَسْتَقْبِلُ الْقِبْلَةَ، وَأَسْتَعْمِلُ الْيُسْرَى، وَأَغْسِلُ يَدَيَّ، وَأَخْرُجُ بِالْيُمْنَى قَائِلًا: غُفْرَانَكَ."}, {"s": "fasih", "t": "وَالْمَسْجِدُ؟"}, {"s": "anos", "t": "أَدْخُلُ بِالْيُمْنَى: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، وَأُصَلِّي رَكْعَتَيْنِ قَبْلَ أَنْ أَجْلِسَ، وَلَا أَمُرُّ بَيْنَ يَدَيِ الْمُصَلِّي، وَأُحَافِظُ عَلَى نَظَافَتِهِ، وَأَخْرُجُ بِالْيُسْرَى: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الْمَدُّ وَالْجَزْرُ فِي الْبِحَارِ سَبَبُهُمَا جَاذِبِيَّةُ الْقَمَرِ لِلْأَرْضِ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: مُسَابَقَةُ أَنُوس! فَرِيقَانِ، وَسُؤَالٌ، وَجَرَسٌ، وَنُقْطَتَانِ لِمَنْ يَذْكُرُ الدُّعَاءَ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس: فريق اليمين وفريق اليسار"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! مَجْلِسٌ مُزْدَحِمٌ، وَمَكَانٌ صَغِيرٌ بَيْنَ اثْنَيْنِ. أ: تُسَلِّمُ وَتَجْلِسُ حَيْثُ يَنْتَهِي الْمَجْلِسُ أَوْ تَسْتَأْذِنُهُمَا. ب: تَدْفَعُ أَحَدَهُمَا. ج: تَدْخُلُ بَيْنَهُمَا بِلَا إِذْنٍ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: المكان المزدحم"}, {"s": "anos", "t": "ب وَج لَيْسَا مِنَ الْأَدَبِ. أَمَّا أ فَهُوَ الصَّحِيحُ، وَيُفْسِحُ الْحَاضِرُونَ لَكَ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: بِأَيِّ قَدَمٍ أَدْخُلُ الْخَلَاءَ؟ فَكِّرُوا…"}, {"s": "anos", "t": "بِالْيُسْرَى! وَإِذَا دَخَلْتُ الْمَسْجِدَ؟ فَكِّرُوا… لَا أَجْلِسُ حَتَّى أُصَلِّيَ رَكْعَتَيْنِ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: أَنَا بِنْتُ النَّبِيِّ، وَسَيِّدَةُ نِسَاءِ أَهْلِ الْجَنَّةِ، وَزَوْجَةُ عَلِيٍّ، وَأُمُّ الْحَسَنِ وَالْحُسَيْنِ. عَائِشَةُ، أَمْ فَاطِمَةُ، أَمْ خَدِيجَةُ، رَضِيَ اللَّهُ عَنْهُنَّ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ عِيشُوا «يَوْمِيَ الْجَمِيلَ بِالْآدَابِ»، وَالْعَبُوا «يَمِينٌ أَمْ يَسَارٌ؟» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 21, "title": "آداب السلام والاستئذان واللعب", "season": 2, "goals": ["adab"], "hook": "أهلًا يا أصدقاء! طق طق طق… مَن على الباب؟ إنه فصيح يقول: «السلام عليكم! هل أدخل؟». فصيح تعلّم أدب الاستئذان، فهل تعرفه أنت؟ واليوم نتعلّم أيضًا آداب اللعب والمزاح والعطاس!", "sections": [{"h": "السلام: كلمة تنشر المحبّة", "p": ["عندما ألقى مسلمًا أبدأ بالسلام كاملًا: <b>السلام عليكم ورحمة الله وبركاته</b>، لا بكلمة أخرى، ولا أشير بيدي وحدها.", "أبتسم في وجهه، وأصافحه بيدي <b>اليمنى</b>. وإذا سلّم عليّ أحد أردّ عليه <b>بأحسن منها أو مثلها</b>. ولا أبدأ الكافر بالسلام، وإذا سلّم عليّ قلت: «وعليكم».", "ومن يسلّم أوّلًا؟ <b>الصغير على الكبير</b>، والراكب على الماشي، والماشي على القاعد، والقليل على الكثير. فإذا رأيتُ جدّي، أسرعتُ أنا بالسلام!"], "board": ["السلام عليكم ورحمة الله وبركاته", "أبتسم وأصافح باليمين", "الصغير يسلّم على الكبير"]}, {"h": "الاستئذان: طق طق… هل أدخل؟", "p": ["أستأذن قبل أن أدخل أيّ مكان مسكون. وأستأذن <b>ثلاث مرّات</b> فقط، فإن لم يُؤذن لي أرجع.", "أطرق الباب <b>برفق</b>، ولا أقف أمام الباب مباشرة، بل على يمينه أو يساره، وأقول: السلام عليكم.", "ولا أدخل غرفة أبي وأمّي إلا بإذن، خصوصًا <b>قبل الفجر، ووقت القيلولة بعد الظهر، وبعد صلاة العشاء</b>. أمّا الأماكن غير المسكونة، مثل المتجر أو المستشفى، فأدخلها بدون استئذان."], "board": ["ثلاث مرّات", "أقف بجانب الباب", "أوقات الاستئذان الثلاثة"]}, {"h": "أرحم الحيوان، وألعب بأدب", "p": ["أُطعم الحيوان وأسقيه، ففي كل <b>كبد رطبة أجر</b>. ولا أحمّله ما لا يطيق، ولا أعذّبه، ولا أضربه على وجهه.", "وفي <b>الرياضة</b>: أنوي أن أتقوّى على طاعة الله، و<b>لا ألعب وقت الصلاة</b>، وألبس لباسًا ساترًا، ويلعب الأولاد مع الأولاد، والبنات مع البنات. وأتجنّب الرياضة التي فيها ضرب للوجه.", "وفي <b>المزاح</b>: أمزح بالصدق ولا أكذب لأُضحك الناس، ولا أسخر من أحد، ولا أُخيف صديقي ولو مزاحًا، ولا أُكثر من الضحك."], "board": ["أرحم الحيوان", "لا ألعب وقت الصلاة", "مزاحي صادق"]}, {"h": "عطسة وتثاؤب: لكلٍّ أدب", "p": ["إذا عطستُ وضعتُ يدي أو منديلًا على فمي، وقلت: <b>الحمد لله</b>. فيقول لي أخي: <b>يرحمك الله</b>. فأقول له: <b>يهديكم الله ويصلح بالكم</b>.", "و<b>التثاؤب</b> من الشيطان، فأحاول أن أكظمه وأردّه ما استطعت، وأضع يدي على فمي، ولا أرفع صوتي بقول «آه آه».", "فصيح يقول: «هاتشو! الحمد لله!». فيردّ أنوس: «يرحمك الله يا فصيح!»."], "board": ["الحمد لله", "يرحمك الله", "يهديكم الله ويصلح بالكم"]}, {"h": "حين أدعو وحين أتلو", "p": ["إذا دعوتُ الله: أبدأ <b>بحمد الله والثناء عليه</b>، ثم أصلّي على النبيّ ﷺ، وأرفع يديّ، وأتوب، وأكرّر الدعاء ولا أستعجل الإجابة، ولا أدعو بإثم أو قطيعة رحم، وأخفض صوتي، وقلبي حاضر.", "وأدعو الله <b>وحده</b> في الشدّة والرخاء، وأتوسّل بأسمائه الحسنى، وأستقبل القبلة، وآكل الحلال.", "وإذا تلوتُ القرآن: أكون <b>على طهارة</b>، وأجلس بأدب ووقار، وأستعيذ بالله من الشيطان الرجيم، وأتدبّر ما أقرأ."], "board": ["أحمد الله وأصلّي على النبيّ ﷺ", "أدعو الله وحده", "أتلو على طهارة"]}], "summary": ["أبدأ بالسلام كاملًا، وأبتسم، وأصافح باليمين، وأردّ بأحسن منه، وأستأذن ثلاثًا ثم أرجع.", "أرحم الحيوان، ولا ألعب وقت الصلاة، وأمزح بالصدق بلا سخرية ولا تخويف.", "إذا عطستُ قلت: الحمد لله، وأكظم التثاؤب، وأتأدّب في الدعاء والتلاوة."], "islam": {"intro": "قال الله تعالى يعلّمنا كيف نردّ التحيّة:", "text": "فإذا قال لك صديقك: السلام عليكم، فقل: وعليكم السلام ورحمة الله وبركاته، وابتسم!", "ayah": {"text": "وَإِذَا حُيِّيتُم بِتَحِيَّةٍۢ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا", "src": "سُورَةُ النِّسَاءِ: ٨٦"}, "hadith": {"text": "في كلّ كبد رطبة أجر", "source": "متفق عليه"}}, "home": {"title": "بيت السلام", "goal": "أن يطبّق الطفل آداب السلام والاستئذان والعطاس مع أسرته.", "materials": ["ورقة لتعليقها على باب الغرفة", "ألوان"], "steps": ["اصنع لافتة لباب غرفتك: «طق طق… السلام عليكم، هل أدخل؟».", "سلّم على كل فرد من أسرتك بالسلام الكامل عند دخولك البيت، وابتسم.", "تدرّب مع إخوتك على الاستئذان: اطرق برفق ثلاث مرّات، وقف بجانب الباب.", "ضع وعاء ماء لعصفور أو قطّة في الحديقة أو الشرفة، واذكر حديث «في كل كبد رطبة أجر»."], "parent": "علّموا طفلكم أوقات الاستئذان الثلاثة بلطف، وكونوا قدوة: اطرقوا باب غرفته واستأذنوا قبل الدخول."}, "online": {"title": "آداب فصيح", "intro": "ساعد فصيحًا على قول الكلام المناسب، واختيار المزاح الجميل!", "steps": [{"type": "match", "title": "ماذا أقول؟", "prompt": "اختر الموقف، ثم الكلام المناسب.", "pairs": [["ألقى مسلمًا", "السلام عليكم ورحمة الله وبركاته"], ["عطستُ", "الحمد لله"], ["عطس أخي وحمد الله", "يرحمك الله"], ["قال لي: يرحمك الله", "يهديكم الله ويصلح بالكم"], ["أبدأ التلاوة", "أعوذ بالله من الشيطان الرجيم"]]}, {"type": "sort", "title": "لعب ومزاح بأدب؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["أدب جميل", "أتركه"], "items": [{"t": "أسقي القطّة ماءً", "icon": "🐱", "bin": 0, "why": "في كل كبد رطبة أجر."}, {"t": "أمزح بكلام صادق", "icon": "😄", "bin": 0, "why": "المزاح الجميل صادق بلا كذب."}, {"t": "أوقف اللعب عند الأذان", "icon": "⏰", "bin": 0, "why": "لا نلعب وقت الصلاة."}, {"t": "أُخيف صديقي مزاحًا", "icon": "😱", "bin": 1, "why": "لا يحلّ لمسلم أن يروّع مسلمًا."}, {"t": "أضرب الحيوان على وجهه", "icon": "🚫", "bin": 1, "why": "نهى النبيّ ﷺ عن ضرب البهيمة في وجهها."}, {"t": "أكذب ليضحك الناس", "icon": "🤥", "bin": 1, "why": "ويل للذي يحدّث فيكذب ليُضحك به القوم."}]}, {"type": "decision", "title": "قرار أنوس", "scenario": "أراد أنوس أن يدخل غرفة والديه بعد صلاة العشاء. ماذا يفعل؟", "options": [{"t": "يفتح الباب ويدخل فورًا", "result": "هذا وقت من أوقات الاستئذان الثلاثة، فلا يدخل بلا إذن."}, {"t": "ينظر من فتحة الباب أوّلًا", "result": "لا نتجسّس على أحد، ونستأذن بأدب."}, {"t": "يطرق برفق، ويقول: السلام عليكم، هل أدخل؟", "result": "أحسنت! هذا أدب الاستئذان الذي علّمنا إيّاه القرآن.", "best": true}]}]}, "case": {"title": "مَن أنا؟", "story": "وجد فصيح سهمًا صغيرًا مربوطًا به ورقة لغز. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا أوّل من رمى بسهم في سبيل الله.", "كنتُ مستجاب الدعوة.", "قُدتُ جيش المسلمين في معركة القادسية."], "options": ["خالد بن الوليد رضي الله عنه", "حمزة بن عبد المطلب رضي الله عنه", "سعد بن أبي وقاص رضي الله عنه"], "deep": "لماذا كان الله يستجيب دعاء سعد؟ وما آداب الدعاء التي تحبّ أن تطبّقها اليوم؟", "reveal": "أنا سعد بن أبي وقاص رضي الله عنه، وأنا من العشرة المبشّرين بالجنّة! وفي الحلقة القادمة نتعلّم حسن الخلق: الإحسان والأمانة والصدق."}, "quiz": [{"q": "مَن يبدأ بالسلام: الصغير أم الكبير؟", "o": ["الكبير دائمًا", "الصغير على الكبير", "لا أحد"], "a": 1, "why": "يسلّم الصغير على الكبير، والراكب على الماشي، والماشي على القاعد."}], "qa": [{"id": 172, "q": "ما آدابُ السلام؟", "a": "١. عندما ألقى مسلمًا أبدأُ بالسلام: \"السلامُ عليكم ورحمةُ الله وبركاته\"، لا بغيرِ السلام، ولا أشيرُ بيدي وحدَها.\n٢. أتبسمُ في وجهِ من أسلمُ عليه. في الحديث: «لا تحقرنَّ من المعروفِ شيئًا، ولو أن تلقى أخاكَ بوجهٍ طلق» رواه مسلم.\n٣. وأصافحُهُ بيدي اليمنى.\n٤. إذا حياني أحدٌ بتحيةٍ أحييهِ بأحسنَ منها، أو أردُّ مثلَها. لقوله تعالى: ﴿وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾ [النساء: ٨٦].\n٥. لا أبدأُ الكافرَ بالسلام، وإذا سلَّمَ عليَّ أردُّ عليه \"وعليكم\". لحديث: «لا تبدؤوا اليهودَ ولا النصارى بالسلام» رواه مسلم.\n٦. ويسلِّمُ الصغيرُ على الكبير، والراكبُ على الماشي، والماشي على القاعد، والقليلُ على الكثير. قال ﷺ: «يسلِّمُ الراكبُ على الماشي، والماشي على القاعد، والقليلُ على الكثير» متفق عليه.\n٧. عدمُ مصافحةِ المرأةِ التي لا تحلُّ من غيرِ المحارم."}, {"id": 173, "q": "ما آدابُ الاستئذان؟", "a": "١. أستأذنُ قبلَ الدخولِ إلى المكان.\n٢. أستأذنُ ثلاثَ مراتٍ ولا أزيد، وبعدَها أنصرف. في الحديث: «إذا استأذنَ أحدُكم ثلاثًا فلم يُؤذنْ له، فليرجع» متفق عليه.\n٣. أطرقُ البابَ برفق، ولا أقفُ في مواجهةِ الباب، بل على يمينِهِ أو يساره. وأقول: السلامُ عليكم. لحديث: «كان رسولُ الله ﷺ إذا أتى بابَ قومٍ لم يستقبلِ البابَ من تلقاءِ وجهه، ولكن من ركنِهِ الأيمنِ أو الأيسر» رواه أبو داود.\n٤. لا أدخلُ على أبي وأمي أو أحدِ الغرفِ قبلَ الاستئذان، وخصوصًا قبلَ الفجر، ووقتَ القيلولةِ من الظهر، وبعدَ صلاةِ العشاء. لقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنكُمْ ثَلَاثَ مَرَّاتٍ...﴾ [النور: ٥٨].\n٥. يمكنُ أن أدخلَ الأماكنَ غيرَ المسكونة، مثل: المشفى أو المتجرِ بدونِ استئذان."}, {"id": 174, "q": "ما آدابُ الرفقِ بالحيوان؟", "a": "١. أُطعِمُ الحيوانَ وأسقيه. في الحديث: قالوا: يا رسولَ الله، وإنَّ لنا في البهائمِ أجرًا؟ قال: «في كلِّ كبدٍ رطبةٍ أجر» متفق عليه.\n٢. الرحمةُ والشفقةُ وعدمُ تحميلِهِ ما لا يطيق. في الحديث: قال ﷺ لصاحبِ الجمل: «أفلا تتقي اللهَ في هذه البهيمةِ التي ملَّكَكَ اللهُ إياها؟ فإنه شكا إليَّ أنكَ تُجيعُهُ وتُدئِبُه» رواه أبو داود وأحمد.\n٣. لا أُعذِّبُ الحيوانَ بأيِّ نوعٍ من العذابِ والأذى. في الحديث عن جابر: أنَّ النبيَّ ﷺ مرَّ عليه بحمارٍ قد وُسِمَ في وجهه، فقال: «أما بلغكم أني قد لعنتُ من وسمَ البهيمةَ في وجهها، أو ضربها في وجهها؟» فنُهيَ عن ذلك. رواه مسلم وأبو داود."}, {"id": 175, "q": "ما آدابُ الرياضة؟", "a": "١. أنوي بالرياضةِ التقوّيَ من أجلِ طاعةِ اللهِ ومرضاته.\n٢. لا نلعبُ وقتَ الصلاة. قال تعالى: ﴿فَوَيْلٌ لِّلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ﴾ [الماعون: ٤–٥].\n٣. لا يمارسُ الأولادُ الرياضةَ مع البنات.\n٤. ألتزمُ بالزيِّ الرياضيِّ الساترِ لعورتي.\n٥. أتجنبُ الرياضةَ المحرمة، كالتي فيها ضربٌ للوجهِ وكشفٌ للعورات. في الحديث: «إذا قاتلَ أحدُكم أخاهُ فليجتنبِ الوجه» رواه مسلم."}, {"id": 176, "q": "ما آدابُ المزاح؟", "a": "١. الصدقُ في المزاحِ وعدمُ الكذب. في الحديث: «ويلٌ للذي يُحدِّثُ فيكذبُ ليُضحِكَ به القوم، ويلٌ له، ويلٌ له» رواه أبو داود وأحمد والترمذي.\n٢. المزاحُ الخالي من السخريةِ والاستهزاءِ والإيذاءِ والترويع. قال ﷺ: «لا يحلُّ لمسلمٍ أن يُروِّعَ مسلمًا» رواه أبو داود وأحمد.\n٣. عدمُ الإكثارِ من المزاح. قال ﷺ: «ولا تُكثرِ الضحك؛ فإنَّ كثرةَ الضحكِ تُميتُ القلب» رواه الترمذي وابن ماجه."}, {"id": 177, "q": "ما آدابُ العطاس؟", "a": "١. وضعُ اليدِ أو الثوبِ أو المنديلِ عند العطاس.\n٢. أن تحمدَ اللهَ بعد العطاس: \"الحمدُ لله\".\n٣. وليقلْ له أخوهُ أو صاحبُه: \"يرحمُكَ الله\".\n٤. فإذا قال له، فليقلْ: \"يهديكمُ اللهُ ويُصلِحُ بالَكم\"."}, {"id": 178, "q": "ما هي آدابُ التثاؤب؟", "a": "١. محاولةُ كظمِ التثاؤب. في الحديث: «التثاؤبُ من الشيطان، فإذا تثاءبَ أحدُكم فليردَّهُ ما استطاع» متفق عليه.\n٢. عدمُ رفعِ الصوتِ بقول \"آه آه\". في الحديث: «ولا يقلْ: آه آه، فإنَّ أحدَكم إذا فتحَ فاه، فإنَّ الشيطانَ يضحكُ منه» رواه أحمد.\n٣. وضعُ اليدِ على الفم."}, {"id": 179, "q": "ما آدابُ الدعاء؟", "a": "١. البدءُ بحمدِ اللهِ والثناءِ عليه.\n٢. الصلاةُ على النبيِّ ﷺ. في الحديث: «إذا صليتَ فقعدت، فاحمدِ اللهَ بما هو أهلُه، وصلِّ عليَّ ثم ادعُه» رواه الترمذي.\n٣. رفعُ اليدينِ في أثناءِ الدعاء. قال ﷺ: «إنَّ ربكم حييٌّ كريمٌ يستحيي من عبدِهِ إذا رفعَ يديهِ إليه أن يردَّهما صفرًا» رواه الترمذي وأبو داود.\n٤. التوبةُ والاعترافُ بالذنب.\n٥. الإلحاحُ في الدعاءِ وتكرارُه.\n٦. عدمُ استعجالِ الإجابة. في الحديث: «يُستجابُ لأحدِكم ما لم يعجلْ، يقول: دعوتُ فلم يُستجبْ لي» متفق عليه.\n٧. لا يدعو بإثمٍ أو قطيعةِ رحم.\n٨. خفضُ الصوتِ في الدعاء. قال تعالى: ﴿ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً﴾ [الأعراف: ٥٥].\n٩. حضورُ القلبِ في أثناءِ الدعاء. في الحديث: «ادعوا اللهَ وأنتم موقنونَ بالإجابة، واعلموا أنَّ اللهَ لا يستجيبُ دعاءً من قلبٍ غافلٍ لاهٍ» رواه الترمذي.\n١٠. الإخلاصُ لله، وسؤالُهُ وحدَهُ في الشدةِ والرخاء. قال تعالى: ﴿وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا﴾ [الجن: ١٨].\n١١. التوسلُ إلى اللهِ بأسمائِهِ الحسنى وصفاته. قال تعالى: ﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَىٰ فَادْعُوهُ بِهَا﴾ [الأعراف: ١٨٠].\n١٢. استقبالُ القبلة.\n١٣. إطابةُ المأكلِ والملبس. في الحديث: «... ومطعمُهُ حرام، ومشربُهُ حرام، وملبسُهُ حرام، وغُذِيَ بالحرام، فأنى يُستجابُ لذلك» رواه مسلم."}, {"id": 180, "q": "ما آدابُ التلاوة؟", "a": "١. التلاوةُ على طهارةٍ بعد الوضوء.\n٢. الجلوسُ بأدبٍ ووقار.\n٣. أستعيذُ بالله من الشيطانِ في بدايةِ التلاوة. قال تعالى: ﴿فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ﴾ [النحل: ٩٨].\n٤. أتدبرُ القراءة. قال تعالى: ﴿أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَا﴾ [محمد: ٢٤]."}], "dyk": ["الرياحُ تنقلُ حبوبَ اللقاحِ والبذورَ فتُساعِدُ النباتاتِ على التكاثرِ في كلِّ مكان."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "طَقْ طَقْ طَقْ! السَّلَامُ عَلَيْكُمْ، هَلْ أَدْخُلُ؟ وَجَوَابُ اللُّغْزِ الْمَاضِي: فَاطِمَةُ الزَّهْرَاءُ رَضِيَ اللَّهُ عَنْهَا، بِنْتُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."}, {"s": "anos", "t": "تَفَضَّلْ يَا فَصِيح! الْيَوْمَ آدَابُ السَّلَامِ وَالِاسْتِئْذَانِ وَاللَّعِبِ. اسْأَلْ!"}, {"s": "fasih", "t": "مَا آدَابُ السَّلَامِ؟"}, {"s": "anos", "t": "أَبْدَأُ بِـ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، لَا بِالْإِشَارَةِ وَحْدَهَا، وَأَبْتَسِمُ، وَأُصَافِحُ بِالْيُمْنَى، وَيُسَلِّمُ الصَّغِيرُ عَلَى الْكَبِيرِ، وَالرَّاكِبُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْقَاعِدِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ. وَاسْمَعُوا كَيْفَ نَرُدُّ التَّحِيَّةَ، بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "4:86", "t": "وَإِذَا حُيِّيتُم بِتَحِيَّةٍۢ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا"}, {"s": "fasih", "t": "فَإِذَا قَالَ صَدِيقُكَ: السَّلَامُ عَلَيْكُمْ، فَقُلْ: وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَابْتَسِمْ! وَمَا آدَابُ الِاسْتِئْذَانِ؟"}, {"s": "anos", "t": "أَسْتَأْذِنُ ثَلَاثًا، فَإِنْ لَمْ يُؤْذَنْ لِي رَجَعْتُ، وَأَطْرُقُ بِرِفْقٍ، وَأَقِفُ عَلَى يَمِينِ الْبَابِ أَوْ يَسَارِهِ، وَأَسْتَأْذِنُ عَلَى وَالِدَيَّ، خُصُوصًا قَبْلَ الْفَجْرِ، وَوَقْتَ الْقَيْلُولَةِ، وَبَعْدَ الْعِشَاءِ."}, {"s": "fasih", "t": "وَالرِّفْقُ بِالْحَيَوَانِ؟"}, {"s": "anos", "t": "أُطْعِمُهُ وَأَسْقِيهِ، وَلَا أُحَمِّلُهُ مَا لَا يُطِيقُ، وَلَا أُعَذِّبُهُ. قَالَ النَّبِيُّ: «فِي كُلِّ كَبِدٍ رَطْبَةٍ أَجْرٌ». مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "وَآدَابُ الرِّيَاضَةِ؟"}, {"s": "anos", "t": "أَنْوِي التَّقَوِّيَ عَلَى طَاعَةِ اللَّهِ، وَلَا أَلْعَبُ وَقْتَ الصَّلَاةِ، وَأَلْبَسُ لِبَاسًا سَاتِرًا، وَلَا يَلْعَبُ الْأَوْلَادُ مَعَ الْبَنَاتِ، وَأَتَجَنَّبُ ضَرْبَ الْوَجْهِ."}, {"s": "fasih", "t": "وَالْمِزَاحُ؟ أَنَا أُحِبُّ الْمِزَاحَ!"}, {"s": "anos", "t": "مِزَاحٌ صَادِقٌ، بِلَا كَذِبٍ، وَلَا سُخْرِيَةٍ، وَلَا تَرْوِيعٍ، وَلَا نُكْثِرُ مِنْهُ، فَكَثْرَةُ الضَّحِكِ تُمِيتُ الْقَلْبَ."}, {"s": "fasih", "t": "وَالْعُطَاسُ؟ هَاتْشُو!"}, {"s": "anos", "t": "أَضَعُ يَدِي أَوْ مِنْدِيلًا عَلَى فَمِي، وَأَقُولُ: الْحَمْدُ لِلَّهِ، فَيَقُولُ أَخِي: يَرْحَمُكَ اللَّهُ، فَأَرُدُّ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ."}, {"s": "fasih", "t": "وَالتَّثَاؤُبُ؟"}, {"s": "anos", "t": "أَرُدُّهُ مَا اسْتَطَعْتُ، فَهُوَ مِنَ الشَّيْطَانِ، وَلَا أَقُولُ: آهْ آهْ، وَأَضَعُ يَدِي عَلَى فَمِي."}, {"s": "fasih", "t": "وَآدَابُ الدُّعَاءِ؟"}, {"s": "anos", "t": "أَبْدَأُ بِحَمْدِ اللَّهِ، ثُمَّ أُصَلِّي عَلَى النَّبِيِّ، وَأَرْفَعُ يَدَيَّ، وَأُلِحُّ وَلَا أَسْتَعْجِلُ، وَأَخْفِضُ صَوْتِي، وَأُحْضِرُ قَلْبِي، وَأَسْأَلُ اللَّهَ وَحْدَهُ بِأَسْمَائِهِ الْحُسْنَى، وَأَسْتَقْبِلُ الْقِبْلَةَ، وَآكُلُ الْحَلَالَ."}, {"s": "fasih", "t": "وَآدَابُ التِّلَاوَةِ؟"}, {"s": "anos", "t": "أَتَوَضَّأُ، وَأَجْلِسُ بِأَدَبٍ، وَأَسْتَعِيذُ بِاللَّهِ مِنَ الشَّيْطَانِ، وَأَتَدَبَّرُ مَا أَقْرَأُ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الرِّيَاحُ تَنْقُلُ حُبُوبَ اللِّقَاحِ وَالْبُذُورَ، فَتُسَاعِدُ النَّبَاتَاتِ عَلَى التَّكَاثُرِ فِي كُلِّ مَكَانٍ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: نَشِيدُ الْعَطْسَةِ. نُمَرِّرُ الْمِنْدِيلَ، وَمَنْ يَصِلُهُ يُمَثِّلُ الْعُطَاسَ، وَيَرُدُّ عَلَيْهِ جَارُهُ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: نشيد العطسة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! طَرَقْتَ بَابَ صَدِيقِكَ ثَلَاثَ مَرَّاتٍ، وَلَمْ يَفْتَحْ أَحَدٌ. أ: تَطْرُقُ بِقُوَّةٍ عَشْرَ مَرَّاتٍ. ب: تَنْظُرُ مِنَ النَّافِذَةِ. ج: تَرْجِعُ بِهُدُوءٍ وَتَعُودُ فِي وَقْتٍ آخَرَ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الباب المغلق"}, {"s": "anos", "t": "أ إِزْعَاجٌ، وَب تَجَسُّسٌ. أَمَّا ج فَهُوَ الْأَدَبُ: «إِذَا اسْتَأْذَنَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ»."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَنْ يَبْدَأُ بِالسَّلَامِ، الصَّغِيرُ أَمِ الْكَبِيرُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "الصَّغِيرُ! وَبِمَاذَا أَبْدَأُ دُعَائِي؟ فَكِّرُوا… بِحَمْدِ اللَّهِ وَالثَّنَاءِ عَلَيْهِ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: أَنَا أَوَّلُ مَنْ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ، وَكُنْتُ مُسْتَجَابَ الدَّعْوَةِ، وَقُدْتُ جَيْشَ الْمُسْلِمِينَ فِي الْقَادِسِيَّةِ. خَالِدٌ، أَمْ حَمْزَةُ، أَمْ سَعْدُ بْنُ أَبِي وَقَّاصٍ، رَضِيَ اللَّهُ عَنْهُمْ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ اجْعَلُوهُ «بَيْتَ السَّلَامِ»، وَالْعَبُوا «آدَابَ فَصِيح» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 22, "title": "حسن الخلق: الإحسان والأمانة والصدق", "season": 3, "goals": ["akhlaq"], "hook": "أهلًا يا أصدقاء! فصيح يحمل ميزانًا صغيرًا ويسأل: «ما أثقل شيء في الميزان يوم القيامة؟ ذهب؟ جبل؟». لا يا فصيح! إنه شيء تستطيع أن تملكه أنت اليوم. هل تعرف ما هو؟", "sections": [{"h": "حسن الخلق: أثقل شيء في الميزان", "p": ["قال النبيّ ﷺ: <b>أكمل المؤمنين إيمانًا أحسنهم خُلُقًا</b>. والخلق الحسن هو أن يكون كلامك وتعاملك جميلًا مع الناس.", "ولماذا نلتزم الأخلاق الإسلامية؟ لأنها <b>سبب لمحبّة الله</b>، وسبب لمحبّة الناس، وهي <b>أثقل شيء في الميزان</b> يوم القيامة، ويدرك المؤمن بحسن خلقه درجة من يقوم الليل ويصوم النهار!", "ومن أين نأخذ الأخلاق؟ من <b>القرآن الكريم</b> الذي يهدي للتي هي أقوم، ومن <b>السنّة النبوية</b>؛ فقد قال ﷺ: «إنما بُعثتُ لأتمّم صالح الأخلاق»."], "board": ["أثقل شيء في الميزان", "من القرآن والسنّة"]}, {"h": "الإحسان: أن أراقب الله وأحسن إلى الخلق", "p": ["<b>الإحسان</b>: أن أراقب الله دائمًا، وأعمل الخير للمخلوقين. قال ﷺ: «إنّ الله كتب الإحسان على كل شيء».", "ومن صوره: الإخلاص في عبادة الله، والإحسان إلى الوالدين والأقارب والجار، واليتامى والمساكين، بل حتى <b>إلى من أساء إليّ</b>! والإحسان في الكلام والجدال، وإلى الحيوان.", "وضدّ الإحسان <b>الإساءة</b>: مثل ترك الإخلاص، وعقوق الوالدين، وقطع الرحم، وسوء الجوار، وترك الإحسان إلى الفقراء."], "board": ["الإحسان", "ضدّه: الإساءة"]}, {"h": "الأمانة: أحفظ ما أُعطيتُ", "p": ["الأمانة نوعان: <b>أمانة في حقوق الله</b>، مثل أن أصلّي وأصوم كما أمرني الله. و<b>أمانة في حقوق الناس</b>: أحفظ أموالهم، وأعراضهم، ودماءهم، وأسرارهم، وكل ما ائتمنوني عليه.", "مثال: أعطاك صديقك كتابه لتقرأه، فحافظ عليه وأرجعه نظيفًا. وأخبرك صديقك بسرّ، فلا تخبر به أحدًا.", "وضدّ الأمانة <b>الخيانة</b>. وقد قال ﷺ عن المنافق: «وإذا اؤتمن خان». فالمؤمن أمين دائمًا."], "board": ["أمانة حقوق الله", "أمانة حقوق الناس", "ضدّها: الخيانة"]}, {"h": "الصدق يهدي إلى الجنّة", "p": ["<b>الصدق</b>: أن أخبر بما يطابق الواقع، أي أقول الشيء كما هو. ومن صوره: الصدق في الحديث، والصدق في الوعد، والصدق في كل قول وعمل.", "قال ﷺ: «إنّ الصدق يهدي إلى البرّ، وإنّ البرّ يهدي إلى الجنّة». وضدّه <b>الكذب</b>: مثل الكذب على الناس، وإخلاف الوعد، وشهادة الزور، والكذب يهدي إلى الفجور، والفجور يهدي إلى النار.", "أنوس كسر كوبًا بالخطأ، فقال لأمّه: «أنا كسرته، آسف». فقالت: «صدقك أجمل عندي من الكوب!»."], "board": ["الصدق ← البرّ ← الجنّة", "ضدّه: الكذب"]}, {"h": "أنواع الصبر الثلاثة", "p": ["<b>الصبر على طاعة الله</b>: مثل أن أقوم لصلاة الفجر وأنا أحبّ النوم.", "<b>الصبر عن المعصية</b>: مثل أن أمتنع عن الكذب ولو كان سهلًا. و<b>الصبر على الأقدار المؤلمة</b>: مثل المرض أو ضياع لعبتي، فأقول: الحمد لله على كل حال.", "قال ﷺ: «عجبًا لأمر المؤمن إنّ أمره كلّه خير… إن أصابته سرّاء شكر، وإن أصابته ضرّاء صبر». والله يحبّ الصابرين."], "board": ["صبر على الطاعة", "صبر عن المعصية", "صبر على الأقدار"]}], "summary": ["حسن الخلق أثقل شيء في الميزان، ونأخذ الأخلاق من القرآن والسنّة.", "الإحسان مراقبة الله وبذل الخير وضدّه الإساءة، والأمانة حفظ حقوق الله والناس وضدّها الخيانة.", "الصدق يهدي إلى البرّ والجنّة وضدّه الكذب، والصبر ثلاثة أنواع: على الطاعة، وعن المعصية، وعلى الأقدار."], "islam": {"intro": "قال الله تعالى في صفات المؤمنين المفلحين:", "text": "فكن أمينًا على ما أُعطيت، وصادقًا في كل كلمة، يحبّك الله ويحبّك الناس.", "ayah": {"text": "وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ", "src": "سُورَةُ المُؤۡمِنُونَ: ٨"}, "hadith": {"text": "إنّ الصدق يهدي إلى البرّ، وإنّ البرّ يهدي إلى الجنّة", "source": "متفق عليه"}}, "home": {"title": "شجرة الأخلاق العائلية", "goal": "أن يطبّق الطفل الإحسان والأمانة والصدق والصبر مع أسرته طوال الأسبوع.", "materials": ["ورقة كبيرة عليها رسم شجرة", "أوراق خضراء صغيرة", "لاصق"], "steps": ["ارسم شجرة كبيرة، واكتب على جذعها: «حسن الخلق».", "كلّما عمل أحد في الأسرة خلقًا حسنًا، اكتبه على ورقة خضراء والصقها على الشجرة: «صدق أخي»، «أرجعت أختي الأمانة».", "في آخر الأسبوع، عدّوا الأوراق، واذكروا أجمل خلق رأيتموه.", "احفظ مع أسرتك: «إنّ الصدق يهدي إلى البرّ، وإنّ البرّ يهدي إلى الجنّة»."], "parent": "امدحوا الصدق دائمًا، حتى لو اعترف الطفل بخطأ؛ فهذا يشجّعه على الصدق ولا يخاف منه."}, "online": {"title": "ميزان فصيح", "intro": "ساعد فصيحًا على وزن الأعمال، ومعرفة كل خلق وضدّه!", "steps": [{"type": "match", "title": "الخلق وضدّه", "prompt": "اختر الخلق، ثم ضدّه.", "pairs": [["الإحسان", "الإساءة"], ["الأمانة", "الخيانة"], ["الصدق", "الكذب"], ["الوفاء بالوعد", "إخلاف الوعد"], ["برّ الوالدين", "عقوق الوالدين"]]}, {"type": "sort", "title": "أمانة أم خيانة؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["أمانة", "خيانة"], "items": [{"t": "أرجعتُ الكتاب نظيفًا لصاحبه", "icon": "📘", "bin": 0, "why": "حفظ ما ائتمنك عليه الناس أمانة."}, {"t": "حفظتُ سرّ صديقي", "icon": "🤐", "bin": 0, "why": "حفظ الأسرار من الأمانة."}, {"t": "صلّيتُ في الوقت", "icon": "🕌", "bin": 0, "why": "أداء العبادات أمانة في حقوق الله."}, {"t": "أخذتُ قلم زميلي بلا إذن ولم أرجعه", "icon": "✏️", "bin": 1, "why": "هذا تضييع لحقوق الناس، وهو خيانة."}, {"t": "أخبرتُ الناس بسرّ صديقي", "icon": "📢", "bin": 1, "why": "إفشاء السرّ خيانة للأمانة."}, {"t": "أضعتُ الصلاة وأنا ألعب", "icon": "🎮", "bin": 1, "why": "تضييع حقوق الله خيانة للأمانة."}]}, {"type": "quiz", "title": "تحدّي أنوس", "items": [{"q": "ما الصدق؟", "o": ["أن أقول ما يُضحك الناس", "أن أخبر بالشيء كما هو", "أن أسكت دائمًا"], "a": 1}, {"q": "أحسنتُ إلى من أساء إليّ. هذا من…", "o": ["الإحسان", "الخيانة", "الكذب"], "a": 0}, {"q": "مرضتُ فقلت: الحمد لله على كل حال. هذا صبر…", "o": ["عن المعصية", "على الطاعة", "على الأقدار المؤلمة"], "a": 2}]}]}, "case": {"title": "مَن أنا؟", "story": "رأى فصيح في منامه أحد عشر كوكبًا، فاستيقظ ووجد ورقة لغز. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["ألقاني إخوتي في البئر حسدًا.", "رأيتُ أحد عشر كوكبًا تسجد لي، وأنا أفسّر الرؤى.", "صرتُ عزيز مصر."], "options": ["موسى عليه السلام", "يوسف عليه السلام", "إبراهيم عليه السلام"], "deep": "إخوة يوسف آذوه كثيرًا، فكيف عاملهم حين صار عزيز مصر؟ وما الخلق الذي نتعلّمه منه؟", "reveal": "أنا يوسف عليه السلام! صبرتُ على البئر والسجن، ثم عفوتُ عن إخوتي وأحسنتُ إليهم. وفي الحلقة القادمة نتعلّم الصبر والتعاون والحياء والرحمة والتواضع."}, "quiz": [{"q": "ما أثقل شيء في الميزان يوم القيامة؟", "o": ["الذهب", "المال الكثير", "الخلق الحسن"], "a": 2, "why": "في الحديث: «أثقل شيء في الميزان يوم القيامة خلق حسن»."}], "qa": [{"id": 181, "q": "ما فضلُ حُسنِ الخُلُق؟", "a": "قال النبيُّ ﷺ: «أكملُ المؤمنينَ إيمانًا أحسنُهم خُلُقًا» رواه الترمذي وأحمد."}, {"id": 182, "q": "لماذا نلتزمُ الأخلاقَ الإسلامية؟", "a": "١. لأنها سببٌ لمحبةِ اللهِ تعالى. في الحديث: «أحبُّ عبادِ اللهِ إلى اللهِ تعالى أحسنُهم خُلُقًا» رواه الحاكم والطبراني.\n٢. وسببٌ لمحبةِ الخلق.\n٣. وهي أثقلُ شيءٍ في الميزان. في الحديث: «أثقلُ شيءٍ في الميزانِ يومَ القيامةِ خُلُقٌ حسن» رواه أبو داود والترمذي.\n٤. وتتضاعفُ الأجرُ والثوابُ بحسنِ الخلق. في الحديث: «إنَّ المؤمنَ يدركُ بحسنِ خُلُقِهِ درجاتِ قائمِ الليلِ صائمِ النهار» رواه أحمد."}, {"id": 183, "q": "من أين نأخذُ الأخلاق؟", "a": "من القرآنِ الكريم، قال تعالى: ﴿إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾ [الإسراء: ٩].\nومن السنةِ النبوية، حيث قال رسولُ الله ﷺ: «إنما بُعِثتُ لأتمِّمَ صالحَ الأخلاق» رواه أحمد."}, {"id": 184, "q": "ما هو خُلُقُ الإحسانِ وصوره؟", "a": "الإحسان: هو مراقبةُ الله على الدوام، وبذلُ الخيرِ والإحسانِ للمخلوقين. قال النبيُّ ﷺ: «إنَّ اللهَ كتبَ الإحسانَ على كلِّ شيء» رواه مسلم.\nمن صورِ الإحسان:\n• الإحسانُ في عبادةِ اللهِ تعالى، وذلك بالإخلاصِ في عبادته.\n• الإحسانُ إلى الوالدينِ بالقولِ والفعل.\n• الإحسانُ إلى الأرحامِ والأقارب.\n• الإحسانُ إلى الجار.\n• الإحسانُ إلى اليتامى والمساكين.\n• الإحسانُ إلى المسيءِ إليك.\n• الإحسانُ في الكلام.\n• الإحسانُ في الجدال.\n• الإحسانُ إلى الحيوان."}, {"id": 185, "q": "ما مضادُّ الإحسان؟", "a": "ضدُّ الإحسانِ الإساءة. ومن ذلك:\n• تركُ الإخلاصِ في عبادةِ اللهِ تعالى.\n• وعقوقُ الوالدين.\n• وقطعُ الأرحام.\n• وسوءُ الجوار.\n• وتركُ الإحسانِ إلى الفقراءِ والمساكينِ وغيرِ ذلك من سيءِ الأقوالِ والأعمال."}, {"id": 186, "q": "ما أنواعُ الأمانةِ وصورها؟", "a": "١. أمانةٌ في حفظِ حقوقِ اللهِ تعالى. صورها: الأمانةُ في أداءِ العباداتِ من الصلاة، والزكاة، والصيام، والحج، وغيرها مما افترضَ اللهُ علينا.\n٢. أمانةٌ في حفظِ حقوقِ الخلق:\n• من حفظِ أعراضِ الناس.\n• وأموالهم.\n• ودمائهم.\n• وأسرارهم، وجميعِ ما ائتمنكَ عليه الناس.\nقال تعالى في ذكرِ صفاتِ المفلحين: ﴿وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ﴾ [المؤمنون: ٨]."}, {"id": 187, "q": "ما ضدُّ الأمانة؟", "a": "الخيانة، وهي تضييعُ حقوقِ اللهِ تعالى وحقوقِ الناس. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنتُمْ تَعْلَمُونَ﴾ [الأنفال: ٢٧]. وقال النبيُّ ﷺ: «آيةُ المنافقِ ثلاث» — وذكرَ منها — «وإذا اؤتُمِنَ خان» متفق عليه."}, {"id": 188, "q": "ما هو خُلُقُ الصدق؟", "a": "هو الإخبارُ بما يطابقُ الواقع، أو الشيءُ على ما هو عليه.\nومن صوره:\n• الصدقُ في الحديثِ مع الناس.\n• الصدقُ في الوعد.\n• الصدقُ في كلِّ قولٍ وعمل.\nقال النبيُّ ﷺ: «إنَّ الصدقَ يهدي إلى البر، وإنَّ البرَّ يهدي إلى الجنة، وإنَّ الرجلَ ليَصدُقُ حتى يكونَ صِدِّيقًا» متفق عليه."}, {"id": 189, "q": "ما مضادُّ الصدق؟", "a": "الكذب، وهو خلافُ الحقيقة، من ذلك: الكذبُ على الناس، وإخلافُ المواعيد، وشهادةُ الزور.\nقال النبيُّ ﷺ: «وإنَّ الكذبَ يهدي إلى الفجور، وإنَّ الفجورَ يهدي إلى النار، وإنَّ الرجلَ ليَكذِبُ حتى يُكتَبَ عند الله كذابًا» متفق عليه. وقال ﷺ: «آيةُ المنافقِ ثلاث» — وذكرَ منها — «إذا حدَّثَ كذب، وإذا وعدَ أخلف» متفق عليه."}, {"id": 190, "q": "ما أنواعُ الصبر؟", "a": "• الصبرُ على طاعةِ اللهِ تعالى.\n• الصبرُ عن المعصية.\n• الصبرُ على الأقدارِ المؤلمة، وحمدُ اللهِ على كلِّ حال.\nقال تعالى: ﴿وَاللَّهُ يُحِبُّ الصَّابِرِينَ﴾ [آل عمران: ١٤٦]. وقال النبيُّ ﷺ: «عجبًا لأمرِ المؤمنِ إنَّ أمرَهُ كلَّهُ خير، وليس ذلك لأحدٍ إلا للمؤمن؛ إن أصابتْهُ سراءُ شكرَ فكان خيرًا له، وإن أصابتْهُ ضراءُ صبرَ فكان خيرًا له» رواه مسلم."}], "dyk": ["للأرضِ مجالٌ مغناطيسيٌّ يحميها من إشعاعاتِ الشمسِ الضارة، كالدرعِ غيرِ المرئي."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "أَحْمِلُ مِيزَانًا صَغِيرًا! وَجَوَابُ اللُّغْزِ الْمَاضِي: سَعْدُ بْنُ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ، مِنَ الْعَشَرَةِ الْمُبَشَّرِينَ بِالْجَنَّةِ."}, {"s": "anos", "t": "وَالْيَوْمَ نَتَعَلَّمُ حُسْنَ الْخُلُقِ. هَاتِ أَسْئِلَتَكَ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا فَضْلُ حُسْنِ الْخُلُقِ؟"}, {"s": "anos", "t": "قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا». رَوَاهُ التِّرْمِذِيُّ وَأَحْمَدُ."}, {"s": "fasih", "t": "وَلِمَاذَا نَلْتَزِمُ الْأَخْلَاقَ؟"}, {"s": "anos", "t": "لِأَنَّهَا سَبَبٌ لِمَحَبَّةِ اللَّهِ وَمَحَبَّةِ النَّاسِ، وَهِيَ أَثْقَلُ شَيْءٍ فِي الْمِيزَانِ يَوْمَ الْقِيَامَةِ، وَبِهَا يُدْرِكُ الْمُؤْمِنُ دَرَجَةَ قَائِمِ اللَّيْلِ صَائِمِ النَّهَارِ."}, {"s": "fasih", "t": "إِذَنِ الْخُلُقُ أَثْقَلُ مِنَ الذَّهَبِ وَالْجَبَلِ! وَمِنْ أَيْنَ نَأْخُذُ الْأَخْلَاقَ؟"}, {"s": "anos", "t": "مِنَ الْقُرْآنِ الَّذِي يَهْدِي لِلَّتِي هِيَ أَقْوَمُ، وَمِنَ السُّنَّةِ، قَالَ النَّبِيُّ: «إِنَّمَا بُعِثْتُ لِأُتَمِّمَ صَالِحَ الْأَخْلَاقِ»."}, {"s": "fasih", "t": "مَا الْإِحْسَانُ؟ وَمَا ضِدُّهُ؟"}, {"s": "anos", "t": "الْإِحْسَانُ: مُرَاقَبَةُ اللَّهِ دَائِمًا، وَبَذْلُ الْخَيْرِ لِلْخَلْقِ: فِي الْعِبَادَةِ، وَإِلَى الْوَالِدَيْنِ وَالْأَقَارِبِ وَالْجَارِ وَالْيَتِيمِ، وَحَتَّى الْمُسِيءِ وَالْحَيَوَانِ. وَضِدُّهُ الْإِسَاءَةُ، كَعُقُوقِ الْوَالِدَيْنِ، وَقَطْعِ الْأَرْحَامِ، وَسُوءِ الْجِوَارِ."}, {"s": "fasih", "t": "وَمَا أَنْوَاعُ الْأَمَانَةِ؟"}, {"s": "anos", "t": "أَمَانَةٌ فِي حُقُوقِ اللَّهِ، كَالصَّلَاةِ وَالصِّيَامِ، وَأَمَانَةٌ فِي حُقُوقِ النَّاسِ: أَعْرَاضِهِمْ، وَأَمْوَالِهِمْ، وَدِمَائِهِمْ، وَأَسْرَارِهِمْ. وَاسْمَعُوا صِفَةَ الْمُؤْمِنِينَ الْمُفْلِحِينَ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "23:8", "t": "وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ"}, {"s": "fasih", "t": "فَكُنْ أَمِينًا عَلَى مَا أُعْطِيتَ! وَمَا ضِدُّ الْأَمَانَةِ؟"}, {"s": "anos", "t": "الْخِيَانَةُ، وَهِيَ تَضْيِيعُ حُقُوقِ اللَّهِ وَحُقُوقِ النَّاسِ. وَمِنْ آيَةِ الْمُنَافِقِ: «إِذَا اؤْتُمِنَ خَانَ»."}, {"s": "fasih", "t": "وَمَا الصِّدْقُ؟"}, {"s": "anos", "t": "أَنْ أُخْبِرَ بِمَا يُطَابِقُ الْوَاقِعَ، فِي الْحَدِيثِ وَالْوَعْدِ وَكُلِّ قَوْلٍ وَعَمَلٍ. قَالَ النَّبِيُّ: «إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ». مُتَّفَقٌ عَلَيْهِ."}, {"s": "fasih", "t": "وَضِدُّهُ؟"}, {"s": "anos", "t": "الْكَذِبُ، وَإِخْلَافُ الْوَعْدِ، وَشَهَادَةُ الزُّورِ. وَالْكَذِبُ يَهْدِي إِلَى الْفُجُورِ، وَالْفُجُورُ يَهْدِي إِلَى النَّارِ."}, {"s": "fasih", "t": "وَالسُّؤَالُ الْأَخِيرُ: مَا أَنْوَاعُ الصَّبْرِ؟"}, {"s": "anos", "t": "صَبْرٌ عَلَى طَاعَةِ اللَّهِ، وَصَبْرٌ عَنِ الْمَعْصِيَةِ، وَصَبْرٌ عَلَى الْأَقْدَارِ الْمُؤْلِمَةِ مَعَ حَمْدِ اللَّهِ. وَأَمْرُ الْمُؤْمِنِ كُلُّهُ خَيْرٌ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ لِلْأَرْضِ مَجَالٌ مِغْنَاطِيسِيٌّ يَحْمِيهَا مِنْ إِشْعَاعَاتِ الشَّمْسِ الضَّارَّةِ، كَالدِّرْعِ غَيْرِ الْمَرْئِيِّ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! دِرْعٌ يَحْمِينَا وَنَحْنُ لَا نَرَاهُ. وَالْآنَ نَشَاطُنَا: مِيزَانُ الْأَخْلَاقِ. اسْحَبُوا بِطَاقَةَ عَمَلٍ، وَضَعُوهَا فِي كِفَّةِ الْخَيْرِ أَوِ ارْفُضُوهَا، وَسَمُّوا الْخُلُقَ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: ميزان الأخلاق"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! وَجَدْتَ مِحْفَظَةَ زَمِيلِكَ وَفِيهَا نُقُودٌ. أ: تَأْخُذُهَا، لَا أَحَدَ يَرَاكَ. ب: تُرْجِعُهَا لِصَاحِبِهَا أَوْ لِلْمُعَلِّمِ كَامِلَةً. ج: تُخْفِيهَا لِتُخِيفَهُ مَازِحًا. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: المال الذي وجدته"}, {"s": "anos", "t": "أ خِيَانَةٌ، وَج تَرْوِيعٌ لِأَخِيكَ. أَمَّا ب فَهِيَ الْأَمَانَةُ الْجَمِيلَةُ!"}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَا أَثْقَلُ شَيْءٍ فِي الْمِيزَانِ؟ فَكِّرُوا…"}, {"s": "anos", "t": "الْخُلُقُ الْحَسَنُ! وَمَا ضِدُّ الْأَمَانَةِ؟ فَكِّرُوا… الْخِيَانَةُ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: أَلْقَانِي إِخْوَتِي فِي الْبِئْرِ حَسَدًا، وَرَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا تَسْجُدُ لِي، وَصِرْتُ عَزِيزَ مِصْرَ. مُوسَى، أَمْ يُوسُفُ، أَمْ إِبْرَاهِيمُ، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ ازْرَعُوا «شَجَرَةَ الْأَخْلَاقِ الْعَائِلِيَّةَ»، وَالْعَبُوا «مِيزَانَ فَصِيح» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 23, "title": "الصبر والتعاون والحياء والرحمة والتواضع", "season": 3, "goals": ["akhlaq"], "hook": "أهلًا يا أصدقاء! فصيح اليوم يرفرف بجناحيه ويقول: «عشرة أخلاق… عشرة أخلاق في حلقة واحدة!». بعضها نحبّه ونلبسه كالثوب الجميل، وبعضها نرميه بعيدًا. هل أنتم مستعدّون لرحلة الأخلاق مع أنوس؟", "sections": [{"h": "الصبر… وضدّه", "p": ["تعلّمنا من قبل أنّ الصبر جميل. واليوم يسأل فصيح: «وما ضدّ الصبر؟». ضدّ الصبر ثلاثة أشياء: <b>ألّا أصبر على الطاعة</b>، مثل أن أترك الصلاة لأني تعبت. و<b>ألّا أصبر عن المعصية</b>، مثل أن أكذب لأني خفت. و<b>التسخّط على قدر الله</b> بالقول أو الفعل، مثل أن أصرخ وأغضب وأقول كلامًا سيّئًا إذا مرضت أو انكسرت لعبتي.", "ومن صور عدم الصبر: <b>تمنّي الموت</b> بسبب مصيبة. فالمؤمن لا يتمنّى الموت، بل يصبر ويقول: الحمد لله، ويدعو الله أن يفرّج عنه."], "board": ["أصبر على الطاعة", "أصبر عن المعصية", "لا أتسخّط"]}, {"h": "التعاون: يدٌ مع يد", "p": ["<b>التعاون</b> أن يساعد الناس بعضهم بعضًا على <b>الحقّ والخير</b>. أنوس يحمل مع أخيه الصندوق الثقيل، وفصيح ينظّف القفص مع صديقه!", "ومن صور التعاون: أن نتعاون في ردّ الحقوق إلى أصحابها، وفي منع الظالم من ظلمه، وفي مساعدة المساكين والمحتاجين، وفي كل خير. لكن انتبه: <b>لا نتعاون على الإثم والأذى</b>؛ فإذا قال لك صاحبك: «ساعدني لأخبّئ حقيبة زميلنا»، فقل له: لا.", "وقال النبيّ ﷺ: «المؤمن للمؤمن كالبنيان؛ يشدّ بعضه بعضًا». مثل الطوب في الجدار، كل طوبة تمسك أختها."], "board": ["تعاون على الخير", "لا تعاون على الأذى"]}, {"h": "الحياء والرحمة والمحبّة والبشاشة", "p": ["<b>الحياء نوعان</b>: حياء من الله، بأن لا أعصيه وهو يراني. وحياء من الناس، بأن أترك الكلام القبيح، وأستر عورتي. و<b>الحياء شعبة من الإيمان</b>.", "و<b>الرحمة</b> لها صور: أحترم الكبير وأوقّره، وأرحم الصغير، وأرحم الفقير والمحتاج، وأرحم الحيوان فأطعمه ولا أؤذيه. وقال النبيّ ﷺ: «الراحمون يرحمهم الرحمن».", "و<b>المحبّة</b>: أحبّ الله أكثر من كل شيء، وأحبّ الرسول ﷺ أكثر من أبي وأمّي والناس جميعًا، وأحبّ للمؤمنين الخير كما أحبّه لنفسي.", "و<b>البشاشة</b>: وجه مبتسم فرحان عند لقاء الناس. فصيح يقول: «ابتسامتك صدقة!». نعم، قال ﷺ: «تبسّمك في وجه أخيك لك صدقة»."], "board": ["حياء", "رحمة", "محبّة", "بشاشة"]}, {"h": "احذر: الحسد والاستهزاء والكِبْر", "p": ["<b>الحسد</b>: أن تتمنّى أن تزول النعمة عن غيرك، أو تكره أن يكون عنده خير. إذا رأيت دراجة صديقك الجديدة فقل: «ما شاء الله، بارك الله لك»، ولا تحسده.", "و<b>الاستهزاء</b>: أن تسخر من أخيك وتحقّره، وهذا لا يجوز؛ فربّما كان هو خيرًا منك عند الله.", "و<b>التواضع</b>: ألّا ترى نفسك أفضل من الناس، فلا تحتقر أحدًا ولا ترفض الحقّ. وضدّه <b>الكِبْر</b>، وهو نوعان: كبر على الحقّ، أي ردّه وعدم قبوله، وكبر على الناس، أي احتقارهم. وقال ﷺ: «لا يدخل الجنة من كان في قلبه مثقال ذرّة من كبر».", "وأنوس يحبّ ثوبه الجميل وحذاءه النظيف، فهل هذا كبر؟ لا! فالثوب الحسن ليس من الكبر، «إنّ الله جميل يحبّ الجمال»."], "board": ["لا حسد", "لا سخرية", "تواضع لا كِبْر"]}], "summary": ["ضدّ الصبر: ترك الصبر على الطاعة وعن المعصية، والتسخّط على قدر الله، ومنه تمنّي الموت.", "نتعاون على الخير لا على الأذى، ونتخلّق بالحياء والرحمة والمحبّة والبشاشة.", "نحذر الحسد والاستهزاء والكبر، ونتواضع، والثوب الحسن ليس من الكبر."], "islam": {"intro": "قال الله تعالى يأمرنا بالتعاون على الخير:", "text": "فكن مع أصدقائك فريقًا للخير: تساعدون المحتاج، وتنصحون المخطئ، ولا يجرّ أحدكم الآخر إلى الأذى.", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًۭا مِّن رَّبِّهِمْ وَرِضْوَٰنًۭا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", "src": "سُورَةُ المَائـِدَةِ: ٢"}, "hadith": {"text": "تبسّمك في وجه أخيك لك صدقة", "source": "رواه الترمذي"}}, "home": {"title": "صندوق الابتسامات", "goal": "أن يطبّق الطفل خُلُق البشاشة والرحمة في البيت أسبوعًا كاملًا.", "materials": ["علبة صغيرة", "أوراق ملوّنة صغيرة"], "steps": ["زيّن العلبة واكتب عليها: «صندوق الابتسامات».", "كل يوم اكتب ورقة صغيرة: ابتسمت لمن؟ وساعدت مَن؟ ورحمت مَن؟ (جدّتي، أخي الصغير، قطّة الجيران…).", "ضع الورقة في الصندوق قبل النوم.", "في آخر الأسبوع افتح الصندوق مع أسرتك، واقرؤوا الأوراق، وقولوا: «تبسّمك في وجه أخيك لك صدقة»."], "parent": "شاركوا طفلكم بأوراقكم أنتم أيضًا، وامدحوا كل عمل رحيم صغير؛ فالقدوة في البيت أقوى من أي كلام."}, "online": {"title": "حديقة الأخلاق", "intro": "ساعد أنوس وفصيحًا على تنظيف حديقة الأخلاق: ازرع الحسن، وأبعد السيّئ!", "steps": [{"type": "sort", "title": "خُلُق حسن أم خُلُق سيّئ؟", "prompt": "اضغط على البطاقة، ثم اختر مكانها.", "bins": ["خُلُق حسن نحبّه", "خُلُق سيّئ نحذره"], "items": [{"t": "أبتسم لصديقي", "icon": "😊", "bin": 0, "why": "البشاشة صدقة."}, {"t": "أطعم القطّة ولا أؤذيها", "icon": "🐈", "bin": 0, "why": "من الرحمة رحمة الحيوان."}, {"t": "أساعد أمّي في ترتيب البيت", "icon": "🤝", "bin": 0, "why": "التعاون على الخير."}, {"t": "أسخر من ملابس زميلي", "icon": "🙊", "bin": 1, "why": "الاستهزاء لا يجوز."}, {"t": "أتمنّى أن تضيع لعبة أخي", "icon": "😠", "bin": 1, "why": "هذا حسد: تمنّي زوال النعمة."}, {"t": "أرفض النصيحة الصحيحة", "icon": "🙅", "bin": 1, "why": "ردّ الحقّ من الكبر."}]}, {"type": "match", "title": "صِل الخُلُق بمعناه", "prompt": "اختر الخُلُق، ثم معناه الصحيح.", "pairs": [["التعاون", "أن نساعد بعضنا على الحقّ والخير"], ["التواضع", "ألّا أرى نفسي فوق الناس"], ["البشاشة", "وجه مبتسم عند لقاء الناس"], ["الحسد", "تمنّي زوال النعمة عن الغير"], ["الحياء من الله", "ألّا أعصيه سبحانه"]]}, {"type": "quiz", "title": "تحدّي فصيح", "items": [{"q": "مَن نحترم ونوقّر؟", "o": ["الصغير فقط", "لا أحد", "الكبير"], "a": 2, "why": "«ليس منّا من لم يوقّر كبيرنا ويرحم صغيرنا»."}, {"q": "الكبر على الناس معناه:", "o": ["احتقارهم", "مساعدتهم", "السلام عليهم"], "a": 0, "why": "غمط الناس: احتقارهم."}, {"q": "المؤمن الحقّ يحبّ لأخيه…", "o": ["الشرّ", "ما يحبّ لنفسه", "أن يخسر"], "a": 1, "why": "«لا يؤمن أحدكم حتى يحبّ لأخيه ما يحبّ لنفسه»."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عن نبيّ كريم صار مثلًا في الصبر. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا نبيّ ابتلاني الله بالمرض سنين طويلة.", "فقدت مالي وأولادي، لكني لم أتسخّط وصبرت.", "صرت مثلًا يضربه الناس في الصبر."], "options": ["يونس عليه السلام", "أيوب عليه السلام", "زكريا عليه السلام"], "deep": "ما الفرق بين المريض الذي يصبر ويقول: الحمد لله، والمريض الذي يتسخّط ويتمنّى الموت؟", "reveal": "أنا أيوب عليه السلام! دعوت ربي بأدب وقلت: «أنّي مسّني الضرّ وأنت أرحم الراحمين»، فشفاني الله وأعاد إليّ أهلي. وفي الحلقة القادمة نتعلّم أخلاقًا سيّئة يجب أن نحذرها: الغشّ والغيبة والنميمة والغضب."}, "quiz": [{"q": "أيّ هذه من صور عدم الصبر؟", "o": ["أن أقول: الحمد لله", "تمنّي الموت بسبب مصيبة", "أن أدعو الله"], "a": 1, "why": "من صور عدم الصبر تمنّي الموت، كما في الكتاب."}], "qa": [{"id": 191, "q": "ما ضدُّ الصبر؟", "a": "هو عدمُ الصبرِ على الطاعة، وعدمُ الصبرِ عن المعصية، والتسخطُ على الأقدارِ بالقولِ أو الفعل.\nمن صوره: تمنّي الموت."}, {"id": 192, "q": "ما هو خُلُقُ التعاون؟", "a": "هو تعاونُ الناسِ فيما بينهم على الحقِّ والخير.\nصورُ التعاون:\n• التعاونُ في ردِّ الحقوق.\n• التعاونُ في ردِّ الظالم.\n• التعاونُ في سدِّ حاجاتِ الناسِ والمساكين.\n• التعاونُ على كلِّ خير.\n• عدمُ التعاونِ على الإثمِ والأذى والعدوان.\nقال تعالى: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ﴾ [المائدة: ٢]. وقال ﷺ: «المؤمنُ للمؤمنِ كالبنيان؛ يشدُّ بعضُهُ بعضًا» متفق عليه. وقال ﷺ: «المسلمُ أخو المسلم، لا يظلمُه، ولا يُسلِمُه، ومن كان في حاجةِ أخيه كان اللهُ في حاجته، ومن فرَّجَ عن مسلمٍ كربةً فرَّجَ اللهُ عنه كربةً من كرباتِ يومِ القيامة، ومن سترَ مسلمًا سترَهُ اللهُ يومَ القيامة» متفق عليه."}, {"id": 193, "q": "ما أنواعُ خُلُقِ الحياء؟", "a": "١. الحياءُ من الله: يكونُ بأن لا تعصيَهُ سبحانه.\n٢. الحياءُ من الناس: ومن ذلك تركُ الكلامِ الفاحشِ البذيءِ وكشفِ العورة.\nقال رسولُ الله ﷺ: «الإيمانُ بضعٌ وسبعون» — أو: «بضعٌ وستون» — «شعبة، أعلاها: قولُ لا إله إلا الله، وأدناها: إماطةُ الأذى عن الطريق، والحياءُ شعبةٌ من الإيمان» رواه مسلم."}, {"id": 194, "q": "ما صورُ خُلُقِ الرحمة؟", "a": "• رحمةُ كبارِ السنِّ وتوقيرهم.\n• رحمةُ صغارِ السنِّ والأطفال. في الحديث: «ليس منا من لم يوقِّرْ كبيرَنا، ويرحمْ صغيرَنا» رواه أحمد.\n• رحمةُ الفقيرِ والمسكينِ والمحتاج.\n• رحمةُ الحيوانِ بأن تطعمَهُ ولا تؤذيه.\nمن ذلك قولُ النبيِّ ﷺ: «ترى المؤمنينَ في تراحمِهم وتوادِّهم وتعاطفِهم كمثلِ الجسد، إذا اشتكى منه عضوٌ تداعى له سائرُ الجسدِ بالسهرِ والحمى» متفق عليه. وقال ﷺ: «الراحمونَ يرحمُهمُ الرحمن، ارحموا أهلَ الأرض، يرحمْكم من في السماء» رواه أبو داود والترمذي."}, {"id": 195, "q": "ما أنواعُ خُلُقِ المحبة؟", "a": "• محبةُ اللهِ تعالى. قال تعالى: ﴿وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِّلَّهِ﴾ [البقرة: ١٦٥].\n• محبةُ الرسولِ ﷺ. قال ﷺ: «والذي نفسي بيده، لا يؤمنُ أحدُكم حتى أكونَ أحبَّ إليه من والدِهِ وولدِه» رواه البخاري.\n• محبةُ المؤمنين، ومحبةُ الخيرِ لهم كما تحبُّهُ لنفسك. قال ﷺ: «لا يؤمنُ أحدُكم حتى يحبَّ لأخيهِ ما يحبُّ لنفسه» رواه البخاري."}, {"id": 196, "q": "ما هي البشاشة؟", "a": "هي طلاقةُ الوجه، مع الفرحِ والتبسمِ واللطفِ وإظهارِ السرورِ عند لقاءِ الناس. وهي بعكسِ العبوسِ في وجهِ الناسِ مما ينفِّرُهم.\nوفي فضلِ ذلك جاءتِ الأحاديث، فعن أبي ذرٍّ قال: قال لي النبيُّ ﷺ: «لا تحقرنَّ من المعروفِ شيئًا، ولو أن تلقى أخاكَ بوجهٍ طلق» رواه مسلم. وقال ﷺ: «تبسمُكَ في وجهِ أخيكَ لك صدقة» رواه الترمذي."}, {"id": 197, "q": "ما هو الحسد؟", "a": "هو تمنّي زوالِ النعمةِ عن الغير، أو كراهيةُ النعمةِ على الغير. قال تعالى: ﴿وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ [الفلق: ٥]. وعن أنسِ بنِ مالكٍ أنَّ رسولَ الله ﷺ قال: «لا تباغضوا، ولا تحاسدوا، ولا تدابروا، وكونوا — عبادَ اللهِ — إخوانًا» رواه البخاري ومسلم."}, {"id": 198, "q": "ما هو الاستهزاء؟", "a": "هو السخريةُ من أخيكَ المسلمِ وتحقيره، وهذا لا يجوز. قال تعالى في النهي عن ذلك: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰ أَن يَكُونُوا خَيْرًا مِّنْهُمْ وَلَا نِسَاءٌ مِّن نِّسَاءٍ عَسَىٰ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ وَلَا تَلْمِزُوا أَنفُسَكُمْ وَلَا تَنَابَزُوا بِالْأَلْقَابِ بِئْسَ الِاسْمُ الْفُسُوقُ بَعْدَ الْإِيمَانِ وَمَن لَّمْ يَتُبْ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ﴾ [الحجرات: ١١]."}, {"id": 199, "q": "ما هو التواضع؟", "a": "هو أن لا يرى الإنسانُ نفسَهُ على الناس، فلا يستحقرَ الناسَ ولا يرفضَ الحق. قال تعالى: ﴿وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا﴾ [الفرقان: ٦٣]، أي: متواضعين."}, {"id": 200, "q": "ما أنواعُ الكِبْرِ المحرَّم؟", "a": "١. الكِبْرُ على الحق، وهو ردُّ الحقِّ وعدمُ قبوله.\n٢. الكِبْرُ على الناس، وهو احتقارُهم والاستهانةُ بهم.\nقال رسولُ الله ﷺ: «لا يدخلُ الجنةَ من كان في قلبِهِ مثقالُ ذرةٍ من كِبْر». فقال رجل: إنَّ الرجلَ يحبُّ أن يكونَ ثوبُهُ حسنًا ونعلُهُ حسنة؟ قال: «إنَّ اللهَ جميلٌ يحبُّ الجمال، الكِبْرُ: بطَرُ الحق، وغَمْطُ الناس» رواه مسلم.\n• بطَرُ الحق: ردُّه. • غَمْطُ الناس: استحقارُهم. • الثوبُ الحسنُ والنعلُ الحسنُ ليس من الكِبْر."}], "dyk": ["دماغُك فيه مليارات الخلايا، ويعملُ حتى وأنتَ نائم، وسرعةُ إشاراتِه أسرعُ من السيارة!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح!"}, {"s": "fasih", "t": "عَشَرَةُ أَخْلَاقٍ فِي حَلْقَةٍ وَاحِدَةٍ! وَجَوَابُ اللُّغْزِ الْمَاضِي: يُوسُفُ عَلَيْهِ السَّلَامُ، صَبَرَ عَلَى الْبِئْرِ وَالسِّجْنِ، ثُمَّ عَفَا عَنْ إِخْوَتِهِ."}, {"s": "anos", "t": "هَيَّا إِلَى رِحْلَةِ الْأَخْلَاقِ. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا ضِدُّ الصَّبْرِ؟"}, {"s": "anos", "t": "عَدَمُ الصَّبْرِ عَلَى الطَّاعَةِ، وَعَنِ الْمَعْصِيَةِ، وَالتَّسَخُّطُ عَلَى الْأَقْدَارِ بِالْقَوْلِ أَوِ الْفِعْلِ، وَمِنْ صُوَرِهِ تَمَنِّي الْمَوْتِ."}, {"s": "fasih", "t": "وَمَا التَّعَاوُنُ؟"}, {"s": "anos", "t": "أَنْ يَتَعَاوَنَ النَّاسُ عَلَى الْحَقِّ وَالْخَيْرِ: فِي رَدِّ الْحُقُوقِ، وَرَدِّ الظَّالِمِ، وَسَدِّ حَاجَاتِ الْمَسَاكِينِ، لَا عَلَى الْإِثْمِ وَالْعُدْوَانِ. اسْمَعُوا الْآيَةَ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "5:2", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًۭا مِّن رَّبِّهِمْ وَرِضْوَٰنًۭا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ"}, {"s": "fasih", "t": "فَكُنْ مَعَ أَصْدِقَائِكَ فَرِيقًا لِلْخَيْرِ! فَالْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا. وَمَا أَنْوَاعُ الْحَيَاءِ؟"}, {"s": "anos", "t": "الْحَيَاءُ مِنَ اللَّهِ بِأَلَّا نَعْصِيَهُ، وَالْحَيَاءُ مِنَ النَّاسِ بِتَرْكِ الْكَلَامِ الْبَذِيءِ وَسَتْرِ الْعَوْرَةِ. وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ."}, {"s": "fasih", "t": "وَصُوَرُ الرَّحْمَةِ؟"}, {"s": "anos", "t": "نُوَقِّرُ الْكَبِيرَ، وَنَرْحَمُ الصَّغِيرَ وَالْفَقِيرَ وَالْحَيَوَانَ. «الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ، ارْحَمُوا أَهْلَ الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ»."}, {"s": "fasih", "t": "وَأَنْوَاعُ الْمَحَبَّةِ؟"}, {"s": "anos", "t": "مَحَبَّةُ اللَّهِ، وَمَحَبَّةُ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَحَبَّةُ الْمُؤْمِنِينَ، وَأَنْ نُحِبَّ لَهُمُ الْخَيْرَ كَمَا نُحِبُّهُ لِأَنْفُسِنَا."}, {"s": "fasih", "t": "وَمَا الْبَشَاشَةُ؟ انْظُرْ إِلَى وَجْهِي!"}, {"s": "anos", "t": "طَلَاقَةُ الْوَجْهِ وَالتَّبَسُّمُ عِنْدَ لِقَاءِ النَّاسِ، عَكْسُ الْعُبُوسِ. قَالَ النَّبِيُّ: «تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ». رَوَاهُ التِّرْمِذِيُّ."}, {"s": "fasih", "t": "وَالْآنَ أَخْلَاقٌ نَرْمِيهَا بَعِيدًا! مَا الْحَسَدُ؟"}, {"s": "anos", "t": "تَمَنِّي زَوَالِ النِّعْمَةِ عَنِ الْغَيْرِ، أَوْ كَرَاهِيَتُهَا لَهُ. قَالَ النَّبِيُّ: «لَا تَحَاسَدُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا»."}, {"s": "fasih", "t": "وَالِاسْتِهْزَاءُ؟"}, {"s": "anos", "t": "السُّخْرِيَةُ مِنْ أَخِيكَ الْمُسْلِمِ وَتَحْقِيرُهُ، وَهُوَ لَا يَجُوزُ، فَقَدْ نَهَى اللَّهُ عَنْهُ فِي سُورَةِ الْحُجُرَاتِ، وَلَعَلَّهُ خَيْرٌ مِنْكَ."}, {"s": "fasih", "t": "وَمَا التَّوَاضُعُ؟"}, {"s": "anos", "t": "أَلَّا يَرَى الْإِنْسَانُ نَفْسَهُ فَوْقَ النَّاسِ، فَلَا يَحْتَقِرُهُمْ وَلَا يَرُدُّ الْحَقَّ، وَعِبَادُ الرَّحْمَنِ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا."}, {"s": "fasih", "t": "وَأَنْوَاعُ الْكِبْرِ الْمُحَرَّمِ؟"}, {"s": "anos", "t": "الْكِبْرُ عَلَى الْحَقِّ بِرَدِّهِ، وَالْكِبْرُ عَلَى النَّاسِ بِاحْتِقَارِهِمْ. أَمَّا الثَّوْبُ الْحَسَنُ فَلَيْسَ كِبْرًا، فَـ«إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ». رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ دِمَاغُكَ فِيهِ مِلْيَارَاتُ الْخَلَايَا، وَيَعْمَلُ حَتَّى وَأَنْتَ نَائِمٌ، وَإِشَارَاتُهُ أَسْرَعُ مِنَ السَّيَّارَةِ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: جِدَارُ الْبُنْيَانِ. اكْتُبُوا عَلَى كُلِّ طُوبَةٍ خُلُقًا حَسَنًا، وَابْنُوا الْجِدَارَ، وَاذْكُرُوا مِثَالًا مِنْ حَيَاتِكُمْ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَابْنُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: جدار البنيان"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! جَاءَ سَالِمٌ بِدَرَّاجَةٍ جَدِيدَةٍ، وَلَيْسَ عِنْدَكَ دَرَّاجَةٌ. أ: تَتَمَنَّى أَنْ تَنْكَسِرَ. ب: تَسْخَرُ مِنْ لَوْنِهَا. ج: تَقُولُ: مَا شَاءَ اللَّهُ، بَارَكَ اللَّهُ لَكَ، وَتَدْعُو أَنْ يَرْزُقَكَ مِثْلَهَا. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الدراجة الجديدة"}, {"s": "anos", "t": "أ حَسَدٌ، وَب اسْتِهْزَاءٌ، وَكِلَاهُمَا لَا يَجُوزُ. أَمَّا ج فَهُوَ الصَّحِيحُ: مَحَبَّةُ الْخَيْرِ لِأَخِيكَ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: عَلَى مَاذَا نَتَعَاوَنُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "عَلَى الْبِرِّ وَالتَّقْوَى! وَهَلِ الثَّوْبُ الْجَمِيلُ كِبْرٌ؟ فَكِّرُوا… لَا، لَيْسَ مِنَ الْكِبْرِ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: نَبِيٌّ ابْتَلَانِيَ اللَّهُ بِالْمَرَضِ سِنِينَ طَوِيلَةً، وَفَقَدْتُ مَالِي وَأَوْلَادِي فَصَبَرْتُ، وَصِرْتُ مَثَلًا فِي الصَّبْرِ. يُونُسُ، أَمْ أَيُّوبُ، أَمْ زَكَرِيَّا، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ امْلَؤُوا «صُنْدُوقَ الِابْتِسَامَاتِ»، وَنَظِّفُوا «حَدِيقَةَ الْأَخْلَاقِ» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 24, "title": "احذر: الغشّ والغيبة والنميمة والغضب", "season": 3, "goals": ["akhlaq"], "hook": "أنوس يرفع لافتة حمراء كبيرة مكتوبًا عليها: «احذر!». وفصيح يصيح: «خطر… خطر… أخلاق سيّئة تقترب!». اليوم نتعلّم كيف نكتشفها ونطردها بعيدًا عن قلوبنا وألسنتنا. هيّا بنا!", "sections": [{"h": "الغشّ: ممنوع في كل مكان", "p": ["فصيح يسأل: «ما الغشّ؟». الغشّ أن تُظهر شيئًا غير الحقيقة لتخدع الناس. ومن صوره: الغشّ في <b>البيع والشراء</b> بإخفاء عيب السلعة، والغشّ في <b>الامتحان</b>، والغشّ في <b>القول</b> مثل شهادة الزور والكذب، و<b>عدم الوفاء</b> بما اتفقت عليه مع الناس.", "مرّ النبيّ ﷺ على كومة طعام، فأدخل يده فيها فوجد أسفلها مبلولًا، فقال: «أفلا جعلته فوق الطعام كي يراه الناس؟ من غشّ فليس مني».", "فإذا نسيت الجواب في الامتحان، فاكتب ما تعرفه بصدق، ولا تنظر في ورقة صديقك."], "board": ["لا غشّ في البيع", "لا غشّ في الامتحان", "أفي بوعدي"]}, {"h": "اللسان: الغيبة والنميمة والكلام القبيح", "p": ["<b>الغيبة</b>: أن تذكر أخاك المسلم بما يكره وهو غائب. مثل أن تقول: «فلان كسول» وهو ليس معنا. وقد شبّهها الله بأمر قبيح جدًّا: أكل لحم الأخ الميت!", "و<b>النميمة</b>: أن تنقل الكلام بين الناس لتُفسد بينهم. مثل أن تذهب إلى سارة فتقول: «قالت عنك هند كذا» لتتخاصما. وقال ﷺ: «لا يدخل الجنة نمّام».", "و<b>التجسّس</b>: أن تبحث عن أسرار الناس، مثل أن تنظر في بيوتهم، أو تستمع إلى حديثهم وهم لا يعلمون. قال تعالى: «ولا تجسّسوا».", "ومن <b>أقوال اللسان المحرّمة</b>: اللعن والسبّ، وقول: «فلان حيوان»، والكلام الفاحش. قال ﷺ: «ليس المؤمن بالطعّان ولا اللعّان ولا الفاحش ولا البذيء»."], "board": ["لا غيبة", "لا نميمة", "لا تجسّس", "لا لعن ولا سبّ"]}, {"h": "الغضب: متى يُحمد ومتى يُذمّ؟", "p": ["الغضب نوعان: <b>غضب محمود</b>، وهو الغضب لله إذا انتُهكت حرماته. و<b>غضب مذموم</b>، وهو الذي يجعلك تفعل وتقول ما لا ينبغي، مثل أن تضرب أخاك لأنه أخذ قلمك.", "فماذا أفعل إذا غضبت؟ أنوس عنده «خطّة الهدوء»: <b>أستعيذ بالله من الشيطان الرجيم</b>، و<b>أسكت</b>، و<b>أجلس</b> إن كنت واقفًا، و<b>أضطجع</b> إن كنت جالسًا، و<b>أتوضّأ</b>، وأتذكّر وصية النبيّ ﷺ: «<b>لا تغضب</b>»، وأمسك نفسي فلا أندفع."], "board": ["أستعيذ", "أسكت", "أجلس", "أتوضّأ"]}, {"h": "الكسل والإسراف والبخل والجبن", "p": ["<b>الكسل</b>: أن تتثاقل عن فعل الخير وما يجب عليك، مثل التكاسل عن الصلاة. والمؤمن نشيط مجتهد.", "<b>الإسراف</b>: أن تنفق المال في غير حقّه، و<b>البخل</b>: أن تمسك المال عن حقّه. والصحيح هو الوسط: أن تكون <b>كريمًا</b>. فلا ترمِ نصف طعامك، ولا تمنع صديقك قطعة من حلواك.", "<b>الجبن</b>: أن تخاف ممّا لا ينبغي أن تخاف منه، مثل الخوف من قول الحقّ. و<b>الشجاعة</b>: الإقدام على الحقّ. وقال ﷺ: «المؤمن القويّ خير وأحبّ إلى الله من المؤمن الضعيف، وفي كلّ خير»."], "board": ["نشاط لا كسل", "كرم بلا إسراف", "شجاعة في الحقّ"]}, {"h": "كيف أصير صاحب خُلُق حسن؟", "p": ["فصيح يسأل: «وكيف أتخلّق بالأخلاق الحسنة؟». الكتاب يعطينا سبعة أسباب: <b>الدعاء</b> بأن يرزقك الله حسن الخلق، و<b>مراقبة الله</b> فهو يسمعك ويراك، وتذكّر أنّ حسن الخلق سبب لدخول <b>الجنة</b>، وأنّ سوء الخلق سبب لدخول <b>النار</b>، وأنّ حسن الخلق يجلب محبّة الله ومحبّة الناس، وقراءة <b>سيرة النبيّ ﷺ</b> والاقتداء به، و<b>مصاحبة الأخيار</b> وترك صحبة الأشرار."], "board": ["الدعاء", "مراقبة الله", "السيرة", "الصحبة الطيّبة"]}], "summary": ["الغشّ محرّم في البيع والامتحان والقول والوعد: «من غشّ فليس مني».", "الغيبة والنميمة والتجسّس واللعن والسبّ كلّها محرّمة، ونحفظ ألسنتنا منها.", "نعالج الغضب بالاستعاذة والسكوت والجلوس والوضوء، ونكون كرماء شجعانًا نشيطين."], "islam": {"intro": "قال الله تعالى ينهانا عن التجسّس والغيبة:", "text": "فإذا بدأ أحد يتكلّم عن غائب بسوء، فغيّر الموضوع بلطف، أو قل: «لنذكره بخير».", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ", "src": "سُورَةُ الحُجُرَاتِ: ١٢"}, "hadith": {"text": "من غشّ فليس مني", "source": "رواه مسلم"}}, "home": {"title": "حارس اللسان", "goal": "أن يراقب الطفل لسانه ويحفظه من الغيبة والنميمة واللعن أسبوعًا.", "materials": ["ورقة جدول بأيام الأسبوع", "ملصقات نجوم"], "steps": ["اكتب في الجدول: «اليوم حفظت لساني من: الغيبة، النميمة، اللعن والسبّ».", "كل مساء اجلس مع أسرتك دقيقتين، وفكّر: هل حفظت لساني اليوم؟", "ضع نجمة لكل يوم نجحت فيه، وإن أخطأت فاستغفر الله وابدأ من جديد.", "اتّفق مع أسرتك على كلمة سرّ مرحة، مثل «فصيح يسمع!»، يقولها أيّ واحد إذا بدأ أحد يغتاب."], "parent": "كونوا قدوة في ترك الغيبة أمام أطفالكم، وذكّروهم بلطف لا بتوبيخ، وامدحوا كل يوم ناجح."}, "online": {"title": "دوريّة أنوس", "intro": "ساعد أنوس في دوريّة الأخلاق: اكتشف الخطأ، واختر التصرّف الحكيم!", "steps": [{"type": "match", "title": "صِل الخُلُق السيّئ بمثاله", "prompt": "اختر الخُلُق، ثم المثال المناسب له.", "pairs": [["الغشّ", "إخفاء عيب اللعبة عند بيعها"], ["الغيبة", "«فلان كسول» وهو غائب"], ["النميمة", "نقل الكلام لتتخاصم صديقتان"], ["التجسّس", "الاستماع إلى حديث قوم دون علمهم"], ["الإسراف", "رمي نصف الطعام في القمامة"]]}, {"type": "decision", "title": "مختبر القرار: القلم المكسور", "scenario": "أخذ أخوك الصغير قلمك المفضّل وكسره، فشعرت بالغضب الشديد. ماذا تفعل؟", "options": [{"t": "أصرخ عليه وأضربه", "result": "هذا غضب مذموم يجعلك تفعل ما لا ينبغي، وقد يؤذي أخاك."}, {"t": "أقول: أعوذ بالله من الشيطان الرجيم، وأسكت وأجلس، ثم أكلّمه بهدوء", "result": "أحسنت! هذا علاج الغضب كما علّمنا النبيّ ﷺ.", "best": true}, {"t": "أكسر لعبته لأنتقم منه", "result": "الانتقام يزيد المشكلة ولا يصلحها."}]}, {"type": "quiz", "title": "تحدّي فصيح", "items": [{"q": "قال ﷺ: «ليس المؤمن بالطعّان ولا…»", "o": ["اللعّان", "الكريم", "الصادق"], "a": 0, "why": "المؤمن لا يلعن ولا يسبّ."}, {"q": "الجبن هو…", "o": ["الإقدام على الحقّ", "الكرم", "الخوف من قول الحقّ"], "a": 2, "why": "الجبن أن تخاف ممّا لا ينبغي الخوف منه."}, {"q": "الكسل هو…", "o": ["النشاط في الخير", "التثاقل عن فعل الخير", "النوم ليلًا"], "a": 1, "why": "الكسل التثاقل عن الخير وما يجب فعله."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عن خليفة مسلم اشتهر بالعدل والخلق الحسن. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا خليفة عادل، ملأت الأرض عدلًا.", "قيل إنّ الذئب صار يرعى مع الغنم في زماني من كثرة العدل.", "يعدّني الناس خامس الخلفاء الراشدين."], "options": ["عمر بن الخطاب رضي الله عنه", "هارون الرشيد رحمه الله", "عمر بن عبد العزيز رحمه الله"], "deep": "لماذا يحبّ الناس الحاكم العادل؟ وكيف تكون عادلًا في بيتك ومدرستك؟", "reveal": "أنا عمر بن عبد العزيز رحمه الله! وأمّي من حفيدات عمر بن الخطاب رضي الله عنه، فتعلّمت العدل من سيرته. وفي الحلقة القادمة نبدأ رحلة «أذكار أحبّها»: من الاستيقاظ إلى الوضوء."}, "quiz": [{"q": "ما هي النميمة؟", "o": ["نقل الكلام بين الناس للإفساد بينهم", "السلام على الناس", "الدعاء للغائب"], "a": 0, "why": "النميمة نقل الأحاديث بين الناس للإفساد بينهم."}], "qa": [{"id": 201, "q": "ما بعضُ أنواعِ الغشِّ المحرَّم؟", "a": "• الغشُّ في البيعِ والشراء، وهو إخفاءُ عيبِ السلعة.\n• الغشُّ في تعلمِ العلم، ومثلُ ذلك غشُّ الطلابِ في الامتحانات.\n• الغشُّ في القولِ كشهادةِ الزورِ والكذب.\n• عدمُ الوفاءِ بما تقولُ وما تتفقُ به مع الناس.\nوفي النهي عن الغش: أنَّ رسولَ الله ﷺ مرَّ على صُبرةِ طعام، فأدخلَ يدَهُ فيها، فنالتْ أصابعُهُ بلَلًا، فقال: «ما هذا يا صاحبَ الطعام؟» قال: أصابتْهُ السماءُ يا رسولَ الله. قال: «أفلا جعلتَهُ فوقَ الطعامِ كي يراهُ الناس؟ من غشَّ فليس مني» رواه مسلم. (الصُّبرة: هي الكَوْمةُ من الطعام)."}, {"id": 202, "q": "ما هي الغِيبة؟", "a": "هي ذِكْرُ أخيكَ المسلمِ بما يكرهُ وهو غائب. قال تعالى: ﴿وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ تَوَّابٌ رَّحِيمٌ﴾ [الحجرات: ١٢]."}, {"id": 203, "q": "ما هي النميمة؟", "a": "هي نقلُ الأحاديثِ بين الناسِ للإفسادِ بينهم. قال رسولُ الله ﷺ: «لا يدخلُ الجنةَ نمَّام» رواه مسلم."}, {"id": 204, "q": "ما هو الكسل؟", "a": "هو التثاقلُ عن فعلِ الخيرِ وما يجبُ على الإنسانِ فعلُه. ومن ذلك: التكاسلُ في فعلِ الواجبات. قال تعالى: ﴿إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَىٰ يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا﴾ [النساء: ١٤٢]. فينبغي للمؤمنِ تركُ الكسلِ والخمولِ والقعود، والسعيُ في العملِ والحركة، والجدُّ والاجتهادُ في هذه الحياةِ بما يرضي اللهَ تعالى."}, {"id": 205, "q": "ما أنواعُ الغضب؟", "a": "١. غضبٌ محمود: وهو أن يكونَ لله إذا انتهكَ الكفارُ أو المنافقونَ أو غيرُهم حرماتِهِ سبحانه.\n٢. غضبٌ مذموم: وهو الغضبُ الذي يجعلُ الإنسانَ يعملُ ويقولُ ما لا ينبغي.\nعلاجُ الغضبِ المذموم:\n• الوضوء.\n• القعودُ إن كان قائمًا، والاضطجاعُ إن كان قاعدًا.\n• أن يلتزمَ بوصيةِ النبيِّ ﷺ في ذلك: «لا تغضب».\n• أن يضبطَ النفسَ عن الاندفاعِ عند الغضب.\n• الاستعاذةُ بالله من الشيطانِ الرجيم.\n• السكوت."}, {"id": 206, "q": "ما هو التجسس؟", "a": "هو الكشفُ والبحثُ عن عوراتِ الناسِ وما يسترونه.\nمن صورِهِ المحرمة:\n• الاطلاعُ على عوراتِ الناسِ في البيوت.\n• استماعُ المرءِ إلى حديثِ قومٍ بدونِ علمِهم.\nقال تعالى: ﴿وَلَا تَجَسَّسُوا﴾ [الحجرات: ١٢]."}, {"id": 207, "q": "ما هو الإسراف؟ وما هو البخل؟ وما هو الكرم؟", "a": "الإسراف: هو إنفاقُ المالِ بغيرِ حقه، وعكسُهُ البخل: وهو الإمساكُ عن حقه. والصحيحُ هو الوسطُ بينهما، وأن يكونَ المسلمُ كريمًا. قال تعالى: ﴿وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا﴾ [الفرقان: ٦٧]."}, {"id": 208, "q": "ما هو الجبن؟ وما هي الشجاعة؟", "a": "الجبن: أن يخافَ مما لا ينبغي أن يخافَ منه، مثلُ الخوفِ من قولِ الحقِّ وإنكارِ المنكر.\nالشجاعة: وهي الإقدامُ على الحق، وذلك مثلُ الإقدامِ في ساحاتِ الجهادِ للدفاعِ عن الإسلامِ والمسلمين.\nوكان النبيُّ ﷺ في دعائِهِ يقول: «اللهم إني أعوذُ بك من الجبن...». وقال رسولُ الله ﷺ: «المؤمنُ القويُّ خيرٌ وأحبُّ إلى اللهِ من المؤمنِ الضعيف، وفي كلٍّ خير» رواه مسلم."}, {"id": 209, "q": "ما بعضُ أقوالِ اللسانِ المحرمة؟", "a": "مثلُ اللعنِ والسباب. ومثلُ قولِ: «فلانٌ حيوان» أو مثلِها من الألفاظ. أو ذكرِ العوراتِ من كلماتِ الفحشِ والبذاءة.\nوقد نهى النبيُّ ﷺ عن ذلك كلِّه، فقال: «ليس المؤمنُ بالطعان، ولا اللعان، ولا الفاحش، ولا البذيء» رواه الترمذي وابن حبان."}, {"id": 210, "q": "ما الأسبابُ التي تُعينُ المسلمَ على التخلقِ بالأخلاقِ الحسنة؟", "a": "١. الدعاءُ بأن يرزقكَ اللهُ حسنَ الخلقِ ويعينَكَ عليه.\n٢. مراقبةُ اللهِ عزَّ وجلَّ، وأنه يعلمُ بك ويسمعُكَ ويراك.\n٣. تذكرُ ثوابِ حسنِ الخلقِ وأنه سببٌ لدخولِ الجنة.\n٤. تذكرُ عاقبةِ سوءِ الخلقِ وأنه سببٌ لدخولِ النار.\n٥. أنَّ حسنَ الخلقِ يجلبُ محبةَ اللهِ تعالى ومحبةَ خلقه، وأنَّ سوءَ الخلقِ يجلبُ بغضَ اللهِ وبغضَ خلقه.\n٦. قراءةُ سيرةِ النبيِّ ﷺ والاقتداءُ به.\n٧. مصاحبةُ الأخيارِ وتجنبُ صحبةِ الأشرار."}], "dyk": ["تتنفَّسُ نحوَ ٢٠ ألفَ مرةٍ في اليومِ دون أن تُفكِّرَ في ذلك — سبحان مَن دبَّرَ جسمَك."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَأَرْفَعُ الْيَوْمَ لَافِتَةً حَمْرَاءَ: احْذَرْ!"}, {"s": "fasih", "t": "خَطَرٌ… خَطَرٌ! جَوَابُ اللُّغْزِ الْمَاضِي: أَيُّوبُ عَلَيْهِ السَّلَامُ، صَبَرَ فَشَفَاهُ اللَّهُ وَأَعَادَ إِلَيْهِ أَهْلَهُ."}, {"s": "anos", "t": "هَيَّا نَكْتَشِفُ هَذِهِ الْأَخْلَاقَ وَنَطْرُدُهَا. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا أَنْوَاعُ الْغِشِّ الْمُحَرَّمِ؟"}, {"s": "anos", "t": "الْغِشُّ فِي الْبَيْعِ بِإِخْفَاءِ الْعَيْبِ، وَالْغِشُّ فِي الِامْتِحَانَاتِ، وَشَهَادَةُ الزُّورِ، وَعَدَمُ الْوَفَاءِ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ غَشَّ فَلَيْسَ مِنِّي». رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "وَمَا الْغِيبَةُ؟"}, {"s": "anos", "t": "ذِكْرُكَ أَخَاكَ الْمُسْلِمَ بِمَا يَكْرَهُ وَهُوَ غَائِبٌ. اسْمَعُوا الْآيَةَ بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "49:12", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ"}, {"s": "fasih", "t": "يَنْهَانَا اللَّهُ عَنِ التَّجَسُّسِ وَالْغِيبَةِ. وَمَا النَّمِيمَةُ؟"}, {"s": "anos", "t": "نَقْلُ الْكَلَامِ بَيْنَ النَّاسِ لِلْإِفْسَادِ بَيْنَهُمْ. قَالَ النَّبِيُّ: «لَا يَدْخُلُ الْجَنَّةَ نَمَّامٌ». رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "وَالْكَسَلُ؟ أَنَا أُحِبُّ النَّوْمَ قَلِيلًا…"}, {"s": "anos", "t": "الْكَسَلُ: التَّثَاقُلُ عَنْ فِعْلِ الْخَيْرِ وَالْوَاجِبَاتِ، وَهُوَ مِنْ صِفَاتِ الْمُنَافِقِينَ إِذَا قَامُوا إِلَى الصَّلَاةِ. فَالْمُؤْمِنُ يَجِدُّ وَيَجْتَهِدُ."}, {"s": "fasih", "t": "وَمَا أَنْوَاعُ الْغَضَبِ؟"}, {"s": "anos", "t": "غَضَبٌ مَحْمُودٌ لِلَّهِ إِذَا انْتُهِكَتْ حُرُمَاتُهُ، وَغَضَبٌ مَذْمُومٌ يَجْعَلُكَ تَفْعَلُ مَا لَا يَنْبَغِي. وَعِلَاجُهُ: الْوُضُوءُ، وَالْجُلُوسُ أَوِ الِاضْطِجَاعُ، وَالِاسْتِعَاذَةُ، وَالسُّكُوتُ، وَوَصِيَّةُ النَّبِيِّ: «لَا تَغْضَبْ»."}, {"s": "fasih", "t": "وَالتَّجَسُّسُ؟"}, {"s": "anos", "t": "الْبَحْثُ عَنْ عَوْرَاتِ النَّاسِ وَمَا يَسْتُرُونَهُ، كَالنَّظَرِ فِي بُيُوتِهِمْ، أَوْ سَمَاعِ حَدِيثِهِمْ دُونَ عِلْمِهِمْ."}, {"s": "fasih", "t": "وَالْإِسْرَافُ وَالْبُخْلُ وَالْكَرَمُ؟"}, {"s": "anos", "t": "الْإِسْرَافُ إِنْفَاقُ الْمَالِ بِغَيْرِ حَقِّهِ، وَالْبُخْلُ إِمْسَاكُهُ عَنْ حَقِّهِ، وَالصَّحِيحُ الْوَسَطُ: أَنْ تَكُونَ كَرِيمًا."}, {"s": "fasih", "t": "وَالْجُبْنُ وَالشَّجَاعَةُ؟"}, {"s": "anos", "t": "الْجُبْنُ أَنْ تَخَافَ مِنْ قَوْلِ الْحَقِّ، وَالشَّجَاعَةُ الْإِقْدَامُ عَلَى الْحَقِّ. وَ«الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ، وَفِي كُلٍّ خَيْرٌ»."}, {"s": "fasih", "t": "وَأَقْوَالُ اللِّسَانِ الْمُحَرَّمَةُ؟"}, {"s": "anos", "t": "اللَّعْنُ وَالسَّبُّ، وَأَنْ تَقُولَ لِأَحَدٍ: يَا حَيَوَانُ، وَكَلِمَاتُ الْفُحْشِ. فَلَيْسَ الْمُؤْمِنُ بِالطَّعَّانِ وَلَا اللَّعَّانِ."}, {"s": "fasih", "t": "وَكَيْفَ أَتَخَلَّقُ بِالْأَخْلَاقِ الْحَسَنَةِ؟"}, {"s": "anos", "t": "بِالدُّعَاءِ، وَمُرَاقَبَةِ اللَّهِ، وَتَذَكُّرِ ثَوَابِ حُسْنِ الْخُلُقِ وَعَاقِبَةِ سُوئِهِ، وَقِرَاءَةِ سِيرَةِ النَّبِيِّ، وَمُصَاحَبَةِ الْأَخْيَارِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ أَنْتَ تَتَنَفَّسُ نَحْوَ عِشْرِينَ أَلْفَ مَرَّةٍ فِي الْيَوْمِ دُونَ أَنْ تُفَكِّرَ! سُبْحَانَ مَنْ دَبَّرَ جِسْمَكَ!"}, {"s": "anos", "t": "نَشَاطُنَا: إِشَارَةُ الْمُرُورِ لِلْغَضَبِ. الْأَحْمَرُ: قِفْ، الْأَصْفَرُ: اهْدَأْ، الْأَخْضَرُ: تَصَرَّفْ بِحِكْمَةٍ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: إشارة المرور للغضب"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! سَمِعَتْ لَيْلَى زَمِيلَتَهَا تَتَكَلَّمُ بِسُوءٍ عَنْ مَرْيَمَ. أ: تَنْقُلُ الْكَلَامَ لِمَرْيَمَ. ب: تَقُولُ بِلُطْفٍ: لَنْ نَتَكَلَّمَ عَنِ الْغَائِبَةِ، لِنَذْكُرْهَا بِخَيْرٍ. ج: تَضْحَكُ وَتَزِيدُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: سرّ صديقتي"}, {"s": "anos", "t": "أ نَمِيمَةٌ، وَج مُشَارَكَةٌ فِي الْغِيبَةِ. أَمَّا ب فَهُوَ الصَّحِيحُ، يُوقِفُ الْغِيبَةَ وَيَحْفَظُ الْأُخُوَّةَ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: قَالَ سَامِي عَنْ زَمِيلِهِ الْغَائِبِ: هُوَ كَسُولٌ. مَاذَا فَعَلَ؟ فَكِّرُوا…"}, {"s": "anos", "t": "غِيبَةٌ! وَمَا عِلَاجُ الْغَضَبِ؟ فَكِّرُوا… الْوُضُوءُ وَالسُّكُوتُ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: خَلِيفَةٌ مَلَأْتُ الْأَرْضَ عَدْلًا، قِيلَ إِنَّ الذِّئْبَ رَعَى مَعَ الْغَنَمِ فِي زَمَانِي، وَيَعُدُّنِي النَّاسُ خَامِسَ الْخُلَفَاءِ الرَّاشِدِينَ. عُمَرُ بْنُ الْخَطَّابِ، أَمْ هَارُونُ الرَّشِيدُ، أَمْ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ كُونُوا «حُرَّاسَ اللِّسَانِ»، وَانْضَمُّوا إِلَى «دَوْرِيَّةِ أَنُوس» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 25, "title": "أذكار أحبّها (١): من الاستيقاظ إلى الوضوء", "season": 3, "goals": ["adhkar"], "hook": "صباح الخير يا أصدقاء! أنوس يتثاءب ويفرك عينيه، وفصيح يصيح فوق السرير: «استيقظ يا أنوس! ماذا تقول أوّل ما تفتح عينيك؟». اليوم نبدأ رحلة «أذكار أحبّها»، وفي آخر الحلقة… مسابقة أنوس الكبرى!", "sections": [{"h": "لماذا نذكر الله؟", "p": ["<b>الذكر</b> أن يتحرّك لسانك بذكر الله: لا إله إلا الله، والله أكبر، وسبحان الله، والحمد لله، وأستغفر الله، وأذكار الصباح والمساء، وأذكار الصلاة والنوم والاستيقاظ. و<b>أفضل الذكر ما اجتمع عليه القلب واللسان</b>؛ أي تقوله بلسانك وتفكّر فيه بقلبك.", "قال النبيّ ﷺ: «مثل الذي يذكر ربّه والذي لا يذكر ربّه، مثل الحيّ والميت». فصيح يقول: «يعني الذي يذكر الله قلبه حيّ!».", "وللذكر <b>فوائد</b>: يُرضي الرحمن، ويطرد الشيطان، ويحصّن المسلم من الشرور كأنه درع، ويحصل به الأجر والثواب. و<b>أفضل الذكر</b>: «لا إله إلا الله»."], "board": ["يرضي الرحمن", "يطرد الشيطان", "يحصّن من الشرور", "أجر وثواب"]}, {"h": "صباح أنوس: الاستيقاظ واللباس", "p": ["أوّل ما يفتح أنوس عينيه يقول: «<b>الحمد لله الذي أحيانا بعد ما أماتنا، وإليه النشور</b>». فالنوم يشبه الموت الصغير، والله أعادنا إلى الحياة يومًا جديدًا!", "ثم يخلع أنوس ثوب النوم ويقول: «<b>بسم الله</b>». ويلبس ثوب المدرسة ويقول: «<b>الحمد لله الذي كساني هذا الثوب ورزقنيه من غير حول مني ولا قوة</b>».", "وإذا كان الثوب <b>جديدًا</b> يقول: «اللهم لك الحمد، أنت كسوتنيه، أسألك خيره وخير ما صُنع له، وأعوذ بك من شرّه وشرّ ما صُنع له».", "وإذا رأى أنوس صديقه بثوب جديد، يدعو له: «<b>تُبلي ويُخلف الله تعالى</b>»، أي: تلبسه حتى يقدم، ويعطيك الله غيره."], "board": ["الاستيقاظ", "خلع الثوب: بسم الله", "لبس الثوب", "الثوب الجديد"]}, {"h": "في الخلاء وعند الوضوء", "p": ["الخلاء هو مكان قضاء الحاجة. قبل أن يدخل أنوس يقول: «<b>اللهم إني أعوذ بك من الخُبث والخبائث</b>»، فيستعيذ بالله من الشياطين.", "وإذا خرج يقول: «<b>غفرانك</b>»، أي: أطلب مغفرتك يا ربّ.", "ثم يتوضّأ للصلاة. قبل الوضوء يقول: «<b>بسم الله</b>». وبعد أن ينتهي يقول: «<b>أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أنّ محمدًا عبده ورسوله</b>».", "فصيح يعدّ على ريشاته: «كم ذكرًا قلنا من الاستيقاظ إلى الوضوء؟ كثير! وكلّ ذكر حسنات!»."], "board": ["قبل الخلاء: أعوذ بالله", "بعده: غفرانك", "قبل الوضوء: بسم الله", "بعده: الشهادتان"]}, {"h": "مسابقة أنوس: راجع ما تعلّمته", "p": ["وصلنا إلى نصف الطريق تقريبًا! واليوم يقدّم فصيح <b>مسابقة أنوس</b>: أسئلة سريعة عن الأخلاق التي تعلّمناها في الحلقات الماضية، وعن أذكار اليوم.", "مثل: ما ضدّ الصبر؟ ما الفرق بين الغيبة والنميمة؟ كيف أعالج الغضب؟ وماذا أقول إذا لبست ثوبي؟", "قوانين المسابقة: نجيب بأدب، ونرفع اليد، ونفرح لصاحبنا إذا فاز، فلا حسد ولا سخرية. والكل فائز لأنه تعلّم!"], "board": ["سؤال", "جواب", "دليل", "ابتسامة"]}], "summary": ["الذكر حياة للقلب: يرضي الرحمن ويطرد الشيطان ويحصّن المسلم، وأفضله «لا إله إلا الله».", "عند الاستيقاظ: «الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور»، وللّبس والخلع والثوب الجديد أذكار.", "قبل الخلاء: «اللهم إني أعوذ بك من الخبث والخبائث»، وبعده «غفرانك»، وقبل الوضوء «بسم الله» وبعده الشهادتان."], "islam": {"intro": "قال الله تعالى يأمر المؤمنين بكثرة ذكره:", "text": "فاجعل لكل لحظة في يومك ذكرًا: عند الاستيقاظ، واللبس، والخلاء، والوضوء، فيصير يومك كلّه في طاعة الله.", "ayah": {"text": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًۭا كَثِيرًۭا", "src": "سُورَةُ الأَحۡزَابِ: ٤١"}, "hadith": {"text": "مثل الذي يذكر ربّه والذي لا يذكر ربّه، مثل الحيّ والميت", "source": "رواه البخاري"}}, "home": {"title": "أوراق التذكير الصباحية", "goal": "أن يحفظ الطفل أذكار الصباح الأولى بربطها بأماكنها في البيت.", "materials": ["أوراق لاصقة ملوّنة", "أقلام"], "steps": ["اكتب ذكر الاستيقاظ على ورقة، والصقها قرب سريرك.", "اكتب ذكر لبس الثوب على ورقة، والصقها على الخزانة.", "اكتب «اللهم إني أعوذ بك من الخبث والخبائث» و«غفرانك» على ورقة، والصقها خارج باب الخلاء.", "اكتب ذكر ما بعد الوضوء على ورقة قرب المغسلة، وكل صباح ضع علامة على كل ذكر قلته."], "parent": "ساعدوا طفلكم في الكتابة، وقولوا الأذكار معه بصوت مسموع في الأيام الأولى، حتى يحفظها دون الأوراق."}, "online": {"title": "صباح أنوس", "intro": "رتّب صباح أنوس، وصِل كل موقف بذكره، ثم ادخل مسابقة فصيح!", "steps": [{"type": "order", "title": "رتّب صباح أنوس", "prompt": "رتّب أذكار الصباح بالترتيب الذي يحدث في يوم أنوس.", "items": ["يستيقظ: الحمد لله الذي أحيانا بعد ما أماتنا", "يخلع ثوب النوم: بسم الله", "يلبس ثوبه: الحمد لله الذي كساني هذا الثوب", "قبل دخول الخلاء: اللهم إني أعوذ بك من الخبث والخبائث", "بعد الخروج: غفرانك", "بعد الوضوء: أشهد أن لا إله إلا الله…"]}, {"type": "match", "title": "صِل الموقف بذكره", "prompt": "اختر الموقف، ثم الذكر المناسب.", "pairs": [["قبل الوضوء", "بسم الله"], ["الخروج من الخلاء", "غفرانك"], ["صديقي لبس ثوبًا جديدًا", "تُبلي ويُخلف الله تعالى"], ["أفضل الذكر", "لا إله إلا الله"]]}, {"type": "quiz", "title": "مسابقة فصيح", "items": [{"q": "أيّ هذه من فوائد الذكر؟", "o": ["يجلب الشيطان", "يطرد الشيطان", "يتعب القلب"], "a": 1, "why": "الذكر يرضي الرحمن ويطرد الشيطان."}, {"q": "من الحلقات الماضية: ما علاج الغضب؟", "o": ["الصراخ", "الضرب", "الاستعاذة والسكوت والوضوء"], "a": 2, "why": "هذه من طرق علاج الغضب المذموم."}, {"q": "من الحلقات الماضية: البشاشة هي…", "o": ["الوجه المبتسم عند لقاء الناس", "العبوس", "السخرية"], "a": 0, "why": "«تبسّمك في وجه أخيك لك صدقة»."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عن نبيّ ذكر الله في مكان مظلم جدًّا. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["ذهبتُ من قومي مغاضبًا.", "التقمني الحوت، فصرت في ظلمات كثيرة.", "ناديت في الظلمات: «لا إله إلا أنت سبحانك إني كنت من الظالمين»."], "options": ["نوح عليه السلام", "موسى عليه السلام", "يونس عليه السلام"], "deep": "لماذا كان الذكر والدعاء أوّل شيء فعله هذا النبيّ في الشدّة؟ وما الذكر الذي تقوله أنت إذا خفت؟", "reveal": "أنا يونس عليه السلام! ذكرت الله في بطن الحوت فنجّاني، وقال النبيّ ﷺ إنّ دعوتي هذه ما دعا بها مسلم في شيء إلا استجاب الله له. وفي الحلقة القادمة نكمل «أذكار أحبّها»: أذكار البيت والمسجد والطعام."}, "quiz": [{"q": "ما أفضل الذكر؟", "o": ["لا إله إلا الله", "صباح الخير", "شكرًا"], "a": 0, "why": "أفضل الذكر «لا إله إلا الله» كما في الكتاب."}], "qa": [{"id": 211, "q": "ما هو فضلُ الذكر؟", "a": "قال النبيُّ ﷺ: «مثلُ الذي يذكرُ ربَّهُ والذي لا يذكرُ ربَّه، مثلُ الحيِّ والميت» رواه البخاري. هذا لأنَّ قيمةَ حياةِ الإنسانِ بقدرِ ذكرِهِ لله تعالى.\n(تعريفُ الذكر: هو حركةُ اللسانِ بذكرِ اللهِ من التهليلِ والتكبيرِ والتسبيحِ والتحميدِ والاستغفارِ والثناءِ على اللهِ سبحانه، وأذكارِ الصباحِ والمساء، وأذكارِ الصلوات، وعند النوم، وعند الاستيقاظ، وغيرِها. وأفضلُ الذكرِ ما اجتمعَ عليه القلبُ واللسان)."}, {"id": 212, "q": "اذكرْ بعضَ فوائدِ الذكر.", "a": "١. يُرضي الرحمن.\n٢. ويطردُ الشيطان.\n٣. ويُحصِّنُ المسلمَ من الشرور.\n٤. ويُحصَّلُ به الأجرُ والثواب."}, {"id": 213, "q": "ما أفضلُ الذكر؟", "a": "«لا إله إلا الله» رواه الترمذي وابن ماجه."}, {"id": 214, "q": "ماذا تقولُ عند الاستيقاظِ من النوم؟", "a": "«الحمدُ لله الذي أحيانا بعد ما أماتنا، وإليه النشور» متفق عليه."}, {"id": 215, "q": "ماذا تقولُ إذا لبستَ ثوبك؟", "a": "«الحمدُ لله الذي كساني هذا الثوبَ ورزقنيهِ من غيرِ حولٍ مني ولا قوة» رواه أبو داود والترمذي وغيرهما."}, {"id": 216, "q": "ما تقولُ إذا خلعتَ الثوب؟", "a": "«بسم الله» رواه الترمذي."}, {"id": 217, "q": "ما دعاءُ لبسِ الثوبِ الجديد؟", "a": "«اللهم لك الحمد، أنت كسوتنيه، أسألُكَ خيرَهُ وخيرَ ما صُنِعَ له، وأعوذُ بك من شرِّهِ وشرِّ ما صُنِعَ له» رواه أبو داود والترمذي."}, {"id": 218, "q": "ما هو الدعاءُ لمن لبِسَ ثوبًا جديدًا؟", "a": "إذا رأيتَ ثوبًا جديدًا على غيرِكَ تدعو له، وتقول: «تُبلي ويُخلِفُ اللهُ تعالى» رواه أبو داود."}, {"id": 219, "q": "ما دعاءُ دخولِ الخلاء، وهو مكانُ قضاءِ الحاجة؟", "a": "«اللهم إني أعوذُ بك من الخُبثِ والخبائث» متفق عليه."}, {"id": 220, "q": "ما هو دعاءُ الخروجِ من الخلاء؟", "a": "«غفرانك» رواه أبو داود والترمذي."}, {"id": 221, "q": "ماذا تقولُ قبل الوضوء؟", "a": "«بسم الله» رواه أبو داود وغيره."}, {"id": 222, "q": "ما هو الذكرُ بعد الفراغِ من الوضوء؟", "a": "«أشهدُ أن لا إله إلا اللهُ وحدَهُ لا شريكَ له، وأشهدُ أن محمدًا عبدُهُ ورسوله» رواه مسلم."}], "dyk": ["يُولَدُ الطفلُ بنحوِ ٣٠٠ عظمة، وتلتحمُ لتصيرَ ٢٠٦ عظاماً عندَ الكبر.", "عينُك تُميِّزُ ملايينَ الألوان، وترمشُ نحوَ ١٥ ألفَ مرةٍ يومياً لتبقى نظيفةً رطبة."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس… آهْ، مَا زِلْتُ نَعْسَانَ!"}, {"s": "fasih", "t": "اسْتَيْقِظْ يَا أَنُوس! وَجَوَابُ اللُّغْزِ الْمَاضِي: عُمَرُ بْنُ عَبْدِ الْعَزِيزِ رَحِمَهُ اللَّهُ، الْخَلِيفَةُ الْعَادِلُ. وَالْيَوْمَ نَبْدَأُ رِحْلَةَ «أَذْكَارٍ أُحِبُّهَا»!"}, {"s": "anos", "t": "هَيَّا يَا فَصِيح، اسْأَلْ!"}, {"s": "fasih", "t": "مَا فَضْلُ الذِّكْرِ؟"}, {"s": "anos", "t": "قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ، مَثَلُ الْحَيِّ وَالْمَيِّتِ». رَوَاهُ الْبُخَارِيُّ. فَقِيمَةُ حَيَاتِنَا بِقَدْرِ ذِكْرِنَا لِلَّهِ، وَأَفْضَلُهُ مَا اجْتَمَعَ عَلَيْهِ الْقَلْبُ وَاللِّسَانُ."}, {"s": "fasih", "t": "وَاللَّهُ أَمَرَنَا بِكَثْرَةِ ذِكْرِهِ. اسْمَعُوا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "33:41", "t": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًۭا كَثِيرًۭا"}, {"s": "anos", "t": "فَاجْعَلْ لِكُلِّ لَحْظَةٍ فِي يَوْمِكَ ذِكْرًا، فَيَصِيرَ يَوْمُكَ كُلُّهُ طَاعَةً."}, {"s": "fasih", "t": "وَمَا فَوَائِدُ الذِّكْرِ؟"}, {"s": "anos", "t": "يُرْضِي الرَّحْمَنَ، وَيَطْرُدُ الشَّيْطَانَ، وَيُحَصِّنُ الْمُسْلِمَ مِنَ الشُّرُورِ، وَبِهِ الْأَجْرُ وَالثَّوَابُ."}, {"s": "fasih", "t": "وَمَا أَفْضَلُ الذِّكْرِ؟"}, {"s": "anos", "t": "لَا إِلَهَ إِلَّا اللَّهُ."}, {"s": "fasih", "t": "مَاذَا تَقُولُ عِنْدَ الِاسْتِيقَاظِ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ."}, {"s": "fasih", "t": "وَإِذَا لَبِسْتَ ثَوْبَكَ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ."}, {"s": "fasih", "t": "وَإِذَا خَلَعْتَهُ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ."}, {"s": "fasih", "t": "وَإِذَا لَبِسْتَ ثَوْبًا جَدِيدًا؟"}, {"s": "anos", "t": "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ."}, {"s": "fasih", "t": "وَإِذَا رَأَيْتَ صَدِيقَكَ بِثَوْبٍ جَدِيدٍ؟"}, {"s": "anos", "t": "أَدْعُو لَهُ: تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى."}, {"s": "fasih", "t": "وَعِنْدَ دُخُولِ الْخَلَاءِ؟"}, {"s": "anos", "t": "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ."}, {"s": "fasih", "t": "وَعِنْدَ الْخُرُوجِ؟"}, {"s": "anos", "t": "غُفْرَانَكَ."}, {"s": "fasih", "t": "وَقَبْلَ الْوُضُوءِ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ."}, {"s": "fasih", "t": "وَبَعْدَ الْوُضُوءِ؟"}, {"s": "anos", "t": "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ يُولَدُ الطِّفْلُ بِنَحْوِ ثَلَاثِمِئَةِ عَظْمَةٍ، تَلْتَحِمُ فَتَصِيرُ مِئَتَيْنِ وَسِتَّ عِظَامٍ عِنْدَ الْكِبَرِ!"}, {"s": "anos", "t": "وَهَلْ تَعْلَمُ أَيْضًا؟ عَيْنُكَ تُمَيِّزُ مَلَايِينَ الْأَلْوَانِ، وَتَرْمُشُ نَحْوَ خَمْسَةَ عَشَرَ أَلْفَ مَرَّةٍ يَوْمِيًّا لِتَبْقَى نَظِيفَةً رَطْبَةً! سُبْحَانَ اللَّهِ!"}, {"s": "fasih", "t": "وَالْآنَ… مُسَابَقَةُ أَنُوس الْكُبْرَى، الْجَوْلَةُ الْأُولَى! فَرِيقُ أَنُوس ضِدَّ فَرِيقِ فَصِيح: أَسْئِلَةٌ عَنِ الْأَخْلَاقِ، ثُمَّ مَوَاقِفُ تَقُولُونَ ذِكْرَهَا، ثُمَّ تَمْثِيلٌ بِلَا كَلَامٍ."}, {"s": "anos", "t": "أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا إِلَيْنَا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس: الجولة الأولى"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! لَبِسَ أَنُوس ثَوْبَهُ بِسُرْعَةٍ وَنَسِيَ الذِّكْرَ. أ: لَا يَهُمُّ، الْأَذْكَارُ لِلْكِبَارِ. ب: يَقُولُ الذِّكْرَ عِنْدَمَا يَتَذَكَّرُ، وَيَضَعُ وَرَقَةَ تَذْكِيرٍ قُرْبَ الْخِزَانَةِ. ج: يَحْزَنُ وَلَا يَذْكُرُ اللَّهَ الْيَوْمَ كُلَّهُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: نسيتُ الذكر!"}, {"s": "anos", "t": "ب هُوَ الْأَفْضَلُ، فَالذِّكْرُ يُحِبُّهُ اللَّهُ فِي كُلِّ وَقْتٍ. أ خَطَأٌ، فَالذِّكْرُ لِلصِّغَارِ وَالْكِبَارِ، وَج يَحْرِمُنَا الْأَجْرَ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مَاذَا تَقُولُ إِذَا خَرَجْتَ مِنَ الْخَلَاءِ؟ فَكِّرُوا…"}, {"s": "anos", "t": "غُفْرَانَكَ! وَمَا أَفْضَلُ الذِّكْرِ؟ فَكِّرُوا… لَا إِلَهَ إِلَّا اللَّهُ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: ذَهَبْتُ مِنْ قَوْمِي مُغَاضِبًا، فَالْتَقَمَنِيَ الْحُوتُ، وَنَادَيْتُ رَبِّي فِي الظُّلُمَاتِ بِدُعَاءٍ فِيهِ التَّوْحِيدُ وَالتَّسْبِيحُ وَالِاعْتِرَافُ بِالذَّنْبِ. نُوحٌ، أَمْ مُوسَى، أَمْ يُونُسُ، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ أَلْصِقُوا «أَوْرَاقَ التَّذْكِيرِ الصَّبَاحِيَّةَ»، وَرَتِّبُوا «صَبَاحَ أَنُوس» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 26, "title": "أذكار أحبّها (٢): البيت والمسجد والطعام", "season": 3, "goals": ["adhkar"], "hook": "طق طق! أنوس يفتح باب البيت ليذهب إلى المسجد، وفصيح على كتفه يقول: «توقّف يا أنوس! نسيت مفتاحًا مهمًّا!». أيّ مفتاح يا فصيح؟ «مفتاح الذكر!». تعالوا نتعلّم أذكار البيت والمسجد والطعام.", "sections": [{"h": "الخروج من البيت والدخول إليه", "p": ["إذا خرج أنوس من البيت يقول: «<b>بسم الله، توكّلت على الله، ولا حول ولا قوّة إلا بالله</b>». فهو يبدأ باسم الله، ويعتمد على الله في طريقه.", "وإذا رجع ودخل البيت يقول: «<b>بسم الله ولجنا، وبسم الله خرجنا، وعلى ربّنا توكّلنا</b>»، ثم <b>يسلّم على أهله</b>: «السلام عليكم». فصيح يقول: «ولجنا يعني دخلنا!»."], "board": ["الخروج: بسم الله توكّلت على الله", "الدخول: بسم الله ولجنا", "ثم السلام على الأهل"]}, {"h": "في المسجد ومع الأذان", "p": ["عند باب المسجد يقول أنوس: «<b>اللهم افتح لي أبواب رحمتك</b>». وإذا خرج يقول: «<b>اللهم إني أسألك من فضلك</b>».", "وإذا سمع <b>الأذان</b> يقول مثل ما يقول المؤذّن: الله أكبر، الله أكبر… إلا عند «حيّ على الصلاة» و«حيّ على الفلاح»، فيقول: «<b>لا حول ولا قوّة إلا بالله</b>».", "وبعد الأذان يصلّي على النبيّ ﷺ، ثم يقول: «<b>اللهم ربّ هذه الدعوة التامّة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته</b>».", "وبين الأذان والإقامة وقت ثمين للدعاء؛ فإنّ الدعاء فيه <b>لا يُردّ</b>. فادعُ لنفسك ولوالديك!"], "board": ["دخول المسجد", "الخروج منه", "أردّد مع المؤذّن", "أدعو بين الأذان والإقامة"]}, {"h": "درع الصباح والمساء… وذكر النوم", "p": ["كل صباح وكل مساء يلبس أنوس «درعًا» من الذكر: يقرأ <b>آية الكرسي</b>، ويقرأ <b>قل هو الله أحد</b> و<b>قل أعوذ بربّ الفلق</b> و<b>قل أعوذ بربّ الناس</b>، كل واحدة <b>ثلاث مرّات</b>.", "ويقول <b>سيّد الاستغفار</b>: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شرّ ما صنعت، أبوء لك بنعمتك عليّ، وأبوء بذنبي، فاغفر لي، فإنه لا يغفر الذنوب إلا أنت».", "وفي الليل، عندما يضع أنوس رأسه على الوسادة يقول: «<b>باسمك اللهمّ أموت وأحيا</b>». ما أجمل أن يبدأ يومك بالذكر وينتهي بالذكر!"], "board": ["آية الكرسي", "الإخلاص والمعوّذتان ٣ مرّات", "سيّد الاستغفار", "باسمك اللهمّ أموت وأحيا"]}, {"h": "على مائدة الطعام", "p": ["قبل أن يأكل أنوس يقول: «<b>بسم الله</b>». فإن نسي في أوّل الطعام ثم تذكّر يقول: «<b>بسم الله في أوّله وآخره</b>».", "وإذا شبع وانتهى يقول: «<b>الحمد لله الذي أطعمني هذا، ورزقنيه من غير حول مني ولا قوّة</b>».", "وإذا كان أنوس <b>ضيفًا</b> عند جدّته أو عند صديقه، يدعو لصاحب الطعام: «<b>اللهم بارك لهم فيما رزقتهم، واغفر لهم وارحمهم</b>». فصيح يقول: «هذا أجمل شكر للمضيف!»."], "board": ["قبل الطعام: بسم الله", "نسيت؟ بسم الله في أوّله وآخره", "بعده: الحمد لله الذي أطعمني", "دعاء الضيف"]}], "summary": ["عند الخروج من البيت: «بسم الله، توكّلت على الله، ولا حول ولا قوّة إلا بالله»، وعند الدخول: «بسم الله ولجنا…» ثم نسلّم.", "عند دخول المسجد: «اللهم افتح لي أبواب رحمتك»، وعند الخروج: «اللهم إني أسألك من فضلك»، ونردّد مع المؤذّن وندعو بعد الأذان.", "في الصباح والمساء آية الكرسي والمعوّذات وسيّد الاستغفار، وقبل الطعام «بسم الله» وبعده الحمد، وعند النوم «باسمك اللهمّ أموت وأحيا»."], "islam": {"intro": "قال الله تعالى عن راحة القلوب:", "text": "فإذا شعرت بالخوف أو الحزن فاذكر الله؛ فالذكر يجعل القلب مطمئنًّا هادئًا.", "ayah": {"text": "ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ", "src": "سُورَةُ الرَّعۡدِ: ٢٨"}, "hadith": {"text": "اللهم افتح لي أبواب رحمتك", "source": "رواه مسلم"}}, "home": {"title": "خريطة بيتي الذاكر", "goal": "أن يربط الطفل كل مكان في البيت بذكره، ويطبّقه مع أسرته.", "materials": ["ورقة كبيرة", "ألوان"], "steps": ["ارسم خريطة بسيطة لبيتك: الباب، والمائدة، وغرفة النوم، وطريق المسجد.", "اكتب بجانب كل مكان ذكره الذي تعلّمته اليوم.", "علّق الخريطة في البيت، وكن «حارس الأذكار»: ذكّر أسرتك بلطف عند الباب وعلى المائدة.", "بعد أذان المغرب ادعُ الله بين الأذان والإقامة، واكتب دعوة جميلة دعوت بها لوالديك."], "parent": "قولوا الأذكار بصوت مسموع أمام أطفالكم عند الخروج والدخول والطعام؛ فالطفل يحفظ ما يسمعه كل يوم."}, "online": {"title": "يوم أنوس الذاكر", "intro": "رافق أنوس من البيت إلى المسجد إلى المائدة، وقل الذكر المناسب!", "steps": [{"type": "sort", "title": "ذكر الدخول أم ذكر الخروج؟", "prompt": "اضغط على البطاقة، ثم اختر: هل نقوله عند الدخول أم عند الخروج؟", "bins": ["عند الدخول", "عند الخروج"], "items": [{"t": "اللهم افتح لي أبواب رحمتك", "icon": "🕌", "bin": 0, "why": "دعاء دخول المسجد."}, {"t": "اللهم إني أسألك من فضلك", "icon": "🚶", "bin": 1, "why": "دعاء الخروج من المسجد."}, {"t": "بسم الله ولجنا، وبسم الله خرجنا، وعلى ربّنا توكّلنا", "icon": "🏠", "bin": 0, "why": "ذكر دخول المنزل، ثم نسلّم على أهلنا."}, {"t": "بسم الله، توكّلت على الله، ولا حول ولا قوّة إلا بالله", "icon": "🚪", "bin": 1, "why": "ذكر الخروج من المنزل."}, {"t": "اللهم إني أعوذ بك من الخبث والخبائث", "icon": "🚻", "bin": 0, "why": "دعاء دخول الخلاء من الحلقة الماضية."}, {"t": "غفرانك", "icon": "🌿", "bin": 1, "why": "دعاء الخروج من الخلاء."}]}, {"type": "match", "title": "صِل الموقف بذكره", "prompt": "اختر الموقف، ثم الذكر المناسب.", "pairs": [["قبل الطعام", "بسم الله"], ["بعد الطعام", "الحمد لله الذي أطعمني هذا"], ["نسيت التسمية أوّل الطعام", "بسم الله في أوّله وآخره"], ["عند النوم", "باسمك اللهمّ أموت وأحيا"], ["بعد الأذان", "اللهم ربّ هذه الدعوة التامّة"]]}, {"type": "quiz", "title": "تحدّي فصيح", "items": [{"q": "ماذا نفعل بعد ذكر دخول المنزل؟", "o": ["نسلّم على أهلنا", "نصرخ", "ننام فورًا"], "a": 0, "why": "ثم ليسلّم على أهله."}, {"q": "ما اسم هذا الذكر: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك…»؟", "o": ["دعاء السفر", "دعاء الريح", "سيّد الاستغفار"], "a": 2, "why": "هو سيّد الاستغفار، رواه البخاري."}, {"q": "الدعاء بين الأذان والإقامة…", "o": ["ممنوع", "لا يُردّ", "للكبار فقط"], "a": 1, "why": "الدعاء بين الأذان والإقامة لا يُردّ."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عن نبيّ كان يحبّ الدعاء في المحراب. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا الذي كفلت مريم ورعيتها في المحراب.", "دعوت ربي وأنا شيخ كبير، وامرأتي لا تلد.", "فرزقني الله غلامًا اسمه يحيى."], "options": ["إبراهيم عليه السلام", "زكريا عليه السلام", "يحيى عليه السلام"], "deep": "لم يتوقّف هذا النبيّ عن الدعاء مع أنه صار كبيرًا جدًّا. ماذا نتعلّم منه عن الدعاء بين الأذان والإقامة؟", "reveal": "أنا زكريا عليه السلام! كنت أدعو ربي في المحراب، وهو مكان الصلاة، فاستجاب الله لي. وفي الحلقة القادمة نكمل «أذكار أحبّها»: أذكار السفر والسوق والمجلس."}, "quiz": [{"q": "ماذا تقول إذا خرجت من المسجد؟", "o": ["اللهم افتح لي أبواب رحمتك", "اللهم إني أسألك من فضلك", "غفرانك"], "a": 1, "why": "دعاء الخروج من المسجد: «اللهم إني أسألك من فضلك»."}], "qa": [{"id": 223, "q": "ما هو الذكرُ عند الخروجِ من المنزل؟", "a": "«بسم الله، توكلتُ على الله، ولا حولَ ولا قوةَ إلا بالله» رواه أبو داود والترمذي."}, {"id": 224, "q": "ما هو الذكرُ عند دخولِ المنزل؟", "a": "«بسم الله ولَجنا، وبسم الله خرَجنا، وعلى ربنا توكلنا»، ثم ليسلِّمْ على أهله. رواه أبو داود."}, {"id": 225, "q": "ما هو دعاءُ دخولِ المسجد؟", "a": "«اللهم افتحْ لي أبوابَ رحمتك» رواه مسلم."}, {"id": 226, "q": "ما دعاءُ الخروجِ من المسجد؟", "a": "«اللهم إني أسألُكَ من فضلك» رواه مسلم."}, {"id": 227, "q": "ما تقولُ عند سماعِ الأذان؟", "a": "أقولُ مثلَ ما يقولُ المؤذن، إلا في: «حي على الصلاة» و«حي على الفلاح» فأقول: «لا حولَ ولا قوةَ إلا بالله» متفق عليه."}, {"id": 228, "q": "ماذا تقولُ بعد الأذان؟", "a": "«تصلي على النبيِّ ﷺ» رواه مسلم. وتقول: «اللهم ربَّ هذه الدعوةِ التامة، والصلاةِ القائمة، آتِ محمدًا الوسيلةَ والفضيلة، وابعثْهُ مقامًا محمودًا الذي وعدتَه» رواه البخاري. وتدعو بين الأذانِ والإقامة، فإنَّ الدعاءَ لا يُرد."}, {"id": 229, "q": "ماذا تقولُ في الصباحِ والمساءِ من الأذكار؟", "a": "١. أقرأُ آيةَ الكرسي: ﴿اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ...﴾ [البقرة: ٢٥٥].\n٢. وأقرأُ: ﴿بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ﴾ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ...﴾ [الإخلاص]، ثلاثَ مرات.\n٣. ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ...﴾ [الفلق]، ثلاثَ مرات.\n٤. ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ...﴾ [الناس]، ثلاثَ مرات.\n٥. سيدُ الاستغفار: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدُك، وأنا على عهدِكَ ووعدِكَ ما استطعت، أعوذُ بك من شرِّ ما صنعت، أبوءُ لك بنعمتِكَ عليَّ، وأبوءُ بذنبي، فاغفرْ لي، فإنه لا يغفرُ الذنوبَ إلا أنت» رواه البخاري."}, {"id": 230, "q": "ما تقولُ عند النوم؟", "a": "«باسمِكَ اللهمَّ أموتُ وأحيا» متفق عليه."}, {"id": 231, "q": "ماذا تقولُ قبل أكلِ الطعام؟", "a": "«بسم الله»، فإذا نسيتَ في أوله فقل: «بسم الله في أوله وآخره» رواه أبو داود والترمذي."}, {"id": 232, "q": "ماذا تقولُ عند الفراغِ من الطعام؟", "a": "«الحمد لله الذي أطعمني هذا، ورزقنيهِ من غيرِ حولٍ مني ولا قوة» رواه أبو داود وابن ماجه وغيرهما."}, {"id": 233, "q": "ما هو دعاءُ الضيفِ لصاحبِ الطعام؟", "a": "«اللهم باركْ لهم فيما رزقتَهم، واغفرْ لهم وارحمهم» رواه مسلم."}], "dyk": ["قلبُك ينبضُ نحوَ ١٠٠ ألفِ مرةٍ كلَّ يومٍ دون أن يتعبَ أو يتوقَّف — نعمةٌ من الله."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَأَنَا ذَاهِبٌ إِلَى الْمَسْجِدِ!"}, {"s": "fasih", "t": "نَسِيتَ مِفْتَاحَ الذِّكْرِ يَا أَنُوس! وَجَوَابُ اللُّغْزِ الْمَاضِي: يُونُسُ عَلَيْهِ السَّلَامُ، ذَكَرَ اللَّهَ فِي بَطْنِ الْحُوتِ فَنَجَّاهُ."}, {"s": "anos", "t": "هَيَّا نَتَعَلَّمُ أَذْكَارَ الْبَيْتِ وَالْمَسْجِدِ وَالطَّعَامِ. اسْأَلْ!"}, {"s": "fasih", "t": "مَاذَا تَقُولُ عِنْدَ الْخُرُوجِ مِنَ الْمَنْزِلِ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ."}, {"s": "fasih", "t": "وَعِنْدَ دُخُولِهِ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى رَبِّنَا تَوَكَّلْنَا، ثُمَّ أُسَلِّمُ عَلَى أَهْلِي."}, {"s": "fasih", "t": "وَعِنْدَ دُخُولِ الْمَسْجِدِ؟"}, {"s": "anos", "t": "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ. رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "وَعِنْدَ الْخُرُوجِ مِنْهُ؟"}, {"s": "anos", "t": "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ."}, {"s": "fasih", "t": "وَعِنْدَ سَمَاعِ الْأَذَانِ؟"}, {"s": "anos", "t": "أَقُولُ مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ، إِلَّا فِي: حَيَّ عَلَى الصَّلَاةِ، وَحَيَّ عَلَى الْفَلَاحِ، فَأَقُولُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ."}, {"s": "fasih", "t": "وَبَعْدَ الْأَذَانِ؟"}, {"s": "anos", "t": "أُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَقُولُ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ. وَأَدْعُو بَيْنَ الْأَذَانِ وَالْإِقَامَةِ، فَالدُّعَاءُ لَا يُرَدُّ."}, {"s": "fasih", "t": "وَأَذْكَارُ الصَّبَاحِ وَالْمَسَاءِ؟"}, {"s": "anos", "t": "أَقْرَأُ آيَةَ الْكُرْسِيِّ، وَالْإِخْلَاصَ وَالْفَلَقَ وَالنَّاسَ ثَلَاثًا، وَسَيِّدَ الِاسْتِغْفَارِ، وَأَوَّلُهُ: اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَآخِرُهُ: فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ."}, {"s": "fasih", "t": "مَا أَجْمَلَهُ! وَبِالذِّكْرِ يَطْمَئِنُّ الْقَلْبُ. اسْمَعُوا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "13:28", "t": "ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ"}, {"s": "anos", "t": "فَإِذَا خِفْتَ أَوْ حَزِنْتَ فَاذْكُرِ اللَّهَ، يَطْمَئِنَّ قَلْبُكَ."}, {"s": "fasih", "t": "وَعِنْدَ النَّوْمِ؟"}, {"s": "anos", "t": "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا."}, {"s": "fasih", "t": "وَقَبْلَ الطَّعَامِ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ، فَإِنْ نَسِيتُ قُلْتُ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ."}, {"s": "fasih", "t": "وَبَعْدَهُ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ."}, {"s": "fasih", "t": "وَدُعَاءُ الضَّيْفِ لِصَاحِبِ الطَّعَامِ؟"}, {"s": "anos", "t": "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ. رَوَاهُ مُسْلِمٌ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ قَلْبُكَ يَنْبِضُ نَحْوَ مِئَةِ أَلْفِ مَرَّةٍ كُلَّ يَوْمٍ دُونَ أَنْ يَتْعَبَ أَوْ يَتَوَقَّفَ، نِعْمَةٌ مِنَ اللَّهِ!"}, {"s": "anos", "t": "نَشَاطُنَا: قِطَارُ الْأَذْكَارِ! تَشُو تَشُو! فِي كُلِّ مَحَطَّةٍ نَقُولُ ذِكْرَهَا. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: قطار الأذكار"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! أَكَلَ أَنُوس بِسُرْعَةٍ وَنَسِيَ التَّسْمِيَةَ، ثُمَّ تَذَكَّرَ. أ: يُكْمِلُ وَلَا يَقُولُ شَيْئًا. ب: يَقُولُ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ. ج: يَتْرُكُ الطَّعَامَ كُلَّهُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الطعام اللذيذ"}, {"s": "anos", "t": "ب هُوَ الصَّحِيحُ، كَمَا عَلَّمَنَا النَّبِيُّ. أ يَفُوتُهُ الذِّكْرُ، وَج لَا دَاعِيَ لَهُ، فَالدِّينُ يُسْرٌ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: قَالَ الْمُؤَذِّنُ: حَيَّ عَلَى الصَّلَاةِ. مَاذَا تَقُولُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ! وَكَمْ مَرَّةً نَقْرَأُ الْإِخْلَاصَ صَبَاحًا وَمَسَاءً؟ فَكِّرُوا… ثَلَاثَ مَرَّاتٍ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: كَفَلْتُ مَرْيَمَ فِي الْمِحْرَابِ، وَدَعَوْتُ رَبِّي وَأَنَا شَيْخٌ كَبِيرٌ وَامْرَأَتِي لَا تَلِدُ، فَرَزَقَنِيَ اللَّهُ غُلَامًا اسْمُهُ يَحْيَى. إِبْرَاهِيمُ، أَمْ زَكَرِيَّا، أَمْ يَحْيَى، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ ارْسُمُوا «خَرِيطَةَ بَيْتِيَ الذَّاكِرِ»، وَرَافِقُوا «يَوْمَ أَنُوس الذَّاكِرِ» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 27, "title": "أذكار أحبّها (٣): السفر والسوق والمجلس", "season": 3, "goals": ["adhkar"], "hook": "أنوس يجرّ حقيبة السفر، وفصيح يلبس نظّارة شمسية صغيرة ويقول: «رحلة! رحلة! لكن… هل حزمت أذكار السفر يا أنوس؟». هيّا نركب معهم في سيّارة الأذكار، ونمرّ بالسوق والمجلس أيضًا!", "sections": [{"h": "العطاس وكفّارة المجلس", "p": ["هاتشوو! عطس أنوس فقال: «<b>الحمد لله</b>». فقال له أخوه: «<b>يرحمك الله</b>». فردّ أنوس: «<b>يهديكم الله ويصلح بالكم</b>». ثلاث جمل جميلة: حمد، ودعاء، وردّ الدعاء!", "وإذا جلست مع أصحابك تتحدّثون، ثم قمتم، فقل <b>دعاء كفّارة المجلس</b>: «سبحانك اللهمّ وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك». فصيح يقول: «هذا مثل الممحاة، يمسح الأخطاء الصغيرة في الكلام!»."], "board": ["العاطس: الحمد لله", "السامع: يرحمك الله", "العاطس: يهديكم الله ويصلح بالكم", "كفّارة المجلس"]}, {"h": "في السيّارة والسفر", "p": ["إذا ركب أنوس السيّارة أو الدراجة يقول <b>دعاء الركوب</b>: «بسم الله، والحمد لله، سبحان الذي سخّر لنا هذا وما كنّا له مقرنين، وإنّا إلى ربّنا لمنقلبون»، ثم يقول: الحمد لله ثلاثًا، والله أكبر ثلاثًا، ثم: «سبحانك اللهمّ إني ظلمت نفسي فاغفر لي؛ فإنه لا يغفر الذنوب إلا أنت».", "وإذا كان <b>مسافرًا</b> يكبّر ثلاثًا، ويقرأ الآية نفسها، ثم يدعو: «اللهم إنّا نسألك في سفرنا هذا البرّ والتقوى، ومن العمل ما ترضى، اللهم هوّن علينا سفرنا هذا…». ويستعيذ بالله من تعب السفر وكآبة المنظر وسوء المنقلب في المال والأهل.", "وإذا رجع من السفر قال الدعاء نفسه، وزاد: «<b>آيبون، تائبون، عابدون، لربّنا حامدون</b>»."], "board": ["دعاء الركوب", "دعاء السفر", "عند الرجوع: آيبون تائبون"]}, {"h": "الوداع: أستودعكم الله", "p": ["عند الوداع في المطار، يقول المسافر لأهله الذين يبقون: «<b>أستودعكم الله الذي لا تضيع ودائعه</b>». أي: أترككم في حفظ الله، والله لا يضيع ما يحفظه.", "ويقول المقيم للمسافر: «<b>أستودع الله دينك، وأمانتك، وخواتيم عملك</b>». فجدّة أنوس قالتها له وهي تبتسم، وأنوس شعر بالأمان."], "board": ["المسافر: أستودعكم الله", "المقيم: أستودع الله دينك"]}, {"h": "في السوق، وعند الغضب، وعند المعروف", "p": ["وإذا دخل أنوس <b>السوق</b> مع أبيه يقول: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو حيّ لا يموت، بيده الخير، وهو على كلّ شيء قدير». الناس في السوق ينشغلون بالشراء، وأنت تذكر الله!", "وإذا <b>غضب</b> يقول: «<b>أعوذ بالله من الشيطان الرجيم</b>»، كما تعلّمنا في حلقة الغضب.", "وإذا ساعده أحد أو أعطاه شيئًا يقول: «<b>جزاك الله خيرًا</b>».", "وإذا <b>تعثّرت</b> دراجته أو دابّته يقول: «<b>بسم الله</b>»، ولا يسبّ ولا يلعن."], "board": ["السوق", "الغضب: أعوذ بالله", "المعروف: جزاك الله خيرًا", "التعثّر: بسم الله"]}], "summary": ["إذا عطست قل: «الحمد لله»، ويقال لك: «يرحمك الله»، فتردّ: «يهديكم الله ويصلح بالكم»، وعند القيام من المجلس نقول دعاء الكفّارة.", "للركوب والسفر أدعية، وعند الرجوع نزيد: «آيبون، تائبون، عابدون، لربّنا حامدون»، ونستودع بعضنا الله عند الوداع.", "في السوق نذكر الله، وعند الغضب نستعيذ، ولمن صنع معروفًا نقول: «جزاك الله خيرًا»، وعند التعثّر: «بسم الله»."], "islam": {"intro": "قال الله تعالى يعلّمنا ما نقول إذا ركبنا:", "text": "فكل سيّارة أو طائرة تركبها نعمة سخّرها الله لك، فاشكره بدعاء الركوب في كل رحلة.", "ayah": {"text": "لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ", "src": "سُورَةُ الزُّخۡرُفِ: ١٣"}, "hadith": {"text": "أستودع الله دينك، وأمانتك، وخواتيم عملك", "source": "رواه أحمد والترمذي"}}, "home": {"title": "حقيبة سفر الأذكار", "goal": "أن يتدرّب الطفل على أذكار الركوب والسفر والوداع مع أسرته.", "materials": ["ظرف ورقي كبير", "بطاقات صغيرة"], "steps": ["اصنع من الظرف «حقيبة سفر» وزيّنها.", "اكتب على البطاقات: دعاء الركوب، دعاء المسافر للمقيم، دعاء المقيم للمسافر، آيبون تائبون.", "في كل مرّة تركب السيّارة مع أسرتك، أخرج بطاقة واقرأ الدعاء بصوت مسموع، والكل يردّد.", "مثّل مع إخوتك مشهد وداع: واحد مسافر وواحد مقيم، وكل واحد يقول دعاءه."], "parent": "اجعلوا دعاء الركوب عادة في كل مشوار بالسيّارة، ولو كان قصيرًا؛ فالتكرار اليومي أسرع طريق للحفظ."}, "online": {"title": "رحلة أنوس", "intro": "اركب مع أنوس وفصيح، ورتّب أذكار الرحلة، ثم ساعدهما في السوق!", "steps": [{"type": "order", "title": "رتّب أذكار العطاس", "prompt": "عطس أنوس! رتّب ما يقال بالترتيب الصحيح.", "items": ["أنوس يعطس ويقول: الحمد لله", "أخوه يقول: يرحمك الله", "أنوس يردّ: يهديكم الله ويصلح بالكم"]}, {"type": "match", "title": "صِل الموقف بدعائه", "prompt": "اختر الموقف، ثم الدعاء المناسب.", "pairs": [["المسافر يودّع أهله", "أستودعكم الله الذي لا تضيع ودائعه"], ["المقيم يودّع المسافر", "أستودع الله دينك وأمانتك وخواتيم عملك"], ["عند الغضب", "أعوذ بالله من الشيطان الرجيم"], ["تعثّرت الدابّة", "بسم الله"], ["القيام من المجلس", "سبحانك اللهمّ وبحمدك…"]]}, {"type": "decision", "title": "مختبر القرار: في السوق", "scenario": "دخل أنوس السوق مع أبيه، والناس مشغولون بالبيع والشراء والضجيج. ماذا يفعل أنوس؟", "options": [{"t": "يركض بين الناس ويصرخ ليلعب", "result": "هذا يزعج الناس، وقد يضيع أنوس في الزحام."}, {"t": "يشتكي ويطلب كل لعبة يراها", "result": "هذا يتعب أباه، والسوق ليس مكانًا للإلحاح."}, {"t": "يقول ذكر السوق: «لا إله إلا الله وحده لا شريك له…» ويمشي بجانب أبيه بهدوء", "result": "أحسنت! ذكرت الله في مكان يغفل فيه الناس عن ذكره.", "best": true}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح وجد ورقة لغز عن مسافر مسلم مشهور جدًّا. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أنا رحّالة، أحبّ السفر واكتشاف البلاد.", "طفت في العالم نحو ثلاثين سنة.", "كتبت رحلتي في كتاب مشهور يقرؤه الناس إلى اليوم."], "options": ["الإدريسي رحمه الله", "ابن بطوطة رحمه الله", "البيروني رحمه الله"], "deep": "لو سافرت ثلاثين سنة مثل هذا الرحّالة، كم مرّة ستقول دعاء السفر ودعاء الركوب؟ ولماذا يحتاج المسافر إلى حفظ الله؟", "reveal": "أنا ابن بطوطة رحمه الله، من مدينة طنجة في المغرب! زرت بلادًا كثيرة، ورأيت فيها المطر والريح والصحارى. وفي الحلقة القادمة نتعلّم أذكار المطر والريح والرعد، وكيف نُلقي السلام."}, "quiz": [{"q": "عطس صديقك وقال: «الحمد لله». ماذا تقول له؟", "o": ["يرحمك الله", "صحّة", "لا شيء"], "a": 0, "why": "نقول للعاطس الحامد: «يرحمك الله»."}], "qa": [{"id": 234, "q": "ما يقولُ الإنسانُ إذا عطس؟", "a": "«الحمد لله». وليقلْ له أخوهُ أو صاحبُه: «يرحمُكَ الله». فإذا قال له، فليقلْ: «يهديكمُ اللهُ ويُصلِحُ بالكم» رواه البخاري."}, {"id": 235, "q": "ما تقولُ عند القيامِ والفراغِ من المجلس «دعاء كفارة المجلس»؟", "a": "«سبحانك اللهمَّ وبحمدك، أشهدُ أن لا إله إلا أنت، أستغفرُكَ وأتوبُ إليك» رواه أبو داود والترمذي وغيرهما."}, {"id": 236, "q": "ما هو دعاءُ الركوب؟", "a": "«بسم الله، والحمد لله ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ ۝ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ﴾ [الزخرف: ١٣–١٤]، الحمد لله، الحمد لله، الحمد لله، الله أكبر، الله أكبر، الله أكبر، سبحانك اللهم إني ظلمتُ نفسي فاغفرْ لي؛ فإنه لا يغفرُ الذنوبَ إلا أنت» رواه أبو داود والترمذي."}, {"id": 237, "q": "ما دعاءُ السفر؟", "a": "«الله أكبر، الله أكبر، الله أكبر ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ ۝ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ﴾ [الزخرف: ١٣–١٤]، اللهم إنا نسألُكَ في سفرِنا هذا البرَّ والتقوى، ومن العملِ ما ترضى، اللهم هوِّنْ علينا سفرَنا هذا، واطوِ عنا بعدَه، اللهم أنت الصاحبُ في السفر، والخليفةُ في الأهل، اللهم إني أعوذُ بك من وعثاءِ السفر، وكآبةِ المنظر، وسوءِ المنقلبِ في المالِ والأهل». وإذا رجعَ قالهنَّ، وزاد: «آيبون، تائبون، عابدون، لربنا حامدون» رواه مسلم."}, {"id": 238, "q": "ما هو دعاءُ المسافرِ للمقيم؟", "a": "«أستودعُكمُ اللهَ الذي لا تضيعُ ودائعُه» رواه أحمد وابن ماجه."}, {"id": 239, "q": "ما هو دعاءُ المقيمِ للمسافر؟", "a": "«أستودعُ اللهَ دينَك، وأمانتَك، وخواتيمَ عملك» رواه أحمد والترمذي."}, {"id": 240, "q": "ما هو دعاءُ دخولِ السوق؟", "a": "«لا إله إلا الله وحده لا شريك له، له الملكُ وله الحمد، يُحيي ويُميت، وهو حيٌّ لا يموت، بيدِهِ الخير، وهو على كلِّ شيءٍ قدير» رواه الترمذي وابن ماجه."}, {"id": 241, "q": "ما الدعاءُ عند الغضب؟", "a": "«أعوذُ بالله من الشيطانِ الرجيم» متفق عليه."}, {"id": 242, "q": "ما تقولُ لمن صنعَ إليك معروفًا؟", "a": "«جزاكَ اللهُ خيرًا» رواه الترمذي."}, {"id": 243, "q": "ما هو الدعاءُ إذا تعِسَ المركوب؟", "a": "«بسم الله» رواه أبو داود."}], "dyk": ["الصحراءُ الكبرى قد تُغطَّى بالثلجِ نادراً، وبعضُ الصحاري كانتْ بحاراً قبلَ ملايينِ السنين."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي حَقِيبَةُ السَّفَرِ!"}, {"s": "fasih", "t": "وَأَنَا فَصِيح، بِنَظَّارَتِيَ الشَّمْسِيَّةِ! جَوَابُ اللُّغْزِ الْمَاضِي: زَكَرِيَّا عَلَيْهِ السَّلَامُ، دَعَا رَبَّهُ فِي الْمِحْرَابِ فَاسْتَجَابَ لَهُ. يَا أَنُوس، هَلْ حَزَمْتَ أَذْكَارَ السَّفَرِ؟"}, {"s": "anos", "t": "هَيَّا نَحْزِمُهَا مَعًا! اسْأَلْ يَا فَصِيح."}, {"s": "fasih", "t": "مَاذَا يَقُولُ مَنْ عَطَسَ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ، فَيَقُولُ لَهُ أَخُوهُ: يَرْحَمُكَ اللَّهُ، فَيَرُدُّ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ. رَوَاهُ الْبُخَارِيُّ."}, {"s": "fasih", "t": "وَعِنْدَ الْقِيَامِ مِنَ الْمَجْلِسِ؟"}, {"s": "anos", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. هَذَا دُعَاءُ كَفَّارَةِ الْمَجْلِسِ."}, {"s": "fasih", "t": "وَدُعَاءُ الرُّكُوبِ؟"}, {"s": "anos", "t": "أَقُولُ: بِسْمِ اللَّهِ، وَالْحَمْدُ لِلَّهِ، ثُمَّ أَقْرَأُ آيَتَيْنِ مِنْ سُورَةِ الزُّخْرُفِ. اسْمَعُوا أُولَاهُمَا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "43:13", "t": "لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ"}, {"s": "fasih", "t": "وَبَعْدَهَا الْآيَةُ الَّتِي تَلِيهَا، ثُمَّ: الْحَمْدُ لِلَّهِ ثَلَاثًا، اللَّهُ أَكْبَرُ ثَلَاثًا، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ."}, {"s": "anos", "t": "فَكُلُّ سَيَّارَةٍ أَوْ طَائِرَةٍ نَرْكَبُهَا نِعْمَةٌ سَخَّرَهَا اللَّهُ لَنَا، فَنَشْكُرُهُ بِهَذَا الدُّعَاءِ."}, {"s": "fasih", "t": "وَدُعَاءُ السَّفَرِ؟"}, {"s": "anos", "t": "أُكَبِّرُ ثَلَاثًا، وَأَقْرَأُ آيَتَيِ الرُّكُوبِ، ثُمَّ: اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ. وَإِذَا رَجَعْتُ زِدْتُ: آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ."}, {"s": "fasih", "t": "وَمَاذَا يَقُولُ الْمُسَافِرُ لِأَهْلِهِ؟"}, {"s": "anos", "t": "أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ."}, {"s": "fasih", "t": "وَمَاذَا يَقُولُ الْمُقِيمُ لِلْمُسَافِرِ؟"}, {"s": "anos", "t": "أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ. رَوَاهُ أَحْمَدُ وَالتِّرْمِذِيُّ."}, {"s": "fasih", "t": "وَعِنْدَ دُخُولِ السُّوقِ؟"}, {"s": "anos", "t": "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."}, {"s": "fasih", "t": "وَعِنْدَ الْغَضَبِ؟"}, {"s": "anos", "t": "أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ."}, {"s": "fasih", "t": "وَلِمَنْ صَنَعَ إِلَيْكَ مَعْرُوفًا؟"}, {"s": "anos", "t": "جَزَاكَ اللَّهُ خَيْرًا."}, {"s": "fasih", "t": "وَإِذَا تَعِسَ الْمَرْكُوبُ، يَعْنِي تَعَثَّرَ؟"}, {"s": "anos", "t": "بِسْمِ اللَّهِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الصَّحْرَاءُ الْكُبْرَى قَدْ تُغَطِّيهَا الثُّلُوجُ نَادِرًا، وَبَعْضُ الصَّحَارِي كَانَتْ بِحَارًا قَبْلَ مَلَايِينِ السِّنِينَ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: رِحْلَةُ الْحَافِلَةِ الذَّاكِرَةِ. اجْلِسُوا كَأَنَّكُمْ فِي حَافِلَةٍ، وَفِي كُلِّ مَحَطَّةٍ ذِكْرُهَا: الرُّكُوبُ، السُّوقُ، الْعُطَاسُ، الرُّجُوعُ. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَانْطَلِقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: رحلة الحافلة الذاكرة"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! تَعَثَّرَتْ دَرَّاجَةُ أَنُوس بِحَجَرٍ. أ: يَسُبُّ الدَّرَّاجَةَ وَالْحَجَرَ. ب: يَقُولُ: بِسْمِ اللَّهِ، وَيُبْعِدُ الْحَجَرَ عَنِ الطَّرِيقِ. ج: يَرْكُلُ الدَّرَّاجَةَ بِغَضَبٍ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الدراجة تعثّرت"}, {"s": "anos", "t": "ب هُوَ الصَّحِيحُ: ذِكْرُ اللَّهِ، وَإِمَاطَةُ الْأَذَى صَدَقَةٌ. أَمَّا أ وَج فَسَبٌّ وَغَضَبٌ مَذْمُومٌ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: أَعْطَتْكَ أُخْتُكَ قَلَمَهَا. مَاذَا تَقُولُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "جَزَاكِ اللَّهُ خَيْرًا! وَمَاذَا يَزِيدُ الْمُسَافِرُ إِذَا رَجَعَ؟ فَكِّرُوا… آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: رَحَّالَةٌ أُحِبُّ اكْتِشَافَ الْبِلَادِ، طُفْتُ الْعَالَمَ نَحْوَ ثَلَاثِينَ سَنَةً، وَكَتَبْتُ رِحْلَتِي فِي كِتَابٍ مَشْهُورٍ. الْإِدْرِيسِيُّ، أَمِ ابْنُ بَطُّوطَةَ، أَمِ الْبِيرُونِيُّ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ احْزِمُوا «حَقِيبَةَ سَفَرِ الْأَذْكَارِ»، وَارْكَبُوا «رِحْلَةَ أَنُوس» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 28, "title": "أذكار أحبّها (٤): المطر والريح والسلام", "season": 3, "goals": ["adhkar"], "hook": "طق… طق… طق! قطرات المطر تنقر على النافذة، وفصيح ينفض ريشه المبلول ويقول: «مطر! مطر! ماذا نقول يا أنوس؟». ثم يهبّ الهواء بقوّة، ويقرقر الرعد: بووم! تعالوا نتعلّم أذكار الجوّ، وأذكار الفرح والحزن، والسلام!", "sections": [{"h": "في الفرح وفي الحزن", "p": ["نجح أنوس في الامتحان! فقال: «<b>الحمد لله الذي بنعمته تتمّ الصالحات</b>». فكلّ خير يحصل لنا هو من نعمة الله.", "وفي يوم آخر انكسرت لعبته المفضّلة، فحزن قليلًا، ثم قال: «<b>الحمد لله على كلّ حال</b>». فالمؤمن يحمد الله في الفرح وفي الحزن. فصيح يقول: «هذا هو الصبر الذي تعلّمناه!»."], "board": ["ما يسرّني: الحمد لله الذي بنعمته تتمّ الصالحات", "ما أكرهه: الحمد لله على كلّ حال"]}, {"h": "السلام: هديّة نتبادلها", "p": ["إذا لقي أنوس صديقه يقول: «<b>السلام عليكم ورحمة الله وبركاته</b>». فيردّ صديقه: «<b>وعليكم السلام ورحمة الله وبركاته</b>».", "كلّ كلمة في السلام دعاء: السلام يعني السلامة من كلّ شرّ، والرحمة من الله، والبركة يعني الخير الكثير. فالسلام هديّة نعطيها لكلّ مسلم نلقاه!"], "board": ["السلام عليكم ورحمة الله وبركاته", "وعليكم السلام ورحمة الله وبركاته"]}, {"h": "المطر والريح والرعد", "p": ["إذا نزل <b>المطر</b> يقول أنوس: «<b>اللهم صيّبًا نافعًا</b>»، أي: اجعله مطرًا نافعًا يسقي الزرع والناس. وبعد أن ينزل المطر يقول: «<b>مُطرنا بفضل الله ورحمته</b>»؛ فالمطر من فضل الله، لا من غيره.", "وإذا هبّت <b>الريح</b> يقول: «<b>اللهم إني أسألك خيرها، وأعوذ بك من شرّها</b>». فالريح قد تحمل الخير، مثل السحاب، وقد تحمل الشرّ.", "وإذا سمع <b>الرعد</b> يقول: «<b>سبحان الذي يسبّح الرعد بحمده والملائكة من خيفته</b>». فصيح يرتجف ويقول: «حتى الرعد يسبّح الله!». نعم يا فصيح، كما أخبرنا القرآن."], "board": ["المطر: اللهم صيّبًا نافعًا", "بعده: مُطرنا بفضل الله ورحمته", "الريح", "الرعد"]}, {"h": "المبتلى، والعين، والصلاة على النبيّ ﷺ", "p": ["إذا رأى أنوس إنسانًا <b>مبتلى</b> بمرض أو مصيبة يقول في سرّه: «<b>الحمد لله الذي عافاني ممّا ابتلاك به، وفضّلني على كثير ممّن خلق تفضيلًا</b>». ويقولها <b>بصوت منخفض</b> حتى لا يسمعها المبتلى فيحزن، فهذه رحمة وأدب.", "وإذا أعجبه شيء عند أخيه أو عند نفسه، مثل رسمة جميلة أو دراجة جديدة، <b>يدعو له بالبركة</b>، مثل: «بارك الله لك»؛ لأنّ النبيّ ﷺ قال: «فإنّ العين حقّ».", "ونختم بأجمل ذكر: <b>الصلاة على النبيّ ﷺ</b>: «اللهم صلّ على محمد وعلى آل محمد، كما صلّيت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد، كما باركت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد»."], "board": ["المبتلى: سرًّا", "ما يعجبك: بارك الله", "الصلاة الإبراهيمية"]}], "summary": ["في الفرح: «الحمد لله الذي بنعمته تتمّ الصالحات»، وفيما نكره: «الحمد لله على كلّ حال»، والسلام: «السلام عليكم ورحمة الله وبركاته» وردّه مثله.", "للمطر: «اللهم صيّبًا نافعًا» و«مُطرنا بفضل الله ورحمته»، وللريح والرعد أذكارهما.", "ندعو سرًّا عند رؤية المبتلى، وندعو بالبركة لما يعجبنا، ونصلّي على النبيّ ﷺ بالصلاة الإبراهيمية."], "islam": {"intro": "قال الله تعالى يخبرنا أنّ الرعد يسبّحه:", "text": "فكلّ شيء حولنا يسبّح الله: الرعد، والملائكة، والطيور. فلنكن نحن أيضًا من المسبّحين.", "ayah": {"text": "وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ", "src": "سُورَةُ الرَّعۡدِ: ١٣"}, "hadith": {"text": "اللهم صيّبًا نافعًا", "source": "رواه البخاري"}}, "home": {"title": "دفتر الطقس الذاكر", "goal": "أن يطبّق الطفل أذكار المطر والريح والرعد والسلام في حياته اليومية.", "materials": ["دفتر صغير", "أقلام تلوين"], "steps": ["ارسم في كل صفحة رمزًا: غيمة ممطرة، رياح، رعد، يدان تتصافحان.", "اكتب تحت كل رمز ذكره الذي تعلّمته اليوم.", "كلّما رأيت المطر أو سمعت الرعد هذا الأسبوع، قل الذكر، ولوّن نجمة في الصفحة.", "سلّم على كل فرد في أسرتك السلام الكامل «السلام عليكم ورحمة الله وبركاته»، وعدّ كم مرّة رددت السلام كاملًا."], "parent": "إذا نزل المطر فقفوا مع أطفالكم عند النافذة وقولوا الدعاء معًا؛ فاللحظات الجميلة تثبّت الذكر في القلب."}, "online": {"title": "نافذة أنوس", "intro": "انظر من نافذة أنوس: مطر، وريح، ورعد! قل الذكر المناسب لكلّ موقف.", "steps": [{"type": "match", "title": "صِل الموقف بذكره", "prompt": "اختر الموقف، ثم الذكر المناسب.", "pairs": [["نزل المطر", "اللهم صيّبًا نافعًا"], ["بعد نزول المطر", "مُطرنا بفضل الله ورحمته"], ["هبّت الريح", "اللهم إني أسألك خيرها، وأعوذ بك من شرّها"], ["سمعت الرعد", "سبحان الذي يسبّح الرعد بحمده"], ["نجحت في الامتحان", "الحمد لله الذي بنعمته تتمّ الصالحات"]]}, {"type": "sort", "title": "في الفرح أم فيما أكره؟", "prompt": "اضغط على الموقف، ثم اختر الذكر المناسب له.", "bins": ["الحمد لله الذي بنعمته تتمّ الصالحات", "الحمد لله على كلّ حال"], "items": [{"t": "فزت في مسابقة القرآن", "icon": "🏆", "bin": 0, "why": "هذا يسرّك، فتحمد الله على نعمته."}, {"t": "جاءت جدّتي لزيارتنا", "icon": "👵", "bin": 0, "why": "خبر مفرح ونعمة من الله."}, {"t": "شفيت من الزكام", "icon": "💪", "bin": 0, "why": "الشفاء نعمة تسرّك."}, {"t": "انكسر قلمي المفضّل", "icon": "✏️", "bin": 1, "why": "هذا ممّا تكره، فتحمد الله على كلّ حال."}, {"t": "أُلغيت الرحلة بسبب المطر", "icon": "🌧️", "bin": 1, "why": "نحمد الله ولا نتسخّط."}, {"t": "أصابني صداع", "icon": "🤒", "bin": 1, "why": "المؤمن يصبر ويحمد الله على كلّ حال."}]}, {"type": "quiz", "title": "تحدّي فصيح", "items": [{"q": "كيف نقول دعاء رؤية المبتلى؟", "o": ["بصوت عالٍ", "سرًّا حتى لا يتأذّى", "لا نقوله"], "a": 1, "why": "يُسرّ بها حتى لا يسمعها المبتلى فيتأذّى."}, {"q": "الصلاة على النبيّ ﷺ فيها: «كما صلّيت على…»", "o": ["إبراهيم وآل إبراهيم", "موسى", "نوح"], "a": 0, "why": "هذه الصلاة الإبراهيمية، متّفق عليه."}, {"q": "المطر ينزل…", "o": ["بلا سبب", "بفضل النجوم", "بفضل الله ورحمته"], "a": 2, "why": "نقول: «مُطرنا بفضل الله ورحمته»."}]}]}, "case": {"title": "مَن أنا؟", "story": "فصيح سمع صوت المطر الغزير، فتذكّر لغزًا عن نبيّ وطوفان عظيم. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["دعوت قومي ألف سنة إلا خمسين عامًا، فما آمن معي إلا قليل.", "صنعت السفينة بأمر الله.", "نجوت أنا والمؤمنون من الطوفان."], "options": ["هود عليه السلام", "صالح عليه السلام", "نوح عليه السلام"], "deep": "المطر رحمة، وقد يكون عذابًا لمن كذّب. لماذا ندعو: «اللهم صيّبًا نافعًا»؟", "reveal": "أنا نوح عليه السلام! صبرت على دعوة قومي سنين طويلة، فنجّاني الله ومن آمن معي في السفينة. وفي الحلقة القادمة ندخل «منوّعات»: الأحكام الخمسة، ونعم الله، وأعياد المسلمين."}, "quiz": [{"q": "انكسرت لعبتك. ماذا تقول؟", "o": ["الحمد لله على كلّ حال", "لن ألعب أبدًا", "الحمد لله الذي بنعمته تتمّ الصالحات"], "a": 0, "why": "إذا حصل ما نكره نقول: «الحمد لله على كلّ حال»."}], "qa": [{"id": 244, "q": "ما تقولُ إذا حصلَ لك ما يسرّك؟", "a": "«الحمدُ لله الذي بنعمتهِ تتمُّ الصالحات» رواه الحاكم وغيره."}, {"id": 245, "q": "ماذا تقولُ إذا حصلَ ما تكرهه؟", "a": "«الحمدُ لله على كلِّ حال» صحيح الجامع."}, {"id": 246, "q": "ما هي كيفيةُ السلامِ وردِّ السلام؟", "a": "يقولُ المسلم: «السلامُ عليكم ورحمةُ اللهِ وبركاتُه». ويردُ عليه أخوه: «وعليكم السلامُ ورحمةُ اللهِ وبركاتُه» رواه الترمذي وأبو داود وغيرهما."}, {"id": 247, "q": "ما هو الدعاءُ عند نزولِ المطر؟", "a": "«اللهم صيّبًا نافعًا» رواه البخاري."}, {"id": 248, "q": "وما هو الدعاءُ بعد نزولِ المطر؟", "a": "«مُطِرنا بفضلِ اللهِ ورحمته» البخاري ومسلم."}, {"id": 249, "q": "ما دعاءُ الريح؟", "a": "«اللهم إني أسألُك خيرَها، وأعوذُ بك من شرِّها» أبو داود وابن ماجه."}, {"id": 250, "q": "ما دعاءُ سماعِ الرعد؟", "a": "«سبحانَ الذي يسبّحُ الرعدُ بحمدهِ والملائكةُ من خيفته» موطأ مالك."}, {"id": 251, "q": "ما هو الدعاءُ إذا رأيتَ مبتلى؟", "a": "«الحمدُ لله الذي عافاني مما ابتلاك به، وفضّلني على كثيرٍ ممن خلقَ تفضيلًا» رواه الترمذي. (ويُسرّ بها حتى لا يسمعَها المبتلى فيتأذّى)."}, {"id": 252, "q": "ما الدعاءُ لمن خشيَ أن يصيبَ شيئًا بعينه؟", "a": "في الحديث: «إذا رأى أحدُكم من أخيه، أو من نفسه، أو من مالهِ ما يعجبه، فليدعُ له بالبركة؛ فإنَّ العينَ حق» رواه أحمد وابن ماجه وغيرهما."}, {"id": 253, "q": "كيف تصلي على النبيِّ عليه الصلاةُ والسلام؟", "a": "«اللهم صلِّ على محمدٍ وعلى آلِ محمد، كما صليتَ على إبراهيم، وعلى آلِ إبراهيم، إنك حميدٌ مجيد، اللهم باركْ على محمدٍ وعلى آلِ محمد، كما باركتَ على إبراهيم، وعلى آلِ إبراهيم، إنك حميدٌ مجيد» متفق عليه."}], "dyk": ["البرقُ أسخنُ من سطحِ الشمس، وسرعتُه تفوقُ تصوُّرَنا، ومع ذلك يحفظُنا اللهُ منه."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَالْمَطَرُ يَنْقُرُ عَلَى النَّافِذَةِ: طَقْ… طَقْ… طَقْ!"}, {"s": "fasih", "t": "وَأَنَا فَصِيح، وَرِيشِي مَبْلُولٌ! جَوَابُ اللُّغْزِ الْمَاضِي: ابْنُ بَطُّوطَةَ رَحِمَهُ اللَّهُ، الرَّحَّالَةُ مِنْ طَنْجَةَ فِي الْمَغْرِبِ."}, {"s": "anos", "t": "وَالْيَوْمَ أَذْكَارُ الْمَطَرِ وَالرِّيحِ وَالسَّلَامِ. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "مَاذَا تَقُولُ إِذَا حَصَلَ لَكَ مَا يَسُرُّكَ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ."}, {"s": "fasih", "t": "وَإِذَا حَصَلَ مَا تَكْرَهُهُ؟ مِثْلَ أَنْ تَنْكَسِرَ لُعْبَتُكَ؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ."}, {"s": "fasih", "t": "وَكَيْفَ نُلْقِي السَّلَامَ وَنَرُدُّهُ؟"}, {"s": "anos", "t": "يَقُولُ الْمُسْلِمُ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَيَرُدُّ أَخُوهُ: وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ."}, {"s": "fasih", "t": "وَعِنْدَ نُزُولِ الْمَطَرِ؟"}, {"s": "anos", "t": "اللَّهُمَّ صَيِّبًا نَافِعًا. رَوَاهُ الْبُخَارِيُّ."}, {"s": "fasih", "t": "وَبَعْدَ نُزُولِهِ؟"}, {"s": "anos", "t": "مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ."}, {"s": "fasih", "t": "وُوووش! هَبَّتِ الرِّيحُ! مَاذَا أَقُولُ؟"}, {"s": "anos", "t": "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا."}, {"s": "fasih", "t": "بُووم! الرَّعْدُ! مَاذَا أَقُولُ؟"}, {"s": "anos", "t": "سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ، وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ. وَهَذَا الذِّكْرُ مِنْ مَعْنَى آيَةٍ فِي سُورَةِ الرَّعْدِ، اسْمَعُوهَا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "13:13", "t": "وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ"}, {"s": "fasih", "t": "فَكُلُّ شَيْءٍ حَوْلَنَا يُسَبِّحُ اللَّهَ: الرَّعْدُ، وَالْمَلَائِكَةُ، وَالطُّيُورُ. فَلْنَكُنْ نَحْنُ أَيْضًا مِنَ الْمُسَبِّحِينَ!"}, {"s": "anos", "t": "أَحْسَنْتَ! السُّؤَالُ التَّالِي؟"}, {"s": "fasih", "t": "مَاذَا تَقُولُ إِذَا رَأَيْتَ مُبْتَلًى؟"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا. وَأَقُولُهَا سِرًّا، حَتَّى لَا يَسْمَعَهَا فَيَتَأَذَّى."}, {"s": "fasih", "t": "وَإِذَا خِفْتُ أَنْ أُصِيبَ شَيْئًا بِعَيْنِي؟"}, {"s": "anos", "t": "إِذَا أَعْجَبَكَ شَيْءٌ مِنْ أَخِيكَ، أَوْ نَفْسِكَ، أَوْ مَالِكَ، فَادْعُ لَهُ بِالْبَرَكَةِ، فَإِنَّ الْعَيْنَ حَقٌّ. قُلْ: بَارَكَ اللَّهُ لَكَ."}, {"s": "fasih", "t": "وَكَيْفَ نُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟"}, {"s": "anos", "t": "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ الْبَرْقُ أَسْخَنُ مِنْ سَطْحِ الشَّمْسِ، وَسُرْعَتُهُ تَفُوقُ تَصَوُّرَنَا، وَمَعَ ذَلِكَ يَحْفَظُنَا اللَّهُ مِنْهُ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: لُعْبَةُ الطَّقْسِ الذَّاكِرِ. صُورَةُ الْمَطَرِ: نُحَرِّكُ أَصَابِعَنَا كَالْقَطَرَاتِ. الرِّيحُ: نَتَمَايَلُ كَالْأَشْجَارِ. الرَّعْدُ: نُسَبِّحُ. وَمَعَ كُلِّ صُورَةٍ ذِكْرُهَا. أَوْقِفُوا الْحَلْقَةَ الْآنَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: لعبة الطقس الذاكر"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! رَأَى أَنُوس فِي الْمُسْتَشْفَى رَجُلًا مَرِيضًا لَا يَسْتَطِيعُ الْمَشْيَ. أ: يَقُولُ الدُّعَاءَ بِصَوْتٍ عَالٍ أَمَامَهُ. ب: يَضْحَكُ وَيُشِيرُ إِلَيْهِ. ج: يَقُولُ الدُّعَاءَ فِي سِرِّهِ، وَيَبْتَسِمُ لَهُ، وَيَدْعُو لَهُ بِالشِّفَاءِ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: الرجل المريض"}, {"s": "anos", "t": "ج هُوَ الصَّحِيحُ: نَقُولُهُ سِرًّا وَنَرْحَمُهُ. أ قَدْ يُحْزِنُهُ، وَب اسْتِهْزَاءٌ مُحَرَّمٌ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: انْكَسَرَتْ لُعْبَتُكَ. مَاذَا تَقُولُ؟ فَكِّرُوا…"}, {"s": "anos", "t": "الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ! وَأَعْجَبَتْكَ رَسْمَةُ صَدِيقِكَ؟ فَكِّرُوا… قُلْ: بَارَكَ اللَّهُ لَكَ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: دَعَوْتُ قَوْمِي أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا، وَصَنَعْتُ السَّفِينَةَ بِأَمْرِ اللَّهِ، وَنَجَوْتُ أَنَا وَالْمُؤْمِنُونَ مِنَ الطُّوفَانِ. هُودٌ، أَمْ صَالِحٌ، أَمْ نُوحٌ، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ اكْتُبُوا «دَفْتَرَ الطَّقْسِ الذَّاكِرِ»، وَانْظُرُوا مِنْ «نَافِذَةِ أَنُوس» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 29, "title": "منوّعات (١): الأحكام والنعم والأعياد", "season": 3, "goals": ["munawaat"], "hook": "فصيح يحمل سلّة ملوّنة فيها أشياء كثيرة ويقول: «منوّعات! منوّعات! سؤال من هنا، وسؤال من هناك!». أنوس يضحك: «سلّة فصيح فيها أحكام، ونعم، وأعياد!». هيّا نفتح السلّة معًا!", "sections": [{"h": "الأحكام الخمسة: إشارات الطريق", "p": ["كلّ عمل نعمله له حكم في الإسلام، والأحكام خمسة، مثل إشارات الطريق:", "١. <b>الواجب</b>: لا بدّ أن نفعله، مثل الصلوات الخمس، وصيام رمضان، وبرّ الوالدين. من فعله أُثيب، ومن تركه عوقب.", "٢. <b>المستحبّ</b> (ويسمّى السنّة والمندوب): فعله جميل وليس لازمًا، مثل السنن الرواتب، وقيام الليل، وإطعام الطعام. من فعله أُثيب، ومن تركه لم يُعاقب.", "٣. <b>المحرّم</b>: لا بدّ أن نتركه، مثل ترك الصلاة، وشرب الخمر، وعقوق الوالدين، وقطع الأرحام. من تركه أُثيب، ومن فعله عوقب.", "٤. <b>المكروه</b>: الأفضل أن نتركه، مثل الأخذ والإعطاء باليد الشمال، وكفّ الثوب في الصلاة. من تركه أُثيب، ومن فعله لم يُعاقب.", "٥. <b>المباح</b> (ويسمّى الجائز والحلال): أنت مخيّر، مثل أكل التفّاحة وشرب الشاي. لا ثواب ولا عقاب."], "board": ["واجب", "مستحبّ", "محرّم", "مكروه", "مباح"]}, {"h": "الفقه في الدين، والبيع الحلال", "p": ["<b>الفقه</b> أن تفهم أحكام دينك. وثمرته أن تصحّ أقوالك وأعمالك وعقيدتك، فتسعد في الدنيا والآخرة. وقال النبيّ ﷺ: «من يرد الله به خيرًا يفقّهه في الدين». فصيح يقول: «يعني نحن الآن في خير لأننا نتعلّم!».", "و<b>الأصل في البيع والمعاملات أنها حلال</b>، إلا أنواعًا حرّمها الله. ومن البيوع المحرّمة: <b>الغشّ</b> مثل إخفاء عيب السلعة، و<b>الربا</b> مثل أن تقترض ألفًا على أن تردّها ألفين؛ فالزيادة هي الربا، و<b>الغرر والجهالة</b> مثل أن تبيع سمكة ما زالت في البحر ولم تصطدها بعد!"], "board": ["الأصل: البيع حلال", "لا غشّ", "لا ربا", "لا غرر"]}, {"h": "نعم الله… لا تُعدّ ولا تُحصى", "p": ["أنوس يحاول أن يعدّ نعم الله: «<b>نعمة الإسلام</b>، فأنا مسلم والحمد لله. <b>ونعمة السنّة</b>، فأنا أتّبع سنّة النبيّ ﷺ ولا أخترع في الدين شيئًا جديدًا. <b>ونعمة الصحّة</b>: عيناي أرى بهما، وأذناي أسمع بهما، ورجلاي أمشي بهما. <b>ونعمة الطعام والشراب واللباس</b>…». ثم توقّف وقال: «لا أستطيع أن أعدّها كلّها!».", "صدقت يا أنوس؛ قال تعالى: «وإن تعدّوا نعمة الله لا تحصوها».", "فكيف نشكر النعم؟ <b>بالحمد باللسان</b>: نقول الحمد لله، ونعرف أنّ الفضل لله وحده. و<b>باستعمال النعم فيما يرضي الله</b>: فالعين ننظر بها إلى الخير، واليد نساعد بها، ولا نستعمل النعم في المعصية."], "board": ["الإسلام", "السنّة", "الصحّة", "الطعام واللباس"]}, {"h": "أعيادنا وأفضل الأوقات", "p": ["للمسلمين <b>عيدان</b>: <b>عيد الفطر</b> و<b>عيد الأضحى</b>. لمّا قدم النبيّ ﷺ المدينة، وجد لأهلها يومين يلعبون فيهما، فقال: «إنّ الله قد أبدلكم بهما خيرًا منهما: يوم الأضحى، ويوم الفطر». وما سواهما من الأعياد فهو من البدع، أي أمور جديدة ليست من ديننا. وفي عيدينا نفرح، ونلبس الجديد، ونلعب، ونزور الأقارب.", "وفصيح يحبّ «الأفضل»: <b>أفضل الشهور</b> رمضان، و<b>أفضل الأيام</b> يوم الجمعة، و<b>أفضل يوم في العام</b> يوم النحر، وقيل يوم عرفة، و<b>أفضل ليلة في العام</b> ليلة القدر."], "board": ["عيد الفطر", "عيد الأضحى", "رمضان", "الجمعة", "ليلة القدر"]}], "summary": ["الأحكام خمسة: الواجب والمستحبّ والمحرّم والمكروه والمباح، ولكلّ منها ثواب أو عقاب يختلف.", "الأصل في البيع الحلّ، ويحرم الغشّ والربا والغرر، والفقه في الدين علامة خير.", "نعم الله لا تُحصى، ونشكرها بالحمد واستعمالها في الطاعة، وعيدانا الفطر والأضحى، وأفضل الشهور رمضان، والأيام الجمعة، والليالي ليلة القدر."], "islam": {"intro": "قال الله تعالى عن نعمه الكثيرة:", "text": "فقبل النوم الليلة، عُدّ خمس نعم أعطاك الله إيّاها اليوم، وقل بعد كلّ واحدة: الحمد لله.", "ayah": {"text": "وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌۭ رَّحِيمٌۭ", "src": "سُورَةُ النَّحۡلِ: ١٨"}, "hadith": {"text": "من يرد الله به خيرًا يفقّهه في الدين", "source": "رواه البخاري ومسلم"}}, "home": {"title": "شجرة النعم", "goal": "أن يتعرّف الطفل على نعم الله في حياته، ويشكرها باللسان والعمل.", "materials": ["ورقة كبيرة", "أوراق خضراء على شكل أوراق شجر", "لاصق"], "steps": ["ارسم جذع شجرة كبيرًا، واكتب عليه: «وإن تعدّوا نعمة الله لا تحصوها».", "كل يوم اكتب مع أسرتك ثلاث نعم على ثلاث أوراق خضراء، والصقها على الشجرة.", "اكتب تحت كل نعمة كيف تشكرها بالعمل، مثل: «عيناي: أقرأ بهما القرآن».", "في آخر الأسبوع عدّوا الأوراق، وقولوا جميعًا: الحمد لله."], "parent": "ساعدوا طفلكم على ملاحظة النعم الصغيرة اليومية كالماء والنوم والأمان، وكونوا قدوة في قول «الحمد لله»."}, "online": {"title": "سلّة فصيح", "intro": "افتح سلّة فصيح: صنّف الأعمال حسب حكمها، واعرف أفضل الأوقات!", "steps": [{"type": "sort", "title": "ما حكم هذا العمل؟", "prompt": "اضغط على العمل، ثم اختر حكمه.", "bins": ["واجب", "مستحبّ", "محرّم", "مكروه", "مباح"], "items": [{"t": "الصلوات الخمس", "icon": "🕌", "bin": 0, "why": "واجبة: يُثاب فاعلها ويُعاقب تاركها."}, {"t": "برّ الوالدين", "icon": "👨‍👩‍👦", "bin": 0, "why": "من الواجب كما في الكتاب."}, {"t": "قيام الليل", "icon": "🌙", "bin": 1, "why": "مستحبّ: يُثاب فاعله ولا يُعاقب تاركه."}, {"t": "إطعام الطعام", "icon": "🍲", "bin": 1, "why": "من المستحبّ."}, {"t": "عقوق الوالدين", "icon": "💔", "bin": 2, "why": "محرّم: يُعاقب فاعله."}, {"t": "الأخذ باليد الشمال", "icon": "✋", "bin": 3, "why": "مكروه: يُثاب تاركه ولا يُعاقب فاعله."}, {"t": "شرب الشاي", "icon": "🍵", "bin": 4, "why": "مباح: لا ثواب ولا عقاب."}]}, {"type": "match", "title": "صِل بالأفضل", "prompt": "اختر السؤال، ثم جوابه.", "pairs": [["أفضل الشهور", "شهر رمضان"], ["أفضل الأيام", "يوم الجمعة"], ["أفضل يوم في العام", "يوم النحر، وقيل يوم عرفة"], ["أفضل ليلة في العام", "ليلة القدر"]]}, {"type": "quiz", "title": "تحدّي فصيح", "items": [{"q": "الأصل في البيع والمعاملات أنها…", "o": ["حرام كلّها", "حلال إلا ما حرّم الله", "مكروهة"], "a": 1, "why": "«وأحلّ الله البيع وحرّم الربا»."}, {"q": "كيف نشكر نعم الله؟", "o": ["بالحمد واستعمالها في الطاعة", "بنسيانها", "باستعمالها في المعصية"], "a": 0, "why": "الشكر بالحمد باللسان واستعمال النعم فيما يرضي الله."}, {"q": "بيع السمكة في الماء قبل صيدها هو…", "o": ["بيع حلال", "صدقة", "غرر منهيّ عنه"], "a": 2, "why": "«نهى رسول الله ﷺ عن بيع الغرر»."}]}]}, "case": {"title": "مَن أنا؟", "story": "في عيد الأضحى سأل فصيح: «لماذا نذبح الأضاحي؟». فأخرج أنوس لغزًا عن نبيّ صابر. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["أمر الله أبي أن يذبحني، فصبرت وسلّمت لأمر الله.", "فداني الله بكبش عظيم.", "ساعدت أبي في رفع قواعد الكعبة."], "options": ["إبراهيم عليه السلام", "إسماعيل عليه السلام", "يوسف عليه السلام"], "deep": "ما علاقة هذه القصّة بعيد الأضحى؟ وماذا نتعلّم من طاعة هذا الابن لأبيه ولربّه؟", "reveal": "أنا إسماعيل عليه السلام! ونحن في عيد الأضحى نذبح الأضاحي تقرّبًا إلى الله، ونتذكّر طاعة أبي إبراهيم وصبري. وفي الحلقة القادمة، آخر حلقة في السلسلة: التقوى والتوبة ومعاني الأذكار، والمسابقة الكبرى!"}, "quiz": [{"q": "صيام رمضان حكمه…", "o": ["مباح", "واجب", "مكروه"], "a": 1, "why": "صيام رمضان من الواجب: يُثاب فاعله ويُعاقب تاركه."}], "qa": [{"id": 254, "q": "ما هي الأحكامُ التكليفيةُ الخمسة؟", "a": "١. الواجب. ٢. المستحب. ٣. المحرم. ٤. المكروه. ٥. المباح."}, {"id": 255, "q": "اشرحْ هذه الأحكامَ الخمسة.", "a": "١. الواجب: وهو على وجهِ اللزوم، مثلُ الصلواتِ الخمس، وصيامِ رمضان، وبرِّ الوالدين. الواجبُ يُثابُ فاعلُهُ ويُعاقَبُ تاركُه.\n٢. المستحب: وهو ليس على وجهِ اللزوم، مثلُ السننِ الرواتب، وقيامِ الليل، وإطعامِ الطعام. ويُسمّى السنةَ والمندوب. يُثابُ فاعلُهُ ولا يُعاقَبُ تاركُه.\n٣. المحرم: وهو ما تركُهُ لازم، مثلُ تركِ الصلاة، وشربِ الخمر، وعقوقِ الوالدين، وقطعِ الأرحام. يُثابُ تاركُهُ ويُعاقَبُ فاعلُه.\n٤. المكروه: تركُهُ غيرُ لازم، مثلُ الأخذِ والإعطاءِ باليدِ الشمال، وكفِّ الثوبِ في الصلاة. يُثابُ تاركُهُ ولا يُعاقَبُ فاعلُه.\n٥. المباح: وهو على التخييرِ بين تركِهِ وفعله، مثلُ أكلِ التفاحةِ وشربِ الشاي. ويُسمّى: الجائزَ والحلال. لا يُثابُ تاركُهُ ولا يُعاقَبُ فاعلُه."}, {"id": 256, "q": "ما ثمرةُ التفقهِ في الدين، وفضلُ الفقهِ في الدين؟", "a": "صحةُ الأقوالِ والأعمالِ والاعتقادات، بما يُثمِرُ السعادةَ في الدنيا والآخرة. في الحديث عن معاويةَ بنِ أبي سفيان: قال رسولُ الله ﷺ: «من يُردِ اللهُ به خيرًا يُفقِّههُ في الدين» رواه البخاري ومسلم. (يُفقّهه: أي يجعلهُ عالمًا بالأحكامِ الشرعية)."}, {"id": 257, "q": "ما حكمُ البيعِ والمعاملات؟", "a": "الأصلُ في كلِّ البيوعِ والمعاملاتِ أنها حلال، إلا بعضَ الأنواعِ مما حرَّمَ اللهُ تعالى. قال تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ [البقرة: ٢٧٥]."}, {"id": 258, "q": "ما بعضُ أنواعِ المعاملاتِ والبيوعِ المحرمة؟", "a": "١. الغش، ومنه: إخفاءُ عيبِ السلعة. فعن أبي هريرة، أنَّ رسولَ الله ﷺ مرَّ على صُبرةِ طعام، فأدخلَ يدَهُ فيها، فنالتْ أصابعُهُ بلَلًا، فقال: «ما هذا يا صاحبَ الطعام؟» قال: أصابتْهُ السماءُ يا رسولَ الله. قال: «أفلا جعلتَهُ فوقَ الطعامِ كي يراهُ الناس؟ من غشَّ فليس مني» رواه مسلم.\n٢. الربا، ومنه: أن آخذَ ألفًا من إنسانٍ دينًا على أن أردَّهُ إليه ألفين. والزيادةُ هي الربا المحرم. قال تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ [البقرة: ٢٧٥].\n٣. الغررُ والجهالة: كأن أبيعَكَ الحليبَ في ضرعِ الشاة، أو السمكةَ في الماءِ ولم أصطدْها بعد. ففي الحديث: «نهى رسولُ الله ﷺ عن بيعِ الغرر» رواه مسلم."}, {"id": 259, "q": "اذكرْ بعضَ نعمِ اللهِ عليك.", "a": "١. نعمةُ الإسلام، وأنك لست من أهلِ الكفر.\n٢. نعمةُ السنة، وأنك لست من أهلِ البدع.\n٣. نعمةُ الصحةِ والعافية، كالسمعِ والبصرِ والمشي وغيرها.\n٤. نعمةُ الطعامِ والشرابِ والملبس.\nونِعمُهُ تعالى علينا كثيرةٌ لا تُعدُّ ولا تُحصى. قال تعالى: ﴿وَإِن تَعُدُّوا نِعْمَتَ اللَّهِ لَا تُحْصُوهَا إِنَّ اللَّهَ لَغَفُورٌ رَّحِيمٌ﴾ [النحل: ١٨]."}, {"id": 260, "q": "ما الواجبُ في النعم؟ وكيف تشكرها؟", "a": "الواجب: شكرُها؛ وذلك بالثناءِ على اللهِ وحمدِهِ باللسانِ وأنه له الفضلُ وحده، واستعمالِ هذه النعمِ بما يرضي اللهَ تعالى، لا بمعصيته. قال تعالى: ﴿فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ﴾ [البقرة: ١٥٢]."}, {"id": 261, "q": "ما هي أعيادُ المسلمين؟", "a": "عيدُ الفطر، وعيدُ الأضحى. لما جاء في حديثِ أنس، قال: قدِمَ رسولُ الله ﷺ المدينةَ ولهم يومانِ يلعبونَ فيهما، فقال: «ما هذانِ اليومان؟» قالوا: كنا نلعبُ فيهما في الجاهلية، فقال رسولُ الله ﷺ: «إنَّ اللهَ قد أبدلكم بهما خيرًا منهما: يومَ الأضحى، ويومَ الفطر» رواه أبو داود. وما سواها من الأعيادِ فمن البدع."}, {"id": 262, "q": "ما هو أفضلُ الشهور؟", "a": "شهرُ رمضان."}, {"id": 263, "q": "ما هو أفضلُ الأيام؟", "a": "يومُ الجمعة."}, {"id": 264, "q": "ما هو أفضلُ يومٍ في العام؟", "a": "يومُ النحر، وقيل يومُ عرفة."}, {"id": 265, "q": "ما هي أفضلُ ليلةٍ في العام؟", "a": "ليلةُ القدر."}], "dyk": ["لو مددتَ أوعيةَ الدمِ في جسمِك لطافتْ حولَ الأرضِ أكثرَ من مرتَين!"], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، وَمَعِي فَصِيح وَسَلَّتُهُ الْمُلَوَّنَةُ!"}, {"s": "fasih", "t": "مُنَوَّعَاتٌ! مُنَوَّعَاتٌ! وَجَوَابُ اللُّغْزِ الْمَاضِي: نُوحٌ عَلَيْهِ السَّلَامُ، نَجَّاهُ اللَّهُ وَمَنْ آمَنَ مَعَهُ فِي السَّفِينَةِ."}, {"s": "anos", "t": "هَيَّا نَفْتَحُ السَّلَّةَ. اسْأَلْ يَا فَصِيح!"}, {"s": "fasih", "t": "مَا الْأَحْكَامُ التَّكْلِيفِيَّةُ الْخَمْسَةُ؟"}, {"s": "anos", "t": "الْوَاجِبُ، وَالْمُسْتَحَبُّ، وَالْمُحَرَّمُ، وَالْمَكْرُوهُ، وَالْمُبَاحُ."}, {"s": "fasih", "t": "اشْرَحْهَا لَنَا!"}, {"s": "anos", "t": "الْوَاجِبُ كَالصَّلَوَاتِ الْخَمْسِ: يُثَابُ فَاعِلُهُ وَيُعَاقَبُ تَارِكُهُ. وَالْمُسْتَحَبُّ كَقِيَامِ اللَّيْلِ: يُثَابُ فَاعِلُهُ وَلَا يُعَاقَبُ تَارِكُهُ. وَالْمُحَرَّمُ كَعُقُوقِ الْوَالِدَيْنِ: يُثَابُ تَارِكُهُ وَيُعَاقَبُ فَاعِلُهُ."}, {"s": "fasih", "t": "وَالْمَكْرُوهُ وَالْمُبَاحُ؟"}, {"s": "anos", "t": "الْمَكْرُوهُ كَالْأَخْذِ بِالْيَدِ الشِّمَالِ: يُثَابُ تَارِكُهُ وَلَا يُعَاقَبُ فَاعِلُهُ. وَالْمُبَاحُ كَأَكْلِ التُّفَّاحَةِ: لَا ثَوَابَ وَلَا عِقَابَ."}, {"s": "fasih", "t": "وَمَا ثَمَرَةُ التَّفَقُّهِ فِي الدِّينِ؟"}, {"s": "anos", "t": "صِحَّةُ الْأَقْوَالِ وَالْأَعْمَالِ وَالِاعْتِقَادَاتِ، وَالسَّعَادَةُ فِي الدُّنْيَا وَالْآخِرَةِ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ». رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ."}, {"s": "fasih", "t": "وَمَا حُكْمُ الْبَيْعِ؟"}, {"s": "anos", "t": "الْأَصْلُ فِي الْبُيُوعِ وَالْمُعَامَلَاتِ أَنَّهَا حَلَالٌ، إِلَّا مَا حَرَّمَهُ اللَّهُ، فَقَدْ أَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا."}, {"s": "fasih", "t": "وَمَا الْبُيُوعُ الْمُحَرَّمَةُ؟"}, {"s": "anos", "t": "الْغِشُّ كَإِخْفَاءِ الْعَيْبِ، وَالرِّبَا كَأَنْ تَقْتَرِضَ أَلْفًا وَتَرُدَّهَا أَلْفَيْنِ، وَالْغَرَرُ كَبَيْعِ السَّمَكَةِ فِي الْمَاءِ قَبْلَ صَيْدِهَا."}, {"s": "fasih", "t": "وَمَا بَعْضُ نِعَمِ اللَّهِ عَلَيْكَ؟"}, {"s": "anos", "t": "نِعْمَةُ الْإِسْلَامِ، وَنِعْمَةُ السُّنَّةِ، وَنِعْمَةُ الصِّحَّةِ كَالسَّمْعِ وَالْبَصَرِ، وَنِعْمَةُ الطَّعَامِ وَاللِّبَاسِ. وَاسْمَعُوا بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "16:18", "t": "وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌۭ رَّحِيمٌۭ"}, {"s": "fasih", "t": "نِعَمٌ لَا تُعَدُّ وَلَا تُحْصَى! فَكَيْفَ نَشْكُرُهَا؟"}, {"s": "anos", "t": "نَحْمَدُ اللَّهَ بِأَلْسِنَتِنَا، وَنَسْتَعْمِلُ النِّعَمَ فِي مَا يُرْضِيهِ لَا فِي مَعْصِيَتِهِ. وَقَبْلَ النَّوْمِ عُدُّوا خَمْسَ نِعَمٍ، وَقُولُوا: الْحَمْدُ لِلَّهِ."}, {"s": "fasih", "t": "وَمَا أَعْيَادُ الْمُسْلِمِينَ؟"}, {"s": "anos", "t": "عِيدُ الْفِطْرِ وَعِيدُ الْأَضْحَى، قَالَ النَّبِيُّ: «إِنَّ اللَّهَ قَدْ أَبْدَلَكُمْ بِهِمَا خَيْرًا مِنْهُمَا». وَمَا سِوَاهُمَا مِنَ الْأَعْيَادِ فَمِنَ الْبِدَعِ."}, {"s": "fasih", "t": "أَسْئِلَةٌ سَرِيعَةٌ: أَفْضَلُ الشُّهُورِ؟"}, {"s": "anos", "t": "شَهْرُ رَمَضَانَ."}, {"s": "fasih", "t": "وَأَفْضَلُ الْأَيَّامِ؟ وَأَفْضَلُ يَوْمٍ فِي الْعَامِ؟ وَأَفْضَلُ لَيْلَةٍ؟"}, {"s": "anos", "t": "يَوْمُ الْجُمُعَةِ، وَيَوْمُ النَّحْرِ، وَقِيلَ يَوْمُ عَرَفَةَ، وَلَيْلَةُ الْقَدْرِ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ لَوْ مَدَدْتَ أَوْعِيَةَ الدَّمِ فِي جِسْمِكَ، لَطَافَتْ حَوْلَ الْأَرْضِ أَكْثَرَ مِنْ مَرَّتَيْنِ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! نَشَاطُنَا: إِشَارَاتُ الْمُرُورِ الْخَمْسُ. خَمْسُ لَافِتَاتٍ لِلْأَحْكَامِ فِي أَرْكَانِ الْغُرْفَةِ، وَمَعَ كُلِّ بِطَاقَةِ عَمَلٍ تَمْشُونَ إِلَى رُكْنِ حُكْمِهَا. أَوْقِفُوا الْحَلْقَةَ، وَالْعَبُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: إشارات المرور الخمس"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! يُرِيدُ أَنُوس بَيْعَ سَيَّارَتِهِ اللُّعْبَةِ، وَعَجَلَتُهَا مَكْسُورَةٌ. أ: يُخْفِي الْعَيْبَ. ب: يُخْبِرُ صَدِيقَهُ وَيَبِيعُهَا بِسِعْرٍ مُنَاسِبٍ. ج: يَبِيعُهُ لُعْبَةً لَمْ يَشْتَرِهَا بَعْدُ. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: اللعبة المكسورة"}, {"s": "anos", "t": "ب هُوَ الصَّحِيحُ: بَيْعٌ صَادِقٌ. أ غِشٌّ، وَج غَرَرٌ نَهَى عَنْهُ النَّبِيُّ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: صِيَامُ رَمَضَانَ حُكْمُهُ…؟ فَكِّرُوا…"}, {"s": "anos", "t": "وَاجِبٌ! وَأَكْلُ التُّفَّاحَةِ؟ فَكِّرُوا… مُبَاحٌ."}, {"s": "fasih", "t": "لُغْزُ «مَنْ أَنَا؟»: أَمَرَ اللَّهُ أَبِي أَنْ يَذْبَحَنِي فَصَبَرْتُ، فَفَدَانِيَ اللَّهُ بِكَبْشٍ عَظِيمٍ، وَسَاعَدْتُ أَبِي فِي رَفْعِ قَوَاعِدِ الْكَعْبَةِ. إِبْرَاهِيمُ، أَمْ إِسْمَاعِيلُ، أَمْ يُوسُفُ، عَلَيْهِمُ السَّلَامُ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ ازْرَعُوا «شَجَرَةَ النِّعَمِ»، وَافْتَحُوا «سَلَّةَ فَصِيح» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ."}, {"s": "fasih", "t": "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. السَّلَامُ عَلَيْكُمْ!"}]}}, {"n": 30, "title": "منوّعات (٢): التقوى والتوبة ومعاني الأذكار", "season": 3, "goals": ["munawaat"], "hook": "طبول الاحتفال تدقّ! أنوس يلبس وشاحًا ذهبيًّا، وفصيح يحمل كأسًا صغيرة ويصيح: «الحلقة الأخيرة! الحلقة الأخيرة! والمسابقة الكبرى!». لكن قبل المسابقة، بقيت في سلّة فصيح أسئلة مهمّة جدًّا. هيّا بنا!", "sections": [{"h": "العين الحارسة والحجاب الساتر", "p": ["فصيح يسأل: «ما الواجب إذا رأى الرجل امرأة أجنبية؟». الواجب <b>غضّ البصر</b>، أي: يخفض نظره ولا يطيل النظر إليها. قال تعالى: «قل للمؤمنين يغضّوا من أبصارهم». فالعين نعمة، ونحفظها كما نحفظ اللسان.", "وللمرأة المسلمة إذا كبرت <b>حجاب</b> يسترها، وهو طاعة لله وحفظ لها. ومن صفاته كما في الكتاب: أن يستر جميع البدن، وألّا يكون فيه زينة، وألّا يكون شفّافًا، وأن يكون <b>واسعًا</b> غير ضيّق، وألّا يكون مطيّبًا بالبخور والعطر، وألّا يشبه لباس الرجال، ولا لباس غير المسلمات. وقد أمر الله به في سورة الأحزاب، وقال: «ذلك أدنى أن يُعرفن فلا يؤذين».", "فالحياء الذي تعلّمناه يظهر في العين التي تُغضّ، وفي اللباس الذي يستر."], "board": ["غضّ البصر", "حجاب ساتر واسع", "الحياء"]}, {"h": "ثلاثة أعداء… والتقوى درعنا", "p": ["للإنسان <b>ثلاثة أعداء</b>: <b>النفس الأمّارة بالسوء</b> عندما تقول لك: «اترك الصلاة والعب»، و<b>الشيطان</b> الذي يوسوس لك بالشرّ ويريد أن يدخلك النار، و<b>أصحاب السوء</b> الذين يدعونك إلى الشرّ ويمنعونك من الخير.", "فكيف نغلبهم؟ بـ<b>التقوى</b>: وهي <b>فعل الطاعات وترك المعاصي</b>. والله مع المتّقين.", "و<b>طريق العزّ والنصر للمسلمين</b>: العمل بالإسلام، وترك المعاصي والذنوب. قال تعالى: «إن تنصروا الله ينصركم ويثبّت أقدامكم»."], "board": ["النفس الأمّارة", "الشيطان", "أصحاب السوء", "التقوى"]}, {"h": "التوبة والدعاء: باب مفتوح", "p": ["إذا أخطأ أنوس، هل ييأس؟ لا! بل يتوب. <b>التوبة</b>: الرجوع عن معصية الله إلى طاعته.", "و<b>شروط التوبة الصحيحة</b> أربعة: ١. أن <b>يترك</b> الذنب. ٢. أن <b>يندم</b> على ما فعل. ٣. أن <b>يعزم</b> ألّا يعود إليه. ٤. أن <b>يردّ الحقوق</b> لأصحابها؛ فإن أخذ قلم أخيه ردّه إليه واعتذر.", "و<b>الدعاء</b> من أعظم الطاعات. قال تعالى: «ادعوني أستجب لكم»، وقال ﷺ: «الدعاء هو العبادة». فصيح يقول: «اطلب من الله كلّ شيء، صغيرًا كان أو كبيرًا!»."], "board": ["أترك", "أندم", "أعزم", "أردّ الحقّ"]}, {"h": "معاني الأذكار التي نحبّها", "p": ["قلنا أذكارًا كثيرة في هذه السلسلة، فما معناها؟", "<b>الصلاة على النبيّ ﷺ</b>: أن تدعو الله أن يثني على نبيّه ﷺ في الملأ الأعلى. <b>سبحان الله</b>: الله منزّه عن كلّ نقص وعيب وسوء. <b>الحمد لله</b>: الثناء على الله ووصفه بكلّ صفات الكمال. <b>الله أكبر</b>: الله أكبر وأجلّ وأعظم وأعزّ من كلّ شيء.", "<b>لا حول ولا قوّة إلا بالله</b>: لا أستطيع أن أنتقل من حال إلى حال، ولا قوّة لي على ذلك، إلا بالله. <b>أستغفر الله</b>: أطلب من ربي أن يمحو ذنوبي ويستر عيوبي."], "board": ["سبحان الله", "الحمد لله", "الله أكبر", "لا حول ولا قوّة إلا بالله", "أستغفر الله"]}, {"h": "المسابقة الكبرى… وشهادة الختام", "p": ["تعلّمنا في ثلاثين حلقة كتاب «<b>ما لا يسع أطفال المسلمين جهله</b>»: التوحيد وأركان الإيمان، والطهارة والصلاة، والأخلاق، والأذكار، والمنوّعات. واليوم <b>مسابقة أنوس الكبرى</b> عن الكتاب كلّه!", "ومن يكمل المسابقة ينال <b>شهادة «صديق أنوس العالِم الصغير»</b>. لكنّ أجمل جائزة ليست الورقة؛ بل أن تعمل بما تعلّمت، وأن تبقى تتعلّم، فالنبيّ ﷺ قال: «من يرد الله به خيرًا يفقّهه في الدين».", "أنوس وفصيح يقولان لكم: شكرًا لأنكم كنتم معنا، ونحبّكم في الله!"], "board": ["تعلّمت", "عملت", "علّمت غيري"]}], "summary": ["الواجب غضّ البصر، وحجاب المرأة المسلمة ساتر واسع بلا زينة ولا شفافية، والتقوى فعل الطاعات وترك المعاصي.", "أعداء الإنسان: النفس الأمّارة والشيطان وأصحاب السوء، والتوبة لها أربعة شروط، والدعاء هو العبادة.", "سبحان الله تنزيه، والحمد لله ثناء، والله أكبر تعظيم، ولا حول ولا قوّة إلا بالله استعانة، وأستغفر الله طلب المغفرة."], "islam": {"intro": "قال الله تعالى يبشّر التائبين:", "text": "فباب التوبة مفتوح دائمًا؛ إذا أخطأت فارجع إلى الله فورًا، وقل: أستغفر الله وأتوب إليه.", "ayah": {"text": "وَإِنِّى لَغَفَّارٌۭ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا ثُمَّ ٱهْتَدَىٰ", "src": "سُورَةُ طه: ٨٢"}, "hadith": {"text": "الدعاء هو العبادة", "source": "رواه أبو داود والترمذي وابن ماجه"}}, "home": {"title": "حفل الختام في البيت", "goal": "أن يراجع الطفل مع أسرته أهمّ ما تعلّمه في السلسلة، ويحتفل بإتمامها.", "materials": ["شهادة الختام", "بطاقات أسئلة من الحلقات", "ضيافة بسيطة"], "steps": ["اجمع أسرتك، وكن أنت «أنوس» الذي يسأل، وليكن أحد إخوتك «فصيحًا».", "اسأل أسرتك عشرة أسئلة من الكتاب: من التوحيد، والصلاة، والأخلاق، والأذكار، والمنوّعات.", "اشرح لأسرتك معاني الأذكار الستّة التي تعلّمتها اليوم.", "اكتب على ظهر شهادتك ثلاثة وعود: خُلُق سأحافظ عليه، وذكر سأقوله كل يوم، وشيء سأعلّمه لغيري."], "parent": "احتفلوا بطفلكم وعلّقوا شهادته في مكان ظاهر، وراجعوا الوعود الثلاثة معه كل أسبوع بلطف ومحبّة."}, "online": {"title": "المسابقة الكبرى", "intro": "هذه آخر محطّة في رحلة أنوس وفصيح: أجب عن أسئلة الكتاب كلّه، وانل شهادة الختام!", "steps": [{"type": "match", "title": "صِل الذكر بمعناه", "prompt": "اختر الذكر، ثم معناه الصحيح.", "pairs": [["سبحان الله", "تنزيه الله عن كلّ نقص وعيب"], ["الحمد لله", "الثناء على الله ووصفه بصفات الكمال"], ["الله أكبر", "الله أكبر وأعظم من كلّ شيء"], ["لا حول ولا قوّة إلا بالله", "لا تحوّل ولا قوّة لنا إلا بالله"], ["أستغفر الله", "طلب محو الذنوب وستر العيوب"]]}, {"type": "order", "title": "رتّب خطوات التوبة", "prompt": "أخذ أنوس قلم أخيه دون إذنه، ثم أراد أن يتوب. رتّب الخطوات كما في الكتاب.", "items": ["يترك الذنب فورًا", "يندم على ما فعل", "يعزم ألّا يعود إليه", "يردّ القلم إلى أخيه ويعتذر"]}, {"type": "quiz", "title": "المسابقة الكبرى: الكتاب كلّه", "items": [{"q": "مَن نبيّك؟", "o": ["موسى عليه السلام", "محمد ﷺ", "عيسى عليه السلام"], "a": 1, "why": "نبيّنا محمد ﷺ خاتم الأنبياء."}, {"q": "ماذا تقول عند الخروج من الخلاء؟", "o": ["غفرانك", "بسم الله", "آيبون تائبون"], "a": 0, "why": "دعاء الخروج من الخلاء: «غفرانك»."}, {"q": "ما هي النميمة؟", "o": ["الدعاء للناس", "السلام", "نقل الكلام للإفساد بين الناس"], "a": 2, "why": "«لا يدخل الجنة نمّام»."}, {"q": "ما أفضل ليلة في العام؟", "o": ["ليلة القدر", "ليلة العيد", "ليلة السفر"], "a": 0, "why": "أفضل ليلة في العام ليلة القدر."}, {"q": "ما الواجب إذا رأى الرجل امرأة أجنبية؟", "o": ["أن يطيل النظر", "غضّ البصر", "أن يضحك"], "a": 1, "why": "قال تعالى: «قل للمؤمنين يغضّوا من أبصارهم»."}]}]}, "case": {"title": "مَن أنا؟", "story": "في الحلقة الأخيرة، أخرج فصيح آخر ورقة لغز في السلسلة، عن بطل مسلم عرف طريق العزّ والنصر. اقرأ الأدلّة وخمّن: مَن أنا؟", "evidence": ["جمعت كلمة المسلمين ووحّدت صفوفهم.", "انتصرت في معركة حطّين.", "حرّرت بيت المقدس بعد ذلك النصر."], "options": ["السلطان قطز رحمه الله", "صلاح الدين الأيوبي رحمه الله", "طارق بن زياد رحمه الله"], "deep": "تعلّمنا اليوم أنّ طريق العزّ والنصر هو العمل بالإسلام وترك المعاصي. كيف يمكن أن تكون أنت سببًا في عزّة المسلمين وأنت صغير؟", "reveal": "أنا صلاح الدين الأيوبي رحمه الله! انتصرت في حطّين، وحرّرت بيت المقدس سنة ٥٨٣ للهجرة، لأنّ المسلمين اجتمعوا على طاعة الله. وهنا تنتهي رحلتنا يا أصدقاء! تعلّمنا معًا ما لا يسع الطفل المسلم جهله، والآن جاء دوركم: اعملوا بما تعلّمتم، وعلّموه إخوتكم وأصدقاءكم. أنوس وفصيح يقولان: إلى اللقاء… في طاعة الله!"}, "quiz": [{"q": "ما التقوى؟", "o": ["فعل الطاعات وترك المعاصي", "النوم مبكّرًا", "كثرة اللعب"], "a": 0, "why": "التقوى فعل الطاعات وترك المعاصي، كما في الكتاب."}], "qa": [{"id": 266, "q": "ما الواجبُ إذا رأيتَ امرأةً أجنبية؟", "a": "الواجبُ غضُّ البصر. قال تعالى: ﴿قُل لِّلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ﴾ [النور: ٣٠]."}, {"id": 267, "q": "ما صفاتُ حجابِ المرأةِ المسلمة؟", "a": "• أن يكونَ ساترًا لجميعِ البدن.\n• أن لا يكونَ به زينة.\n• أن لا يكونَ شفافًا.\n• أن يكونَ واسعًا غيرَ ضيق.\n• أن لا يكونَ مبخَّرًا مطيبًا.\n• أن لا يشبهَ لباسَ الرجل.\n• أن لا يشبهَ لباسَ الكافراتِ والفاسقات.\nقال تعالى: ﴿يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَابِيبِهِنَّ ذَٰلِكَ أَدْنَىٰ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا﴾ [الأحزاب: ٥٩]."}, {"id": 268, "q": "من هم أعداءُ الإنسان؟", "a": "١. النفسُ الأمَّارةُ بالسوء: وذلك أن يتبعَ الإنسانُ ما تمليه عليه نفسُهُ وهواهُ في معصيةِ الله. قال سبحانه: ﴿إِنَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي إِنَّ رَبِّي غَفُورٌ رَّحِيمٌ﴾ [يوسف: ٥٣].\n٢. الشيطان: وهو عدوُّ ابنِ آدم، وغايتُهُ أن يُضِلَّ الإنسانَ ويوسوسَ له في الشر ويدخلَهُ النار. قال تعالى: ﴿وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ﴾ [البقرة: ١٦٨].\n٣. أصحابُ السوء: الذين يحثُّونَ على الشر، ويصدُّونَ عن الخير. قال تعالى: ﴿الْأَخِلَّاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا الْمُتَّقِينَ﴾ [الزخرف: ٦٧]."}, {"id": 269, "q": "ما هي التقوى؟", "a": "هي فعلُ الطاعاتِ وتركُ المعاصي. قال تعالى: ﴿وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ﴾ [البقرة: ١٩٤]."}, {"id": 270, "q": "ما هي التوبة؟", "a": "التوبة: هي الرجوعُ عن معصيةِ اللهِ تعالى إلى طاعته. قال تعالى: ﴿وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَىٰ﴾ [طه: ٨٢]."}, {"id": 271, "q": "ما شروطُ التوبةِ الصحيحة؟", "a": "١. الإقلاعُ عن الذنب.\n٢. الندمُ على ما فات.\n٣. العزمُ على عدمِ العودةِ إليه.\n٤. ردُّ الحقوقِ والمظالمِ لأهلها.\nقال تعالى: ﴿وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ﴾ [آل عمران: ١٣٥]."}, {"id": 272, "q": "ما هو طريقُ العزِّ والنصرِ للمسلمين؟", "a": "هو العملُ بالإسلام، وتركُ المعاصي والذنوب. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تَنصُرُوا اللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ﴾ [محمد: ٧]. وقال سبحانه: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ﴾ [الرعد: ١١]."}, {"id": 273, "q": "ما أهميةُ الدعاء؟", "a": "الدعاءُ هو من أعظمِ الطاعاتِ وأجلِّ القربات. قال تعالى: ﴿وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ﴾ [غافر: ٦٠]. وقال النبيُّ ﷺ: «الدعاءُ هو العبادة» رواه أبو داود والترمذي وابن ماجه."}, {"id": 274, "q": "ما معنى الصلاةِ على النبيِّ ﷺ؟", "a": "معناها أنك تدعو اللهَ أن يُثنيَ على نبيِّهِ ﷺ في الملأِ الأعلى."}, {"id": 275, "q": "ما معنى «سبحان الله»؟", "a": "التسبيح، وهو تنزيهُهُ سبحانه وتعالى عن كلِّ نقصٍ وعيبٍ وسوء."}, {"id": 276, "q": "ما معنى «الحمد لله»؟", "a": "هو الثناءُ على اللهِ تعالى، ووصفُهُ بكلِّ صفاتِ الكمال."}, {"id": 277, "q": "ما معنى «الله أكبر»؟", "a": "أي: إنه سبحانه أكبرُ من كلِّ شيءٍ وأجلُّ وأعظمُ وأعزُّ من كلِّ شيء."}, {"id": 278, "q": "ما معنى «لا حول ولا قوة إلا بالله»؟", "a": "معناها: لا تحوُّلَ للعبدِ من حالٍ إلى حال، ولا قوةَ له على ذلك إلا بالله."}, {"id": 279, "q": "ما معنى «أستغفر الله»؟", "a": "أي: طلبُ العبدِ من ربِّهِ أن يمحوَ ذنوبَهُ ويسترَ عيوبه."}], "dyk": ["داخلُ الأرضِ حارٌّ جداً كالشمس، والبراكينُ منافذُ تخرجُ منها هذه الحرارة."], "verses": [], "singer": null, "podcast": {"lines": [{"s": "anos", "t": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ! بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. أَنَا أَنُوس، بِوِشَاحِيَ الذَّهَبِيِّ!"}, {"s": "fasih", "t": "الْحَلْقَةُ الْأَخِيرَةُ! الْحَلْقَةُ الْأَخِيرَةُ! وَجَوَابُ اللُّغْزِ الْمَاضِي: إِسْمَاعِيلُ عَلَيْهِ السَّلَامُ، الَّذِي صَبَرَ وَأَطَاعَ رَبَّهُ وَأَبَاهُ."}, {"s": "anos", "t": "بَقِيَتْ فِي سَلَّتِكَ أَسْئِلَةٌ مُهِمَّةٌ يَا فَصِيح. هَاتِهَا!"}, {"s": "fasih", "t": "مَا الْوَاجِبُ إِذَا رَأَيْتَ امْرَأَةً أَجْنَبِيَّةً؟"}, {"s": "anos", "t": "غَضُّ الْبَصَرِ، كَمَا أَمَرَ اللَّهُ الْمُؤْمِنِينَ."}, {"s": "fasih", "t": "وَمَا صِفَاتُ حِجَابِ الْمَرْأَةِ الْمُسْلِمَةِ؟"}, {"s": "anos", "t": "سَاتِرٌ لِجَمِيعِ الْبَدَنِ، بِلَا زِينَةٍ، غَيْرُ شَفَّافٍ، وَاسِعٌ، غَيْرُ مُطَيَّبٍ، لَا يُشْبِهُ لِبَاسَ الرَّجُلِ، وَلَا لِبَاسَ الْكَافِرَاتِ وَالْفَاسِقَاتِ."}, {"s": "fasih", "t": "وَمَنْ أَعْدَاءُ الْإِنْسَانِ؟"}, {"s": "anos", "t": "النَّفْسُ الْأَمَّارَةُ بِالسُّوءِ، وَالشَّيْطَانُ الَّذِي يُرِيدُ أَنْ يُضِلَّنَا، وَأَصْحَابُ السُّوءِ الَّذِينَ يَحُثُّونَ عَلَى الشَّرِّ."}, {"s": "fasih", "t": "وَمَا التَّقْوَى؟"}, {"s": "anos", "t": "فِعْلُ الطَّاعَاتِ وَتَرْكُ الْمَعَاصِي."}, {"s": "fasih", "t": "وَمَا التَّوْبَةُ؟"}, {"s": "anos", "t": "الرُّجُوعُ عَنْ مَعْصِيَةِ اللَّهِ إِلَى طَاعَتِهِ. اسْمَعُوا الْبُشْرَى بِصَوْتِ الشَّيْخِ الْحُصَرِيِّ."}, {"s": "quran", "ref": "20:82", "t": "وَإِنِّى لَغَفَّارٌۭ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا ثُمَّ ٱهْتَدَىٰ"}, {"s": "fasih", "t": "بَابُ التَّوْبَةِ مَفْتُوحٌ دَائِمًا! فَمَا شُرُوطُهَا؟"}, {"s": "anos", "t": "الْإِقْلَاعُ عَنِ الذَّنْبِ، وَالنَّدَمُ عَلَى مَا فَاتَ، وَالْعَزْمُ عَلَى عَدَمِ الْعَوْدَةِ، وَرَدُّ الْحُقُوقِ لِأَهْلِهَا."}, {"s": "fasih", "t": "وَمَا طَرِيقُ الْعِزِّ وَالنَّصْرِ لِلْمُسْلِمِينَ؟"}, {"s": "anos", "t": "الْعَمَلُ بِالْإِسْلَامِ، وَتَرْكُ الْمَعَاصِي وَالذُّنُوبِ، فَمَنْ نَصَرَ اللَّهَ نَصَرَهُ اللَّهُ."}, {"s": "fasih", "t": "وَمَا أَهَمِّيَّةُ الدُّعَاءِ؟"}, {"s": "anos", "t": "مِنْ أَعْظَمِ الطَّاعَاتِ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الدُّعَاءُ هُوَ الْعِبَادَةُ». رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَابْنُ مَاجَهْ."}, {"s": "fasih", "t": "الْآنَ مَعَانِي الْأَذْكَارِ! مَا مَعْنَى الصَّلَاةِ عَلَى النَّبِيِّ؟"}, {"s": "anos", "t": "أَنْ تَدْعُوَ اللَّهَ أَنْ يُثْنِيَ عَلَى نَبِيِّهِ فِي الْمَلَأِ الْأَعْلَى."}, {"s": "fasih", "t": "سُبْحَانَ اللَّهِ؟"}, {"s": "anos", "t": "تَنْزِيهُ اللَّهِ عَنْ كُلِّ نَقْصٍ وَعَيْبٍ وَسُوءٍ."}, {"s": "fasih", "t": "الْحَمْدُ لِلَّهِ؟"}, {"s": "anos", "t": "الثَّنَاءُ عَلَى اللَّهِ، وَوَصْفُهُ بِكُلِّ صِفَاتِ الْكَمَالِ."}, {"s": "fasih", "t": "اللَّهُ أَكْبَرُ؟"}, {"s": "anos", "t": "أَنَّهُ سُبْحَانَهُ أَكْبَرُ وَأَعْظَمُ وَأَعَزُّ مِنْ كُلِّ شَيْءٍ."}, {"s": "fasih", "t": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ؟"}, {"s": "anos", "t": "لَا تَحَوُّلَ لِلْعَبْدِ مِنْ حَالٍ إِلَى حَالٍ، وَلَا قُوَّةَ لَهُ عَلَى ذَلِكَ، إِلَّا بِاللَّهِ."}, {"s": "fasih", "t": "أَسْتَغْفِرُ اللَّهَ؟"}, {"s": "anos", "t": "أَنْ تَطْلُبَ مِنْ رَبِّكَ أَنْ يَمْحُوَ ذُنُوبَكَ وَيَسْتُرَ عُيُوبَكَ."}, {"s": "fasih", "t": "هَلْ تَعْلَمُ؟ دَاخِلُ الْأَرْضِ حَارٌّ جِدًّا كَالشَّمْسِ، وَالْبَرَاكِينُ مَنَافِذُ تَخْرُجُ مِنْهَا هَذِهِ الْحَرَارَةُ!"}, {"s": "anos", "t": "سُبْحَانَ اللَّهِ! وَالْآنَ: مُسَابَقَةُ أَنُوس الْكُبْرَى وَحَفْلُ الشَّهَادَاتِ! فِرَقٌ بِأَسْمَاءِ الْأَخْلَاقِ، وَثَلَاثُ جَوْلَاتٍ: الْعَقِيدَةُ، وَالْأَخْلَاقُ وَالْأَذْكَارُ، وَالْمُنَوَّعَاتُ. أَوْقِفُوا الْحَلْقَةَ، وَتَسَابَقُوا مَعَ مُعَلِّمِكُمْ أَوْ أُسْرَتِكُمْ، ثُمَّ عُودُوا!"}, {"s": "pause", "label": "النشاط ١: مسابقة أنوس الكبرى وحفل الشهادات"}, {"s": "fasih", "t": "مُخْتَبَرُ الْقَرَارِ! قَالَ صَدِيقٌ: تَعَالَ نَتْرُكْ صَلَاةَ الْعَصْرِ وَنُكْمِلِ اللَّعِبَ! أ: يُوَافِقُ، فَلَا أَحَدَ يَرَاهُ. ب: يَقُولُ: اللَّهُ يَرَانِي، وَيَدْعُوهُ إِلَى الصَّلَاةِ، ثُمَّ يَلْعَبَانِ. ج: يَتْرُكُهَا الْيَوْمَ وَيَتُوبُ غَدًا. أَوْقِفُوا الْحَلْقَةَ وَنَاقِشُوا، ثُمَّ ارْجِعُوا!"}, {"s": "pause", "label": "النشاط ٢: مختبر القرار: صديق يدعو إلى الخطأ"}, {"s": "anos", "t": "ب هُوَ التَّقْوَى وَمُرَاقَبَةُ اللَّهِ. أ اتِّبَاعٌ لِصَاحِبِ السُّوءِ، وَج لَيْسَ تَوْبَةً صَحِيحَةً، لِأَنَّهُ عَزْمٌ عَلَى الذَّنْبِ."}, {"s": "fasih", "t": "سُؤَالٌ سَرِيعٌ: مِنْ شُرُوطِ التَّوْبَةِ؟ فَكِّرُوا…"}, {"s": "anos", "t": "النَّدَمُ عَلَى مَا فَاتَ! وَمَا أَعْظَمُ وَاجِبٍ عَلَيْنَا؟ فَكِّرُوا… تَوْحِيدُ اللَّهِ."}, {"s": "fasih", "t": "آخِرُ لُغْزِ «مَنْ أَنَا؟»: جَمَعْتُ كَلِمَةَ الْمُسْلِمِينَ، وَانْتَصَرْتُ فِي حِطِّينَ، وَحَرَّرْتُ بَيْتَ الْمَقْدِسِ. قُطُزُ، أَمْ صَلَاحُ الدِّينِ الْأَيُّوبِيُّ، أَمْ طَارِقُ بْنُ زِيَادٍ؟ مَا رَأْيُكُمْ؟"}, {"s": "anos", "t": "وَفِي الْبَيْتِ أَقِيمُوا «حَفْلَ الْخِتَامِ»، وَادْخُلُوا «الْمُسَابَقَةَ الْكُبْرَى» عَلَى مَوْقِعِ تَرْبِيَة، فِي كَوْكَبِ الْإِبْدَاعِ، وَنَالُوا شَهَادَةَ الْخِتَامِ!"}, {"s": "fasih", "t": "اعْمَلُوا بِمَا تَعَلَّمْتُمْ، وَعَلِّمُوهُ إِخْوَتَكُمْ وَأَصْدِقَاءَكُمْ. سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ."}, {"s": "anos", "t": "إِلَى اللِّقَاءِ… فِي طَاعَةِ اللَّهِ! السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ!"}]}}], "podcast_hosts": {"anos": {"name": "أنوس", "g": "male", "icon": "🧒"}, "fasih": {"name": "فصيح", "g": "female", "icon": "🦜"}}};
